$global:languageFlags = @{ "el" = "🇬🇷"; "en" = "🇬🇧"; "de" = "🇩🇪"; "fr" = "🇫🇷" }
$global:languageNames = @{ "el" = "Ελληνικά"; "en" = "English"; "de" = "Deutsch"; "fr" = "Français" }

function T {
    param([string]$Key)
    $lang = $global:appSettings.Language
    if ($global:translations.ContainsKey($lang) -and $global:translations[$lang].ContainsKey($Key)) {
        return $global:translations[$lang][$Key]
    }
    if ($global:translations["el"].ContainsKey($Key)) { return $global:translations["el"][$Key] }
    return $Key
}

# ===== ΝΕΟ (v1.5.1): TT() - ΜΕΤΑΦΡΑΣΗ ΠΕΡΙΕΧΟΜΕΝΟΥ ΜΕ ΤΟ ΙΔΙΟ ΤΟ ΕΛΛΗΝΙΚΟ ΚΕΙΜΕΝΟ ΩΣ ΚΛΕΙΔΙ =====
# Σε αντίθεση με την T() (χρησιμοποιεί ονομαστικά keys για το "σκελετό" - μενού/καρτέλες), η TT()
# χρησιμοποιεί απευθείας το ΠΡΑΓΜΑΤΙΚΟ ελληνικό κείμενο ως κλειδί αναζήτησης. Αυτό επιτρέπει να
# "τυλίγεται" κάθε υπάρχον hardcoded string στον κώδικα με TT("...") χωρίς να χρειάζεται να εφευρεθεί
# ξεχωριστό συμβολικό όνομα για εκατοντάδες μεμονωμένους τίτλους/περιγραφές λειτουργιών. Αν δεν υπάρχει
# ακόμα μετάφραση για μια γλώσσα/κείμενο, επιστρέφει το πρωτότυπο ελληνικό (ασφαλές fallback).
function TT {
    param([string]$GreekText)
    $lang = $global:appSettings.Language
    if ($lang -eq "el") { return $GreekText }
    if ($global:stringTranslations.ContainsKey($lang) -and $global:stringTranslations[$lang].ContainsKey($GreekText)) {
        return $global:stringTranslations[$lang][$GreekText]
    }
    return $GreekText
}

