    $chkSkip = [System.Windows.Forms.CheckBox]::new()
    $chkSkip.Text = (TT "Να μην εμφανιστεί ξανά αυτό το μήνυμα")
    $chkSkip.Font = $fontStatus
    $chkSkip.ForeColor = $currTheme.SubText
    $chkSkip.BackColor = [System.Drawing.Color]::Transparent
    $chkSkip.Size = [System.Drawing.Size]::new(380, 26)
    $chkSkip.Location = [System.Drawing.Point]::new(30, 120)
    $rpForm.Controls.Add($chkSkip)

    $btnYes = [System.Windows.Forms.Button]::new()
    $btnYes.Text = (T "BtnYes")
    $btnYes.Font = New-Object System.Drawing.Font("Segoe UI", 9.5, [System.Drawing.FontStyle]::Bold)
    $btnYes.Size = [System.Drawing.Size]::new(110, 38)
    $btnYes.Location = [System.Drawing.Point]::new(110, 165)
    $btnYes.BackColor = $currTheme.Accent
    $btnYes.ForeColor = [System.Drawing.Color]::White
    $btnYes.FlatStyle = "Flat"
    $btnYes.FlatAppearance.BorderSize = 0
    $btnYes.Cursor = [System.Windows.Forms.Cursors]::Hand
    $btnYes.Add_Click({ $rpForm.DialogResult = [System.Windows.Forms.DialogResult]::Yes; $rpForm.Close() })
    $rpForm.Controls.Add($btnYes)

    $btnNo = [System.Windows.Forms.Button]::new()
    $btnNo.Text = (T "BtnNo")
    $btnNo.Font = New-Object System.Drawing.Font("Segoe UI", 9.5, [System.Drawing.FontStyle]::Regular)
    $btnNo.Size = [System.Drawing.Size]::new(110, 38)
    $btnNo.Location = [System.Drawing.Point]::new(230, 165)
    $btnNo.BackColor = $currTheme.BtnDefault
    $btnNo.ForeColor = $currTheme.Text
    $btnNo.FlatStyle = "Flat"
    $btnNo.FlatAppearance.BorderSize = 0
    $btnNo.Cursor = [System.Windows.Forms.Cursors]::Hand
    $btnNo.Add_Click({ $rpForm.DialogResult = [System.Windows.Forms.DialogResult]::No; $rpForm.Close() })
    $rpForm.Controls.Add($btnNo)

    $result = $rpForm.ShowDialog($mainForm)
    $skipChecked = $chkSkip.Checked
    $rpForm.Dispose()
    return [PSCustomObject]@{ Result = $result; SkipFuture = $skipChecked }
}

# ===== ΝΕΟ (v1.6.2): ΑΥΤΟΜΑΤΗ ΕΠΑΝΕΚΚΙΝΗΣΗ ΓΙΑ ΡΥΘΜΙΣΕΙΣ ΠΟΥ ΤΟ ΑΠΑΙΤΟΥΝ =====
# Ορισμένες ρυθμίσεις (τρόπος/θέση μενού, γλώσσα - όχι ΟΛΑ τα πεδία ενημερώνονται ζωντανά) χρειάζονται
# πλήρη επανεκκίνηση της εφαρμογής για να εφαρμοστούν παντού με συνέπεια. Αντί ο χρήστης να κλείνει/
# ανοίγει χειροκίνητα την εφαρμογή, εμφανίζεται ένα pop-up που ρωτάει αν να γίνει η επανεκκίνηση ΤΩΡΑ.
# Η επανεκκίνηση επαναχρησιμοποιεί την ίδια λογική self-elevation με την αρχική εκκίνηση του script.
function Request-AppRestart {
    $result = Show-CustomMessage -Message (TT "Οι αλλαγές που κάνατε απαιτούν επανεκκίνηση της εφαρμογής για να εφαρμοστούν πλήρως.`n`nΘέλετε να γίνει επανεκκίνηση τώρα;") -Title (TT "Απαιτείται Επανεκκίνηση") -Type "YesNo"
    if ($result -eq [System.Windows.Forms.DialogResult]::Yes) {
        try {
            $pwsh = Get-Command pwsh -ErrorAction SilentlyContinue
            $ps = Get-Command powershell -ErrorAction SilentlyContinue
            $shellPath = if ($pwsh) { $pwsh.Source } else { $ps.Source }
            if (-not $shellPath) { $shellPath = 'powershell' }
            # ΔΙΟΡΘΩΣΗ v1.7.2: Ίδια διόρθωση με την αρχική ανύψωση δικαιωμάτων στην κορυφή του script -
            # -WindowStyle Minimized απευθείας στην εκκίνηση, όχι post-hoc.
            Start-Process $shellPath -WindowStyle Minimized -ArgumentList "-NoProfile -ExecutionPolicy Bypass -File `"$PSCommandPath`"" -Verb RunAs
        } catch {}
        $mainForm.Close()
        [System.Environment]::Exit(0)
    }
}

# ===== ΝΕΟ (v1.6.9): ΖΩΝΤΑΝΗ ΕΦΑΡΜΟΓΗ ΤΡΟΠΟΥ/ΘΕΣΗΣ ΜΕΝΟΥ (ΧΩΡΙΣ ΕΠΑΝΕΚΚΙΝΗΣΗ) =====
# ΔΙΕΡΕΥΝΗΘΗΚΕ αν ο τρόπος (πλευρικό/οριζόντιο) και η θέση (αριστερά/δεξιά) του σύγχρονου μενού μπορούν
# να αλλάξουν χωρίς επανεκκίνηση - ΝΑΙ, μπορούν: το πλευρικό panel, η οριζόντια λωρίδα και το κουμπί
# hamburger υπάρχουν ήδη όλα από την εκκίνηση (απλώς κρυμμένα/εμφανή ανάλογα). Αρκεί να επανατοποθετηθεί
# το πλευρικό panel και να κλείσουν και τα δύο (καθαρή κατάσταση) - το επόμενο κλικ στο ☰ θα διαβάσει
# την ΝΕΑ ρύθμιση αυτόματα, αφού ήδη ελέγχεται ζωντανά από το $global:appSettings.MenuMode.
function Apply-MenuModeSettings {
    # ΔΙΟΡΘΩΣΗ v2.0.1: χρησιμοποιεί το κεντρικό Hide-Sidebar() (ΝΕΟ, ξεχωριστό Form) αντί για απευθείας
    # χειρισμό του παλιού εσωτερικού Panel - διασφαλίζει συνέπεια με τον νέο μηχανισμό sidebar.
    if ($global:sidebarForm) {
        $global:sidebarSlideTimer.Stop()
        $global:sidebarOpen = $false
        $global:sidebarClosing = $false
        $global:sidebarForm.Visible = $false
    }
    # ΔΙΟΡΘΩΣΗ ΡΙΖΙΚΗ v2.2.0 (χρήστης ανέφερε επανειλημμένα - "όταν αλλάζω σε αριστερό/δεξί/οριζόντιο
    # μενού, το [πλευρικό] μενού μένει [ορατό]"): το $global:sidebarEmbedPanel (νέο, embedded child panel
    # - βλ. αναλυτικό σχόλιο στη δημιουργία του) ΔΕΝ κρυβόταν ΠΟΤΕ εδώ, μόνο το παλιό $global:sidebarForm
    # παραπάνω. Αφού το sidebarOpen ορίζεται $false λίγο πιο πάνω, το Update-SidebarDockLayout στο τέλος
    # αυτής της συνάρτησης καλούσε Update-SidebarFormPosition (όχι Show-Sidebar) - το οποίο αγγίζει ΜΟΝΟ
    # το sidebarForm, ΠΟΤΕ το embedded panel. Αποτέλεσμα: το embedded panel έμενε "κολλημένο" ορατό.
    if ($global:sidebarEmbedPanel) {
        if ($global:sidebarEmbedSlideTimer) { $global:sidebarEmbedSlideTimer.Stop() }
        $global:sidebarEmbedPanel.Visible = $false
    }
    if ($global:horizModernStrip) {
        $global:horizModernStrip.Visible = $false
        if ($lblTitle) { $lblTitle.Visible = $true }
    }
    # ΔΙΟΡΘΩΣΗ v2.1.0 (αίτημα χρήστη - "ΔΕΝ ΚΑΝΕΙΣ AUTOADJUSTMENT ΣΤΟ ΠΕΡΙΕΧΟΜΕΝΟ ΤΩΝ ΚΑΡΤΕΛΩΝ"): μέχρι
    # εδώ γινόταν μόνο απόκρυψη/επανατοποθέτηση του ίδιου του sidebar - το $content κάθε καρτέλας ΔΕΝ
    # ξαναϋπολογιζόταν ποτέ μετά την εκκίνηση, γι' αυτό έμενε με το παλιό Size/Location (απλό στατικό
    # περιθώριο) και επικαλυπτόταν όποτε το sidebar εμφανιζόταν σε νέα θέση/λειτουργία. Βλ.
    # Update-SidebarDockLayout (ορίζεται στο Add-CustomTabPage) για την πλήρη διόρθωση.
    Update-SidebarDockLayout
}

# ===== ΚΥΡΙΟ ΠΑΡΑΘΥΡΟ =====
$theme = Get-ThemeColors
$mainForm = [System.Windows.Forms.Form]::new()
$mainForm.AutoScaleMode = [System.Windows.Forms.AutoScaleMode]::Dpi
# ΔΙΟΡΘΩΣΗ v1.6.7: Ενοποιήθηκε με το κείμενο του lblTitle (πριν το τίτλο του παραθύρου έγραφε "...Pro"
# ενώ η ορατή ετικέτα στην οθόνη έγραφε "Windows 11 Maintenance & Optimizer Tool" - διαφορετικά ονόματα
# για την ίδια εφαρμογή). Παραμένει σταθερό στα Αγγλικά ανεξαρτήτως γλώσσας (βλ. lblTitle παρακάτω).
$mainForm.Text = "Windows 11 Maintenance & Optimizer Tool (v2.8.2)"
# ΔΙΟΡΘΩΣΗ v2.0.8 (αίτημα χρήστη): πλάτος αυξήθηκε 1150->1280 - με τόσες προσθήκες χαρακτηριστικών
# φέτος, αρκετές καρτέλες έχουν γίνει πιο πυκνές. ΠΑΡΑΜΕΝΕΙ FixedSingle/όχι resizable - αυτό δεν είναι
# προσπάθεια πλήρους resizable παραθύρου (βλ. ενότητα "Μεγιστοποίηση/Resize" στο HANDOFF.md για τους
# λόγους που αυτό εγκαταλείφθηκε σκόπιμα), απλά μεγαλύτερο σταθερό μέγεθος.
# ΣΗΜΕΙΩΣΗ: αρχικά δοκιμάστηκε ΚΑΙ μείωση ύψους (800->720, λογική αναλογίας 16:9) αλλά αναιρέθηκε κατόπιν
# ρητού αιτήματος χρήστη - η καρτέλα Αρχική (χωρίς δικό της nested scrollPanel, τα cards ζουν απευθείας
# στο $content) χρειάζεται το πλήρες, αρχικό ύψος (610 content) ώστε να ΜΗΝ χρειάζεται κύλιση - το
# cardHealthScore φτάνει μέχρι y=595, πολύ κοντά στο μειωμένο όριο των 530. Ύψος παραμένει 800.
$mainForm.Size = [System.Drawing.Size]::new(1280, 800)
# ΔΙΟΡΘΩΣΗ v2.1.0 (αίτημα χρήστη - στιγμιότυπο: το anchored sidebar ΕΠΙΚΑΛΥΠΤΕ τίτλο/καρτέλες/κάρτες
# αντί να τους ελευθερώνει χώρο): πραγματικός, ΔΕΣΜΕΥΜΕΝΟΣ χώρος για το πλευρικό μενού όταν είναι ενεργό.
# ΔΙΟΡΘΩΣΗ (ρητή διόρθωση χρήστη σε ΚΕΦΑΛΑΙΑ): η δέσμευση χώρου αφορά ΑΠΟΚΛΕΙΣΤΙΚΑ το $content (το σώμα
# κάθε καρτέλας, κάτω από τη λωρίδα καρτελών) - η γραμμή τίτλου (λογότυπο/τίτλος/search bar/γλώσσα/
# hamburger/theme) ΚΑΙ η ίδια η λωρίδα καρτελών (pills) παραμένουν ΕΝΤΕΛΩΣ ανεπηρέαστες. Το sidebar
# τοποθετείται ΚΑΤΩ από τη λωρίδα καρτελών (Y=118, βλ. Update-SidebarFormPosition/Show-Sidebar), ώστε να
# μην τις καλύπτει καθόλου ούτε κατακόρυφα.
$global:sidebarDockActive = ($global:appSettings.MenuMode -eq "Sidebar") -and $global:appSettings.SidebarEnabled
$global:sidebarDockWidth = if ($global:sidebarDockActive) { 110 } else { 0 }
$global:sidebarDockLeft = $global:sidebarDockActive -and ($global:appSettings.SidebarPosition -eq "Left")
$global:sidebarDockRight = $global:sidebarDockActive -and (-not $global:sidebarDockLeft)
# Χρησιμοποιείται ΜΟΝΟ από το $content (Add-CustomTabPage) - μετατοπίζεται δεξιά ώστε να αφήσει χώρο στο
# sidebar όταν αυτό είναι δεσμευμένο ΑΡΙΣΤΕΡΑ (σε δεξιά δέσμευση δεν χρειάζεται μετατόπιση X, μόνο
# μικρότερο πλάτος - βλ. $global:sidebarDockWidth).
$global:titleLeftOffset = if ($global:sidebarDockLeft) { $global:sidebarDockWidth } else { 0 }
$mainForm.StartPosition = "CenterScreen"
$mainForm.BackColor = $theme.MainBg
# ΝΕΟ v1.7.5: Εφαρμόζει το αποθηκευμένο επίπεδο διαφάνειας ήδη από την εκκίνηση (όχι μόνο μέσα στο
# παράθυρο Ρυθμίσεων) - το native Form.Opacity είναι αξιόπιστη, καθιερωμένη ιδιότητα WinForms.
$mainForm.Opacity = switch ($global:appSettings.TransparencyLevel) {
    "Light" { 0.97 }
    "Medium" { 0.94 }
    default { 1.0 }
}
$global:bgAnimPhase = 0.0

# ΔΙΟΡΘΩΣΗ v1.6.2: Αφαιρέθηκε το "αυτόματο ενεργό για Vista" default (κατόπιν ρητού αιτήματος) - το
# κινούμενο φόντο είναι πλέον ΠΑΝΤΑ απενεργοποιημένο εξ ορισμού για ΟΛΑ τα θέματα, αμιγώς επιλογή του
# χρήστη μέσω Ρυθμίσεις Εμφάνισης, ανεξαρτήτως ποιο θέμα είναι ενεργό.
function Test-ShouldAnimateBackground {
    if ($null -ne $global:appSettings.AnimatedBackground) { return $global:appSettings.AnimatedBackground }
    return $false
}

# ΔΙΟΡΘΩΣΗ v1.5.8: Το φόντο της ίδιας της φόρμας παραμένει σκόπιμα ΣΤΑΤΙΚΟ (Phase 0) - μόνο το
# εσωτερικό panel της ενεργής καρτέλας κινείται πλέον (βλ. Update-ActiveTabBackgroundTint).
$mainForm.BackgroundImage = New-ThemedBackgroundBitmap -Width 1280 -Height 800 -Style $theme.BgStyle -IsDark $global:isDarkMode -Phase 0
$mainForm.BackgroundImageLayout = "Stretch"
$mainForm.Opacity = 0.99

# ΔΙΟΡΘΩΣΗ v1.5.7: Το DoubleBuffered ΜΟΝΟ ΤΟΥ δεν αρκεί για να σταματήσει το flicker όταν αλλάζει το
# BackgroundImage ενός top-level Form - το background περνάει από ξεχωριστό painting pipeline
# (WM_ERASEBKGND) που ΔΕΝ καλύπτεται από την απλή ιδιότητα DoubleBuffered. Η πλήρης, τεκμηριωμένη λύση
# είναι ο συνδυασμός τριών ControlStyles μέσω της (επίσης protected) μεθόδου SetStyle: αναγκάζει ΟΛΟ το
# ζωγράφισμα -συμπεριλαμβανομένου του background erase- να περάσει από το buffered pipeline.
$setStyleMethod = [System.Windows.Forms.Control].GetMethod("SetStyle", [System.Reflection.BindingFlags]::Instance -bor [System.Reflection.BindingFlags]::NonPublic)
if ($setStyleMethod) {
    $flickerFixStyles = [System.Windows.Forms.ControlStyles]::OptimizedDoubleBuffer -bor [System.Windows.Forms.ControlStyles]::AllPaintingInWmPaint -bor [System.Windows.Forms.ControlStyles]::UserPaint
    $setStyleMethod.Invoke($mainForm, @($flickerFixStyles, $true)) | Out-Null
}
$dbProp = [System.Windows.Forms.Control].GetProperty("DoubleBuffered", [System.Reflection.BindingFlags]::Instance -bor [System.Reflection.BindingFlags]::NonPublic)
if ($dbProp) { $dbProp.SetValue($mainForm, $true, $null) }
$mainForm.FormBorderStyle = "FixedSingle"
$mainForm.MaximizeBox = $false
# ΔΙΟΡΘΩΣΗ v2.0.4 (χρήστης ανέφερε πολλαπλά, επίμονα προβλήματα με τη μεγιστοποίηση - κουμπιά κύλισης
# καρτελών που παραμένουν, περιεχόμενο που δεν αναδιατάσσεται, κινούμενο φόντο που εξαφανίζεται): μετά
# από 2 αποτυχημένες προσπάθειες πλήρους responsive resize σε αυτή την ήδη τεράστια WinForms εφαρμογή
# (12.000+ γραμμές, εκατοντάδες hardcoded-θέσης στοιχεία), η ΥΠΕΥΘΥΝΗ επιλογή είναι να επιστρέψει σε
# fixed-size παράθυρο - ασφαλής, δοκιμασμένη κατάσταση, μηδενικό ρίσκο νέων bugs. Πλήρες responsive
# redesign θα απαιτούσε είτε εκτεταμένη αναδόμηση σε container-based/κεντραρισμένο σύστημα, είτε πλήρη
# μετάβαση σε framework με εγγενές layout engine (WPF) - αμφότερα εκτός εφικτού πεδίου για ασφαλές,
# επαναλαμβανόμενο chat-based patching ενός ήδη ώριμου, λειτουργικού script.

# ΝΕΟ (v1.4.8): Timer κίνησης φόντου.
# ΔΙΟΡΘΩΣΗ v1.7.5: Interval μειώθηκε από 180ms (≈5.5fps) σε 50ms (≈20fps) - στα 5.5fps τα εφέ "Τροχιές"
# και "Σωματίδια" έδειχναν να εναλλάσσονται σε ξεχωριστά καρέ αντί για ομαλή κίνηση, ειδικά αισθητό σε
# σκοτεινά θέματα. Το βήμα φάσης μειώθηκε αναλογικά (4 -> 1.1) ώστε η ΣΥΝΟΛΙΚΗ ταχύτητα περιστροφής να
# παραμείνει ίδια (ένας πλήρης κύκλος εξακολουθεί να διαρκεί ~16 δευτερόλεπτα) - απλά με 3.6x περισσότερα,
# μικρότερα βήματα ανάμεσα, άρα αισθητά πιο ρευστή κίνηση. Τα Γρανάζια παραμένουν οπτικά "μηχανικά" χάρη
# στο ίδιο το σχήμα τους (διακριτά δόντια), όχι λόγω του ρυθμού καρέ - ωφελούνται εξίσου από την
# ομαλότερη κίνηση, χωρίς να χάνουν τον χαρακτήρα τους.
$global:bgAnimTimer = [System.Windows.Forms.Timer]::new()
$global:bgAnimTimer.Interval = 150
$global:isResizing = $false
$global:bgAnimTimer.Add_Tick({
    if ($mainForm.WindowState -eq [System.Windows.Forms.FormWindowState]::Minimized) { return }
    # ΔΙΟΡΘΩΣΗ v2.0.2 (χρήστης ανέφερε "η απόκριση είναι αργή/κολλάει", "οι μπάρες κύλισης έχουν χάσει
    # την ομαλότητά τους"): εντοπίστηκε ότι αυτό δημιουργούσε ΕΝΤΕΛΩΣ ΝΕΟ bitmap στο μέγεθος ολόκληρης
    # της ενεργής καρτέλας 20 φορές/δευτερόλεπτο (interval 50ms) - με το νέο maximize support, το tab
    # content μπορεί να είναι πολύ μεγαλύτερο, κάνοντας αυτό ακόμα πιο ακριβό. Interval αυξήθηκε σε 150ms
    # (ακόμα ομαλό οπτικά για ένα αργό ambient εφέ) και προστέθηκε παράκαμψη κατά τη διάρκεια ενεργού
    # αλλαγής μεγέθους του παραθύρου, ώστε να μην επιβαρύνεται η ίδια η αλλαγή μεγέθους.
    if ($global:isResizing) { return }
    if (-not (Test-ShouldAnimateBackground)) { $global:bgAnimTimer.Stop(); return }
    $global:bgAnimPhase = ($global:bgAnimPhase + 1.1) % 360
    # ΔΙΟΡΘΩΣΗ v1.5.8: Πριν ενημερώνονταν ΔΥΟ ξεχωριστά bitmaps ανά καρέ - το φόντο ΟΛΟΚΛΗΡΗΣ της φόρμας
    # ΚΑΙ ένα cropped+tinted αντίγραφό του για το εσωτερικό panel - τα δύο δεν ευθυγραμμίζονταν τέλεια
    # (διαφορετική διαφάνεια/θέση), δίνοντας την εντύπωση "δύο instances" κίνησης να συγκρούονται στα
    # όρια τους. Το εξωτερικό φόντο της φόρμας παραμένει πλέον ΣΤΑΤΙΚΟ (ορίζεται μία φορά, όχι εδώ) -
    # κινείται ΜΟΝΟ το εσωτερικό panel της ενεργής καρτέλας, το οποίο παράγει το ΔΙΚΟ ΤΟΥ bitmap στο
    # ακριβές μέγεθός του (όχι crop από αλλού) - ένα ενιαίο, συνεπές κινούμενο στοιχείο συνολικά.
    if ($global:customTabs -and $global:customTabs.Count -gt 0) { Update-ActiveTabBackgroundTint }
    # ΝΕΟ v2.4.0: επανασχεδίαση των glass-background panels (βλ. Set-PanelGlassBackground) σε κάθε καρέ,
    # ΜΟΝΟ όσα είναι πραγματικά ορατά αυτή τη στιγμή (το ανενεργό tab's panel είναι ήδη Visible=$false
    # στο δικό του $content - κανένα κόστος επιπλέον σε αόρατα panels, το WinForms τα παρακάμπτει).
    foreach ($gp in $global:glassBackgroundPanels) { if ($gp.Visible) { $gp.Invalidate() } }
})
if (Test-ShouldAnimateBackground) { $global:bgAnimTimer.Start() }


try {
    # ΔΙΟΡΘΩΣΗ: Το προηγούμενο εικονίδιο εξαγόταν από το shell32.dll (index 0) - ένα γενικό/σχεδόν
    # κενό εικονίδιο συστήματος, ασύνδετο με την ταυτότητα της εφαρμογής (γι' αυτό φαινόταν "κενό").
    # Αντικαταστάθηκε με δικό μας, σχεδιασμένο λογότυπο (κυκλικό badge με διπλό βέλος ταχύτητας) μέσω
    # GDI+, με την ίδια λογική vector σχεδίασης που ήδη χρησιμοποιείται στα εικονίδια των καρτελών.
    function New-AppLogoBitmap {
        param([int]$Size = 64)
        $bmp = [System.Drawing.Bitmap]::new($Size, $Size)
        $g = [System.Drawing.Graphics]::FromImage($bmp)
        $g.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
        $g.InterpolationMode = [System.Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
        $g.Clear([System.Drawing.Color]::Transparent)

        $rectF = [System.Drawing.RectangleF]::new($Size * 0.04, $Size * 0.04, $Size * 0.92, $Size * 0.92)
        $gradBrush = [System.Drawing.Drawing2D.LinearGradientBrush]::new($rectF, [System.Drawing.Color]::FromArgb(0, 122, 204), [System.Drawing.Color]::FromArgb(0, 190, 165), 45)
        $g.FillEllipse($gradBrush, $rectF)
        $gradBrush.Dispose()

        $penBorder = [System.Drawing.Pen]::new([System.Drawing.Color]::FromArgb(90, 255, 255, 255), [Math]::Max(1, $Size / 48))
        $g.DrawEllipse($penBorder, $rectF)
        $penBorder.Dispose()

        # ΔΙΟΡΘΩΣΗ v1.6.6: Το εικονίδιο της εφαρμογής έγινε τα ίδια τα γρανάζια (στατική απεικόνιση, ίδιο
        # σχέδιο με το ζωντανό "λογότυπο" δίπλα στον τίτλο) αντί για το προηγούμενο σύμβολο διπλού βέλους.
        $gr1 = $Size * 0.24; $gr2 = $Size * 0.16; $gr3 = $Size * 0.11
        $gcx1 = $Size * 0.40; $gcy1 = $Size * 0.58
        $gcx2 = $Size * 0.68; $gcy2 = $Size * 0.34
        $gcx3 = $Size * 0.80; $gcy3 = $Size * 0.62
        Draw-SimpleGear -Graphics $g -CenterX $gcx1 -CenterY $gcy1 -Radius $gr1 -Teeth 10 -RotationDeg 15 -Color ([System.Drawing.Color]::FromArgb(235, 255, 255, 255))
        Draw-SimpleGear -Graphics $g -CenterX $gcx2 -CenterY $gcy2 -Radius $gr2 -Teeth 8 -RotationDeg -10 -Color ([System.Drawing.Color]::FromArgb(245, 255, 255, 255))
        Draw-SimpleGear -Graphics $g -CenterX $gcx3 -CenterY $gcy3 -Radius $gr3 -Teeth 8 -RotationDeg 25 -Color ([System.Drawing.Color]::FromArgb(255, 255, 255, 255))
        $g.Dispose()
        return $bmp
    }

    $logoBmp = New-AppLogoBitmap -Size 64
    $hIcon = $logoBmp.GetHicon()
    $mainForm.Icon = [System.Drawing.Icon]::FromHandle($hIcon)
    # ΣΗΜΕΙΩΣΗ: Το Icon.FromHandle δεν "κατέχει" το native handle (μικρή, αναπόφευκτη διαρροή GDI
    # handle μέχρι το τέλος της εφαρμογής) - αποδεκτό εδώ αφού καλείται ΜΙΑ φορά σε όλη τη διάρκεια ζωής.
    $logoBmp.Dispose()
} catch {}

# ===== ΔΙΑΧΕΙΡΙΣΗ ΓΡΑΜΜΑΤΟΣΕΙΡΩΝ ΜΕ ΑΣΦΑΛΕΣ FALLBACK =====
# Ελέγχει ποιες γραμματοσειρές είναι πραγματικά εγκατεστημένες στο σύστημα και επιλέγει την καλύτερη
# διαθέσιμη επιλογή, ώστε η εφαρμογή να μην εμφανίζει ποτέ "σπασμένη" γραμματοσειρά (π.χ. σε παλιά
# Windows ή σε εικόνες συστήματος χωρίς την "Segoe UI Variable").
$global:installedFontFamilies = (New-Object System.Drawing.Text.InstalledFontCollection).Families.Name
function Get-SafeFont {
    param(
        [string]$PreferredFamily = "Segoe UI Variable Display",
        [single]$Size,
        [System.Drawing.FontStyle]$Style = [System.Drawing.FontStyle]::Regular
    )
    $family = if ($global:installedFontFamilies -contains $PreferredFamily) { $PreferredFamily }
              elseif ($global:installedFontFamilies -contains "Segoe UI") { "Segoe UI" }
              else { "Microsoft Sans Serif" }
    return New-Object System.Drawing.Font($family, $Size, $Style)
}

$fontTitle     = Get-SafeFont -PreferredFamily "Segoe UI Variable Display" -Size 17 -Style ([System.Drawing.FontStyle]::Bold)
$fontTabText   = Get-SafeFont -Size 10 -Style ([System.Drawing.FontStyle]::Bold)
$fontBtnCustom = Get-SafeFont -Size 9.75 -Style ([System.Drawing.FontStyle]::Bold)
$fontText      = Get-SafeFont -Size 10 -Style ([System.Drawing.FontStyle]::Regular)
$fontBoldText  = Get-SafeFont -Size 11 -Style ([System.Drawing.FontStyle]::Bold)
$fontStatus    = Get-SafeFont -Size 9.5 -Style ([System.Drawing.FontStyle]::Italic)
# ΝΕΟ v2.8.2 (αίτημα χρήστη - στιγμιότυπο: "η γραμμή κατάστασης είναι πολύ μικρή, να φέρεις σε ύψος που
# να εμφανίζονται ευκρινώς το κυκλικό εικονίδιο και η κατάσταση"): μεγαλύτερη, μη-πλάγια γραμματοσειρά
# αποκλειστικά για τη γραμμή κατάστασης - βλ. $statusBarStrip/$lblStatus παρακάτω.
$fontStatusBar = Get-SafeFont -Size 10.5 -Style ([System.Drawing.FontStyle]::Regular)
$fontDescSmall = Get-SafeFont -Size 8.75 -Style ([System.Drawing.FontStyle]::Regular)
# ΝΕΟ v2.2.5: αφιερωμένη, μικρότερη ΜΗ-πλάγια γραμματοσειρά για τις ετικέτες της κάθετης μπάρας
# εικονιδίων του θέματος "Microsoft PC Manager" (βλ. Add-PCManagerRailItem) - οι ελληνικές λέξεις εκεί
# είναι αισθητά μακρύτερες από τα αντίστοιχα αγγλικά (Optimization/Health/...), χρειάζονται μικρότερο
# μέγεθος γραμματοσειράς ΚΑΙ όχι πλάγια γραφή (η οποία είναι ελαφρώς πλατύτερη) για να χωράνε καθαρά.
$fontRailLabel = Get-SafeFont -Size 7.5 -Style ([System.Drawing.FontStyle]::Regular)

$global:allDefaultButtons = @()
$global:allTextLabels = @()
$global:allThemedButtons = @()
$global:allSubTextLabels = @()
$global:allCards = @()
$global:allIconBoxes = @()

# ===== MENU BAR (ΜΕΝΟΥ ΕΦΑΡΜΟΓΗΣ - ΘΕΜΑΤΑ & ΒΟΗΘΕΙΑ) =====
$mainMenu = [System.Windows.Forms.MainMenu]::new()
$menuThemes = [System.Windows.Forms.MenuItem]::new((T "MenuThemes"))
$global:themeMenuItems = @()
$themeNamesList = @("Windows Vista", "Office 2007 (Aurora)", "Windows XP Luna", "Cyberpunk", "Matrix", "Nordic Night", "Windows 7 Aero", "Windows 98 Retro", "macOS Monterey", "Solarized Dark", "GitHub Dark", "VS Code Dark+", "Terminal DOS Green", "Discord Blurple", "Steam Deck Dark", "RGB Gaming Rig", "Circuit Board PCB", "Synthwave Outrun", "Windows 11 Fluent", "Retro DOS Blue", "Microsoft PC Manager")

foreach ($tName in $themeNamesList) {
    $item = [System.Windows.Forms.MenuItem]::new($tName)
    if ($tName -eq $global:currentThemeName) { $item.Checked = $true }
    $item.Add_Click({
        param($sender,$e)
        $global:currentThemeName = $sender.Text
        foreach ($mi in $global:themeMenuItems) { $mi.Checked = ($mi.Text -eq $global:currentThemeName) }
        Update-UITheme
    })
    $global:themeMenuItems += $item
    $menuThemes.MenuItems.Add($item) | Out-Null
}
# ΔΙΟΡΘΩΣΗ v1.6.6: Το μενού "Θέματα" αφαιρέθηκε από την ορατή γραμμή κλασικού μενού (κατόπιν αιτήματος) -
# τα θέματα είναι πλέον πλήρως ενσωματωμένα στο παράθυρο Ρυθμίσεις Εμφάνισης. Το ίδιο το $menuThemes
# object (και τα $global:themeMenuItems μέσα του) διατηρούνται ΜΟΝΟ ως εσωτερική κατάσταση - άλλος
# κώδικας (π.χ. το Save του Show-AppearanceSettingsWindow) ενημερώνει το .Checked τους για συνέπεια,
# χωρίς να χρειάζεται να είναι ορατά πουθενά στο UI.
# $mainMenu.MenuItems.Add($menuThemes) | Out-Null

# ΔΙΟΡΘΩΣΗ v1.5.8: Το "Κινούμενο Φόντο" αφαιρέθηκε ως ξεχωριστό ορατό στοιχείο στη γραμμή μενού -
# υπάρχει πλέον ΜΟΝΟ ως checkbox μέσα στο παράθυρο Ρυθμίσεις > Εμφάνιση Μενού (βλ.
# Show-AppearanceSettingsWindow). Το ίδιο το MenuItem object διατηρείται (χωρίς να προστίθεται στη
# γραμμή μενού) μόνο επειδή άλλος κώδικας ήδη αναφέρεται στο $menuAnimatedBg.Checked για συγχρονισμό
# κατάστασης - λειτουργεί σαν εσωτερική μεταβλητή, όχι σαν ορατό στοιχείο UI.
$menuAnimatedBg = [System.Windows.Forms.MenuItem]::new((T "MenuAnimatedBg"))
$menuAnimatedBg.Checked = (Test-ShouldAnimateBackground)
$menuAnimatedBg.Add_Click({
    $global:appSettings.AnimatedBackground = -not $menuAnimatedBg.Checked
    $menuAnimatedBg.Checked = $global:appSettings.AnimatedBackground
    Save-AppSettings -Settings $global:appSettings
    if ($global:appSettings.AnimatedBackground) { $global:bgAnimTimer.Start(); Update-ActiveTabBackgroundTint } else { $global:bgAnimTimer.Stop(); Reset-TabBackgroundToFlat }
})

# ΝΕΟ v1.4.2: Μενού "Εργαλεία" - φιλοξενεί λειτουργίες που μετατράπηκαν από καρτέλα σε δευτερεύον
# παράθυρο κατά την πλήρη επανακατηγοριοποίηση της εφαρμογής (βλ. Ιστορικό Εκδόσεων).
$menuTools = [System.Windows.Forms.MenuItem]::new((T "MenuTools"))
$menuViveToolItem = [System.Windows.Forms.MenuItem]::new((T "MenuViveTool"))
$menuViveToolItem.Add_Click({ Show-ViveToolWindow })
$menuTools.MenuItems.Add($menuViveToolItem) | Out-Null
# ΝΕΟ v1.8.7 (κατόπιν αιτήματος εμπλουτισμού της γραμμής μενού): "Διαχείριση UWP Εφαρμογών" - ήδη
# υπάρχουσα λειτουργία (κουμπί στην καρτέλα Εφαρμογές & Bloat), τώρα προσβάσιμη και από το menu bar,
