$menuHelpItem = [System.Windows.Forms.MenuItem]::new((T "MenuHelpItem"))
$menuHelpItem.Add_Click({ Show-HelpWindow })
$menuHelp.MenuItems.Add($menuHelpItem) | Out-Null
$mainMenu.MenuItems.Add($menuHelp) | Out-Null

# ΔΙΟΡΘΩΣΗ v1.6.2: Το κλασικό μενού ξεκινά πλέον ΚΡΥΦΟ από προεπιλογή (αντί να ανατίθεται πάντα στο
# $mainForm.Menu εδώ) - παραμένει πλήρως λειτουργικό και διαθέσιμο ανά πάσα στιγμή μέσω Ctrl+M.
# $mainForm.Menu = $mainMenu

$lblTitle = [System.Windows.Forms.Label]::new()
# ΔΙΟΡΘΩΣΗ v1.6.7: Ο τίτλος της εφαρμογής (πάνω αριστερά ΚΑΙ στο πλαίσιο/τίτλο του παραθύρου) παραμένει
# ΠΑΝΤΑ στα Αγγλικά, ανεξαρτήτως επιλεγμένης γλώσσας (κατόπιν ρητού αιτήματος) - δεν χρησιμοποιεί πλέον
# το μεταφρασμένο T('AppTitle'), είναι σταθερό κείμενο.
$lblTitle.Text = "Windows 11 Maintenance & Optimizer Tool"
$lblTitle.Font = $fontTitle
$lblTitle.ForeColor = $theme.Text
$lblTitle.BackColor = [System.Drawing.Color]::Transparent
# ΔΙΟΡΘΩΣΗ (bug εντοπίστηκε - "η έκδοση δεν είναι ευθυγραμμισμένη με τον τίτλο"): ρητό BottomLeft (πριν
# ήταν το προεπιλεγμένο TopLeft) ώστε το $lblTitleVersion (δίπλα, βλ. παρακάτω) να μπορεί να
# ευθυγραμμιστεί στο ΙΔΙΟ κάτω άκρο και οι δύο ετικέτες να μοιράζονται συνεπή οπτική βάση.
$lblTitle.TextAlign = "BottomLeft"
# ΔΙΟΡΘΩΣΗ v1.6.2: Στα Γαλλικά ο τίτλος ("Outil de Maintenance et d'Optimisation Windows 11...") είναι
# αρκετά πιο μακρύς από τα Ελληνικά/Αγγλικά και αναδιπλωνόταν άσχημα - αυξήθηκε το πλάτος του πλαισίου
# (όχι η γραμματοσειρά) ώστε να χωράει σε μία γραμμή σε όλες τις γλώσσες.
$lblTitle.Size = [System.Drawing.Size]::new(845, 38)
# ΔΙΟΡΘΩΣΗ v1.9.4 (αίτημα χρήστη): ο τίτλος μετακινήθηκε δεξιά (X=25->70) για να αφήσει χώρο στο
# γρανάζι, το οποίο μετακινείται τώρα σε ΣΤΑΘΕΡΗ θέση τέρμα αριστερά (X=15), αντί να ακολουθεί το τέλος
# του τίτλου όπως πριν.
$lblTitle.Location = [System.Drawing.Point]::new(70, 18)
$mainForm.Controls.Add($lblTitle)
$global:allTextLabels += $lblTitle

# ΝΕΟ v2.0.2 (χρήστης ζήτησε να επανέλθει η έκδοση στον τίτλο, με μικρότερη γραμματοσειρά ώστε να μην
# επηρεαστούν τα περιθώρια): ξεχωριστό, δεύτερο label (WinForms δεν υποστηρίζει μικτές γραμματοσειρές
# μέσα στο ίδιο Label) - τοποθετείται δυναμικά αμέσως μετά το πραγματικό πλάτος του κειμένου του τίτλου.
$lblTitleVersion = [System.Windows.Forms.Label]::new()
$lblTitleVersion.Text = "v2.8.2"
# ΔΙΟΡΘΩΣΗ (αίτημα χρήστη): η γραμματοσειρά ήταν πολύ μικροσκοπική (0.5x) και το κενό από τον τίτλο
# αρκετά μεγάλο - μεγαλύτερη γραμματοσειρά (0.68x) και μικρότερο κενό (βλ. Update-TitleGearPosition).
$lblTitleVersion.Font = [System.Drawing.Font]::new($fontTitle.FontFamily, $fontTitle.Size * 0.68, [System.Drawing.FontStyle]::Bold)
$lblTitleVersion.ForeColor = $theme.SubText
$lblTitleVersion.BackColor = [System.Drawing.Color]::Transparent
# ΔΙΟΡΘΩΣΗ (bug εντοπίστηκε, ρητή αναφορά χρήστη με στιγμιότυπο - "η έκδοση δεν είναι ευθυγραμμισμένη με
# τον τίτλο"): το $lblTitle (ο κύριος τίτλος) ΔΕΝ έχει ρητό TextAlign - παίρνει το προεπιλεγμένο TopLeft
# του WinForms Label (το κείμενο ξεκινά από την ΚΟΡΥΦΗ του πλαισίου του, y=18). Το version label όμως
# χρησιμοποιούσε MiddleLeft (κατακόρυφα κεντραρισμένο στο ΔΙΚΟ ΤΟΥ, μικρότερο πλαίσιο) - δύο ΔΙΑΦΟΡΕΤΙΚΕΣ
# λογικές ευθυγράμμισης, που δεν συμπίπτουν οπτικά. Τώρα και τα δύο χρησιμοποιούν BottomLeft με το κάτω
# άκρο τους στο ίδιο σημείο (y=54, το ίδιο "βάθρο" - baseline-like ευθυγράμμιση, στυλ subscript/version tag).
$lblTitleVersion.TextAlign = "BottomLeft"
# Ίδιο κάτω άκρο (y=56) με το πλαίσιο του $lblTitle (y=18, ύψος=38 -> κάτω άκρο 56) παρακάτω.
$lblTitleVersion.Size = [System.Drawing.Size]::new(80, 34)
$lblTitleVersion.Location = [System.Drawing.Point]::new(400, 22)
$mainForm.Controls.Add($lblTitleVersion)
$global:allSubTextLabels += $lblTitleVersion

# ===== ΝΕΟ (v1.6.6): ΜΙΚΡΟ, ΠΑΝΤΑ-ΕΝΕΡΓΟ "ΛΟΓΟΤΥΠΟ" ΓΡΑΝΑΖΙΩΝ ΔΙΠΛΑ ΣΤΟΝ ΤΙΤΛΟ =====
# ΔΙΟΡΘΩΣΗ: Το εφέ γραναζιών μετακινήθηκε από επιλογή φόντου περιεχομένου (καρτέλες) σε μόνιμο, μικρό
# "λογότυπο" δίπλα στον τίτλο - μέγεθος προσαρμοσμένο στο ύψος της γραμματοσειράς του τίτλου (~38px),
# ΠΑΝΤΑ κινούμενο, ανεξάρτητα από τη ρύθμιση "Κινούμενο Φόντο" (που συνεχίζει να αφορά ΜΟΝΟ το
# περιεχόμενο κάτω από τις καρτέλες - "χώρισμα" ανάμεσα στις δύο ζώνες, όπως ζητήθηκε).
# ΔΙΟΡΘΩΣΗ v1.9.4 (αίτημα χρήστη - προετοιμασία για το Quick Find search bar): το γρανάζι μετακινήθηκε
# σε ΣΤΑΘΕΡΗ θέση τέρμα αριστερά (X=15), αντί να είναι σχεδόν πάνω στον τίτλο όπως πριν (X=30, ενώ ο
# τίτλος ξεκινούσε στο X=25). Νέα σειρά: γρανάζι -> τίτλος -> search bar -> κουμπιά γλώσσας/modes.
$global:titleGearBadge = [System.Windows.Forms.Panel]::new()
$global:titleGearBadge.Size = [System.Drawing.Size]::new(44, 40)
$global:titleGearBadge.Location = [System.Drawing.Point]::new(15, 18)
$global:titleGearBadge.BackColor = [System.Drawing.Color]::Transparent
if ($setStyleMethod) { $setStyleMethod.Invoke($global:titleGearBadge, @($flickerFixStyles, $true)) | Out-Null }
$global:titleGearPhase = 0.0
$global:titleGearBadge.Add_Paint({
    param($s, $e)
    $currTheme = Get-ThemeColors
    $g = $e.Graphics
    $g.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
    # ΔΙΟΡΘΩΣΗ v1.7.2: Τα δόντια κάθε γραναζιού επεκτείνονται ΠΕΡΑ από την ακτίνα του κύκλου (~1.22x, βλ.
    # Draw-SimpleGear) - οι προηγούμενες τιμές δεν άφηναν αρκετό περιθώριο μέσα στο panel (40x38), οπότε
    # τα δόντια των μεγαλύτερων γραναζιών έκοβαν στις άκρες. Μικρότερες ακτίνες + επαναϋπολογισμένα
    # κέντρα + μεγαλύτερο panel (44x40) αφήνουν πλέον άνετο περιθώριο σε όλες τις πλευρές.
    $r1 = 12; $r2 = 8; $r3 = 6
    $cx1 = 16; $cy1 = 21
    $cx2 = 26; $cy2 = 12
    $cx3 = 32; $cy3 = 24
    $rot1 = $global:titleGearPhase
    $rot2 = -$global:titleGearPhase * ($r1 / $r2)
    $rot3 = $global:titleGearPhase * ($r1 / $r3)
    Draw-SimpleGear -Graphics $g -CenterX $cx1 -CenterY $cy1 -Radius $r1 -Teeth 10 -RotationDeg $rot1 -Color ([System.Drawing.Color]::FromArgb(190, $currTheme.Accent))
    Draw-SimpleGear -Graphics $g -CenterX $cx2 -CenterY $cy2 -Radius $r2 -Teeth 8 -RotationDeg $rot2 -Color ([System.Drawing.Color]::FromArgb(215, $currTheme.Accent))
    Draw-SimpleGear -Graphics $g -CenterX $cx3 -CenterY $cy3 -Radius $r3 -Teeth 8 -RotationDeg $rot3 -Color ([System.Drawing.Color]::FromArgb(235, $currTheme.Accent))
})
$mainForm.Controls.Add($global:titleGearBadge)
$global:titleGearBadge.BringToFront()

# ===== ΝΕΟ (v1.9.4): QUICK FIND - ΚΑΘΟΛΙΚΗ ΑΝΑΖΗΤΗΣΗ =====
# Search box δίπλα στον τίτλο, ίδιο ύψος με τα κουμπιά γλώσσας/modes (36px). Live φιλτράρισμα σε
# προκαθορισμένο ευρετήριο (index) των πιο σημαντικών ρυθμίσεων/κουμπιών της εφαρμογής - επιλέγοντας ένα
# αποτέλεσμα μεταβαίνει αυτόματα στη σωστή καρτέλα. Σκόπιμα ΔΕΝ εκτελεί αυτόματα την ενέργεια (μόνο
# πλοήγηση) - πιο ασφαλές από το να "μαντεύει" ποιο UI στοιχείο να ενεργοποιήσει αυτόματα.
$global:txtQuickFind = [System.Windows.Forms.TextBox]::new()
$global:txtQuickFind.Size = [System.Drawing.Size]::new(190, 36)
$global:txtQuickFind.Font = $fontText
$global:txtQuickFind.BackColor = $theme.CardBg
$global:txtQuickFind.ForeColor = $theme.Text
# ΔΙΟΡΘΩΣΗ (bug εντοπίστηκε, ρητή αναφορά χρήστη - "το searchbar θέλει στοίχιση"): ένα single-line
# TextBox στο WinForms ΑΓΝΟΕΙ ρητά ορισμένο .Height πέρα από το φυσικό ύψος μίας γραμμής στο τρέχον font
# (~20-23px, όχι τα 36px που ζητήθηκαν) - η ίδια η ορατή θέση εμφανίζεται ΠΑΝΤΑ στην κορυφή του
# πλαισίου 36px, ασυνεπής με τα γειτονικά κουμπιά γλώσσας/hamburger/theme (που ΓΕΜΙΖΟΥΝ πραγματικά τα
# δικά τους 36px). Υπολογίζεται εδώ το πραγματικό PreferredHeight και κεντράρεται κατακόρυφα μέσα στην
# ΙΔΙΑ ζώνη Y=18-54 με τα κουμπιά, αντί να τοποθετείται στην κορυφή της.
$quickFindY = 18 + [int]((36 - $global:txtQuickFind.PreferredHeight) / 2)
$global:txtQuickFind.Location = [System.Drawing.Point]::new(500, $quickFindY)
$mainForm.Controls.Add($global:txtQuickFind)
$global:txtQuickFind.BringToFront()

$global:quickFindResultsList = [System.Windows.Forms.ListBox]::new()
$global:quickFindResultsList.Size = [System.Drawing.Size]::new(190, 160)
$global:quickFindResultsList.Location = [System.Drawing.Point]::new(500, 56)
$global:quickFindResultsList.Font = $fontText
$global:quickFindResultsList.BackColor = $theme.CardBg
$global:quickFindResultsList.ForeColor = $theme.Text
$global:quickFindResultsList.Visible = $false
$mainForm.Controls.Add($global:quickFindResultsList)
$global:quickFindResultsList.BringToFront()

# Ευρετήριο: {Text, TabIndex} - κατόπιν σαφών, μη-ασαφών ονομάτων ρυθμίσεων ώστε η αναζήτηση να είναι
# αξιόπιστη. Καλύπτει τα πιο "θαμμένα"/λιγότερο προφανή σημεία της εφαρμογής.
$global:quickFindIndex = @(
    [PSCustomObject]@{ Text = "Αρχική / Παρακολούθηση Απόδοσης Συστήματος"; TabIndex = 0 }
    [PSCustomObject]@{ Text = "Winget / Microsoft Store Ενημερώσεις"; TabIndex = 1 }
    [PSCustomObject]@{ Text = "Ενημερώσεις Οδηγών (Drivers)"; TabIndex = 1 }
    [PSCustomObject]@{ Text = "Office / Gaming Mode"; TabIndex = 1 }
    [PSCustomObject]@{ Text = "Health & Διαγνωστικά Συστήματος"; TabIndex = 2 }
    [PSCustomObject]@{ Text = "SFC / DISM Επιδιόρθωση"; TabIndex = 2 }
    [PSCustomObject]@{ Text = "Δίκτυο & Ασφάλεια"; TabIndex = 3 }
    [PSCustomObject]@{ Text = "Διαχείριση Firewall"; TabIndex = 3 }
    [PSCustomObject]@{ Text = "DNS Ρυθμίσεις"; TabIndex = 3 }
    [PSCustomObject]@{ Text = "Επιπλέον Ρυθμίσεις / Tweaks"; TabIndex = 4 }
    [PSCustomObject]@{ Text = "AI & Copilot Ρυθμίσεις"; TabIndex = 4 }
    [PSCustomObject]@{ Text = "Απόδοση (HAGS/Battery/USB/PCIe)"; TabIndex = 4 }
    [PSCustomObject]@{ Text = "Κρυπτογράφηση Συσκευής"; TabIndex = 4 }
    [PSCustomObject]@{ Text = "Εφαρμογές & Bloatware"; TabIndex = 5 }
    [PSCustomObject]@{ Text = "Βαθιά Απεγκατάσταση Εφαρμογών"; TabIndex = 5 }
    [PSCustomObject]@{ Text = "Διαχείριση UWP Εφαρμογών"; TabIndex = 5 }
    [PSCustomObject]@{ Text = "Προηγμένα Εργαλεία / Advanced Tools"; TabIndex = 6 }
    [PSCustomObject]@{ Text = "Εργαλειοθήκη (Toolbox)"; TabIndex = 6 }
    [PSCustomObject]@{ Text = "Σύστημα (Εκκίνηση/Διεργασίες/Αποθηκευτικός Χώρος)"; TabIndex = 7 }
    [PSCustomObject]@{ Text = "Εφαρμογές Εκκίνησης Συστήματος"; TabIndex = 7 }
    [PSCustomObject]@{ Text = "Διεργασίες Συστήματος"; TabIndex = 7 }
    [PSCustomObject]@{ Text = "Εύρεση Διπλότυπων/Μεγάλων Αρχείων"; TabIndex = 7 }
    [PSCustomObject]@{ Text = "OneDrive Ελευθέρωση Χώρου"; TabIndex = 7 }
    [PSCustomObject]@{ Text = "Σημεία Επαναφοράς Συστήματος"; TabIndex = 7 }
)

function Update-QuickFindResults {
    $term = $global:txtQuickFind.Text.Trim()
    if (-not $term) {
        $global:quickFindResultsList.Visible = $false
        return
    }
    $qfMatches = @($global:quickFindIndex | Where-Object { $_.Text -like "*$term*" } | Select-Object -First 10)
    $global:quickFindResultsList.Items.Clear()
    foreach ($m in $qfMatches) { [void]$global:quickFindResultsList.Items.Add($m.Text) }
    $global:quickFindResultsList.Visible = ($qfMatches.Count -gt 0)
}
$global:txtQuickFind.Add_TextChanged({ Update-QuickFindResults })
$global:quickFindResultsList.Add_Click({
    if ($global:quickFindResultsList.SelectedIndex -lt 0) { return }
    $selectedText = $global:quickFindResultsList.SelectedItem
    $match = $global:quickFindIndex | Where-Object { $_.Text -eq $selectedText } | Select-Object -First 1
    if ($match) {
        Select-CustomTab -Index $match.TabIndex
        $global:quickFindResultsList.Visible = $false
        $global:txtQuickFind.Text = ""
    }
})

# Το badge τοποθετείται δυναμικά ΑΚΡΙΒΩΣ μετά το πραγματικό (όχι το πλαίσιο) πλάτος του κειμένου του
# τίτλου - διαφέρει ανά γλώσσα, οπότε υπολογίζεται ξανά κάθε φορά που αλλάζει η γλώσσα.
# ΔΙΟΡΘΩΣΗ v1.9.4: Η function τοποθετεί πλέον το Quick Find search bar (όχι το γρανάζι, το οποίο έγινε
# σταθερής θέσης) - το όνομα διατηρήθηκε ίδιο ώστε να μη χρειαστεί αλλαγή στα σημεία που την καλούν.
function Update-TitleGearPosition {
    $measureBmp = [System.Drawing.Bitmap]::new(1, 1)
    $measureG = [System.Drawing.Graphics]::FromImage($measureBmp)
    $textSize = $measureG.MeasureString($lblTitle.Text, $lblTitle.Font)
    $versionSize = $measureG.MeasureString($lblTitleVersion.Text, $lblTitleVersion.Font)
    $measureG.Dispose(); $measureBmp.Dispose()
    # ΔΙΟΡΘΩΣΗ v2.0.2 (χρήστης ζήτησε να επανέλθει η έκδοση στον τίτλο): το version label τοποθετείται
    # δυναμικά αμέσως μετά το πραγματικό πλάτος του κειμένου του τίτλου, και το search bar υπολογίζει τη
    # θέση του βάσει του ΣΥΝΔΥΑΣΜΕΝΟΥ πλάτους (τίτλος + version + κενά) - όχι μόνο του τίτλου.
    # ΔΙΟΡΘΩΣΗ (αίτημα χρήστη - "η έκδοση είναι μακριά από τον τίτλο"): το κενό μειώθηκε (8->4).
    $versionX = $lblTitle.Left + [int]$textSize.Width + 4
    $lblTitleVersion.Location = [System.Drawing.Point]::new($versionX, 22)
    # ΔΙΟΡΘΩΣΗ v1.9.4: Ασφαλές ανώτατο όριο θέσης - σε πολύ μακρύ τίτλο (π.χ. Γαλλικά) το search bar δεν
    # πρέπει ΠΟΤΕ να φτάσει/επικαλύψει τα κουμπιά γλώσσας/hamburger/θέματος (ξεκινούν στο x=881). Το
    # search bar έχει πλάτος 220px, άρα το μέγιστο X του είναι 881-220-15=646.
    # ΔΙΟΡΘΩΣΗ v2.0.2 (χρήστης ζήτησε: "το search bar να είναι στο ίδιο ύψος και σε διπλανή ακριβώς θέση
    # στο κουμπί της γλώσσας"): πριν, η θέση υπολογιζόταν δυναμικά βάσει του πλάτους τίτλου+έκδοσης,
    # αφήνοντας συχνά ένα ορατό κενό πριν το btnLanguage αν ο τίτλος ήταν σύντομος. Τώρα το search bar
    # τοποθετείται ΠΑΝΤΑ ακριβώς πριν το btnLanguage (σταθερή θέση, ίδιο Y=18 με τα κουμπιά).
    # ΔΙΟΡΘΩΣΗ v2.0.8: το btnLanguage μετατοπίστηκε στο νέο πλάτος mainForm (881->1011, +130, βλ. σχόλιο
    # στο mainForm.Size) - το όριο εδώ ενημερώθηκε ανάλογα.
    $maxX = 1011 - 15 - 190
    # ΔΙΟΡΘΩΣΗ (bug εντοπίστηκε): ίδιο κατακόρυφο κεντράρισμα με το αρχικό Location παραπάνω (PreferredHeight),
    # όχι σταθερό Y=18 - βλ. αναλυτικό σχόλιο στην αρχική δημιουργία του $global:txtQuickFind.
    $quickFindY = 18 + [int]((36 - $global:txtQuickFind.PreferredHeight) / 2)
    $global:txtQuickFind.Location = [System.Drawing.Point]::new($maxX, $quickFindY)
    $global:quickFindResultsList.Location = [System.Drawing.Point]::new($maxX, 55)
}
Update-TitleGearPosition

# Ξεχωριστό, ελαφρύ Timer - ΠΑΝΤΑ ενεργό όσο τρέχει η εφαρμογή (δεν σταματά ποτέ, σε αντίθεση με το
# $global:bgAnimTimer του περιεχομένου που ο χρήστης μπορεί να απενεργοποιήσει).
$global:titleGearTimer = [System.Windows.Forms.Timer]::new()
$global:titleGearTimer.Interval = 180
$global:titleGearTimer.Add_Tick({
    if ($mainForm.WindowState -eq [System.Windows.Forms.FormWindowState]::Minimized) { return }
    $global:titleGearPhase = ($global:titleGearPhase + 5) % 360
    $global:titleGearBadge.Invalidate()
})
$global:titleGearTimer.Start()

$btnThemeToggle = [System.Windows.Forms.Button]::new()
# ΔΙΟΡΘΩΣΗ v1.7.7: Αφαιρέθηκαν τα πρόχειρα emoji ☀/☾ (μη σταθερή απόδοση ανά γραμματοσειρά/σύστημα) -
# αντικαταστάθηκαν με πραγματικά εικονίδια μέσω Button.Image (Segoe Fluent Icons "Brightness"/
# "QuietHours" glyphs), καλύτερης και σταθερής ποιότητας.
$btnThemeToggle.Text = "Light Mode"
$btnThemeToggle.Image = Get-AppIcon -Type "Sun" -Color $theme.Text
$btnThemeToggle.ImageAlign = [System.Drawing.ContentAlignment]::MiddleLeft
$btnThemeToggle.TextAlign = [System.Drawing.ContentAlignment]::MiddleCenter
$btnThemeToggle.TextImageRelation = [System.Windows.Forms.TextImageRelation]::ImageBeforeText
$btnThemeToggle.Padding = [System.Windows.Forms.Padding]::new(6, 0, 0, 0)
$btnThemeToggle.Font = $fontBtnCustom
# ΔΙΟΡΘΩΣΗ v1.8.0: Πλάτος μικρύνθηκε ελαφρώς (150->132) - το εικονίδιο/κείμενο παραμένουν αναλλοίωτα,
# μειώνεται μόνο ο περιττός περιμετρικός χώρος. Το ύψος ΠΑΡΕΜΕΙΝΕ 36px (ίδιο με τα γειτονικά κουμπιά
# hamburger/γλώσσας) για να μη χαλάσει η ήδη υπάρχουσα κατακόρυφη ευθυγράμμιση μεταξύ τους.
$btnThemeToggle.Size = [System.Drawing.Size]::new(132, 36)
# ΔΙΟΡΘΩΣΗ v2.0.8: μετατοπίστηκε στο νέο πλάτος mainForm (+130).
$btnThemeToggle.Location = [System.Drawing.Point]::new(1095, 18)
# ΣΗΜΕΙΩΣΗ: ΔΕΝ γίνεται Right-anchored σκόπιμα - το search bar υπολογίζει δυναμικά τη θέση του βάσει
# του ΣΤΑΘΕΡΟΥ X=881 του btnLanguage (βλ. Update-TitleGearPosition). Right-anchor εδώ θα μετακινούσε το
# κουμπί σε μεγιστοποίηση, χαλώντας αυτόν τον υπολογισμό - ασφαλέστερο να παραμείνουν σταθερά.
