$global:languageContextMenu = [System.Windows.Forms.ContextMenuStrip]::new()
# ΔΙΟΡΘΩΣΗ v2.2.0 (αίτημα χρήστη - στιγμιότυπο: "dropdown menus όπως το σύγχρονο μενού δεν βλέπω"): το
# ContextMenuStrip χρησιμοποιούσε το προεπιλεγμένο, ΑΘΕΜΑΤΙΚΟ (λευκό, στυλ παλιού Windows) rendering -
# δεν υπήρχε ΚΑΘΟΛΟΥ σύνδεση με το ενεργό θέμα της εφαρμογής. ProfessionalRenderer + ρητό BackColor/
# ForeColor δίνουν ένα πιο "σύγχρονο", σκουρόχρωμο/ανοιχτόχρωμο αποτέλεσμα ανάλογα με το θέμα (ΔΕΝ είναι
# 100% ίδιο custom-drawn στυλ με τις υπόλοιπες κάρτες της εφαρμογής - το WinForms ContextMenuStrip δεν
# υποστηρίζει πλήρη custom draw χωρίς C#/Add-Type subclass - αλλά ήδη πολύ πιο κοντά στο "σύγχρονο" ύφος
# από το προηγούμενο, εντελώς αθέματο μενού). Ανανεώνεται ΚΑΙ στο Update-UITheme (ζωντανή αλλαγή θέματος).
$global:languageContextMenu.Renderer = [System.Windows.Forms.ToolStripProfessionalRenderer]::new()
$global:languageContextMenu.ShowImageMargin = $false
$global:languageContextMenu.BackColor = $theme.CardBg
$global:languageContextMenu.ForeColor = $theme.Text
foreach ($langCode in @("el", "en", "de", "fr")) {
    $langLabel = "$($global:languageFlags[$langCode])  $($global:languageNames[$langCode])"
    $langItem = $global:languageContextMenu.Items.Add($langLabel)
    # ΔΙΟΡΘΩΣΗ v2.2.0 (αίτημα χρήστη - στιγμιότυπο: "σημαίες στις γλώσσες δεν έβαλες"): οι σημαίες
    # ΥΠΗΡΧΑΝ ήδη στο κείμενο (βλ. $global:languageFlags) αλλά η προεπιλεγμένη γραμματοσειρά μενού (Segoe
    # UI) δεν αποδίδει αξιόπιστα emoji σημαιών (regional indicator ζεύγη) - το ρητό Segoe UI Emoji (ΙΔΙΟ
    # με τη γραμματοσειρά του ίδιου του κουμπιού υδρόγειου) είναι η γραμματοσειρά που πράγματι υποστηρίζει
    # την απόδοσή τους στα Windows.
    $langItem.Font = [System.Drawing.Font]::new("Segoe UI Emoji", 10)
    $langItem.BackColor = $theme.CardBg
    $langItem.ForeColor = $theme.Text
    $langItem.Tag = $langCode
    $langItem.Add_Click({
        param($sender, $e)
        Set-AppLanguage -LangCode $sender.Tag
        # ΔΙΟΡΘΩΣΗ v1.6.2: Η γρήγορη επιλογή γλώσσας (κουμπί υδρόγειος) εφάρμοζε μόνο ζωντανά τα στοιχεία
        # "σκελετού" (μενού/τίτλοι) χωρίς να ενημερώνει τα εκατοντάδες tooltips/περιγραφές μέσα στις
        # καρτέλες (αυτά δημιουργήθηκαν μία φορά στην εκκίνηση με την τότε τρέχουσα γλώσσα). Τώρα ζητά
        # επανεκκίνηση, ίδια λογική με την επιλογή γλώσσας μέσα από τις Ρυθμίσεις Εμφάνισης.
        Request-AppRestart
    })
}
$btnLanguage.Add_Click({ $global:languageContextMenu.Show($btnLanguage, [System.Drawing.Point]::new(0, $btnLanguage.Height)) })

function Set-AppLanguage {
    param([string]$LangCode)
    if ($LangCode -eq $global:appSettings.Language) { return }
    $global:appSettings.Language = $LangCode
    Save-AppSettings -Settings $global:appSettings

    # ΝΕΟ v1.4.9: Ακαριαία εφαρμογή (χωρίς επανεκκίνηση) στα στοιχεία "σκελετού" που καλύπτονται -
    # μενού, τίτλος παραθύρου, τίτλοι καρτελών, πλευρικό/οριζόντιο μοντέρνο μενού.
    $mainForm.Text = "Windows 11 Maintenance & Optimizer Tool (v2.8.2)"
    $lblTitle.Text = "Windows 11 Maintenance & Optimizer Tool"
    Update-TitleGearPosition
    $menuThemes.Text = T "MenuThemes"
    $menuAnimatedBg.Text = T "MenuAnimatedBg"
    $menuTools.Text = T "MenuTools"
    $menuViveToolItem.Text = T "MenuViveTool"
    $menuUwpManagerItem.Text = T "MenuUwpManager"
    $menuView.Text = T "MenuView"
    $menuHelp.Text = T "MenuHelp"
    $menuVersionHistoryItem.Text = T "MenuVersionHistory"
    $menuHelpItem.Text = T "MenuHelpItem"
    $menuSettings.Text = T "MenuSettings"
    $menuAppearanceItem.Text = T "MenuAppearance"

    $tabKeys = @("TabOptimization", "TabHealth", "TabNetwork", "TabTweaks", "TabBloatware", "TabAdvanced", "TabSystem")
    for ($vti = 0; $vti -lt $global:menuViewTabItems.Count -and $vti -lt $tabKeys.Count; $vti++) {
        $global:menuViewTabItems[$vti].Text = T $tabKeys[$vti]
    }

    $tabKeys = @("TabOptimization", "TabHealth", "TabNetwork", "TabTweaks", "TabBloatware", "TabAdvanced", "TabSystem")
    for ($i = 0; $i -lt $global:customTabs.Count -and $i -lt $tabKeys.Count; $i++) {
        $global:customTabs[$i].Pill.Tag.Text = T $tabKeys[$i]
        $global:customTabs[$i].Pill.Invalidate()
    }
    Rebuild-TabStripLayout

    if ($global:sidebarForm -and $global:sidebarForm.Controls.Count -ge 5) {
        # ΔΙΟΡΘΩΣΗ v2.0.2: προστέθηκε "Ιστορικό Ενεργειών" - 5 στοιχεία αντί για 4 (parity με το
        # οριζόντιο μενού, που ο χρήστης εντόπισε ότι είχε μείνει πίσω).
        # ΔΙΟΡΘΩΣΗ (bug εντοπίστηκε - "2 ερωτηματικά στη Βοήθεια"): "MenuActionLog" έχει emoji ενσωματωμένο
        # (φτιαγμένο για το κλασικό μενού) - χρήση του καθαρού "SidebarActionLog" αντ' αυτού, αλλιώς η
        # αλλαγή γλώσσας θα επανέφερε το διπλό εικονίδιο που μόλις διορθώθηκε στην αρχική δημιουργία.
        $sbKeys = @("SidebarHelp", "SidebarHistory", "SidebarActionLog", "SidebarTools", "SidebarSettings")
        for ($i = 0; $i -lt 5; $i++) {
            $lbl = $global:sidebarForm.Controls[$i].Controls | Where-Object { $_ -is [System.Windows.Forms.Label] } | Select-Object -First 1
            if ($lbl) { $lbl.Text = T $sbKeys[$i] }
        }
    }
    if ($global:horizModernStrip -and $global:horizModernStrip.Controls.Count -ge 5) {
        # ΔΙΟΡΘΩΣΗ v2.0.2 (χρήστης εντόπισε "παραπάνω εικονίδια αχρείαστα που δεν εμφανίζονται σωστά"):
        # το array είχε μείνει με 4 keys ενώ το strip έχει πλέον 5 items (προστέθηκε "Document"/Ιστορικό
        # Ενεργειών σε προηγούμενο πέρασμα) - το 3ο στοιχείο έπαιρνε λάθος κείμενο ("Εργαλειοθήκη" αντί
        # για το δικό του σωστό) και το 5ο δεν ενημερωνόταν καθόλου μετά από αλλαγή γλώσσας.
        # ΔΙΟΡΘΩΣΗ (ίδιο bug με το $sbKeys παραπάνω, ΚΑΙ bug πλάτους λωρίδας - βλ. σχόλιο στο σημείο
        # αρχικής δημιουργίας): "MenuHelpClean" (κοντό "Βοήθεια"), όχι το μεγαλύτερο "SidebarHelp".
        $hmKeys = @("MenuHelpClean", "SidebarHistory", "SidebarActionLog", "SidebarTools", "SidebarSettings")
        for ($i = 0; $i -lt 5; $i++) {
            $lbl = $global:horizModernStrip.Controls[$i].Controls | Where-Object { $_ -is [System.Windows.Forms.Label] } | Select-Object -First 1
            if ($lbl) { $lbl.Text = T $hmKeys[$i] }
        }
    }
}

# =========================================================================
# ΝΕΟ ΣΥΣΤΗΜΑ ΚΑΡΤΕΛΩΝ (custom, στυλ εφαρμογής Claude) - ΑΝΤΙΚΑΤΕΣΤΗΣΕ ΤΟ ΕΓΓΕΝΕΣ TabControl
# =========================================================================
# ΔΙΟΡΘΩΣΗ: Το εγγενές System.Windows.Forms.TabControl είχε δύο επίμονα προβλήματα που δεν λύνονταν
# αξιόπιστα μέσω owner-draw: (α) ένα λευκό/άσχημο περίγραμμα το οποίο ζωγραφίζουν πάντα εσωτερικά τα
# Windows γύρω από τον έλεγχο ανεξαρτήτως owner-draw, και (β) σταθερό πλάτος καρτέλας (ItemSize) που
# έκοβε τους μεγαλύτερους ελληνικούς τίτλους ("Advanced Tools", "Εφαρμογές & Bloat"). Αντί να συνεχίσουμε
# να παλεύουμε με τους περιορισμούς ενός εγγενούς control, φτιάχτηκε ένα πλήρως custom tab-strip από απλά
# Panels (επίπεδα "pills" - ίδια λογική με τις καρτέλες της εφαρμογής Claude: επιλεγμένη = συμπαγές
# φόντο, ανενεργή = διάφανο φόντο, χωρίς κανένα περίγραμμα/κάδρο). Έχουμε 100% έλεγχο του σχεδίου, οπότε
# ΔΕΝ υπάρχει πλέον κανένα λευκό πλαίσιο, και κάθε "pill" παίρνει το πλάτος που πραγματικά χρειάζεται
# για τον τίτλο του (μέσω MeasureString) - άρα το κείμενο ΔΕΝ κόβεται ποτέ.
#
# ═══════════════════════════════════════════════════════════════════════════════════════════
# ΜΟΝΙΜΟΣ ΚΑΝΟΝΑΣ ΣΧΕΔΙΑΣΗΣ (ισχύει για κάθε μελλοντική προσθήκη/αναδιοργάνωση καρτελών):
# Οι καρτέλες παραμένουν ΠΑΝΤΑ σε ΜΙΑ γραμμή. Αν στο μέλλον προστεθούν άλλες καρτέλες και δεν χωράνε
# όλες στο πλάτος της λωρίδας, ΔΕΝ τυλίγονται σε 2η γραμμή (WrapContents) - κυλάνε οριζόντια μέσω των
# δύο κουμπιών ‹ › (ή με τη ροδέλα του ποντικιού) στα άκρα της λωρίδας. Αυτή η απόφαση οριστικοποιήθηκε
# μετά από ρητό αίτημα του χρήστη - να μην αλλάξει ξανά σε FlowLayoutPanel/WrapContents.
# ═══════════════════════════════════════════════════════════════════════════════════════════
$global:customTabs = @()
$global:activeTabIndex = -1
$global:tabStripScrollX = 0

