    function Update-TransparencyLive {
        if ($radioTransLight.Checked) { $mainForm.Opacity = 0.97 }
        elseif ($radioTransMedium.Checked) { $mainForm.Opacity = 0.94 }
        else { $mainForm.Opacity = 1.0 }
    }
    $radioTransNone.Add_CheckedChanged({ if ($radioTransNone.Checked) { Update-TransparencyLive } })
    $radioTransLight.Add_CheckedChanged({ if ($radioTransLight.Checked) { Update-TransparencyLive } })
    $radioTransMedium.Add_CheckedChanged({ if ($radioTransMedium.Checked) { Update-TransparencyLive } })

