    function Update-ThemePreviewSwatch {
        param($ThemeName)
        $oldName = $global:currentThemeName
        $global:currentThemeName = $ThemeName
        $previewTheme = Get-ThemeColors
        $global:currentThemeName = $oldName
        $oldImg = $picThemePreview.Image
        if ($chkAnimBg -and $chkAnimBg.Checked) {
            $styleOverride = if ($radioAnimGears.Checked) { "Gears" } elseif ($radioAnimOrbit.Checked) { "Orbit" } elseif ($radioAnimParticles.Checked) { "Particles" } elseif ($radioAnimWaves.Checked) { "Waves" } elseif ($radioAnimGridPulse.Checked) { "GridPulse" } else { "Theme" }
            $picThemePreview.Image = Get-AnimatedBackgroundBitmap -Width 420 -Height 70 -Theme $previewTheme -Phase $global:bgAnimPhase -StyleOverride $styleOverride
        } else {
            $picThemePreview.Image = New-ThemedBackgroundBitmap -Width 420 -Height 70 -Style $previewTheme.BgStyle -IsDark $global:isDarkMode
        }
        if ($oldImg) { $oldImg.Dispose() }
    }
    Update-ThemePreviewSwatch -ThemeName $global:currentThemeName

    $comboTheme.Add_SelectedIndexChanged({
        if (-not $comboTheme.SelectedItem) { return }
        Update-ThemePreviewSwatch -ThemeName $comboTheme.SelectedItem
        if ($comboTheme.SelectedItem -ne $global:currentThemeName) {
            $global:currentThemeName = $comboTheme.SelectedItem
            foreach ($mi in $global:themeMenuItems) { $mi.Checked = ($mi.Text -eq $global:currentThemeName) }
            Update-UITheme
        }
        # ΝΕΟ v2.2.0: συγχρονίζει την καρτέλα "Skins" (αν είναι ήδη χτισμένη σε αυτό το άνοιγμα του
        # dialog) με το ΝΕΟ επιλεγμένο θέμα - καλύπτει ΚΑΙ την περίπτωση που ο χρήστης αλλάζει θέμα
        # απευθείας από εδώ (καρτέλα Θέματα) αντί από τα radio buttons του Skins.
        if ($radioSkinPcManager -and -not $radioSkinPcManager.IsDisposed) {
            $radioSkinPcManager.Checked = ($comboTheme.SelectedItem -eq "Microsoft PC Manager")
            $radioSkinClassic.Checked = -not $radioSkinPcManager.Checked
        }
    })
    $chkAnimBg.Add_CheckedChanged({
        $radioAnimTheme.Enabled = $chkAnimBg.Checked
        $radioAnimGears.Enabled = $chkAnimBg.Checked
        $radioAnimOrbit.Enabled = $chkAnimBg.Checked
        $radioAnimParticles.Enabled = $chkAnimBg.Checked
        Update-ThemePreviewSwatch -ThemeName $global:currentThemeName
    })
    $radioAnimTheme.Add_CheckedChanged({ if ($radioAnimTheme.Checked) { Update-ThemePreviewSwatch -ThemeName $global:currentThemeName } })
    $radioAnimGears.Add_CheckedChanged({ if ($radioAnimGears.Checked) { Update-ThemePreviewSwatch -ThemeName $global:currentThemeName } })
    $radioAnimOrbit.Add_CheckedChanged({ if ($radioAnimOrbit.Checked) { Update-ThemePreviewSwatch -ThemeName $global:currentThemeName } })
    $radioAnimParticles.Add_CheckedChanged({ if ($radioAnimParticles.Checked) { Update-ThemePreviewSwatch -ThemeName $global:currentThemeName } })
    # ΝΕΟ v1.7.7: Change handlers για τα 2 νέα radio buttons (Κύματα/Πλέγμα) - χωρίς αυτά, η επιλογή
    # τους δεν θα ενημέρωνε την προεπισκόπηση ζωντανά (ίδιο μοτίβο με τα υπόλοιπα 4 στυλ).
    $radioAnimWaves.Add_CheckedChanged({ if ($radioAnimWaves.Checked) { Update-ThemePreviewSwatch -ThemeName $global:currentThemeName } })
    $radioAnimGridPulse.Add_CheckedChanged({ if ($radioAnimGridPulse.Checked) { Update-ThemePreviewSwatch -ThemeName $global:currentThemeName } })

