function Show-VersionHistoryWindow {
    $currTheme = Get-ThemeColors
    $histForm = [System.Windows.Forms.Form]::new()
    $histForm.Text = "$(TT 'Ιστορικό Εκδόσεων') (v2.8.2)"
    $histForm.Size = [System.Drawing.Size]::new(760, 680)
    $histForm.StartPosition = "CenterParent"
    $histForm.FormBorderStyle = "FixedDialog"
    $histForm.MaximizeBox = $false
    $histForm.MinimizeBox = $false
    $histForm.BackColor = $currTheme.MainBg
    $histForm.BackgroundImage = New-ThemedBackgroundBitmap -Width 760 -Height 680 -Style $currTheme.BgStyle -IsDark $global:isDarkMode
    $histForm.BackgroundImageLayout = "Stretch"

    $txtHistContent = [System.Windows.Forms.RichTextBox]::new()
    $txtHistContent.Size = [System.Drawing.Size]::new(700, 560)
    $txtHistContent.Location = [System.Drawing.Point]::new(25, 20)
    $txtHistContent.BackColor = $currTheme.CardBg
    $txtHistContent.ForeColor = $currTheme.Text
    $txtHistContent.BorderStyle = "None"
    $txtHistContent.ReadOnly = $true
    $txtHistContent.Font = $fontText
    # ΔΙΟΡΘΩΣΗ v2.0.1 (χρήστης εντόπισε "στο ιστορικό δεν εμφανίζονται τα εικονίδια παρά μόνο
    # τετράγωνα"): το κανονικό font κειμένου (fontText) δεν έχει glyphs για emoji χαρακτήρες όπως
    # 🔧/➕ - το RichTextBox ΔΕΝ κάνει αυτόματο font fallback, οπότε εμφανίζονται ως "tofu boxes"
    # (το γνωστό, τυπικό σύμπτωμα missing-glyph). Λύση: per-character font switching μέσω
    # SelectionFont - το emoji πρόθεμα γράφεται με "Segoe UI Emoji", το υπόλοιπο κείμενο με το
    # κανονικό font.
    $emojiFont = [System.Drawing.Font]::new("Segoe UI Emoji", $fontText.Size)

    function Add-HistLineWithEmoji {
        param($RichTextBox, [string]$Text, $NormalFont, $EmojiFont, [switch]$Indent)
        # ΔΙΟΡΘΩΣΗ ΡΙΖΙΚΗ (η τεχνική emoji-font-switching αποδείχτηκε επανειλημμένα αναξιόπιστη στην
        # πράξη - v1.9.2, v2.0.1, και η προηγούμενη προσπάθεια ΑΥΤΗΣ της συνεδρίας, ρητή αναφορά χρήστη
        # ότι ΑΚΟΜΑ έδειχνε τετράγωνα ΚΑΙ ασυνεπή "+" σε λάθος σημεία). Αντί να προσπαθούμε να αποδώσουμε
        # το ΙΔΙΟ το emoji glyph (το 🔧 είναι εκτός BMP - ιστορικά το πιο αναξιόπιστο), χρησιμοποιείται
        # ΕΝΑ ενιαίο, ΕΓΧΡΩΜΟ κουκκίδα (●, U+25CF) - κοινό σύμβολο πάντα διαθέσιμο στο ΙΔΙΟ το κανονικό
        # font (καμία εξάρτηση σε emoji font/glyph fallback, άρα ΜΗΔΕΝΙΚΗ πιθανότητα tofu-box πλέον):
        # μπλε για διορθώσεις/βελτιώσεις (πρώην 🔧), πράσινο για προσθήκες (πρώην ➕) - σαφής, αξιόπιστη
        # οπτική διάκριση των δύο κατηγοριών μέσω χρώματος. Η ΙΔΙΑ συνάρτηση παράγει πλέον ΚΑΙ το bullet -
        # αφαιρέθηκε το χειροκίνητο "  •  " πρόθεμα από το σημείο κλήσης (παρακάτω), που δημιουργούσε
        # ΔΙΠΛΟ bullet δίπλα-δίπλα με το emoji/κουκκίδα (ρητή αναφορά χρήστη).
        $bulletColor = $null
        $cleanText = $Text
        if ($cleanText.Contains("🔧")) { $bulletColor = [System.Drawing.Color]::FromArgb(90, 150, 255); $cleanText = $cleanText.Replace("🔧", "").Trim() }
        elseif ($cleanText.Contains("➕")) { $bulletColor = [System.Drawing.Color]::FromArgb(90, 200, 120); $cleanText = $cleanText.Replace("➕", "").Trim() }

        $normalColor = $RichTextBox.ForeColor
        $RichTextBox.SelectionFont = $NormalFont
        $RichTextBox.SelectionColor = $normalColor
        if ($Indent) { $RichTextBox.AppendText("  ") }
        if ($bulletColor) {
            $RichTextBox.SelectionColor = $bulletColor
            $RichTextBox.AppendText("$([char]0x25CF)  ")
            $RichTextBox.SelectionColor = $normalColor
        } elseif ($Indent) {
            $RichTextBox.AppendText("$([char]0x2022)  ")
        }
        $RichTextBox.AppendText($cleanText)
        $RichTextBox.AppendText("`n")
    }

    Add-HistLineWithEmoji -RichTextBox $txtHistContent -Text "Windows 11 Maintenance & Optimizer Tool" -NormalFont $fontText -EmojiFont $emojiFont
    Add-HistLineWithEmoji -RichTextBox $txtHistContent -Text (TT "ΙΣΤΟΡΙΚΟ ΕΚΔΟΣΕΩΝ") -NormalFont $fontText -EmojiFont $emojiFont
    $txtHistContent.AppendText("`n")
    Add-HistLineWithEmoji -RichTextBox $txtHistContent -Text (TT "Η Windows 11 Maintenance & Optimizer Tool είναι μια εξειδικευμένη εφαρμογή συντήρησης και βελτιστοποίησης, σχεδιασμένη να συγκεντρώνει τα πλέον χρήσιμα εργαλεία διάγνωσης, επιδιόρθωσης και παραμετροποίησης των Windows σε ένα ενιαίο, σύγχρονο και ελαφρύ περιβάλλον - καθιστώντας το σύστημά σας ταχύτερο, πιο σταθερό και πιο λειτουργικό.") -NormalFont $fontText -EmojiFont $emojiFont
    $txtHistContent.AppendText("`n")
    Add-HistLineWithEmoji -RichTextBox $txtHistContent -Text "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━" -NormalFont $fontText -EmojiFont $emojiFont
    $txtHistContent.AppendText("`n")

    foreach ($ver in $global:versionHistory.Keys) {
        Add-HistLineWithEmoji -RichTextBox $txtHistContent -Text "$(TT 'Έκδοση') $ver" -NormalFont $fontText -EmojiFont $emojiFont
        foreach ($change in $global:versionHistory[$ver]) {
            # ΔΙΟΡΘΩΣΗ v1.7.7: Κάθε γραμμή του ιστορικού περνάει πλέον από το TT() (ίδιο σύστημα
            # μετάφρασης με όλη την υπόλοιπη εφαρμογή) - πριν εμφανιζόταν ΠΑΝΤΑ στα Ελληνικά,
            # ανεξαρτήτως επιλεγμένης γλώσσας. Ασφαλής, σταδιακή μετάφραση: όσες γραμμές δεν έχουν
            # ακόμα μετάφραση εμφανίζονται στα Ελληνικά (το ίδιο ασφαλές fallback που έχει το TT()
            # παντού αλλού), όχι σφάλμα.
            Add-HistLineWithEmoji -RichTextBox $txtHistContent -Text (TT $change) -NormalFont $fontText -EmojiFont $emojiFont -Indent
        }
        $txtHistContent.AppendText("`n")
    }

    $histForm.Controls.Add($txtHistContent)

    $btnHistClose = [System.Windows.Forms.Button]::new()
    $btnHistClose.Text = (T "BtnClose")
    $btnHistClose.Font = $fontBtnCustom
    $btnHistClose.Size = [System.Drawing.Size]::new(120, 38)
    $btnHistClose.Location = [System.Drawing.Point]::new(600, 592)
    $btnHistClose.BackColor = $currTheme.Accent
    $btnHistClose.ForeColor = [System.Drawing.Color]::White
    $btnHistClose.FlatStyle = "Flat"
    $btnHistClose.FlatAppearance.BorderSize = 0
    $btnHistClose.Cursor = [System.Windows.Forms.Cursors]::Hand
    $btnHistClose.Add_Click({ $histForm.Close() })
    $histForm.Controls.Add($btnHistClose)

    $histForm.ShowDialog($mainForm) | Out-Null
    $histForm.Dispose()
}

# ΔΙΟΡΘΩΣΗ v1.9.6 (ΚΡΙΣΙΜΟ, επιβεβαιωμένο από στιγμιότυπο χρήστη σε Light Mode): γενική, αποδοτική
# βοηθητική function για την ενημέρωση θέματος σε ΟΠΟΙΟΔΗΠΟΤΕ δυναμικά δημιουργημένο panel λίστας
# (Startup/Process/Storage/DeepUninstall/Driver) - αναδρομική διάσχιση παιδικών controls, ΧΩΡΙΣ να
# χρειάζεται πλήρες re-scan (θα ήταν αργό/άσκοπο σε κάθε εναλλαγή θέματος). Ενημερώνει ΜΟΝΟ Panel.BackColor
# και Label.ForeColor - ΣΚΟΠΙΜΑ αγνοεί Button elements, αφού τα κουμπιά ενεργειών (κόκκινο "Τερματισμός"/
# "Κάδος", accent "Έλεγχος") έχουν εσκεμμένα σταθερό χρώμα ανεξάρτητο θέματος.
function Update-DynamicListTheme {
    param($ParentControl, $CardColor, $TextColor)
    if (-not $ParentControl -or $ParentControl.IsDisposed) { return }
    foreach ($ctrl in $ParentControl.Controls) {
        if ($ctrl -is [System.Windows.Forms.Panel]) {
            $ctrl.BackColor = $CardColor
            Update-DynamicListTheme -ParentControl $ctrl -CardColor $CardColor -TextColor $TextColor
        } elseif ($ctrl -is [System.Windows.Forms.Label]) {
            $ctrl.ForeColor = $TextColor
        }
    }
}

function Update-UITheme {
    $currTheme = Get-ThemeColors
    # ΔΙΟΡΘΩΣΗ ΡΙΖΙΚΗ v2.1.2 (ρητό αίτημα χρήστη - "όταν κάνω εναλλαγή light/dark, μετά από ενέργεια ή
    # ανανέωση εμφανίζονται πάλι σκοτεινά πλαίσια"): το script-scope $theme (ορίζεται ΜΙΑ ΦΟΡΑ στην
    # εκκίνηση, γραμμή ~5790) ΠΟΤΕ δεν ενημερωνόταν εδώ - μόνο το τοπικό $currTheme. Δεκάδες συναρτήσεις
    # "Load-X"/"Render-X" (Εφαρμογές Εκκίνησης, Διεργασίες, Drivers, Registry Cleaner, Ghost Devices,
    # Storage κ.ά.) που ξαναχτίζουν γραμμές δυναμικά (μετά από Controls.Clear()) διαβάζουν $theme.CardBg/
    # $theme.Text κλπ ΑΠΕΥΘΕΙΑΣ - αφού ΠΟΤΕ δεν ενημερωνόταν, οι νέες γραμμές έπαιρναν ΠΑΝΤΑ το θέμα της
    # εκκίνησης, όχι το τρέχον. Το ίδιο το container panel (π.χ. $global:startupPanelList) ενημερωνόταν
    # σωστά (ρητές γραμμές παρακάτω) - γι' αυτό το "πλαίσιο" έδειχνε σωστό χρώμα αλλά οι γραμμές μέσα του
    # όχι, μετά από ΟΠΟΙΑΔΗΠΟΤΕ ανανέωση/ενέργεια που τις ξαναχτίζει. Η ενημέρωση του ΙΔΙΟΥ script-scope
    # $theme εδώ διορθώνει ΟΛΕΣ αυτές τις συναρτήσεις ταυτόχρονα, χωρίς να χρειαστεί να επεξεργαστεί η
    # καθεμία ξεχωριστά (μηδενικό πρόσθετο ρίσκο - μόνο ΠΡΟΣΘΗΚΗ μιας ανάθεσης, καμία άλλη λογική αλλάζει).
    $script:theme = $currTheme
    # ΝΕΟ v2.2.0: ξανατρέχει τον υπολογισμό διάταξης sidebar/κάθετης μπάρας εικονιδίων ΚΑΘΕ φορά που
    # αλλάζει το θέμα - απαραίτητο ώστε η εναλλαγή σε/από το θέμα "Microsoft PC Manager" να
    # εμφανίζει/κρύβει αμέσως την κάθετη μπάρα και να μετατοπίζει σωστά το περιεχόμενο, ΧΩΡΙΣ να
    # χρειάζεται επανεκκίνηση της εφαρμογής. Ασφαλές να καλείται εδώ - η ίδια συνάρτηση καλείται ήδη
    # από το Apply-MenuModeSettings με τον ίδιο τρόπο, idempotent σχεδιασμός.
    if (Get-Command Update-SidebarDockLayout -ErrorAction SilentlyContinue) { Update-SidebarDockLayout }
    $mainForm.BackColor = $currTheme.MainBg
    # ΔΙΟΡΘΩΣΗ (εις βάθος έλεγχος): Κάθε αλλαγή θέματος/light-dark δημιουργούσε ΝΕΟ μεγάλο bitmap
    # (1150x800, ~3.6MB) για background χωρίς ποτέ να γίνεται Dispose στο προηγούμενο - πραγματική
    # διαρροή μνήμης/GDI handles σε κάθε εναλλαγή θέματος κατά τη διάρκεια μιας συνεδρίας.
    $oldBg = $mainForm.BackgroundImage
    # ΔΙΟΡΘΩΣΗ v1.5.8: Στατικό φόντο φόρμας (βλ. σχόλιο παραπάνω στην αρχική δημιουργία).
    $mainForm.BackgroundImage = New-ThemedBackgroundBitmap -Width 1280 -Height 800 -Style $currTheme.BgStyle -IsDark $global:isDarkMode -Phase 0
    if ($oldBg) { $oldBg.Dispose() }

    # ΝΕΟ v1.6.8.1: Ανανεώνει το border ΟΛΩΝ των ήδη-δημιουργημένων κουμπιών ώστε να αντανακλά το ΝΕΟ
    # θέμα/ButtonStyle αμέσως - χωρίς αυτό, τα κουμπιά κρατούσαν το border του θέματος με το οποίο
    # δημιουργήθηκαν στην εκκίνηση, ακόμα κι αν ο χρήστης άλλαζε θέμα ζωντανά.
    # ΔΙΟΡΘΩΣΗ (bug εντοπίστηκε, διαρροή μνήμης - ίδιο μοτίβο με allTextLabels/allSubTextLabels/
    # allIconBoxes παρακάτω): τα κουμπιά μέσα σε δυναμικές λίστες (drivers/winget/uninstall κ.λπ.)
    # προστίθενται εδώ σε κάθε ανανέωση χωρίς να αφαιρούνται ποτέ τα παλιά μετά από Controls.Clear().
    $global:allThemedButtons = @($global:allThemedButtons | Where-Object { $_ -and -not $_.IsDisposed -and $_.Parent })
    foreach ($btn in $global:allThemedButtons) {
        if ($btn -and -not $btn.IsDisposed) { Set-ThemedButtonBorder -Button $btn }
    }

    # ΝΕΟ v2.2.0: ζωντανή ενημέρωση του native dark-mode theming (βελάκι/scrollbar dropdown λίστας) σε
    # ΟΛΑ τα ComboBox της εφαρμογής, κάθε φορά που αλλάζει θέμα/light-dark - βλ. Set-NativeControlDarkMode.
    $global:allThemedComboBoxes = @($global:allThemedComboBoxes | Where-Object { $_ -and -not $_.IsDisposed })
    foreach ($cb in $global:allThemedComboBoxes) {
        if ($cb -and -not $cb.IsDisposed) { Set-NativeControlDarkMode -Control $cb }
    }

    # ΝΕΟ v2.8.1: ίδια ζωντανή ενημέρωση, ΤΩΡΑ και για τις γραμμές κύλισης (scrollbars) των κύριων
    # scrollable panels - βλ. Set-PanelScrollbarDarkMode.
    $global:allThemedScrollPanels = @($global:allThemedScrollPanels | Where-Object { $_ -and -not $_.IsDisposed })
    foreach ($sp in $global:allThemedScrollPanels) {
        if ($sp -and -not $sp.IsDisposed) { Set-PanelScrollbarDarkMode -Panel $sp }
    }

    # ΝΕΟ v2.8.1: ζωντανή επανασχεδίαση των θεματισμένων επικαλύψεων βέλους ComboBox - βλ.
    # Add-ComboBoxArrowOverlay. Διαβάζουν το θέμα ζωντανά στο δικό τους Paint, χρειάζονται μόνο Invalidate.
    $global:allComboBoxArrowOverlays = @($global:allComboBoxArrowOverlays | Where-Object { $_ -and -not $_.IsDisposed })
    foreach ($ov in $global:allComboBoxArrowOverlays) {
        if ($ov -and -not $ov.IsDisposed) { $ov.Invalidate() }
    }

    # ΝΕΟ (v1.4.8): Ξεκινά/σταματά αυτόματα το animation timer ανάλογα με το αν το ΝΕΟ θέμα (μετά από
    # αλλαγή θέματος ή light/dark) θα έπρεπε να έχει κινούμενο φόντο.
    if (Test-ShouldAnimateBackground) {
        if (-not $global:bgAnimTimer.Enabled) { $global:bgAnimTimer.Start() }
    } else {
        $global:bgAnimTimer.Stop()
    }
    
    # ΔΙΟΡΘΩΣΗ v1.7.7: Ενημερώνει πλέον και το .Image (όχι μόνο το κείμενο) - ήλιος όταν προτείνεται η
    # μετάβαση σε Light Mode, ημισέληνος όταν προτείνεται η μετάβαση σε Dark Mode. Ο παλιός icon πρέπει
    # να απορριφθεί (Dispose) πριν αντικατασταθεί, ίδιο μοτίβο με τα υπόλοιπα bitmaps της εφαρμογής.
    $oldToggleIcon = $btnThemeToggle.Image
    if ($global:isDarkMode) {
        $btnThemeToggle.Text = "Light Mode"
        $btnThemeToggle.Image = Get-AppIcon -Type "Sun" -Color $currTheme.Text
    } else {
        $btnThemeToggle.Text = "Dark Mode"
        $btnThemeToggle.Image = Get-AppIcon -Type "Moon" -Color $currTheme.Text
    }
    if ($oldToggleIcon) { $oldToggleIcon.Dispose() }
    
    $btnThemeToggle.BackColor = $currTheme.BtnDefault
    $btnThemeToggle.ForeColor = $currTheme.Text

    # ΝΕΟ v1.4.5: theming για hamburger + πλευρικό/οριζόντιο μοντέρνο μενού
    $btnHamburger.BackColor = $currTheme.BtnDefault
    $btnHamburger.ForeColor = $currTheme.Text
    $btnLanguage.BackColor = $currTheme.BtnDefault
    $btnLanguage.ForeColor = $currTheme.Text
    # ΝΕΟ v2.2.0: ζωντανή ενημέρωση χρωμάτων του ContextMenuStrip επιλογής γλώσσας (βλ. σχόλιο στη
    # δημιουργία του, ~γραμμή 6648) - χωρίς αυτό, θα έμενε "κολλημένο" στα χρώματα του θέματος εκκίνησης.
    if ($global:languageContextMenu) {
        $global:languageContextMenu.BackColor = $currTheme.CardBg
        $global:languageContextMenu.ForeColor = $currTheme.Text
        foreach ($li in $global:languageContextMenu.Items) {
            $li.BackColor = $currTheme.CardBg
            $li.ForeColor = $currTheme.Text
        }
    }
    # ΔΙΟΡΘΩΣΗ: το ComboBox επιλογής δίσκου (καρτέλα Αρχική) ζει στην κύρια, μη-modal φόρμα - σε αντίθεση
    # με τα ComboBox/RadioButton μέσα στο (modal) παράθυρο Ρυθμίσεις Εμφάνισης, μπορεί να είναι ορατό
    # ενώ ο χρήστης αλλάζει θέμα ζωντανά, άρα χρειάζεται ρητή ενημέρωση εδώ.
    if ($cboHomeDrive) { $cboHomeDrive.BackColor = $currTheme.CardBg; $cboHomeDrive.ForeColor = $currTheme.Text }
    if ($global:btnDriverScan) { $global:btnDriverScan.BackColor = $currTheme.CardBg; $global:btnDriverScan.Invalidate() }
    if ($global:sidebarEmbedPanel) { $global:sidebarEmbedPanel.BackColor = $currTheme.CardBg }
    if ($cboBenchDrive) { $cboBenchDrive.BackColor = $currTheme.CardBg; $cboBenchDrive.ForeColor = $currTheme.Text }
    # ΝΕΟ (κατόπιν reverse engineering του WMT): το textbox του Επεξεργαστή Αρχείου Hosts ζει επίσης στην
    # κύρια, μη-modal φόρμα (καρτέλα Δίκτυο & Ασφάλεια) - ίδιος λόγος με το $cboHomeDrive παραπάνω.
    if ($global:txtHostsEditor) { $global:txtHostsEditor.BackColor = $currTheme.CardBg; $global:txtHostsEditor.ForeColor = $currTheme.Text }
    # ΔΙΟΡΘΩΣΗ (bug εντοπίστηκε): το txtFirewallSearch δεν είχε ΠΟΤΕ BackColor/ForeColor - εμφανιζόταν
    # πάντα με το προεπιλεγμένο λευκό φόντο/μαύρο κείμενο των WinForms, σπασμένο σε σκούρα θέματα.
    if ($global:txtFirewallSearch) { $global:txtFirewallSearch.BackColor = $currTheme.CardBg; $global:txtFirewallSearch.ForeColor = $currTheme.Text }
    if ($global:txtWinFeaturesSearch) { $global:txtWinFeaturesSearch.BackColor = $currTheme.CardBg; $global:txtWinFeaturesSearch.ForeColor = $currTheme.Text }
    if ($global:winFeaturesPanelList) { $global:winFeaturesPanelList.BackColor = $currTheme.MainBg }
    # ΔΙΟΡΘΩΣΗ (bug εντοπίστηκε κατά τον έλεγχο theme-compliance όλων των TextBox/ComboBox της εφαρμογής):
    # ούτε το txtQuickFind (search bar τίτλου) ούτε το quickFindResultsList είχαν ΠΟΤΕ BackColor/ForeColor.
    if ($global:txtQuickFind) { $global:txtQuickFind.BackColor = $currTheme.CardBg; $global:txtQuickFind.ForeColor = $currTheme.Text }
    if ($global:quickFindResultsList) { $global:quickFindResultsList.BackColor = $currTheme.CardBg; $global:quickFindResultsList.ForeColor = $currTheme.Text }
    if ($global:sidebarForm) { $global:sidebarForm.BackColor = $currTheme.CardBg }
    if ($global:horizModernStrip) { $global:horizModernStrip.BackColor = $currTheme.CardBg }
    
    foreach ($t in $global:customTabs) { $t.Content.BackColor = $currTheme.TabBg }
    $tabStripPanel.BackColor = $currTheme.MainBg
    $btnTabScrollLeft.BackColor = $currTheme.MainBg
    $btnTabScrollLeft.ForeColor = $currTheme.Text
    $btnTabScrollRight.BackColor = $currTheme.MainBg
    $btnTabScrollRight.ForeColor = $currTheme.Text
    if ($global:scrollPanel) { $global:scrollPanel.BackColor = $currTheme.TabBg }
    if ($global:scrollPanelAdvanced) { $global:scrollPanelAdvanced.BackColor = $currTheme.TabBg }
    if ($global:scrollPanelTweaks) { $global:scrollPanelTweaks.BackColor = $currTheme.TabBg }
    
    if ($global:wingetPanelList) { 
        $global:wingetPanelList.BackColor = $currTheme.CardBg 
        foreach ($item in $global:wingetRowItems) {
            if ($item.Panel) { 
                $item.Panel.BackColor = $currTheme.MainBg 
                foreach ($ctrl in $item.Panel.Controls) {
                    if ($ctrl -is [System.Windows.Forms.Label] -or $ctrl -is [System.Windows.Forms.CheckBox]) {
                        $ctrl.ForeColor = $currTheme.Text
                    }
                }
            }
        }
    }
    # ΔΙΟΡΘΩΣΗ (bug εντοπίστηκε, διαρροή μνήμης): οι δυναμικές λίστες (winget/drivers/firewall/registry
    # cleaner/uninstall/startup/processes/storage/restore points/services) κάνουν Controls.Clear() +
    # ξαναδημιουργία σε κάθε ανανέωση, αλλά τα labels/icons τους ΠΡΟΣΤΙΘΕΝΤΑΙ μόνιμα στα παρακάτω global
    # arrays μέσω "+=" χωρίς να αφαιρούνται ΠΟΤΕ τα παλιά - κάθε ανανέωση μεγάλωνε τα arrays για πάντα σε
    # όλη τη διάρκεια της συνεδρίας (Controls.Clear() μηδενίζει το .Parent των αφαιρεθέντων controls,
    # χωρίς όμως αυτό να αφαιρεί τα ίδια τα αντικείμενα από αυτά τα arrays). Καθαρισμός εδώ, στο ΜΟΝΑΔΙΚΟ
    # σημείο κατανάλωσής τους, ώστε να μην αγγίζονται τα 12 ξεχωριστά σημεία ανανέωσης λίστας.
    $global:allTextLabels = @($global:allTextLabels | Where-Object { $_ -and -not $_.IsDisposed -and $_.Parent })
    $global:allSubTextLabels = @($global:allSubTextLabels | Where-Object { $_ -and -not $_.IsDisposed -and $_.Parent })
    foreach ($lbl in $global:allTextLabels) { $lbl.ForeColor = $currTheme.Text }
    foreach ($lbl in $global:allSubTextLabels) { $lbl.ForeColor = $currTheme.SubText }
    $global:allIconBoxes = @($global:allIconBoxes | Where-Object { $_ -and -not $_.IsDisposed -and $_.Parent })
    foreach ($pic in $global:allIconBoxes) {
        $oldImg = $pic.Image
        # ΔΙΟΡΘΩΣΗ v2.1.4 (βλ. αναλυτικό σχόλιο στο Get-AppIcon): σχεδίαση ΑΠΕΥΘΕΙΑΣ στο πραγματικό μέγεθος
        # του PictureBox (π.χ. 18x18 στο οριζόντιο μενού, 32x32 στο πλευρικό) αντί για πάντα 24x24 +
        # τέντωμα/σμίκρυνση από το PictureBox - διορθώνει το pixelation/θόλωμα που ανέφερε ο χρήστης.
        $pic.Image = Get-AppIcon -Type $pic.Tag -Color $currTheme.Text -Size $pic.Width
        if ($oldImg) { $oldImg.Dispose() }
    }
    foreach ($control in $allDefaultButtons) {
        $control.BackColor = $currTheme.BtnDefault
        $control.ForeColor = $currTheme.Text
        $control.Tag = $currTheme.BtnDefault
    }
    foreach ($card in $global:allCards) { $card.BackColor = $currTheme.CardBg }

    # ΝΕΟ v1.9.6: εφαρμογή του παραπάνω fix στα 5 δυναμικά panels λίστας που δεν είχαν ΚΑΘΟΛΟΥ κάλυψη
    # στο theme-switching μηχανισμό.
    # ΔΙΟΡΘΩΣΗ (bug εντοπίστηκε, screenshot χρήστη - μαύρο φόντο στο Light Mode): 3 νέα δυναμικά panels
    # λίστας (Driver Store Cleanup, Ghost Devices, Custom Context Menu) δεν είχαν προστεθεί σε αυτή τη
    # λίστα κατά τη δημιουργία τους - το ίδιο ακριβές bug pattern με το v1.9.6 σχόλιο παραπάνω.
    foreach ($dynPanel in @($global:startupPanelList, $global:processPanelList, $global:storagePanelList, $global:deepUninstallPanelList, $global:driverPanelList, $global:restorePointsPanelList, $global:firewallPanelList, $global:servicesOptPanelList, $global:regCleanPanelList, $global:driverStorePanelList, $global:ghostDevicePanelList, $global:customMenuPanelList)) {
        if ($dynPanel) {
            $dynPanel.BackColor = $currTheme.MainBg
            Update-DynamicListTheme -ParentControl $dynPanel -CardColor $currTheme.CardBg -TextColor $currTheme.Text
        }
    }

    foreach ($t in $global:customTabs) { $t.Pill.Invalidate() }
    # ΝΕΟ v2.4.0: τα glass-background panels (βλ. Set-PanelGlassBackground) διαβάζουν το θέμα ζωντανά σε
    # κάθε Paint, αλλά χρειάζονται ρητό Invalidate εδώ ώστε η αλλαγή θέματος να φανεί αμέσως αντί να
    # περιμένει το επόμενο φυσικό repaint trigger (π.χ. το επόμενο καρέ του bgAnimTimer).
    foreach ($gp in $global:glassBackgroundPanels) { $gp.Invalidate() }
}

$btnThemeToggle.Add_Click({
    $global:isDarkMode = -not $global:isDarkMode
    Update-UITheme
})

function Helper-CreateCard {
    param($x, $y, $w, $h, $parent)
    $theme = Get-ThemeColors
    $card = [System.Windows.Forms.Panel]::new()
    $card.Size = [System.Drawing.Size]::new($w, $h)
    $card.Location = [System.Drawing.Point]::new($x,$y)
    $card.BackColor = $theme.CardBg
    # ΔΙΟΡΘΩΣΗ v1.6.2: Οι κάρτες ΔΕΝ είχαν το ίδιο διορθωτικό SetStyle (double-buffering) που εφαρμόστηκε
    # στο γονικό panel κάθε καρτέλας (βλ. Add-CustomTabPage) - όταν ο γονέας ξαναζωγραφιζόταν λόγω του
    # κινούμενου φόντου, οι κάρτες από πάνω του "αναβόσβηναν" ορατά. Ίδια λύση εφαρμόζεται και εδώ.
    if ($setStyleMethod) { $setStyleMethod.Invoke($card, @($flickerFixStyles, $true)) | Out-Null }
    # ΝΕΟ v1.6.0: Αυθεντικότητα θεμάτων - τα "γυάλινα" θέματα (Vista/Win7 Aero/macOS) παίρνουν
    # στρογγυλεμένο περίγραμμα κάρτας (CardRadius στο θέμα), όπως τα πραγματικά glass panels της εποχής
    # τους. Τα flat/ρετρό θέματα (Win98, Cyberpunk, Matrix, XP, Office2007, Nordic, Solarized) δεν
    # ορίζουν CardRadius και παραμένουν τετράγωνα ως έχουν - καμία οπτική αλλαγή γι' αυτά.
    $card.Add_Paint({
        param($s, $e)
        $currTheme = Get-ThemeColors
        if ($currTheme.CardRadius -and $currTheme.CardRadius -gt 0) {
            $rect = [System.Drawing.Rectangle]::new(0, 0, $s.Width - 1, $s.Height - 1)
            $path = New-RoundedRectPath -Rect $rect -Radius $currTheme.CardRadius
            $pen = [System.Drawing.Pen]::new($currTheme.CardBorder, 1)
            $e.Graphics.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
            $e.Graphics.DrawPath($pen, $path)
            $pen.Dispose()
            $path.Dispose()
        }
    })
    $parent.Controls.Add($card)
    $global:allCards += $card
    return $card
}

# ===== ΒΟΗΘΗΤΙΚΗ ΣΥΝΑΡΤΗΣΗ HOVER EFFECT ΓΙΑ ΚΟΥΜΠΙΑ =====
# Φωτίζει ελαφρώς το χρώμα του κουμπιού όταν το ποντίκι περνά από πάνω και το επαναφέρει όταν φεύγει,
# ώστε τα κουμπιά να δίνουν οπτική ανάδραση (πριν δεν άλλαζαν καθόλου εμφάνιση στο hover).
function Add-ButtonHoverEffect {
    param($Button, [System.Drawing.Color]$BaseColor)
    # ΣΗΜΕΙΩΣΗ: Το "τρέχον" χρώμα βάσης αποθηκεύεται στο $Button.Tag αντί να παγιδεύεται σε closure,
    # έτσι ώστε η αλλαγή θέματος (Update-UITheme) να ενημερώνει σωστά και το χρώμα hover.
    $Button.Tag = $BaseColor
    $Button.Add_MouseEnter({
        $base = $this.Tag
        $this.BackColor = [System.Drawing.Color]::FromArgb(255, [Math]::Min(255,$base.R+25), [Math]::Min(255,$base.G+25), [Math]::Min(255,$base.B+25))
    })
    $Button.Add_MouseLeave({ $this.BackColor = $this.Tag })
    # ΔΙΟΡΘΩΣΗ v1.6.8.1: Η προηγούμενη προσέγγιση (custom Add_Paint με semi-transparent Pen/Brush πάνω
    # στο κουμπί) αποδείχτηκε αναξιόπιστη στην πράξη - τα εφέ είτε δεν εμφανίζονταν καθόλου είτε άφηναν
    # "φαντάσματα" (stale ζωγραφισμένες περιοχές αποκομμένες από το κουμπί τους, βλ. αναφορά χρήστη με
    # στιγμιότυπα). Αντικαταστάθηκε με FlatAppearance.BorderSize/BorderColor - ιδιότητες που ανήκουν στη
    # ΔΙΚΗ ΤΟΥ, ΕΓΓΥΗΜΕΝΗ native σχεδίαση του Button (όχι bolted-on Paint handler), άρα ΠΑΝΤΑ αποδίδονται
    # σωστά, χωρίς κίνδυνο ασυνέπειας ή ορφανών περιοχών ζωγραφικής.
    Set-ThemedButtonBorder -Button $Button
    # ΝΕΟ v1.7.5: ΕΠΑΝΑΦΟΡΑ του πλουσιότερου, θέμα-προς-θέμα οπτικού εφέ (glossy/bevel/glow) - κατόπιν
    # ρητού αιτήματος. ΣΗΜΑΝΤΙΚΗ ΔΙΑΦΟΡΑ από την πρώτη απόπειρα (v1.6.1, αφαιρέθηκε στη v1.6.8.1): η
    # τότε αναφερόμενη αναξιοπιστία ("δεν εμφανίζονταν"/"φαντάσματα") εμφανιζόταν αποκλειστικά σε
    # κουμπιά ΜΕΣΑ σε AutoScroll panels (Εφαρμογές & Bloat, Advanced Tools) που ΤΟΤΕ άλλαζαν δικό τους
    # BackgroundImage κάθε 180ms (βλ. Update-ActiveTabBackgroundTint) - η ρίζα ήταν πιθανότατα ο
    # συνδυασμός AutoScroll+συνεχές BackgroundImage-change, ΟΧΙ η ζωγραφική του ίδιου του κουμπιού. Αυτός
    # ο συνδυασμός αφαιρέθηκε ήδη στη v1.7.0/v1.7.2 (τα 3 αυτά panels πλέον ΔΕΝ αλλάζουν φόντο ανά καρέ),
    # άρα η βασική πιθανή αιτία της αστάθειας δεν ισχύει πια. Το εφέ παραμένει καθαρά ΠΡΟΣΘΕΤΙΚΟ (ποτέ
    # Clear/FillRectangle πλήρους επιφάνειας) πάνω από το ήδη-σωστό FlatAppearance border - αν για
    # οποιονδήποτε λόγο δεν αποδοθεί, το border παραμένει ούτως ή άλλως ορατό (ασφαλής υποβάθμιση).
    Add-ThemedButtonGlossEffect -Button $Button
    # ΝΕΟ: καταγράφεται σε global λίστα ώστε το Update-UITheme να μπορεί να ανανεώσει το border ΟΛΩΝ
    # των ήδη-δημιουργημένων κουμπιών όταν αλλάζει θέμα (όχι μόνο τη στιγμή της αρχικής δημιουργίας).
    $global:allThemedButtons += $Button
}

# ΝΕΟ v1.6.8.1: Θέμα-προς-θέμα διαφοροποίηση κουμπιών μέσω ΝΑΤIVE FlatAppearance (όχι custom Paint).
# Κάθε στυλ κουμπιού ($theme.ButtonStyle) αντιστοιχεί σε ένα διαφορετικό πάχος/χρώμα περιγράμματος -
# λιγότερο εντυπωσιακό από το προηγούμενο gloss/bevel/glow σχέδιο, αλλά ΕΓΓΥΗΜΕΝΑ ορατό σε κάθε θέμα.
function Set-ThemedButtonBorder {
    param($Button)
    $currTheme = Get-ThemeColors
    $style = $currTheme.ButtonStyle
    if (-not $style) {
        $Button.FlatAppearance.BorderSize = 1
        $Button.FlatAppearance.BorderColor = $currTheme.CardBorder
        return
    }
    switch ($style) {
        "Bevel" {
            # Windows 98: παχύ, ανοιχτόχρωμο περίγραμμα - υπαινιγμός ανάγλυφου raised κουμπιού.
            $Button.FlatAppearance.BorderSize = 2
            $Button.FlatAppearance.BorderColor = [System.Drawing.Color]::FromArgb(220, 220, 220)
        }
        "Gloss" {
            # Vista / Windows 7 Aero / Office 2007: λεπτό περίγραμμα στο χρώμα του θέματος.
            $Button.FlatAppearance.BorderSize = 2
            $Button.FlatAppearance.BorderColor = $currTheme.CardBorder
        }
        "Rounded" {
            # Windows XP Luna / macOS: περίγραμμα στο accent χρώμα (υπαινιγμός "απαλού" κουμπιού).
            $Button.FlatAppearance.BorderSize = 2
            $Button.FlatAppearance.BorderColor = $currTheme.Accent
        }
        "Glow" {
            # Cyberpunk / Matrix / RGB Gaming κ.λπ.: πιο παχύ, έντονο περίγραμμα σε νέον accent χρώμα.
            $Button.FlatAppearance.BorderSize = 3
            $Button.FlatAppearance.BorderColor = $currTheme.Accent
        }
        default {
            $Button.FlatAppearance.BorderSize = 1
            $Button.FlatAppearance.BorderColor = $currTheme.CardBorder
        }
    }
}

# ΝΕΟ v1.7.5: Πλουσιότερο, ΠΡΟΣΘΕΤΙΚΟ οπτικό εφέ ανά ButtonStyle - βλ. εκτενές σχόλιο στο σημείο κλήσης
# (Add-ButtonHoverEffect) για το γιατί θεωρείται πλέον ασφαλές να επανέλθει. ΠΟΤΕ $g.Clear()/FillRectangle
# πλήρους επιφάνειας - μόνο λεπτές, ημιδιάφανες προσθήκες ΠΑΝΩ από το ήδη σωστά σχεδιασμένο κουμπί.
function Add-ThemedButtonGlossEffect {
    param($Button)
    $Button.Add_Paint({
        param($s, $e)
        $currTheme = Get-ThemeColors
        $style = $currTheme.ButtonStyle
        if (-not $style) { return }
        $g = $e.Graphics
        $g.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
        $w = $s.Width; $h = $s.Height
        switch ($style) {
            "Bevel" {
                # Windows 98: επιπλέον εσωτερική σκιά κάτω-δεξιά (πέρα από το FlatAppearance border) -
                # ενισχύει την αίσθηση ανάγλυφου raised κουμπιού της εποχής.
                $penDark = [System.Drawing.Pen]::new([System.Drawing.Color]::FromArgb(90, 0, 0, 0), 1)
                $g.DrawLine($penDark, 2, $h - 3, $w - 3, $h - 3)
                $g.DrawLine($penDark, $w - 3, 2, $w - 3, $h - 3)
                $penDark.Dispose()
            }
            "Gloss" {
                # Vista / Windows 7 Aero / Office 2007: γυάλινη "λάμψη" στο πάνω μισό - το χαρακτηριστικό
                # glossy look αυτής της εποχής Windows/Office.
                $glossRect = [System.Drawing.Rectangle]::new(2, 2, [Math]::Max(1, $w - 4), [Math]::Max(1, [int]($h * 0.45)))
                $glossBrush = [System.Drawing.Drawing2D.LinearGradientBrush]::new($glossRect, [System.Drawing.Color]::FromArgb(75, 255, 255, 255), [System.Drawing.Color]::FromArgb(0, 255, 255, 255), 90)
                $g.FillRectangle($glossBrush, $glossRect)
                $glossBrush.Dispose()
            }
            "Rounded" {
                # Windows XP Luna / macOS: απαλή, ημιδιάφανη κορυφή (λιγότερο έντονη από το Gloss) -
                # υπαινιγμός στρογγυλεμένου, "μαλακού" κουμπιού.
                $topRect = [System.Drawing.Rectangle]::new(3, 2, [Math]::Max(1, $w - 6), [Math]::Max(1, [int]($h * 0.35)))
                $softBrush = [System.Drawing.Drawing2D.LinearGradientBrush]::new($topRect, [System.Drawing.Color]::FromArgb(45, 255, 255, 255), [System.Drawing.Color]::FromArgb(0, 255, 255, 255), 90)
                $g.FillRectangle($softBrush, $topRect)
                $softBrush.Dispose()
            }
            "Glow" {
                # Cyberpunk / Matrix / RGB Gaming κ.λπ.: δεύτερο, εξωτερικό "φωτοστέφανο" περίγραμμα σε
                # χαμηλότερη διαφάνεια γύρω από το ήδη υπάρχον έντονο FlatAppearance border - δίνει την
                # αίσθηση φωτεινής λάμψης (glow) αντί για απλή συμπαγή γραμμή.
                $glowPen = [System.Drawing.Pen]::new([System.Drawing.Color]::FromArgb(70, $currTheme.Accent), 1)
                $g.DrawRectangle($glowPen, 0, 0, $w - 1, $h - 1)
                $glowPen.Dispose()
            }
        }
    })
}

# ===== ΝΕΟ (v1.7.5): TOGGLE SWITCH ΣΤΥΛ WINDOWS 11 (αντί για ζεύγος κουμπιών Ενεργοποίηση/Επαναφορά) =====
# Ασφαλής, καθαρά προσθετική σχεδίαση (Panel + Paint handler), ίδιο μοτίβο με τα ήδη λειτουργικά
# custom pill-tabs. ΣΗΜΑΝΤΙΚΟΣ ΠΕΡΙΟΡΙΣΜΟΣ (αναφέρεται ρητά): δεν υπάρχει αξιόπιστη, γενική μέθοδος να
# διαβαστεί η ΠΡΑΓΜΑΤΙΚΗ τρέχουσα κατάσταση κάθε ρύθμισης (πολλές είναι registry τιμές χωρίς απλό
# boolean read-back, ή αφορούν ενέργειες όπως καθαρισμό cache). Το switch ξεκινά πάντα σε θέση "off" -
# ίδιος περιορισμός είχε και το προηγούμενο ζεύγος κουμπιών (πρόσφερε πάντα ΚΑΙ τις δύο επιλογές,
# ανεξαρτήτως πραγματικής κατάστασης) - το toggle απλά ενοποιεί οπτικά τις ίδιες δύο ενέργειες.
function New-ToggleSwitch {
    param([scriptblock]$OnScript, [scriptblock]$OffScript, [bool]$InitialState = $false)
    $sw = [System.Windows.Forms.Panel]::new()
    $sw.Size = [System.Drawing.Size]::new(56, 28)
    $sw.Cursor = [System.Windows.Forms.Cursors]::Hand
    # ΔΙΟΡΘΩΣΗ v1.7.5: Προστέθηκε προαιρετική παράμετρος $InitialState (προεπιλογή $false, ίδια
    # συμπεριφορά με πριν για τις Επιπλέον Ρυθμίσεις/Office/Gaming Mode που δεν έχουν αξιόπιστη μέθοδο
    # ανίχνευσης). Το ViVeTool (βλ. Add-ViveFeatureRow) πλέον περνάει την ΠΡΑΓΜΑΤΙΚΑ ανιχνευμένη
    # κατάσταση εδώ, αφού διορθώθηκε η Test-ViveFeatureState να διαβάζει σωστά την έξοδο.
    $sw.Tag = [PSCustomObject]@{ IsOn = $InitialState; OnScript = $OnScript; OffScript = $OffScript }
    if ($setStyleMethod) { $setStyleMethod.Invoke($sw, @($flickerFixStyles, $true)) | Out-Null }
    $sw.Add_Paint({
        param($s, $e)
        $t = Get-ThemeColors
        $g = $e.Graphics
        $g.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
        $trackColor = if ($s.Tag.IsOn) { $t.Accent } else { [System.Drawing.Color]::FromArgb(130, 130, 136) }
        $rect = [System.Drawing.Rectangle]::new(0, 0, $s.Width - 1, $s.Height - 1)
        $path = New-RoundedRectPath -Rect $rect -Radius ([int]($s.Height / 2))
        $trackBrush = [System.Drawing.SolidBrush]::new($trackColor)
        $g.FillPath($trackBrush, $path)
        $trackBrush.Dispose(); $path.Dispose()
        $circleD = $s.Height - 6
        $circleX = if ($s.Tag.IsOn) { $s.Width - $circleD - 3 } else { 3 }
        $circleBrush = [System.Drawing.SolidBrush]::new([System.Drawing.Color]::White)
        $g.FillEllipse($circleBrush, $circleX, 3, $circleD, $circleD)
        $circleBrush.Dispose()
    })
    $sw.Add_Click({
        param($s, $e)
        $s.Tag.IsOn = -not $s.Tag.IsOn
        if ($s.Tag.IsOn) { & $s.Tag.OnScript } else { & $s.Tag.OffScript }
        $s.Invalidate()
    })
    return $sw
}

$global:appToolTip = [System.Windows.Forms.ToolTip]::new()
$global:appToolTip.AutoPopDelay = 8000
$global:appToolTip.InitialDelay = 400
$global:appToolTip.ReshowDelay = 200
$global:appToolTip.IsBalloon = $true
# ΔΙΟΡΘΩΣΗ v1.9.4: Το tooltip του κουμπιού Log Panel προστέθηκε εδώ (όχι στο σημείο δημιουργίας του
# κουμπιού, γραμμή ~5745) - το appToolTip δεν είχε ακόμα οριστεί εκεί (κλήση-πριν-τον-ορισμό).
# ΔΙΟΡΘΩΣΗ v2.0.1: το tooltip αφαιρέθηκε - το btnShowLog δεν υπάρχει πια (μετακινήθηκε σε menu items).

# ΔΙΟΡΘΩΣΗ v1.5.0: Αφαιρέθηκαν τα tooltips από όλα τα κουμπιά (κατόπιν αιτήματος) - τα tooltips
# υπάρχουν πλέον ΜΟΝΟ στις ετικέτες περιγραφής των λειτουργιών, ποτέ στα ίδια τα κουμπιά.

# ===== ΒΟΗΘΗΤΙΚΗ ΣΥΝΑΡΤΗΣΗ ΕΠΙΚΕΦΑΛΙΔΑΣ ΚΑΡΤΕΛΑΣ ΜΕ ΕΙΚΟΝΙΔΙΟ =====
# Προσθέτει ένα μικρό vector εικονίδιο δίπλα σε τίτλο/υπότιτλο, ώστε κάθε καρτέλα και κάθε κάρτα
# να έχει άμεση οπτική αναγνώριση (πριν μόνο οι καρτέλες του tabControl είχαν εικονίδιο).
function Add-IconedLabel {
    param($IconType, $Text, $x, $y, $w, $Font, $IsSubText, $Parent)
    $theme = Get-ThemeColors
    $color = if ($IsSubText) { $theme.SubText } else { $theme.Text }
    $pic = [System.Windows.Forms.PictureBox]::new()
    $pic.Size = [System.Drawing.Size]::new(20, 20)
    $pic.Location = [System.Drawing.Point]::new($x, $y)
    $pic.SizeMode = "Zoom"
    $pic.BackColor = [System.Drawing.Color]::Transparent
    $pic.Image = Get-AppIcon -Type $IconType -Color $color
    $pic.Tag = $IconType
    $global:allIconBoxes += $pic
    $Parent.Controls.Add($pic)

    $lbl = [System.Windows.Forms.Label]::new()
    $lbl.Text = $Text
    $lbl.Font = $Font
    $lbl.ForeColor = $color
    $lbl.BackColor = [System.Drawing.Color]::Transparent
    $lbl.Size = [System.Drawing.Size]::new($w, 25)
    $lbl.Location = [System.Drawing.Point]::new($x + 27, $y - 1)
    $Parent.Controls.Add($lbl)
    if ($IsSubText) { $global:allSubTextLabels += $lbl } else { $global:allTextLabels += $lbl }
    return $lbl
}

function Helper-CreateButton {
    param($text, $x, $y, $w, $h, $color, $clickAction, $parent, $isCustomColor = $false, $tooltip = "")
    $theme = Get-ThemeColors
    $btn = [System.Windows.Forms.Button]::new()
    $btn.Text = $text
    $btn.Font = $fontBtnCustom
    $btn.Size = [System.Drawing.Size]::new($w, $h)
    $btn.Location = [System.Drawing.Point]::new($x,$y)
    $btn.BackColor = $color
    $btn.ForeColor = [System.Drawing.Color]::White
    $btn.FlatStyle = "Flat"
    $btn.FlatAppearance.BorderSize = 0
    $btn.Cursor = [System.Windows.Forms.Cursors]::Hand
    $btn.Add_Click($clickAction)
    Add-ButtonHoverEffect -Button $btn -BaseColor $color
    # ΔΙΟΡΘΩΣΗ v1.5.0: Tooltip στο κουμπί αφαιρέθηκε (κατόπιν αιτήματος) - πλέον τα tooltips εμφανίζονται
    # ΜΟΝΟ σε ετικέτες περιγραφής, ποτέ σε κουμπιά. Η παράμετρος $tooltip διατηρείται (δεν αφαιρέθηκε
    # από κάθε μεμονωμένη κλήση σε όλο το αρχείο) αλλά απλά δεν χρησιμοποιείται πλέον εδώ.
    $parent.Controls.Add($btn)
    if (-not $isCustomColor) { $global:allDefaultButtons += $btn }
    return $btn
}

# ===== ΒΟΗΘΗΤΙΚΗ ΣΥΝΑΡΤΗΣΗ ΑΣΦΑΛΟΥΣ ΕΓΓΡΑΦΗΣ ΣΤΟ REGISTRY =====
# ΔΙΟΡΘΩΣΗ: Αρκετά από τα παρακάτω Set-ItemProperty έγραφαν σε registry paths που μπορεί να ΜΗΝ υπάρχουν
# ακόμα σε ένα φρέσκο Windows 11 (π.χ. HKCU:\System\GameConfigStore, τα Tasks\Games κλειδιά, το
# DeviceGuard\Scenarios κλειδί). Το Set-ItemProperty ΔΕΝ δημιουργεί μόνο του το path· αν δεν υπάρχει,
# αποτυγχάνει σιωπηλά λόγω -ErrorAction SilentlyContinue, δίνοντας την ψευδή εντύπωση ότι η ρύθμιση
# εφαρμόστηκε ενώ στην πραγματικότητα δεν έγινε τίποτα. Η Set-RegSafe δημιουργεί πρώτα το path αν λείπει.
function Set-RegSafe {
    param([string]$Path, [string]$Name, $Value, [string]$Type = "DWord")
    try {
        if (-not (Test-Path $Path)) {
            New-Item -Path $Path -Force -ErrorAction Stop | Out-Null
        }
        New-ItemProperty -Path $Path -Name $Name -Value $Value -PropertyType $Type -Force -ErrorAction Stop | Out-Null
    } catch {
        # Παράκαμψη μεμονωμένου σφάλματος registry για να συνεχίσει η υπόλοιπη εφαρμογή ρυθμίσεων
    }
}

# ===== ΝΕΟ (κατόπιν reverse engineering του κώδικα αναφοράς WMT - registry λογική, framework-agnostic):
# ΒΟΗΘΗΤΙΚΗ ΣΥΝΑΡΤΗΣΗ ΓΙΑ ΕΓΓΡΑΦΕΣ ΔΕΞΙ-ΚΛΙΚ ΜΕΝΟΥ =====
# Η προεπιλεγμένη (Default) τιμή ενός registry key ΔΕΝ ορίζεται σωστά μέσω New-ItemProperty (που είναι
# για ΟΝΟΜΑΣΤΙΚΕΣ τιμές) - χρησιμοποιείται το ειδικό Set-Item στο ίδιο το key path, ο καθιερωμένος
# PowerShell τρόπος. Πλήρως αναστρέψιμο: Remove-ContextMenuCommand διαγράφει απλά ολόκληρο το key tree
# που δημιουργήθηκε, καμία μόνιμη αλλαγή σε κάτι που προϋπήρχε.
function Install-ContextMenuCommand {
    param([string]$KeyPath, [string]$MenuText, [string]$Command, [string]$Icon = "", [switch]$RequireElevation)
    New-Item -Path $KeyPath -Force -ErrorAction Stop | Out-Null
    Set-Item -Path $KeyPath -Value $MenuText -ErrorAction Stop
    if ($Icon) { New-ItemProperty -Path $KeyPath -Name "Icon" -Value $Icon -PropertyType String -Force -ErrorAction SilentlyContinue | Out-Null }
    if ($RequireElevation) { New-ItemProperty -Path $KeyPath -Name "HasLUAShield" -Value "" -PropertyType String -Force -ErrorAction SilentlyContinue | Out-Null }
    New-Item -Path "$KeyPath\command" -Force -ErrorAction Stop | Out-Null
    Set-Item -Path "$KeyPath\command" -Value $Command -ErrorAction Stop
}
function Remove-ContextMenuCommand {
    param([string]$KeyPath)
    Remove-Item -Path $KeyPath -Recurse -Force -ErrorAction SilentlyContinue
}

# ===== ΝΕΟ: BACKUP/RESTORE ΤΗΣ ΠΡΑΓΜΑΤΙΚΗΣ ΑΡΧΙΚΗΣ ΤΙΜΗΣ REGISTRY (JSON) =====
# Πριν οι "Επιπλέον Ρυθμίσεις" αλλάξουν οποιαδήποτε τιμή registry για πρώτη φορά, αποθηκεύεται η
# ΠΡΑΓΜΑΤΙΚΗ τιμή που είχε ο χρήστης (όχι μια αυθαίρετη "προεπιλογή" που μαντεύουμε). Έτσι το κουμπί
# "Επαναφορά" επαναφέρει ό,τι είχε πραγματικά ο χρήστης πριν αγγίξει τίποτα η εφαρμογή - ακόμα κι αν
# αυτό διέφερε από το εργοστασιακό προεπιλεγμένο των Windows. Συμβατό με Windows PowerShell 5.1
# (ΔΕΝ χρησιμοποιεί ConvertFrom-Json -AsHashtable, που υπάρχει μόνο σε PowerShell 7+).
$global:tweakBackupPath = Join-Path $PSScriptRoot "OptimizerTweakBackup.json"

function Get-TweakBackupData {
    if (Test-Path $global:tweakBackupPath) {
        try { return (Get-Content $global:tweakBackupPath -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop) } catch { return [PSCustomObject]@{} }
    }
    return [PSCustomObject]@{}
}

function Save-TweakBackupData {
    param($Data)
    try { $Data | ConvertTo-Json -Depth 5 | Out-File -FilePath $global:tweakBackupPath -Encoding UTF8 -Force } catch {}
}

function ConvertTo-BackupKey {
    param([string]$Path, [string]$Name)
    return (($Path + "||" + $Name) -replace '[\\:\s]', '_')
}

function Backup-RegValueIfNeeded {
    param([string]$Path, [string]$Name)
    $data = Get-TweakBackupData
    $key = ConvertTo-BackupKey -Path $Path -Name $Name
    # Αν έχουμε ήδη αποθηκεύσει την αρχική τιμή στο παρελθόν, ΔΕΝ την ξαναγράφουμε - θα χάναμε την
    # πραγματική αρχική τιμή του χρήστη αν το κουμπί "Ενεργοποίηση" πατηθεί ξανά μετά από μια Επαναφορά.
    if ($data.PSObject.Properties.Name -contains $key) { return }
    $existing = "__NOTSET__"
    try { $existing = (Get-ItemProperty -Path $Path -Name $Name -ErrorAction Stop).$Name } catch {}
    $data | Add-Member -NotePropertyName $key -NotePropertyValue $existing -Force
    Save-TweakBackupData -Data $data
}

function Restore-BackedUpRegValue {
    param([string]$Path, [string]$Name, [string]$Type = "DWord")
    $data = Get-TweakBackupData
    $key = ConvertTo-BackupKey -Path $Path -Name $Name
    if ($data.PSObject.Properties.Name -contains $key) {
        $val = $data.$key
        if ($val -eq "__NOTSET__" -or $null -eq $val) {
            # Η τιμή δεν υπήρχε καθόλου πριν - η σωστή "επαναφορά" είναι να αφαιρεθεί εντελώς, όχι να
            # μπει κάποια αυθαίρετη τιμή.
            Remove-ItemProperty -Path $Path -Name $Name -ErrorAction SilentlyContinue
        } else {
            Set-RegSafe -Path $Path -Name $Name -Value $val -Type $Type
        }
    }
    # Αν δεν υπάρχει καταγεγραμμένο backup (π.χ. πατήθηκε "Επαναφορά" χωρίς προηγούμενη "Ενεργοποίηση"
    # μέσα από αυτή την εφαρμογή), δεν πειράζουμε τίποτα - δεν έχουμε πραγματική αρχική τιμή να βάλουμε.
}

# ===== ΝΕΟ (v1.9.4): BACKUP/RESTORE ΓΙΑ StartType ΥΠΗΡΕΣΙΩΝ (Services to Manual) =====
# Επαναχρησιμοποιεί το ΙΔΙΟ, ήδη υπάρχον JSON backup αρχείο (tweakBackupPath) με διαφορετικό key prefix
# ("SVC_") - όχι νέος μηχανισμός αποθήκευσης. Το $svc.StartType (από Get-Service) επιστρέφει ήδη την
# ακριβή τιμή που δέχεται το Set-Service -StartupType, οπότε δεν χρειάζεται μετατροπή/mapping.
function Backup-ServiceStartTypeIfNeeded {
    param([string]$ServiceName)
    $data = Get-TweakBackupData
    $key = "SVC_$ServiceName"
    if ($data.PSObject.Properties.Name -contains $key) { return }
    $svc = Get-Service -Name $ServiceName -ErrorAction SilentlyContinue
    $existing = if ($svc) { $svc.StartType.ToString() } else { "Automatic" }
    $data | Add-Member -NotePropertyName $key -NotePropertyValue $existing -Force
    Save-TweakBackupData -Data $data
}

function Restore-ServiceStartType {
    param([string]$ServiceName)
    $data = Get-TweakBackupData
    $key = "SVC_$ServiceName"
    if ($data.PSObject.Properties.Name -contains $key) {
        $originalType = $data.$key
        Set-Service -Name $ServiceName -StartupType $originalType -ErrorAction SilentlyContinue
    }
}

# ===== ΝΕΟ: ΕΠΑΝΑΦΟΡΑ ΑΦΑΙΡΕΘΕΝΤΩΝ APPX ΠΑΚΕΤΩΝ (ΔΙΟΡΘΩΣΗ) =====
# ΔΙΟΡΘΩΣΗ: Τα κουμπιά "Εγκατάσταση" για Copilot/HEVC/News&Weather προσπαθούσαν να κάνουν register
# από ΣΤΑΘΕΡΟ (hardcoded) μονοπάτι στο WindowsApps, το οποίο ΔΕΝ υπάρχει πια αφού το Remove-AppxPackage
# διαγράφει πλήρως τα αρχεία του πακέτου (Path Not Found). Η σωστή, αξιόπιστη μέθοδος επαναφοράς είναι:
# 1) αναζήτηση στα ήδη "provisioned" πακέτα του Windows (αν υπάρχουν ακόμα εκεί),
# 2) αλλιώς προσπάθεια μέσω winget (αν το πακέτο διανέμεται εκεί),
# 3) τελική εναλλακτική: άνοιγμα της σελίδας του Microsoft Store για χειροκίνητη επανεγκατάσταση.
function Restore-AppxPackage {
    param([string]$PackageNamePattern, [string]$WingetId = "", [string]$StoreUri = "")

    $prov = Get-AppxProvisionedPackage -Online -ErrorAction SilentlyContinue | Where-Object { $_.PackageName -like "$PackageNamePattern*" } | Select-Object -First 1
    if ($prov) {
        try {
            $manifestPath = Join-Path $prov.InstallLocation "AppxManifest.xml"
            if (Test-Path $manifestPath) {
                Add-AppxPackage -Register $manifestPath -DisableDevelopmentMode -ErrorAction Stop
                return $true
            }
        } catch {}
    }

    if ($WingetId -and (Get-Command winget.exe -ErrorAction SilentlyContinue)) {
        try {
            Start-Process -FilePath "winget.exe" -ArgumentList @("install","--id",$WingetId,"--exact","--silent","--accept-source-agreements","--accept-package-agreements") -Wait -NoNewWindow -ErrorAction Stop
            return $true
        } catch {}
    }

    if ($StoreUri) {
        Start-Process $StoreUri -ErrorAction SilentlyContinue
    }
    return $false
}

# ===== ΝΕΟ: ΟΡΙΣΜΟΣ ΠΡΟΕΠΙΛΕΓΜΕΝΗΣ ΕΦΑΡΜΟΓΗΣ ΓΙΑ ΕΠΕΚΤΑΣΕΙΣ ΑΡΧΕΙΩΝ (BEST-EFFORT) =====
# ΣΗΜΕΙΩΣΗ: Από τα Windows 10 1803+ η Microsoft περιορίζει σκόπιμα τον προγραμματιστικό ορισμό
# προεπιλεγμένων εφαρμογών (για λόγους ασφάλειας/ανταγωνισμού). Η μέθοδος DISM Import-DefaultAppAssociations
# παραμένει η επίσημα υποστηριζόμενη οδός, αλλά σε ορισμένα builds/εκδόσεις των Windows 11 ενδέχεται να
# μην εφαρμοστεί πλήρως - σε αυτή την περίπτωση η επιλογή Ρυθμίσεις > Προεπιλεγμένες Εφαρμογές παραμένει
# ο μόνος 100% αξιόπιστος τρόπος.
function Set-DefaultAppAssociations {
    param([hashtable]$Associations)
    $xmlLines = $Associations.GetEnumerator() | ForEach-Object { "  <Association Identifier=`"$($_.Key)`" ProgId=`"$($_.Value)`" ApplicationName=`"`" />" }
    $xmlContent = "<?xml version=`"1.0`" encoding=`"UTF-8`"?>`r`n<DefaultAssociations>`r`n$($xmlLines -join "`r`n")`r`n</DefaultAssociations>"
    $xmlPath = Join-Path $env:TEMP "OptimizerDefaultAppAssoc.xml"
    try {
        $xmlContent | Out-File -FilePath $xmlPath -Encoding UTF8 -Force
        Start-Process -FilePath "dism.exe" -ArgumentList "/Online","/Import-DefaultAppAssociations:`"$xmlPath`"" -Wait -NoNewWindow -ErrorAction Stop
        return $true
    } catch {
        return $false
    } finally {
        Remove-Item $xmlPath -Force -ErrorAction SilentlyContinue
    }
}

# ===== ΝΕΟ: ΚΑΡΦΙΤΣΩΜΑ ΣΤΗ ΓΡΑΜΜΗ ΕΡΓΑΣΙΩΝ (BEST-EFFORT ΜΕΣΩ SHELL VERB) =====
# ΣΗΜΕΙΩΣΗ: Η Microsoft δεν προσφέρει καμία επίσημη/τεκμηριωμένη μέθοδο για προγραμματιστικό pin στη
# γραμμή εργασιών των Windows 11. Χρησιμοποιείται το "verb" του Explorer (ίδιο με δεξί-κλικ > Καρφίτσωμα
# στη γραμμή εργασιών), το οποίο λειτουργεί σε πολλά builds αλλά δεν είναι εγγυημένο σε όλα.
function Add-TaskbarPin {
    param([string]$ExePath)
    if (-not (Test-Path $ExePath)) { return $false }
    try {
        $folder = Split-Path $ExePath -Parent
        $fileName = Split-Path $ExePath -Leaf
        $shellApp = New-Object -ComObject Shell.Application
        $ns = $shellApp.Namespace($folder)
        $item = $ns.ParseName($fileName)
        if (-not $item) { return $false }
        $pinVerb = $item.Verbs() | Where-Object { ($_.Name -replace '&','') -match 'στη γραμμή εργασιών|to Tas' }
        if ($pinVerb) { $pinVerb.DoIt(); return $true }
        return $false
    } catch {
        return $false
    }
}

function Set-OfficeMode {
    $progressBar.Visible = $true
    $progressBar.Value = 20
    $lblStatus.Text = (TT "Ενεργοποίηση Office Mode...")
    $mainForm.Refresh()
    
    powercfg /setactive SCHEME_BALANCED | Out-Null
    $progressBar.Value = 50
    Set-RegSafe -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects" -Name "VisualFXSetting" -Value 2
    Set-RegSafe -Path "HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management" -Name "ClearPageFileAtShutdown" -Value 0
    Set-RegSafe -Path "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer" -Name "SmartScreenEnabled" -Value "RequireAdmin" -Type String
    $progressBar.Value = 85
    Set-RegSafe -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\UserProfileEngagement" -Name "ScoobeSystemSettingEnabled" -Value 0
    Set-RegSafe -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager" -Name "SystemPaneSuggestionsEnabled" -Value 0
    $progressBar.Value = 100
    
    Start-Sleep -Milliseconds 300
    $progressBar.Visible = $false
    $lblStatus.Text = (TT "Κατάσταση: Το Office Mode ενεργοποιήθηκε επιτυχώς!")
}

function Disable-OfficeMode {
    $progressBar.Visible = $true
    $progressBar.Value = 30
    $lblStatus.Text = (TT "Απενεργοποίηση Office Mode & Επανεκκίνηση Explorer...")
    $mainForm.Refresh()
    
    Set-RegSafe -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects" -Name "VisualFXSetting" -Value 0
    Set-RegSafe -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\UserProfileEngagement" -Name "ScoobeSystemSettingEnabled" -Value 1
    Set-RegSafe -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager" -Name "SystemPaneSuggestionsEnabled" -Value 1
    $progressBar.Value = 75
    Stop-Process -Name explorer -Force -ErrorAction SilentlyContinue
    $progressBar.Value = 100
    
    Start-Sleep -Milliseconds 300
    $progressBar.Visible = $false
    $lblStatus.Text = (TT "Κατάσταση: Το Office Mode απενεργοποιήθηκε & ο Explorer επανεκκινήθηκε!")
}

function Set-GamingMode {
    $progressBar.Visible = $true
    $progressBar.Value = 15
    $lblStatus.Text = (TT "Ενεργοποίηση Gaming Mode...")
    $mainForm.Refresh()
    
    powercfg /setactive SCHEME_MIN | Out-Null
    $progressBar.Value = 40
    Set-RegSafe -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects" -Name "VisualFXSetting" -Value 2
    Set-RegSafe -Path "HKCU:\Software\Microsoft\GameBar" -Name "AllowAutoGameMode" -Value 1
    Set-RegSafe -Path "HKCU:\System\GameConfigStore" -Name "GameDVR_Enabled" -Value 0
    $progressBar.Value = 70
    Set-RegSafe -Path "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile" -Name "NetworkThrottlingIndex" -Value 255
    Set-RegSafe -Path "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile" -Name "SystemResponsiveness" -Value 0
    Set-RegSafe -Path "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Games" -Name "GPU Priority" -Value 8
    Set-RegSafe -Path "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Games" -Name "Priority" -Value 6
    Set-RegSafe -Path "HKCU:\Control Panel\Desktop" -Name "MenuShowDelay" -Value "0" -Type String
    Set-RegSafe -Path "HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl" -Name "Win32PrioritySeparation" -Value 38
    Set-RegSafe -Path "HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers" -Name "HwSchMode" -Value 2
    Set-RegSafe -Path "HKLM:\SYSTEM\CurrentControlSet\Control\DeviceGuard\Scenarios\HypervisorEnforcedCodeIntegrity" -Name "Enabled" -Value 0
    # ΔΙΟΡΘΩΣΗ: Το προηγούμενο μόνο του HVCI-specific key ΔΕΝ απενεργοποιεί πλήρως το VBS - λείπει ο
    # κύριος διακόπτης EnableVirtualizationBasedSecurity. Προστέθηκε, ΚΑΙ προστέθηκε αντίστοιχη
    # επαναφορά στο Disable-GamingMode παρακάτω (πριν δεν υπήρχε ΚΑΘΟΛΟΥ - το VBS έμενε μόνιμα off).
    Set-RegSafe -Path "HKLM:\SYSTEM\CurrentControlSet\Control\DeviceGuard" -Name "EnableVirtualizationBasedSecurity" -Value 0
    $progressBar.Value = 100
    
    Start-Sleep -Milliseconds 300
    $progressBar.Visible = $false
    $lblStatus.Text = (TT "Κατάσταση: Το Gaming Mode ενεργοποιήθηκε! (Συνιστάται επανεκκίνηση)")
}

function Disable-GamingMode {
    $progressBar.Visible = $true
    $progressBar.Value = 30
    $lblStatus.Text = (TT "Απενεργοποίηση Gaming Mode & Επανεκκίνηση Explorer...")
    $mainForm.Refresh()
    
    powercfg /setactive SCHEME_BALANCED | Out-Null
    Set-RegSafe -Path "HKCU:\System\GameConfigStore" -Name "GameDVR_Enabled" -Value 1
    Set-RegSafe -Path "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile" -Name "NetworkThrottlingIndex" -Value 10
    Set-RegSafe -Path "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile" -Name "SystemResponsiveness" -Value 14
    # ΔΙΟΡΘΩΣΗ: Επαναφορά VBS/HVCI που απενεργοποιούνται στο Set-GamingMode - πριν δεν υπήρχε καμία
    # επαναφορά εδώ, οπότε η ασφάλεια VBS έμενε μόνιμα κλειστή ακόμα και μετά από "Απενεργοποίηση".
    Set-RegSafe -Path "HKLM:\SYSTEM\CurrentControlSet\Control\DeviceGuard\Scenarios\HypervisorEnforcedCodeIntegrity" -Name "Enabled" -Value 1
    Set-RegSafe -Path "HKLM:\SYSTEM\CurrentControlSet\Control\DeviceGuard" -Name "EnableVirtualizationBasedSecurity" -Value 1
    $progressBar.Value = 75
    Stop-Process -Name explorer -Force -ErrorAction SilentlyContinue
    $progressBar.Value = 100
    
    Start-Sleep -Milliseconds 300
    $progressBar.Visible = $false
    $lblStatus.Text = (TT "Κατάσταση: Το Gaming Mode απενεργοποιήθηκε & ο Explorer επανεκκινήθηκε! (Χρειάζεται επανεκκίνηση PC για πλήρη επαναφορά VBS)")
}

