if ($setStyleMethod) { $setStyleMethod.Invoke($global:wingetProgressWrapper, @($flickerFixStyles, $true)) | Out-Null }
$global:wingetProgressWrapper.Tag = [PSCustomObject]@{ Percent = 0; Text = "0%" }
# ΔΙΟΡΘΩΣΗ (bug επιβεβαιωμένα ΠΑΡΕΜΕΝΕ παρά τις προηγούμενες προσπάθειες v1.9.2/v2.0.1 - "μόνο το
# ποσοστό φαίνεται, όχι η πράσινη μπάρα"): η ρίζα ΔΕΝ ήταν έλλειψη Transparent BackColor ή απουσία
# Refresh() - ένα WinForms Label με BackColor=Transparent γίνεται "διάφανο" ΜΟΝΟ ως προς το ΔΙΚΟ ΤΟΥ
# γονικό control (το σκούρο φόντο του wrapper), ΟΧΙ ως προς αδέρφια controls στο ίδιο επίπεδο (την
# πράσινη μπάρα) - το BringToFront() στο label εγγυόταν μάλιστα ότι η μπάρα ΠΟΤΕ δεν θα φαινόταν πίσω
# του. Η μόνη αξιόπιστη λύση σε WinForms είναι ΕΝΑ ενιαίο owner-drawn control που ζωγραφίζει ΚΑΙ τα δύο
# (μπάρα + κείμενο) στο ΙΔΙΟ Paint pass - ίδια τεχνική με το ήδη λειτουργικό κυκλικό κουμπί σάρωσης
# οδηγών (New-DriverScanButton) και τα custom pill-tabs. Τα ξεχωριστά wingetProgressBarFill/
# wingetLblProgressPercent αφαιρέθηκαν - όλοι οι καλούντες ενημερώνουν πλέον το .Tag + Invalidate().
$global:wingetProgressWrapper.Add_Paint({
    param($s, $e)
    $g = $e.Graphics
    $pct = [Math]::Max(0, [Math]::Min(100, $s.Tag.Percent))
    $fillWidth = [int](($pct / 100.0) * $s.Width)
    if ($fillWidth -gt 0) {
        $fillBrush = [System.Drawing.SolidBrush]::new([System.Drawing.Color]::FromArgb(46, 139, 87))
        $g.FillRectangle($fillBrush, 0, 0, $fillWidth, $s.Height)
        $fillBrush.Dispose()
    }
    $txtBrush = [System.Drawing.SolidBrush]::new([System.Drawing.Color]::White)
    $txtFormat = [System.Drawing.StringFormat]::new()
    $txtFormat.Alignment = [System.Drawing.StringAlignment]::Center
    $txtFormat.LineAlignment = [System.Drawing.StringAlignment]::Center
    $g.DrawString($s.Tag.Text, $fontBtnCustom, $txtBrush, [System.Drawing.RectangleF]::new(0, 0, $s.Width, $s.Height), $txtFormat)
    $txtBrush.Dispose()
    $txtFormat.Dispose()
})
$cardOpt3.Controls.Add($global:wingetProgressWrapper)

function Update-WingetProgressBar {
    param([double]$Percent = -1, [string]$Text = $null)
    if ($Percent -ge 0) { $global:wingetProgressWrapper.Tag.Percent = $Percent }
    if ($null -ne $Text) { $global:wingetProgressWrapper.Tag.Text = $Text }
    $global:wingetProgressWrapper.Refresh()
}

$global:wingetChkAll = [System.Windows.Forms.CheckBox]::new()
$global:wingetChkAll.Text = (TT "Επιλογή Όλων")
$global:wingetChkAll.Font = $fontBtnCustom
$global:wingetChkAll.ForeColor = $theme.Text
$global:wingetChkAll.BackColor = [System.Drawing.Color]::Transparent
$global:wingetChkAll.Location = [System.Drawing.Point]::new(575, 337)
$global:wingetChkAll.Size = [System.Drawing.Size]::new(140, 24)
$cardOpt3.Controls.Add($global:wingetChkAll)

# ΝΕΟ: Timer που επεξεργάζεται τη σειρά αναβαθμίσεων ΜΙΑ-ΜΙΑ χωρίς να μπλοκάρει το GUI thread.
# ΠΡΙΝ: το foreach loop έκανε Start-Process -Wait για κάθε εφαρμογή ΑΠΕΥΘΕΙΑΣ στο thread του GUI -
# όσο διαρκούσε η εγκατάσταση κάθε εφαρμογής, ολόκληρο το παράθυρο ήταν "Not Responding".
# ΤΩΡΑ: Start-Process ΧΩΡΙΣ -Wait (PassThru) + Timer που ελέγχει κάθε 500ms αν τελείωσε η τρέχουσα
# εφαρμογή πριν ξεκινήσει την επόμενη - το παράθυρο παραμένει πλήρως αποκρίσιμο καθ' όλη τη διάρκεια.
# ΣΗΜΕΙΩΣΗ: διατηρείται το -NoNewWindow (ΧΩΡΙΣ RedirectStandardOutput) - το redirect ήταν αυτό που
# προηγουμένως έκανε το winget να κολλάει, όχι το -Wait καθαυτό.
$global:wingetUpgradeQueue = @()
$global:wingetUpgradeIndex = 0
$global:wingetUpgradeTotal = 0
$global:wingetUpgradeCurrentProc = $null
$global:wingetUpgradeFailures = @()
function Get-UpgradeCommandForSource {
    # ΝΕΟ v1.8.9 (κατόπιν παροχής πραγματικού κώδικα αναφοράς από τον χρήστη): επιστρέφει (FilePath,
    # ArgumentList) για κάθε υποστηριζόμενο πάροχο πακέτων. Πολλά από αυτά (npm, scoop, gem, composer)
    # είναι .cmd/.ps1 script wrappers στα Windows, ΟΧΙ .exe - χρειάζονται cmd.exe /c για να βρεθούν
    # αξιόπιστα μέσω PATH από το Start-Process.
    param([string]$Source, [string]$Id)
    switch -Regex ($Source) {
        "^winget$" { return @{ FilePath = "winget.exe"; ArgumentList = @("upgrade", "--id", $Id, "--exact", "--silent", "--accept-source-agreements", "--accept-package-agreements", "--disable-interactivity") } }
        "^pip$" { return @{ FilePath = "python.exe"; ArgumentList = @("-m", "pip", "--disable-pip-version-check", "--no-input", "install", "--upgrade", $Id) } }
        "^npm \(global\)$" { return @{ FilePath = "cmd.exe"; ArgumentList = @("/c", "npm", "install", "-g", "$Id@latest") } }
        "^npm$" { return @{ FilePath = "cmd.exe"; ArgumentList = @("/c", "npm", "update", $Id) } }
        "^pnpm \(global\)$" { return @{ FilePath = "cmd.exe"; ArgumentList = @("/c", "pnpm", "update", "-g", $Id) } }
        "^pnpm$" { return @{ FilePath = "cmd.exe"; ArgumentList = @("/c", "pnpm", "update", $Id) } }
        "^chocolatey$" { return @{ FilePath = "choco.exe"; ArgumentList = @("upgrade", $Id, "-y") } }
        "^scoop$" { return @{ FilePath = "cmd.exe"; ArgumentList = @("/c", "scoop", "update", $Id) } }
        "^gem$" { return @{ FilePath = "cmd.exe"; ArgumentList = @("/c", "gem", "update", $Id) } }
        "^cargo$" { return @{ FilePath = "cargo.exe"; ArgumentList = @("install", $Id, "--force") } }
        "^dotnet$" { return @{ FilePath = "dotnet.exe"; ArgumentList = @("tool", "update", "--global", $Id) } }
        "^psmodule$" { return @{ FilePath = "powershell.exe"; ArgumentList = @("-NoProfile", "-Command", "Update-Module -Name '$Id' -Force") } }
        "^composer$" { return @{ FilePath = "cmd.exe"; ArgumentList = @("/c", "composer", "global", "update", $Id) } }
        default { return @{ FilePath = "winget.exe"; ArgumentList = @("upgrade", "--id", $Id, "--exact", "--silent", "--accept-source-agreements", "--accept-package-agreements", "--disable-interactivity") } }
    }
}

$global:wingetUpgradeTimer = [System.Windows.Forms.Timer]::new()
$global:wingetUpgradeTimer.Interval = 500
$global:wingetUpgradeTimer.Add_Tick({
    if ($global:wingetUpgradeCurrentProc -and -not $global:wingetUpgradeCurrentProc.HasExited) { return }
    # ΔΙΟΡΘΩΣΗ v2.0.1 (ΚΡΙΣΙΜΟ): πριν, ο κώδικας ΔΕΝ έλεγχε ΠΟΤΕ το ExitCode της διεργασίας που μόλις
    # τερμάτισε - απλά προχωρούσε στο επόμενο item, θεωρώντας πάντα επιτυχία. Τώρα καταγράφει πραγματική
    # αποτυχία (μη-μηδενικό exit code) ώστε ο τελικός χρήστης να ενημερώνεται σωστά.
    if ($global:wingetUpgradeCurrentProc -and $global:wingetUpgradeCurrentProc.HasExited -and $global:wingetUpgradeCurrentProc.ExitCode -ne 0) {
        $failedName = if ($global:wingetUpgradeIndex -gt 0 -and $global:wingetUpgradeIndex -le $global:wingetUpgradeQueue.Count) { $global:wingetUpgradeQueue[$global:wingetUpgradeIndex - 1].Name } else { "?" }
        $global:wingetUpgradeFailures += $failedName
    }

    # ΔΙΟΡΘΩΣΗ v1.6.2: Πριν το ποσοστό υπολογιζόταν με βάση πόσες εφαρμογές έχουν ΔΡΟΜΟΛΟΓΗΘΕΙ (ξεκινήσει),
    # όχι ΟΛΟΚΛΗΡΩΘΕΙ - για ουρά με 1 μόνο εφαρμογή αυτό εμφάνιζε 100% αμέσως μόλις ξεκινούσε η εγκατάσταση,
    # πριν καν τελειώσει. Το redirect του stdout του winget για πραγματική εσωτερική πρόοδο ΔΕΝ είναι
    # ασφαλές (ήδη τεκμηριωμένο πρόβλημα - το winget "κολλάει" όταν η έξοδός του ανακατευθύνεται), οπότε
    # η πιο τίμια διαθέσιμη λύση είναι το ποσοστό να αντανακλά όσες εφαρμογές έχουν ΠΡΑΓΜΑΤΙΚΑ ολοκληρωθεί.
    $completedCount = $global:wingetUpgradeIndex
    $percent = [int](($completedCount / $global:wingetUpgradeTotal) * 100)
    Update-WingetProgressBar -Percent $percent

    if ($global:wingetUpgradeIndex -ge $global:wingetUpgradeQueue.Count) {
        $global:wingetUpgradeTimer.Stop()
        Update-WingetProgressBar -Percent 100 -Text (TT "100% - Ολοκληρώθηκε!")
        # ΔΙΟΡΘΩΣΗ v2.0.1 (ΚΡΙΣΙΜΟ): πριν το μήνυμα έλεγε πάντα "Ολοκληρώθηκε!" ανεξάρτητα από το αν
        # πραγματικά πέτυχε κάτι - τώρα αναφέρει ειλικρινά ποιες εφαρμογές (αν υπάρχουν) απέτυχαν να
        # ενημερωθούν, ώστε ο χρήστης να μην νομίζει ότι έγινε κάτι που στην πραγματικότητα απέτυχε.
        if ($global:wingetUpgradeFailures.Count -eq 0) {
            if ($global:wingetUpgradeQueue.Count -le 1) {
                Show-CustomMessage -Message "Ολοκληρώθηκε η αναβάθμιση της εφαρμογής!" -Title "Τέλος Εργασίας"
            } else {
                Show-CustomMessage -Message "Ολοκληρώθηκε η μαζική ενημέρωση!" -Title "Τέλος Εργασίας"
            }
        } else {
            $failedList = $global:wingetUpgradeFailures -join ", "
            Show-CustomMessage -Message "$(TT 'Η ενημέρωση απέτυχε για:') $failedList. $(TT 'Ελέγξτε ότι το winget λειτουργεί σωστά (winget source reset --force σε PowerShell) ή δοκιμάστε ξανά.')" -Title (TT "Μερική Αποτυχία") -Type "Error"
        }
        & $script:LoadWingetUpdatesList
        $global:wingetBtnUpdateSelected.Enabled = $true
        $global:wingetChkAll.Enabled = $true
        Update-WingetProgressBar -Percent 0 -Text "0%"
        $global:wingetUpgradeQueue = @()
        $global:wingetUpgradeCurrentProc = $null
        $global:wingetUpgradeFailures = @()
        # ΝΕΟ: καθαρισμός μνήμης μετά από τη βαριά μαζική διεργασία (πρόταση από τον έλεγχο πόρων)
        [System.GC]::Collect()
        [System.GC]::WaitForPendingFinalizers()
        return
    }

    $item = $global:wingetUpgradeQueue[$global:wingetUpgradeIndex]
    # ΔΙΟΡΘΩΣΗ v1.6.2: Το ποσοστό εδώ αναφέρεται στις ΗΔΗ ολοκληρωμένες εφαρμογές (completedCount), το
    # "..." στο τέλος δείχνει ρητά ότι η τρέχουσα είναι ΣΕ ΕΞΕΛΙΞΗ, όχι ήδη έτοιμη.
    Update-WingetProgressBar -Text "$percent% ($completedCount/$($global:wingetUpgradeTotal)) - $(TT 'Αναβάθμιση'): $($item.Name)..."
    $global:wingetUpgradeIndex++

    $wingetArgs = @("upgrade", "--id", "$($item.Id)", "--exact", "--silent", "--accept-source-agreements", "--accept-package-agreements", "--disable-interactivity")
    # ΝΕΟ v1.8.9: Χρήση της κεντρικής Get-UpgradeCommandForSource - υποστηρίζει πλέον και τους 10 νέους
    # παρόχους πακέτων (pip, npm, pnpm, chocolatey, scoop, gem, cargo, dotnet, psmodule, composer), όχι
    # μόνο winget. Το πεδίο Source (προεπιλογή "winget" αν λείπει, για συμβατότητα με παλαιότερα items).
    $itemSource = if ($item.PSObject.Properties["Source"] -and $item.Source) { $item.Source } else { "winget" }
    $upgradeCmd = Get-UpgradeCommandForSource -Source $itemSource -Id $item.Id
    # ΔΙΟΡΘΩΣΗ v2.0.1 (ΚΡΙΣΙΜΟ, χρήστης ανέφερε "λέει ότι εγκαταστάθηκε αλλά στην πραγματικότητα δεν
    # έγινε τίποτα - στην ανανέωση επανεμφανίζονται"): επιβεβαιωμένο από επίσημα GitHub issues του ίδιου
    # του winget-cli project (#3418, discussion #3185): "the winget source isn't initialised" όταν το
    # winget τρέχει σε elevated/Administrator context (η εφαρμογή μας ΠΑΝΤΑ τρέχει elevated) - η εντολή
    # μπορεί να "τερματίσει κανονικά" χωρίς να κάνει ΤΙΠΟΤΑ. Επιπλέον, το -NoNewWindow σε ένα WinForms
    # process (χωρίς δικό του console) μπορεί να προκαλέσει προβλήματα σε ένα console εργαλείο σαν το
    # winget.exe. Διόρθωση: (1) winget source reset πριν το πρώτο item του batch, (2) -WindowStyle Hidden
    # αντί για -NoNewWindow (ίδιο μοτίβο με τις υπόλοιπες background κλήσεις της εφαρμογής), (3) ΠΡΑΓΜΑΤΙΚΟΣ
    # έλεγχος ExitCode μετά την ολοκλήρωση - πριν ο κώδικας ΠΟΤΕ δεν το ήλεγχε, θεωρώντας πάντα επιτυχία.
    if ($itemSource -eq "winget" -and $global:wingetUpgradeIndex -eq 1) {
        try { Start-Process -FilePath "winget.exe" -ArgumentList "source", "reset", "--force" -WindowStyle Hidden -Wait -ErrorAction SilentlyContinue } catch {}
    }
    try {
        $global:wingetUpgradeCurrentProc = Start-Process -FilePath $upgradeCmd.FilePath -ArgumentList $upgradeCmd.ArgumentList -WindowStyle Hidden -PassThru -ErrorAction Stop
    } catch {
        # Παράκαμψη μεμονωμένου σφάλματος εφαρμογής για να συνεχιστεί η μαζική αναβάθμιση
        $global:wingetUpgradeCurrentProc = $null
        $global:wingetUpgradeFailures += $item.Name
    }
})

# ΝΕΟ v1.8.8 (αναφορά χρήστη: "το MS Store είχε ενημερώσεις που το winget δεν ανίχνευσε"): επιβεβαιωμένο,
# τεκμηριωμένο, γνωστό όριο του ΙΔΙΟΥ του winget (GitHub microsoft/winget-cli #2374, #5299 - "MS Store
# shows an update, but Winget does not" / "winget upgrade ignores all packages from source msstore"),
# ενεργό από το 2022 έως σήμερα - ΔΕΝ διορθώνεται από τον κώδικα της εφαρμογής, αφού βρίσκεται στο ίδιο το
# backend του winget/msstore REST source. Προστέθηκε αξιόπιστη εναλλακτική: επίσημο URI scheme του
# Windows (ms-windows-store://downloadsandupdates) που ανοίγει απευθείας τη σελίδα ενημερώσεων του ίδιου
# του Microsoft Store - 100% επίσημος μηχανισμός, καμία εξάρτηση στο ελαττωματικό winget/msstore κανάλι.
# ΔΙΟΡΘΩΣΗ v1.8.9 (ΚΡΙΣΙΜΟ, χρήστης εντόπισε "κουμπί πίσω από τη μπάρα προόδου"): επιβεβαιώθηκε ότι
# αυτό το κουμπί ΕΠΙΚΑΛΥΠΤΟΤΑΝ ΠΛΗΡΩΣ με το wingetProgressWrapper (και οι δύο στο X=20, Y~330-335) -
# δικό μου positioning bug όταν προστέθηκε το κουμπί στο v1.8.8, χωρίς έλεγχο των ήδη υπαρχουσών θέσεων.
# Μετακινήθηκε σε ΔΙΚΗ ΤΟΥ, καθαρή γραμμή κάτω από όλα τα υπόλοιπα στοιχεία (η κάρτα μεγάλωσε κατά 40px
# για να χωρέσει).
# ΕΝΙΣΧΥΣΗ v1.9.0 (κατόπιν κώδικα αναφοράς - WMT): προστέθηκε ΠΡΑΓΜΑΤΙΚΟ trigger σάρωσης μέσω του
# επίσημου MDM_EnterpriseModernAppManagement_AppManagement01 CIM provider (UpdateScanMethod) - το ΙΔΙΟ
# μηχανισμό που χρησιμοποιεί το ίδιο το Store όταν ο χρήστης πατά "Check for updates" εκεί. ΣΗΜΑΝΤΙΚΟ: η
# μέθοδος αυτή ΔΕΝ επιστρέφει λίστα ενημερώσεων (μόνο ενεργοποιεί σάρωση στο παρασκήνιο) - τα αποτελέσματα
# εμφανίζονται ΜΕΣΑ στο ίδιο το Store app, γι' αυτό το κουμπί ΠΑΡΑΜΕΝΕΙ απαραίτητο (δεν αντικαθίσταται),
# απλά τώρα ενεργοποιεί την πραγματική σάρωση πριν ανοίξει το Store, αντί απλώς να το ανοίγει.
# ΔΙΟΡΘΩΣΗ v1.9.3 (χρήστης εντόπισε κομμένο κείμενο): πλάτος αυξήθηκε (280->380) - το κείμενο "Έλεγχος
# Ενημερώσεων μέσω Microsoft Store" (και οι μεταφράσεις του) χρειάζονταν περισσότερο χώρο. Επανακεντράρωση
# (X: 375->325, δεδομένου του νέου πλάτους, μέσα στην κάρτα 1030px).
$global:btnCheckMsStore = Helper-CreateButton (TT "Έλεγχος Ενημερώσεων μέσω Microsoft Store") 325 380 380 36 ([System.Drawing.Color]::FromArgb(90, 90, 100)) {
    try {
        $appMgmt = Get-CimInstance -Namespace "Root\cimv2\mdm\dmmap" -ClassName "MDM_EnterpriseModernAppManagement_AppManagement01" -ErrorAction Stop | Select-Object -First 1
        if ($appMgmt) { Invoke-CimMethod -InputObject $appMgmt -MethodName "UpdateScanMethod" -ErrorAction SilentlyContinue | Out-Null }
    } catch {}
    Start-Process "ms-windows-store://downloadsandupdates"
} $cardOpt3 $true (TT "Ενεργοποιεί πλήρη σάρωση ενημερώσεων μέσω των επίσημων μηχανισμών των Windows και ανοίγει το Microsoft Store για επιβεβαίωση - οι ενημερώσεις Store apps εμφανίζονται ήδη στη λίστα παραπάνω μέσω του επίσημου Store CLI.")

$global:wingetBtnUpdateSelected = Helper-CreateButton (TT "Αναβάθμιση Επιλεγμένων") 755 330 255 36 ([System.Drawing.Color]::FromArgb(16, 124, 65)) {
    $selectedItems = @($global:wingetRowItems | Where-Object { $_.CheckBox.Checked })
    if ($selectedItems.Count -eq 0) {
        Show-CustomMessage -Message "Δεν έχετε επιλέξει καμία εφαρμογή προς αναβάθμιση." -Title "Προσοχή" -Type "Info"
        return
    }

    $global:wingetBtnUpdateSelected.Enabled = $false
    $global:wingetChkAll.Enabled = $false

    $global:wingetUpgradeQueue = $selectedItems
    $global:wingetUpgradeTotal = $selectedItems.Count
    $global:wingetUpgradeIndex = 0
    $global:wingetUpgradeCurrentProc = $null
    $global:wingetUpgradeFailures = @()
    $global:wingetUpgradeTimer.Start()
} $cardOpt3 $true

$global:wingetRowItems = @()

# ΝΕΟ: Timer που επιτηρεί την ασύγχρονη φόρτωση της λίστας winget χωρίς να μπλοκάρει το GUI thread.
$global:wingetRefreshState = $null
$global:wingetRefreshTimer = [System.Windows.Forms.Timer]::new()
$global:wingetRefreshTimer.Interval = 400
$global:wingetRefreshTimer.Add_Tick({
    if (-not $global:wingetRefreshState) { $global:wingetRefreshTimer.Stop(); return }
    if (-not $global:wingetRefreshState.Process.HasExited) { return }
    $global:wingetRefreshTimer.Stop()
    $rawText = @()
    if (Test-Path $global:wingetRefreshState.OutFile) {
        $rawText = @(Get-Content -Path $global:wingetRefreshState.OutFile -ErrorAction SilentlyContinue)
        Remove-Item -Path $global:wingetRefreshState.OutFile -Force -ErrorAction SilentlyContinue
    }
    # ΝΕΟ v1.8.6: Καθαρισμός του προσωρινού .ps1 αρχείου σεναρίου (ίδιο μοτίβο με K-Lite/driver scan).
    if (Test-Path $global:wingetRefreshState.ScriptFile) {
        Remove-Item -Path $global:wingetRefreshState.ScriptFile -Force -ErrorAction SilentlyContinue
    }
    $global:wingetRefreshState = $null
    Complete-WingetListLoad -RawText $rawText
    # ΝΕΟ: καθαρισμός μνήμης μετά από τη βαριά διεργασία (πρόταση από τον έλεγχο πόρων)
    [System.GC]::Collect()
    [System.GC]::WaitForPendingFinalizers()
})

$script:LoadWingetUpdatesList = {
    # ΔΙΟΡΘΩΣΗ: Δεν υπήρχε έλεγχος αν το winget.exe υπάρχει καν στο σύστημα - σε μηχανή χωρίς winget
    # (σπάνιο αλλά πιθανό σε παλιότερα/server Windows) η κλήση "winget source update" θα πετούσε
    # ανεξέλεγκτο σφάλμα "term not recognized".
    if (-not (Get-Command winget.exe -ErrorAction SilentlyContinue)) {
        $global:wingetLoadingLabel.Text = (TT "Το winget δεν βρέθηκε στο σύστημα. Εγκαταστήστε το 'App Installer' από το Microsoft Store.")
        $global:wingetBtnUpdateSelected.Enabled = $false
        $global:wingetChkAll.Enabled = $false
        return
    }

    $global:wingetPanelList.Controls.Clear()
    $global:wingetRowItems = @()
    $global:wingetLoadingLabel.Text = (TT "Συγχρονισμός πηγών (Winget & MS Store) & φόρτωση λίστας ενημερώσεων...")

    # ===== ΝΕΟ (Async φόρτωση - ΔΕΝ παγώνει πλέον το παράθυρο) =====
    # ΠΡΙΝ: οι κλήσεις "winget source update" / "winget upgrade" γίνονταν ΑΠΕΥΘΕΙΑΣ στο thread του GUI,
    # μπλοκάροντας ολόκληρη την εφαρμογή (Not Responding) για όσα δευτερόλεπτα χρειάζεται το winget.
    # ΤΩΡΑ: το winget τρέχει σε ξεχωριστή (ελαχιστοποιημένη, όχι κρυφή - μάθαμε από προηγούμενο bug ότι
    # η πλήρης απόκρυψη κονσόλας σπάει το winget) διεργασία PowerShell που γράφει το αποτέλεσμα σε
    # προσωρινό αρχείο, ενώ ένα System.Windows.Forms.Timer ελέγχει κάθε 400ms αν τελείωσε - το κύριο
    # παράθυρο παραμένει πλήρως αποκρίσιμο (μπορείτε να αλλάζετε καρτέλα, να μετακινείτε το παράθυρο κ.λπ.)
    # ΝΕΟ v1.7.5: Προστέθηκε ΞΕΧΩΡΙΣΤΗ κλήση "winget upgrade --source msstore" πέρα από την κανονική -
    # το βασικό "winget upgrade" ΚΑΝΟΝΙΚΑ περιλαμβάνει και τις πηγές Microsoft Store, αλλά σε ορισμένες
    # διαμορφώσεις συστήματος (π.χ. αν η πηγή msstore δεν είναι ενημερωμένη/ενεργή) μπορεί να μην
    # εμφανίζει ενημερώσεις εφαρμογών Store - η ρητή δεύτερη κλήση εξασφαλίζει ότι δεν χάνονται.
    $tempOut = Join-Path $env:TEMP "OptimizerWingetList_$([guid]::NewGuid().ToString('N')).txt"
    # ΔΙΟΡΘΩΣΗ v1.8.1: Προστέθηκε --include-unknown - τεκμηριωμένη επίσημη σημαία του winget: χωρίς
    # αυτήν, εφαρμογές των οποίων η "τρέχουσα έκδοση" δεν είναι με σιγουριά ανιχνεύσιμη από το winget
    # αποκρύπτονται εντελώς από τη λίστα ενημερώσεων (ακόμα κι αν υπάρχει πράγματι διαθέσιμη ενημέρωση) -
    # πιθανή πρόσθετη αιτία του "καμία ενημέρωση" ενώ στην πραγματικότητα υπάρχουν.
    #
    # ΔΙΟΡΘΩΣΗ v1.8.6 (ΚΡΙΣΙΜΟ, αναφορά χρήστη - "winget εξακολουθεί να μην δείχνει ενημερώσεις"): αυτό
    # το σημείο ΞΕΦΥΓΕ από τη γενική μετάβαση σε -EncodedCommand/αρχείο-σεναρίου (βλ. σχόλιο γραμμή 54) -
    # χρησιμοποιούσε ΑΚΟΜΑ -Command "..." με ΔΙΠΛΟ επίπεδο εμφωλευμένων εισαγωγικών (το $wingetCmd περιέχει
    # ΔΙΚΑ ΤΟΥ escaped εισαγωγικά `"...`", και ΟΛΟΚΛΗΡΟ αυτό περνούσε ΞΑΝΑ μέσα σε άλλο escaped εισαγωγικό
    # `"$wingetCmd`" στο -ArgumentList). Αυτό το διπλό επίπεδο εμφώλευσης είναι ακριβώς το ασταθές μοτίβο
    # που το -EncodedCommand/αρχείο-σεναρίου αποφεύγει - το tokenization της γραμμής εντολών των Windows
    # μπορεί εύκολα να χαλάσει σε τέτοιο βάθος εμφώλευσης, οδηγώντας σε ΚΑΤΕΣΤΡΑΜΜΕΝΗ/ελλιπή εντολή μέσα
    # στη νέα διεργασία - πιθανότατα η ΠΡΑΓΜΑΤΙΚΗ, βαθύτερη αιτία του προβλήματος (πιο θεμελιώδης από το
    # ANSI-stripping της ίδιας έκδοσης, το οποίο παραμένει ορθό αλλά ανεπαρκές από μόνο του). Αντικαταστάθηκε
    # με το ίδιο, ήδη αποδεδειγμένα αξιόπιστο πρότυπο αρχείου-σεναρίου που χρησιμοποιείται στο K-Lite και
    # στη σάρωση drivers - μηδενική εμφώλευση εισαγωγικών στη γραμμή εντολών.
    # ΔΙΟΡΘΩΣΗ v1.8.9: Μετατράπηκε σε single-quoted heredoc (@'...'@) + .Replace() - ίδιο ασφαλές
    # πρότυπο με driver/storage scan. Μηδενικό ρίσκο εσφαλμένου interpolation/escaping σε heredoc με
    # ΠΟΛΛΕΣ μεταβλητές μέσα (κρίσιμο μάθημα από προηγούμενα, πραγματικά bugs σε αυτή την εφαρμογή).
    #
    # ΝΕΟ v1.8.9 (κατόπιν παροχής πραγματικού κώδικα αναφοράς από τον χρήστη - WMT-GUI.ps1): πέρα από
    # winget/msstore, ελέγχονται τώρα ΚΑΙ ενημερώσεις από: pip, npm, pnpm, Chocolatey, Scoop, RubyGems,
    # Cargo, .NET global tools, PowerShell modules, Composer - όποιος από αυτούς τους διαχειριστές
    # πακέτων υπάρχει εγκατεστημένος στο σύστημα. Κάθε provider είναι πλήρως ανεξάρτητος (try/catch) -
    # η αποτυχία ενός δεν εμποδίζει τους υπόλοιπους.
    $wingetScriptContent = @'
$ErrorActionPreference = "Continue"
winget source update --disable-interactivity *> $null
winget upgrade --include-unknown --accept-source-agreements --disable-interactivity | Out-File -FilePath "OUTFILE_PLACEHOLDER" -Encoding utf8

$otherPmResults = New-Object System.Collections.ArrayList

# --- MICROSOFT STORE (v1.9.6: ΑΝΤΙΚΑΤΑΣΤΑΘΗΚΕ το παλιό "winget upgrade --source msstore" - επιβεβαιωμένο,
# τεκμηριωμένο όριο του winget στην ανίχνευση ενημερώσεων Store apps. ΝΕΟ mechanism: το επίσημο "store.exe"
# CLI εργαλείο (ήδη ενσωματωμένο στα σύγχρονα Windows 11, καμία εγκατάσταση απαιτούμενη) με την εντολή
# "store updates" - πολύ πιο αξιόπιστη πηγή, δεδομένου ότι είναι το ΙΔΙΟ εργαλείο που χρησιμοποιεί το Store
# εσωτερικά. Η λογική ανίχνευσης στηλών (header-based) βασίζεται σε επαληθευμένο κώδικα αναφοράς.)
try {
    if (Get-Command store -ErrorAction SilentlyContinue) {
        $storeInfo = New-Object System.Diagnostics.ProcessStartInfo
        $storeInfo.FileName = "store"
        $storeInfo.Arguments = "updates"
        $storeInfo.RedirectStandardOutput = $true
        $storeInfo.RedirectStandardError = $true
        $storeInfo.RedirectStandardInput = $true
        $storeInfo.UseShellExecute = $false
        $storeInfo.CreateNoWindow = $true
        # ΔΙΟΡΘΩΣΗ v1.9.2 (ΚΡΙΣΙΜΟ, επιβεβαιωμένο από στιγμιότυπο χρήστη - κατεστραμμένο κείμενο "έΦΓ" και
        # χαλασμένοι χαρακτήρες πλαισίου): ξέχασα να ορίσω ρητά το StandardOutputEncoding όταν απλοποίησα
        # τον κώδικα αναφοράς (το WMT ΕΙΧΕ αυτή τη ρύθμιση) - χωρίς αυτήν, η .NET διαβάζει με το
        # προεπιλεγμένο OEM codepage του συστήματος (σε ελληνικά Windows: CP737), ενώ το store.exe γράφει
        # σε UTF-8 - η αναντιστοιχία codepage προκαλεί ακριβώς αυτό το mojibake (κατεστραμμένο κείμενο).
        $storeInfo.StandardOutputEncoding = [System.Text.UTF8Encoding]::new($false)
        $storeInfo.StandardErrorEncoding = [System.Text.UTF8Encoding]::new($false)
        $storeProc = [System.Diagnostics.Process]::Start($storeInfo)
        try { $storeProc.StandardInput.WriteLine("n"); $storeProc.StandardInput.Close() } catch {}
        if ($storeProc.WaitForExit(60000)) {
            $storeOut = $storeProc.StandardOutput.ReadToEnd()
            # Αφαίρεση ANSI escape sequences - ίδιο τεκμηριωμένο μάθημα με το winget parsing παραπάνω.
            $storeClean = [regex]::Replace($storeOut, "`e\[[0-9;]*[a-zA-Z]", "")
            $sVertical = [string][char]0x2502
            $sHeaders = $null
            foreach ($sLine in ($storeClean -split "`r?`n")) {
                $sLineTrim = $sLine.Trim()
                if ([string]::IsNullOrWhiteSpace($sLineTrim)) { continue }
                if ($sLineTrim -match "(?i)^(checking|usage:|commands?:|options?:|examples?:|store cli)") { continue }
                if ($sLineTrim -match "(?i)^(no updates|all apps are up to date|your apps are up to date)") { continue }

                $sCols = @()
                if ($sLineTrim.Contains($sVertical)) {
                    $sRawCols = $sLineTrim -split [regex]::Escape($sVertical)
                    if ($sRawCols.Count -gt 2) {
                        for ($sci = 1; $sci -lt ($sRawCols.Count - 1); $sci++) {
                            $sVal = $sRawCols[$sci].Trim()
                            if ($sVal -ne "") { $sCols += $sVal }
                        }
                    }
                } elseif ($sLineTrim -match "\s{2,}") {
                    $sCols = @($sLineTrim -split "\s{2,}" | ForEach-Object { $_.Trim() } | Where-Object { $_ -ne "" })
                }
                if ($sCols.Count -lt 2) { continue }

                $sLowerCols = @($sCols | ForEach-Object { $_.ToLowerInvariant() })
                if ($sLowerCols -contains "name" -or $sLowerCols -contains "app" -or $sLowerCols -contains "title") {
                    $sHeaders = $sCols
                    continue
                }

                $sNameIdx = 0
                $sVerIdx = -1
                $sAvailIdx = -1
                if ($sHeaders) {
                    for ($hi = 0; $hi -lt $sHeaders.Count; $hi++) {
                        if ($sHeaders[$hi] -match "(?i)^(name|app|title)$") { $sNameIdx = $hi }
                        elseif ($sHeaders[$hi] -match "(?i)installed|current|^version$") { $sVerIdx = $hi }
                        elseif ($sHeaders[$hi] -match "(?i)available|latest|new\s+version|update") { $sAvailIdx = $hi }
                    }
                }
                if ($sAvailIdx -eq $sVerIdx) { $sAvailIdx = -1 }

                $sName = if ($sNameIdx -lt $sCols.Count) { $sCols[$sNameIdx] } else { "" }
                # ΔΙΟΡΘΩΣΗ v1.9.2 (δεύτερη, αμυντική γραμμή προστασίας): αφαίρεση Unicode box-drawing
                # χαρακτήρων (U+2500-U+257F, χρησιμοποιούνται για πλαίσια πίνακα σε CLI εργαλεία) και
                # κάθε "σκουπίδι" πρόθεμα πριν το πρώτο πραγματικό γράμμα/ψηφίο - προστατεύει από
                # οποιοδήποτε υπολειπόμενο πρόβλημα κωδικοποίησης, ανεξάρτητα από την αιτία του.
                $sName = [regex]::Replace($sName, '[\u2500-\u257F]', '')
                $sName = [regex]::Replace($sName, '^[^\p{L}\p{Nd}]+', '')
                $sName = $sName.Trim()
                if ([string]::IsNullOrWhiteSpace($sName) -or $sName -match "(?i)^(name|app|title)$") { continue }
                $sVer = if ($sVerIdx -ge 0 -and $sVerIdx -lt $sCols.Count) { $sCols[$sVerIdx] } else { "?" }
                $sAvail = if ($sAvailIdx -ge 0 -and $sAvailIdx -lt $sCols.Count) { $sCols[$sAvailIdx] } else { "Update available" }

                [void]$otherPmResults.Add([PSCustomObject]@{ Source = "msstore"; Name = $sName; Id = $sName; Version = $sVer; Available = $sAvail })
            }
        } else {
            try { $storeProc.Kill() } catch {}
        }
    }
} catch {}

# --- PIP ---
try {
    if (Get-Command python -ErrorAction SilentlyContinue) {
        $pipJson = & python -m pip --disable-pip-version-check --no-input --timeout 20 --retries 1 list --outdated --format=json 2>$null
        if ($pipJson -and ([string]$pipJson).Trim().StartsWith("[")) {
            foreach ($pkg in ($pipJson | ConvertFrom-Json)) {
                [void]$otherPmResults.Add([PSCustomObject]@{ Source = "pip"; Name = $pkg.name; Id = $pkg.name; Version = $pkg.version; Available = $pkg.latest_version })
            }
        }
    }
} catch {}

# --- NPM (local + global) ---
try {
    if (Get-Command npm -ErrorAction SilentlyContinue) {
        $npmJson = cmd /c "npm outdated --json 2>nul"
        if ($npmJson -and ([string]$npmJson).Trim().StartsWith("{")) {
            $npmObj = $npmJson | ConvertFrom-Json
            foreach ($k in $npmObj.PSObject.Properties.Name) {
                $o = $npmObj.$k
                [void]$otherPmResults.Add([PSCustomObject]@{ Source = "npm"; Name = $k; Id = $k; Version = $o.current; Available = $o.latest })
            }
        }
        $npmJsonG = cmd /c "npm outdated -g --json 2>nul"
        if ($npmJsonG -and ([string]$npmJsonG).Trim().StartsWith("{")) {
            $npmObjG = $npmJsonG | ConvertFrom-Json
            foreach ($k in $npmObjG.PSObject.Properties.Name) {
                $o = $npmObjG.$k
                [void]$otherPmResults.Add([PSCustomObject]@{ Source = "npm (global)"; Name = $k; Id = $k; Version = $o.current; Available = $o.latest })
            }
        }
    }
} catch {}

# --- PNPM (local + global) ---
try {
    if (Get-Command pnpm -ErrorAction SilentlyContinue) {
        $pnpmJson = cmd /c "pnpm outdated --format json 2>nul"
        if ($pnpmJson -and ([string]$pnpmJson).Trim().StartsWith("[")) {
            foreach ($pkg in ($pnpmJson | ConvertFrom-Json)) {
                [void]$otherPmResults.Add([PSCustomObject]@{ Source = "pnpm"; Name = $pkg.name; Id = $pkg.name; Version = $pkg.current; Available = $pkg.latest })
            }
        }
        $pnpmJsonG = cmd /c "pnpm outdated -g --format json 2>nul"
        if ($pnpmJsonG -and ([string]$pnpmJsonG).Trim().StartsWith("[")) {
            foreach ($pkg in ($pnpmJsonG | ConvertFrom-Json)) {
                [void]$otherPmResults.Add([PSCustomObject]@{ Source = "pnpm (global)"; Name = $pkg.name; Id = $pkg.name; Version = $pkg.current; Available = $pkg.latest })
            }
        }
    }
} catch {}

# --- CHOCOLATEY ---
try {
    if (Get-Command choco -ErrorAction SilentlyContinue) {
        $chocoOut = & choco outdated -r 2>$null
        foreach ($line in ($chocoOut -split "`r`n")) {
            if (-not $line) { continue }
            $parts = $line -split "\|"
            if ($parts.Count -ge 4) {
                [void]$otherPmResults.Add([PSCustomObject]@{ Source = "chocolatey"; Name = $parts[0]; Id = $parts[0]; Version = $parts[1]; Available = $parts[2] })
            }
        }
    }
} catch {}

# --- SCOOP ---
try {
    if (Get-Command scoop -ErrorAction SilentlyContinue) {
        $scoopOut = cmd /c "scoop status" 2>$null
        foreach ($line in ($scoopOut -split "`r`n")) {
            $line = $line.Trim()
            if ([string]::IsNullOrWhiteSpace($line) -or $line -match "^Name\s+Version" -or $line -match "^----" -or $line -match "up to date") { continue }
            if ($line -match '^(\S+)\s+(\S+)\s+(\S+)') {
                [void]$otherPmResults.Add([PSCustomObject]@{ Source = "scoop"; Name = $matches[1]; Id = $matches[1]; Version = $matches[2]; Available = $matches[3] })
            }
        }
    }
} catch {}

# --- RUBY GEMS ---
try {
    if (Get-Command gem -ErrorAction SilentlyContinue) {
        $gemOut = cmd /c "gem outdated" 2>$null
        foreach ($line in ($gemOut -split "`r`n")) {
            if ($line -match '^(\S+)\s+\(([\d\.]+)\s+<\s+([\d\.]+)\)') {
                [void]$otherPmResults.Add([PSCustomObject]@{ Source = "gem"; Name = $matches[1]; Id = $matches[1]; Version = $matches[2]; Available = $matches[3] })
            }
        }
    }
} catch {}

# --- CARGO --- (το cargo δεν έχει ενσωματωμένη έκδοση "τελευταία διαθέσιμη" χωρίς plugin - δείχνει μόνο εγκατεστημένη έκδοση, "Available" ερωτηματικό)
try {
    if (Get-Command cargo -ErrorAction SilentlyContinue) {
        $cargoOut = cmd /c "cargo install --list" 2>$null
        foreach ($line in ($cargoOut -split "`r`n")) {
            if ($line -match '^([a-zA-Z0-9_\-]+)\s+v([\d\.]+):') {
                [void]$otherPmResults.Add([PSCustomObject]@{ Source = "cargo"; Name = $matches[1]; Id = $matches[1]; Version = $matches[2]; Available = "?" })
            }
        }
    }
} catch {}

# --- .NET GLOBAL TOOLS ---
try {
    if (Get-Command dotnet -ErrorAction SilentlyContinue) {
        $dotnetOut = & dotnet tool list --global 2>$null
        foreach ($line in ($dotnetOut -split "`r?`n")) {
            $trimmed = $line.Trim()
            if ([string]::IsNullOrWhiteSpace($trimmed) -or $trimmed -match "(?i)^Package\s+Id" -or $trimmed -match "^-+") { continue }
            $parts = @($trimmed -split "\s+" | Where-Object { $_ })
            if ($parts.Count -ge 2) {
                [void]$otherPmResults.Add([PSCustomObject]@{ Source = "dotnet"; Name = $parts[0]; Id = $parts[0]; Version = $parts[1]; Available = "?" })
            }
        }
    }
} catch {}

# --- POWERSHELL MODULES ---
try {
    if (Get-Command Get-InstalledModule -ErrorAction SilentlyContinue) {
        $installedModules = @(Get-InstalledModule -ErrorAction SilentlyContinue)
        foreach ($mod in $installedModules) {
            try {
                $found = Find-Module -Name $mod.Name -Repository PSGallery -ErrorAction SilentlyContinue
                if ($found -and ([version]$found.Version -gt [version]$mod.Version)) {
                    [void]$otherPmResults.Add([PSCustomObject]@{ Source = "psmodule"; Name = $mod.Name; Id = $mod.Name; Version = $mod.Version; Available = $found.Version })
                }
            } catch {}
        }
    }
} catch {}

# --- COMPOSER ---
try {
    if (Get-Command composer -ErrorAction SilentlyContinue) {
        $composerJson = cmd /c "composer global outdated --format=json --no-interaction 2>nul"
        if ($composerJson -and ([string]$composerJson).Trim().StartsWith("{")) {
            $composerObj = $composerJson | ConvertFrom-Json
            $pkgs = if ($composerObj.PSObject.Properties["installed"]) { $composerObj.installed } else { @() }
            foreach ($pkg in $pkgs) {
                [void]$otherPmResults.Add([PSCustomObject]@{ Source = "composer"; Name = $pkg.name; Id = $pkg.name; Version = $pkg.version; Available = $pkg.latest })
            }
        }
    }
} catch {}

Add-Content -Path "OUTFILE_PLACEHOLDER" -Value ""
Add-Content -Path "OUTFILE_PLACEHOLDER" -Value "--- OTHERPM_JSON ---"
($otherPmResults | ConvertTo-Json -Depth 4 -Compress) | Out-File -FilePath "OUTFILE_PLACEHOLDER" -Encoding utf8 -Append
'@
    $wingetScriptContent = $wingetScriptContent.Replace("OUTFILE_PLACEHOLDER", $tempOut)
    $wingetScriptFile = Join-Path $env:TEMP "OptimizerWingetListScript_$([guid]::NewGuid().ToString('N')).ps1"
    Set-Content -Path $wingetScriptFile -Value $wingetScriptContent -Encoding utf8
    try {
        $proc = Start-Process -FilePath "powershell.exe" -ArgumentList "-NoProfile -ExecutionPolicy Bypass -File `"$wingetScriptFile`"" -WindowStyle Minimized -PassThru -ErrorAction Stop
    } catch {
        $global:wingetLoadingLabel.Text = "$(TT 'Αποτυχία εκκίνησης winget'): $($_.Exception.Message)"
        return
    }

    $global:wingetRefreshState = [PSCustomObject]@{ Process = $proc; OutFile = $tempOut; ScriptFile = $wingetScriptFile }
    $global:wingetRefreshTimer.Start()
}

# ΝΕΟ: Η ολοκλήρωση της ανάλυσης/εμφάνισης αποτελεσμάτων, διαχωρισμένη σε ξεχωριστή συνάρτηση ώστε να
# καλείται είτε από το Timer (async φόρτωση) όσο και -αν ποτέ χρειαστεί- συγχρονισμένα.
function Complete-WingetListLoad {
    param([string[]]$RawText)

    # ΔΙΟΡΘΩΣΗ v2.0.1 (χρήστης εντόπισε "η μπάρα κύλισης της καρτέλας Βελτιστοποίηση πηγαίνει τέρμα κάτω
    # στους Drivers όταν γίνεται η ενημέρωση"): πιθανή αιτία - όταν αναδημιουργούνται τα controls της
    # λίστας (Controls.Clear() + re-add), το WinForms μπορεί αυτόματα να δώσει Focus σε κάποιο άλλο
    # control παρακάτω στην ίδια scrollable περιοχή, προκαλώντας αυτόματο scroll-into-view. Αποθηκεύεται
    # η τρέχουσα θέση κύλισης και επαναφέρεται αμέσως μετά (με μικρή καθυστέρηση ώστε να προλάβει τυχόν
    # αυτόματο scroll που συμβαίνει κατά το layout pass, μετά την επιστροφή της συνάρτησης).
    $savedScrollPos = $global:scrollPanelOptimization.AutoScrollPosition
    $savedScrollX = [Math]::Abs($savedScrollPos.X)
    $savedScrollY = [Math]::Abs($savedScrollPos.Y)
    $restoreScrollTimer = [System.Windows.Forms.Timer]::new()
    $restoreScrollTimer.Interval = 50
    $restoreScrollTimer.Add_Tick({
        $global:scrollPanelOptimization.AutoScrollPosition = [System.Drawing.Point]::new($savedScrollX, $savedScrollY)
        $restoreScrollTimer.Stop()
        $restoreScrollTimer.Dispose()
    }.GetNewClosure())
    $restoreScrollTimer.Start()

    # ΔΙΟΡΘΩΣΗ v1.8.1 (αναφορά χρήστη: "λέει καμία ενημέρωση ενώ υπάρχουν"): τεκμηριωμένο, γνωστό bug
    # του ίδιου του winget (GitHub microsoft/winget-cli #2582) - όταν η έξοδός του ανακατευθύνεται σε
    # αρχείο (όπως κάνουμε εδώ), οι κωδικοί ANSI της γραφικής μπάρας προόδου δεν αφαιρούνται πάντα και
    # καταλήγουν ως "θόρυβος" μέσα στο κείμενο - αυτό μπορούσε να χαλάσει την αναγνώριση της κεφαλίδας
    # πίνακα ή/και τη θέση των στηλών. Προστέθηκε ρητή αφαίρεση ANSI escape sequences σε ΚΑΘΕ γραμμή πριν
    # από οποιαδήποτε ανάλυση.
    $RawText = @($RawText | ForEach-Object { $_ -replace "`e\[[0-9;]*[a-zA-Z]", "" })

    # ΔΙΟΡΘΩΣΗ v1.7.5: Η έξοδος περιέχει πλέον ΔΥΟ πίνακες (κανονικό winget upgrade + ξεχωριστό
    # "--source msstore" για εφαρμογές Microsoft Store) χωρισμένους με τον δείκτη "--- MSSTORE ---".
    # Ο παλιός κώδικας σταματούσε στο ΠΡΩΤΟ header match αλλά συνέχιζε να διαβάζει ΓΡΑΜΜΕΣ μέχρι το τέλος
    # του αρχείου - θα προσπαθούσε να αναλύσει τον δείκτη και το 2ο header ως δεδομένα, χαλώντας τη λίστα.
    # Τώρα κάθε πίνακας αναλύεται ΞΕΧΩΡΙΣΤΑ (ίδια λογική στηλών-βάσει-θέσης), με αφαίρεση διπλότυπων Id.
    $splitIndex = -1
    for ($i = 0; $i -lt $RawText.Count; $i++) {
        if ($RawText[$i] -match "^--- MSSTORE ---$") { $splitIndex = $i; break }
    }
    # ΝΕΟ v1.8.9: Τρίτο section "--- OTHERPM_JSON ---" με τα αποτελέσματα από τους 10 επιπλέον
    # παρόχους πακέτων (pip/npm/pnpm/chocolatey/scoop/gem/cargo/dotnet/psmodule/composer), σε JSON
    # αντί για πίνακα-κειμένου (κάθε provider έχει διαφορετική εγγενή μορφή εξόδου, το JSON είναι το
    # κοινό, αξιόπιστο ενδιάμεσο format που ήδη επιλέγω σε άλλα σημεία της εφαρμογής).
    $otherPmIndex = -1
    for ($i = 0; $i -lt $RawText.Count; $i++) {
        if ($RawText[$i] -match "^--- OTHERPM_JSON ---$") { $otherPmIndex = $i; break }
    }
    if ($splitIndex -ge 0) {
        $section1 = $RawText[0..($splitIndex - 1)]
        $msstoreEnd = if ($otherPmIndex -ge 0) { $otherPmIndex - 1 } else { $RawText.Count - 1 }
        $section2 = if ($msstoreEnd -ge ($splitIndex + 1)) { $RawText[($splitIndex + 1)..$msstoreEnd] } else { @() }
    } else {
        $wingetEnd = if ($otherPmIndex -ge 0) { $otherPmIndex - 1 } else { $RawText.Count - 1 }
        $section1 = if ($wingetEnd -ge 0) { $RawText[0..$wingetEnd] } else { @() }
        $section2 = @()
    }
    $otherPmJsonText = ""
    if ($otherPmIndex -ge 0 -and ($otherPmIndex + 1) -lt $RawText.Count) {
        $otherPmJsonText = ($RawText[($otherPmIndex + 1)..($RawText.Count - 1)] -join "")
    }

    function Parse-WingetTableSection {
        param([string[]]$Lines)
        $result = @()
        $headerIndex = -1
        for ($i = 0; $i -lt $Lines.Count; $i++) {
            # ΔΙΟΡΘΩΣΗ v1.8.1: Το regex χαλάρωσε (επιτρέπει προαιρετικό κενό/whitespace πριν το "Name")
            # ώστε να μην αποτυγχάνει η αναγνώριση αν έμεινε έστω και ένας μεμονωμένος κενός χαρακτήρας
            # από την ANSI αφαίρεση παραπάνω.
            if ($Lines[$i] -match "^\s*Name\s+Id\s+Version") { $headerIndex = $i; break }
        }
        if ($headerIndex -lt 0 -or ($headerIndex + 2) -ge $Lines.Count) { return $result }

        $headerLine = $Lines[$headerIndex]
        $colDefs = @()
        foreach ($colName in @("Name", "Id", "Version", "Available", "Source")) {
            $pos = $headerLine.IndexOf($colName)
            if ($pos -ge 0) { $colDefs += [PSCustomObject]@{ Name = $colName; Start = $pos } }
        }
        $colDefs = @($colDefs | Sort-Object Start)

        for ($i = $headerIndex + 2; $i -lt $Lines.Count; $i++) {
            $line = $Lines[$i]
            if (-not $line -or $line.Trim().Length -eq 0) { continue }
            if ($line -match "^\d+ upgrades? available" -or $line -match "^No installed package found" -or $line -match "^-+$") { continue }

            $fields = @{}
            for ($c = 0; $c -lt $colDefs.Count; $c++) {
                $start = $colDefs[$c].Start
                if ($start -ge $line.Length) { continue }
                $fieldLen = if ($c + 1 -lt $colDefs.Count) { $colDefs[$c + 1].Start - $start } else { $line.Length - $start }
                if ($start + $fieldLen -gt $line.Length) { $fieldLen = $line.Length - $start }
                if ($fieldLen -le 0) { continue }
                $fields[$colDefs[$c].Name] = $line.Substring($start, $fieldLen).Trim()
            }

            if ($fields.ContainsKey("Id") -and $fields["Id"]) {
                $result += [PSCustomObject]@{
                    Name             = $fields["Name"]
                    Id               = $fields["Id"]
                    CurrentVersion   = $fields["Version"]
                    AvailableVersion = $fields["Available"]
                }
            }
        }
        return $result
    }

    $updates = @(Parse-WingetTableSection -Lines $section1)
    $msstoreUpdates = @(Parse-WingetTableSection -Lines $section2)
    # Συγχώνευση με αφαίρεση διπλότυπων (ίδιο Id να μην εμφανιστεί δύο φορές αν εμφανίστηκε και στις
    # δύο λίστες).
    $existingIds = [System.Collections.Generic.HashSet[string]]::new()
    foreach ($u in $updates) { [void]$existingIds.Add($u.Id) }
    foreach ($u in $msstoreUpdates) {
        if (-not $existingIds.Contains($u.Id)) { $updates += $u; [void]$existingIds.Add($u.Id) }
    }
    # ΝΕΟ v1.8.9: όλα τα winget/msstore αποτελέσματα παίρνουν ρητά Source="winget" (η ίδια εντολή
    # αναβάθμισης ισχύει και για τα δύο - το msstore είναι απλά διαφορετική πηγή δεδομένων, όχι
    # διαφορετικός μηχανισμός αναβάθμισης).
    foreach ($u in $updates) { $u | Add-Member -MemberType NoteProperty -Name "Source" -Value "winget" -Force }

    # ΝΕΟ v1.8.9: ανάλυση του OTHERPM_JSON section (pip/npm/pnpm/chocolatey/scoop/gem/cargo/dotnet/
    # psmodule/composer) και προσθήκη στην ενιαία λίστα, με το δικό τους πραγματικό Source.
    if ($otherPmJsonText -and $otherPmJsonText.Trim().Length -gt 0) {
        try {
            $otherPmData = $otherPmJsonText | ConvertFrom-Json -ErrorAction Stop
            foreach ($op in @($otherPmData)) {
                if (-not $op -or -not $op.Name) { continue }
                $opKey = "$($op.Source):$($op.Id)"
                if ($existingIds.Contains($opKey)) { continue }
                [void]$existingIds.Add($opKey)
                $updates += [PSCustomObject]@{
                    Name             = $op.Name
                    Id               = $op.Id
                    CurrentVersion   = $op.Version
                    AvailableVersion = $op.Available
                    Source           = $op.Source
                }
            }
        } catch {}
    }

    if ($updates.Count -eq 0) {
        $global:wingetLoadingLabel.Text = (TT "Το σύστημά σας είναι πλήρως ενημερωμένο! Δεν βρέθηκαν εκκρεμείς αναβαθμίσεις.")
        $global:wingetBtnUpdateSelected.Enabled = $false
        $global:wingetChkAll.Enabled = $false
        return
    }

    $global:wingetLoadingLabel.Text = "$(TT 'Βρέθηκαν') $($updates.Count) $(TT 'διαθέσιμες ενημερώσεις εφαρμογών:')"
    $global:wingetBtnUpdateSelected.Enabled = $true
    $global:wingetChkAll.Enabled = $true
    $yPos = 10
    $currTheme = Get-ThemeColors

    foreach ($app in $updates) {
        $cardApp = [System.Windows.Forms.Panel]::new()
        $cardApp.Size = [System.Drawing.Size]::new(950, 65)
        $cardApp.Location = [System.Drawing.Point]::new(10, $yPos)
        $cardApp.BackColor = $currTheme.MainBg
        $global:wingetPanelList.Controls.Add($cardApp)

        $chk = [System.Windows.Forms.CheckBox]::new()
        $chk.Location = [System.Drawing.Point]::new(12, 20)
        $chk.Size = [System.Drawing.Size]::new(24, 24)
        $chk.BackColor = [System.Drawing.Color]::Transparent
        $chk.Checked = $true
        $cardApp.Controls.Add($chk)

        $lblInfo = [System.Windows.Forms.Label]::new()
        $lblInfo.Font = $fontText
        $lblInfo.ForeColor = $currTheme.Text
        $lblInfo.BackColor = [System.Drawing.Color]::Transparent
        $lblInfo.Size = [System.Drawing.Size]::new(880, 50)
        $lblInfo.Location = [System.Drawing.Point]::new(45, 8)
        $lblInfo.Text = "[$($app.Source)] $($app.Name) [ ID: $($app.Id) ]`n$(TT 'Τρέχουσα Έκδοση'): $($app.CurrentVersion)  ➔  $(TT 'Νέα Έκδοση'): $($app.AvailableVersion)"
        $cardApp.Controls.Add($lblInfo)

        $global:wingetRowItems += [PSCustomObject]@{
            Panel    = $cardApp
            CheckBox = $chk
            Id       = $app.Id
            Name     = $app.Name
            Current  = $app.CurrentVersion
            Target   = $app.AvailableVersion
            Source   = $app.Source
        }
        $yPos += 75
    }
}

$global:wingetChkAll.Add_CheckedChanged({
    foreach ($item in $global:wingetRowItems) {
        $item.CheckBox.Checked = $global:wingetChkAll.Checked
    }
})

$mainForm.Add_Shown({
    # ΝΕΟ v1.4.8: Η εφαρμογή τρέχει ανυψωμένη (Administrator) - στα Windows, ανυψωμένα παράθυρα μερικές
    # φορές ανοίγουν ΠΙΣΩ από ήδη ανοιχτά κανονικά παράθυρα λόγω του μηχανισμού "foreground lock". Το
    # τέχνασμα TopMost=true->false αναγκάζει αξιόπιστα το παράθυρο στο προσκήνιο μία φορά κατά το
    # άνοιγμα, ΧΩΡΙΣ να το κάνει μόνιμα "πάντα από πάνω" (θα ήταν ενοχλητικό για τον χρήστη).
    $mainForm.TopMost = $true
    $mainForm.Activate()
    $mainForm.TopMost = $false

    # ===== ΔΙΟΡΘΩΣΗ v1.4.0: Το pop-up επαναφοράς συστήματος μετακινήθηκε εδώ (Add_Shown) ώστε να
    # εμφανίζεται ΜΕΤΑ το άνοιγμα του κύριου παραθύρου, όχι πριν - ο χρήστης βλέπει πρώτα την εφαρμογή
    # και μετά αποφασίζει για το σημείο επαναφοράς, αντί να περιμένει ένα διάλογο πριν καν δει τίποτα.
    # ΝΕΟ v1.4.5: Αν ο χρήστης έχει επιλέξει "να μην εμφανιστεί ξανά" σε προηγούμενη εκτέλεση, παραλείπεται.
    if (-not $global:appSettings.SkipRestorePrompt) {
        $rpPrompt = Show-RestorePointPrompt
        if ($rpPrompt.SkipFuture) {
            $global:appSettings.SkipRestorePrompt = $true
            Save-AppSettings -Settings $global:appSettings
        }
        if ($rpPrompt.Result -eq [System.Windows.Forms.DialogResult]::Yes) {
            try {
                Enable-ComputerRestore -Drive "C:" -ErrorAction SilentlyContinue
                Checkpoint-Computer -Description "Before Windows Optimizer Integration v2.8.2" -RestorePointType "MODIFY_SETTINGS" -ErrorAction Stop
                $lblStatus.Text = (TT "Σημείο επαναφοράς δημιουργήθηκε επιτυχώς! (v2.8.2) | Κατάσταση: Έτοιμο")
                Show-ToastNotification -Message (TT "Το σημείο επαναφοράς δημιουργήθηκε με επιτυχία.") -Title (TT "Σημείο Επαναφοράς")
            } catch {
                Show-CustomMessage -Message "Αποτυχία δημιουργίας σημείου επαναφοράς. Βεβαιωθείτε ότι η Προστασία Συστήματος είναι ενεργοποιημένη στον δίσκο C:." -Title "Σφάλμα" -Type "Error"
            }
        }
    }

    & $script:LoadWingetUpdatesList
})

# =========================================================================
# ΝΕΟ (v1.8.0): ΕΝΗΜΕΡΩΣΕΙΣ ΟΔΗΓΩΝ (DRIVERS)
# =========================================================================
# Ανίχνευση εγκατεστημένων drivers μέσω Win32_PnPSignedDriver (αξιόπιστο, τοπικό, χωρίς δίκτυο) και
# έλεγχος διαθέσιμων ενημερώσεων μέσω του επίσημου Windows Update COM API φιλτραρισμένο για Type='Driver'
# (ο μόνος πραγματικά αξιόπιστος μηχανισμός - καμία επίσημη, ενιαία υπηρεσία δεν υπάρχει για απευθείας
# "τελευταία έκδοση ανά κατασκευαστή" χωρίς εύθραυστο web-scraping ανά ιστότοπο κατασκευαστή).
# ΡΗΤΑ: η εφαρμογή ΔΕΝ εγκαθιστά κανέναν driver από προεπιλογή - μόνο εμφανίζει τη λίστα. Η αυτόματη
# λήψη/εγκατάσταση είναι αμιγώς προαιρετική, ενεργοποιήσιμη από Ρυθμίσεις (μενού Εργαλεία).
$cardOpt4 = Helper-CreateCard 20 650 1030 520 $global:scrollPanelOptimization
Add-IconedLabel -IconType "Optimization" -Text (TT "Ενημερώσεις Οδηγών Συσκευών (Drivers)") -x 15 -y 12 -w 700 -Font $fontBoldText -IsSubText $false -Parent $cardOpt4 | Out-Null

# ΔΙΟΡΘΩΣΗ ΡΙΖΙΚΗ v2.2.0 (πολυ-πηγαία αρχιτεκτονική driver engine, βλ. HANDOFF.md ενότητα 0 - ΚΑΙ ρητή,
# επαναλαμβανόμενη απαίτηση χρήστη "δεν θέλω να εμφανίζεται το παράθυρο SNAPPY... δεν θέλω επιπλέον
# κουμπιά"): το ΣΑΡΩΣΗ κουμπί ενεργοποιούσε παλιότερα το SDI (άνοιγμα του ΔΙΚΟΥ ΤΟΥ ξεχωριστού παραθύρου).
# Ανακαλύφθηκε ότι υπήρχε ΗΔΗ πλήρες, δοκιμασμένο pipeline μέσω του επίσημου Windows Update API
# (Start-DriverScan/Complete-DriverScan/Install-DriverUpdate, αποτελέσματα ΑΠΟΚΛΕΙΣΤΙΚΑ στη ΔΙΚΗ ΜΑΣ
# λίστα, ΠΟΤΕ εξωτερικό παράθυρο) - αυτό είναι πλέον η ΜΟΝΗ ενέργεια του κουμπιού. Το SDIO ΔΕΝ καλείται
# πλέον από ΚΑΝΕΝΑ σημείο αυτής της κάρτας (ούτε από δεύτερο κουμπί - δοκιμάστηκε και απορρίφθηκε ρητά
# από τον χρήστη). Η επέκταση σε ΠΕΡΙΣΣΟΤΕΡΕΣ headless πηγές (π.χ. Microsoft Update Catalog) παραμένει
# πιθανό μελλοντικό βήμα - βλ. HANDOFF.md §Α.3 - αλλά ΠΟΤΕ ξανά το SDIO με τρόπο που εμφανίζει δικό του
# παράθυρο, ανεξάρτητα από το πόσο μεγαλύτερη είναι η βάση οδηγών του.
$lblDriverDesc = [System.Windows.Forms.Label]::new()
$lblDriverDesc.Text = (TT "Ανιχνεύει ενημερώσεις οδηγών μέσω του επίσημου Windows Update - τα αποτελέσματα εμφανίζονται εδώ, ποτέ σε εξωτερικό παράθυρο.")
$lblDriverDesc.Font = $fontText
$lblDriverDesc.ForeColor = $theme.SubText
$lblDriverDesc.BackColor = [System.Drawing.Color]::Transparent
$lblDriverDesc.Size = [System.Drawing.Size]::new(1000, 22)
$lblDriverDesc.Location = [System.Drawing.Point]::new(15, 40)
$cardOpt4.Controls.Add($lblDriverDesc)
$global:allTextLabels += $lblDriverDesc

# ΝΕΟ v1.8.0: Ρητή προειδοποίηση ευθύνης, ζητήθηκε να βρίσκεται αμέσως μετά την περιγραφή, στην κορυφή.
$lblDriverDisclaimer = [System.Windows.Forms.Label]::new()
$lblDriverDisclaimer.Text = (TT "Η λήψη και τυχόν εγκατάσταση του εκάστοτε οδηγού γίνεται με αποκλειστική ευθύνη του χρήστη - για οποιαδήποτε δυσλειτουργία δεν ευθύνεται η εφαρμογή.")
