$lblDriverDisclaimer.ForeColor = [System.Drawing.Color]::FromArgb(230, 170, 60)
$lblDriverDisclaimer.BackColor = [System.Drawing.Color]::Transparent
$lblDriverDisclaimer.Size = [System.Drawing.Size]::new(1000, 32)
$lblDriverDisclaimer.Location = [System.Drawing.Point]::new(15, 62)
$cardOpt4.Controls.Add($lblDriverDisclaimer)
$global:allSubTextLabels += $lblDriverDisclaimer

# Κυκλικό μπλε κουμπί σάρωσης - στο κέντρο, όπως ζητήθηκε.
