$global:driverPanelList = [System.Windows.Forms.Panel]::new()
# ΔΙΟΡΘΩΣΗ v2.2.0: μετατοπίστηκε (296->327) μαζί με το lblDriverStatus παραπάνω· ύψος μειώθηκε ανάλογα
# (165->134) ώστε να ΜΗΝ χρειαστεί να μεγαλώσει/μετατοπιστεί ολόκληρη η κάρτα (και ό,τι ακολουθεί μετά
# της στην ίδια καρτέλα) - μικρή, αποδεκτή μείωση ορατών γραμμών έναντι μεγαλύτερου, ριψοκίνδυνου cascade.
$global:driverPanelList.Size = [System.Drawing.Size]::new(1000, 134)
$global:driverPanelList.Location = [System.Drawing.Point]::new(15, 327)
$global:driverPanelList.AutoScroll = $true
Set-PanelScrollbarDarkMode -Panel $global:driverPanelList
$global:allThemedScrollPanels = @($global:allThemedScrollPanels) + $global:driverPanelList
$global:driverPanelList.BackColor = $theme.MainBg
if ($setStyleMethod) { $setStyleMethod.Invoke($global:driverPanelList, @($flickerFixStyles, $true)) | Out-Null }
$cardOpt4.Controls.Add($global:driverPanelList)

$global:driverRowItems = @()

# ΝΕΟ v1.8.0: Ασύγχρονη σάρωση - background διεργασία PowerShell (ίδιο μοτίβο με το Winget, δεν μπλοκάρει
# το GUI thread) που συνδυάζει: (α) Get-CimInstance Win32_PnPSignedDriver για τους εγκατεστημένους
# drivers (τοπικό, αξιόπιστο, χωρίς δίκτυο), και (β) το επίσημο Windows Update COM API φιλτραρισμένο σε
# Type='Driver' για διαθέσιμες ενημερώσεις (ο μόνος αξιόπιστος, ενιαίος μηχανισμός - καμία επίσημη API
# δεν υπάρχει για "τελευταία έκδοση ανά ιστότοπο κατασκευαστή" χωρίς εύθραυστο web-scraping ανά site).
$global:driverScanTimer = [System.Windows.Forms.Timer]::new()
$global:driverScanTimer.Interval = 500
$global:driverScanTimer.Add_Tick({
    if (-not $global:driverScanState) { $global:driverScanTimer.Stop(); return }
    if (-not $global:driverScanState.Process.HasExited) {
        # Ζωντανή ενημέρωση του τόξου προόδου στο κυκλικό κουμπί (αυξάνεται σταδιακά όσο περιμένουμε,
        # καθαρά ενδεικτικό - δεν γνωρίζουμε την πραγματική πρόοδο του Windows Update αναζήτησης).
        $global:btnDriverScan.Tag.Progress = [Math]::Min(92, $global:btnDriverScan.Tag.Progress + 4)
        # ΝΕΟ (ρητό αίτημα χρήστη): το γρανάζι μέσα στο κουμπί περιστρέφεται ταυτόχρονα με το τόξο
        # προόδου - ίδιο βήμα φάσης με το κεντρικό γρανάζι τίτλου, για συνεπή αίσθηση κίνησης.
        $global:btnDriverScan.Tag.GearPhase = ($global:btnDriverScan.Tag.GearPhase + 18) % 360
        $global:btnDriverScan.Invalidate()
        return
    }
    $global:driverScanTimer.Stop()
    $rawJson = $null
    if (Test-Path $global:driverScanState.OutFile) {
        $rawJson = Get-Content -Path $global:driverScanState.OutFile -Raw -ErrorAction SilentlyContinue
        Remove-Item -Path $global:driverScanState.OutFile -Force -ErrorAction SilentlyContinue
    }
    # ΔΙΟΡΘΩΣΗ (bug εντοπίστηκε: ΔΕΝ καθαριζόταν ποτέ, σε αντίθεση με τα ίδια μοτίβα σε winget/registry
    # cleaner/firewall/storage scan) - κάθε σάρωση οδηγών άφηνε μόνιμα ένα .ps1 αρχείο στον φάκελο TEMP.
    if (Test-Path $global:driverScanState.ScriptFile) {
        Remove-Item -Path $global:driverScanState.ScriptFile -Force -ErrorAction SilentlyContinue
    }
    $global:driverScanState = $null
    Complete-DriverScan -RawJson $rawJson
    [System.GC]::Collect()
    [System.GC]::WaitForPendingFinalizers()
})

function Start-DriverScan {
    if ($global:driverScanState) { return }
    $global:btnDriverScan.Tag.Scanning = $true
    $global:btnDriverScan.Tag.Progress = 5
    $global:btnDriverScan.Tag.GearPhase = 0
    $global:btnDriverScan.Invalidate()
    $global:lblDriverStatus.Text = (TT "Σάρωση εγκατεστημένων οδηγών & έλεγχος Windows Update σε εξέλιξη (μπορεί να διαρκέσει έως 1-2 λεπτά)...")
    $global:driverPanelList.Controls.Clear()
    $global:driverRowItems = @()

    $tempOut = Join-Path $env:TEMP "OptimizerDriverScan_$([guid]::NewGuid().ToString('N')).json"
    $scanScript = @'
$ErrorActionPreference = "Continue"
$installed = @()
try {
    # ΔΙΟΡΘΩΣΗ v1.8.6: Προστέθηκε το πεδίο HardWareID - επιτρέπει σύνδεσμο απευθείας στο επίσημο
    # Microsoft Update Catalog ανά συσκευή (βλ. Complete-DriverScan), ώστε ο χρήστης να μπορεί να
    # ελέγξει χειροκίνητα ακόμα και όταν το Windows Update API δεν επιστρέφει αυτόματα αποτελέσματα.
    $installed = Get-CimInstance Win32_PnPSignedDriver -ErrorAction Stop |
        Where-Object { $_.DeviceName -and $_.DriverVersion } |
        Select-Object DeviceName, DriverVersion, DriverDate, DeviceClass, Manufacturer, HardWareID
} catch {}

# ΝΕΟ v1.8.1: Έλεγχος για την τεκμηριωμένη πολιτική "ExcludeWUDriversInQualityUpdate" (σε πολλαπλά
# πιθανά registry paths) που ΑΠΟΚΛΕΙΕΙ ΕΝΤΕΛΩΣ τους drivers από το Windows Update, ανεξάρτητα από το αν
# υπάρχουν πράγματι διαθέσιμες ενημερώσεις - χωρίς αυτόν τον έλεγχο, η εφαρμογή θα έδειχνε παραπλανητικά
# "όλοι οι οδηγοί ενημερωμένοι" ενώ στην πραγματικότητα το Windows Update απλά δεν επιτρέπεται να τους
# αναζητήσει καν.
$policyBlocked = $false
$policyPaths = @(
    "HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate",
    "HKLM:\SOFTWARE\Microsoft\PolicyManager\current\device\Update",
    "HKLM:\SOFTWARE\Microsoft\PolicyManager\default\Update",
    "HKLM:\SOFTWARE\Microsoft\WindowsUpdate\UX\Settings"
)
foreach ($p in $policyPaths) {
    try {
        $v = (Get-ItemProperty -Path $p -Name "ExcludeWUDriversInQualityUpdate" -ErrorAction SilentlyContinue).ExcludeWUDriversInQualityUpdate
        if ($v -eq 1) { $policyBlocked = $true; break }
    } catch {}
}

$updates = @()
$wuError = $null
if (-not $policyBlocked) {
    try {
        $session = New-Object -ComObject Microsoft.Update.Session
        $searcher = $session.CreateUpdateSearcher()
        $result = $searcher.Search("IsInstalled=0 and Type='Driver'")
        foreach ($u in $result.Updates) {
            $updates += [PSCustomObject]@{
                Title              = $u.Title
                DriverClass        = $u.DriverClass
                DriverManufacturer = $u.DriverManufacturer
                DriverModel        = $u.DriverModel
                DriverVerDate      = if ($u.DriverVerDate) { $u.DriverVerDate.ToString("yyyy-MM-dd") } else { $null }
                MaxDownloadSize    = $u.MaxDownloadSize
                UpdateID           = $u.Identity.UpdateID
            }
        }
    } catch {
        $wuError = $_.Exception.Message
    }
}

$amdResults = @()
try {
    # ΝΕΟ v2.2.0 (2η αυτοματοποιημένη πηγή, μετά το Windows Update - βλ. HANDOFF.md ενότητα 0/§Α.3):
    # η επίσημη σελίδα drivers.amd.com είναι server-rendered (ΚΑΝΕΝΑ κρυφό AJAX API) - επιβεβαιώθηκε
    # ζωντανά (Αύγουστος 2026) ότι η σελίδα ανά μοντέλο GPU (π.χ. .../amd-radeon-rx-7800-xt.html)
    # περιέχει απευθείας στο HTML το Release Date και το link λήψης (το οποίο περιέχει την έκδοση
    # Adrenalin στο ίδιο το filename, π.χ. amd-software-adrenalin-edition-26.8.1-...exe). ΔΕΝ γίνεται
    # σύγκριση εκδόσεων (το DriverVersion των Windows ΔΕΝ είναι στην ίδια αρίθμηση με το Adrenalin
    # marketing version) - αντ' αυτού συγκρίνονται ΗΜΕΡΟΜΗΝΙΕΣ (DriverDate εγκατεστημένου έναντι
    # Release Date της AMD), πιο αξιόπιστη σύγκριση χωρίς ψευδή βεβαιότητα.
    $amdGpus = Get-CimInstance Win32_VideoController -ErrorAction Stop | Where-Object { $_.Name -match "AMD|Radeon" }
    foreach ($gpu in $amdGpus) {
        $gpuName = $gpu.Name
        $slugFamily = $null; $slugSeries = $null
        if ($gpuName -match "RX\s*9\d{3}") { $slugFamily = "radeon-rx"; $slugSeries = "radeon-rx-9000-series" }
        elseif ($gpuName -match "RX\s*7\d{3}") { $slugFamily = "radeon-rx"; $slugSeries = "radeon-rx-7000-series" }
        elseif ($gpuName -match "RX\s*6\d{3}") { $slugFamily = "radeon-rx"; $slugSeries = "radeon-rx-6000-series" }
        elseif ($gpuName -match "RX\s*5\d{3}") { $slugFamily = "radeon-rx"; $slugSeries = "radeon-rx-5000-series" }
        elseif ($gpuName -match "RX\s*Vega") { $slugFamily = "radeon-rx"; $slugSeries = "radeon-rx-vega-series" }
        if (-not $slugFamily) { continue }
        $modelSlug = ($gpuName -replace "[™®()]", "").Trim()
        $modelSlug = ($modelSlug -replace "\s+", "-").ToLower()
        if ($modelSlug -notmatch "^amd-") { $modelSlug = "amd-$modelSlug" }
        $amdUrl = "https://www.amd.com/en/support/downloads/drivers.html/graphics/$slugFamily/$slugSeries/$modelSlug.html"
        try {
            $amdResp = Invoke-WebRequest -Uri $amdUrl -UseBasicParsing -TimeoutSec 15 -ErrorAction Stop
            $amdHtml = $amdResp.Content
            $verMatch = [regex]::Match($amdHtml, 'amd-software-adrenalin-edition-([\d.]+)-[^"]*\.exe')
            $dateMatch = [regex]::Match($amdHtml, '<strong>\s*Release Date\s*</strong>\s*<p>\s*([\d-]+)\s*</p>')
            if ($verMatch.Success) {
                $installedGpuDrv = $installed | Where-Object { $_.DeviceName -eq $gpuName } | Select-Object -First 1
                $installedDateStr = $null
                if ($installedGpuDrv -and $installedGpuDrv.DriverDate) {
                    try { $installedDateStr = ([datetime]$installedGpuDrv.DriverDate).ToString("yyyy-MM-dd") } catch {}
                }
                $amdResults += [PSCustomObject]@{
                    GpuName           = $gpuName
                    LatestVersion     = $verMatch.Groups[1].Value
                    LatestReleaseDate = if ($dateMatch.Success) { $dateMatch.Groups[1].Value } else { $null }
                    InstalledVersion  = if ($installedGpuDrv) { $installedGpuDrv.DriverVersion } else { $null }
                    InstalledDate     = $installedDateStr
                    DownloadUrl       = $amdUrl
                }
            }
        } catch {}
    }
} catch {}

$nvidiaResults = @()
try {
    # ΝΕΟ v2.2.0 (4η αυτοματοποιημένη πηγή): χρησιμοποιεί το ΔΙΚΟ ΤΗΣ NVIDIA δημόσιο API που τροφοδοτεί
    # τη σελίδα λήψης οδηγών της (ίδιο μηχανισμό με το ευρέως χρησιμοποιούμενο, ανοιχτού κώδικα εργαλείο
    # TinyNvidiaUpdateChecker - επιβεβαιώθηκε ζωντανά, Αύγουστος 2026, ΟΛΟΚΛΗΡΗ η αλυσίδα):
    # 1) https://www.nvidia.com/Download/API/lookupValueSearch.aspx?TypeID=3 - επίσημη λίστα GPU->pfid
    # 2) https://gfwsl.geforce.com/.../AjaxDriverService.php?func=DriverManualLookup&pfid=X&osID=Y&upCRD=0&dch=1
    # Η σύγκριση "νεότερη έκδοση" γίνεται ΚΑΙ εδώ με ΗΜΕΡΟΜΗΝΙΕΣ (όχι version strings - η NVIDIA marketing
    # version π.χ. "616.56" δεν αντιστοιχεί απευθείας στο εσωτερικό DriverVersion των Windows).
    $nvidiaGpus = Get-CimInstance Win32_VideoController -ErrorAction Stop | Where-Object { $_.Name -match "NVIDIA|GeForce|Quadro|RTX|GTX" }
    if ($nvidiaGpus) {
        $osId = if ([Environment]::OSVersion.Version.Build -ge 22000) { 135 } else { 57 }
        $gpuListResp = Invoke-WebRequest -Uri "https://www.nvidia.com/Download/API/lookupValueSearch.aspx?TypeID=3" -UseBasicParsing -TimeoutSec 20 -ErrorAction Stop
        [xml]$gpuListXml = $gpuListResp.Content
        $allGpuEntries = @($gpuListXml.LookupValueSearch.LookupValues.LookupValue)

        foreach ($gpu in $nvidiaGpus) {
            $gpuName = $gpu.Name
            # Καθάρισμα ονόματος όπως τεκμηριωμένο (ZenitH-AT/nvidia-data README) - αφαίρεση προθέματος
            # "NVIDIA ", κατάληξης "with Max-Q Design"/"(OEM)"/μεγέθους μνήμης, και "Super" -> "SUPER".
            $cleanName = $gpuName -replace "^NVIDIA\s+", ""
            $cleanName = $cleanName -replace "\s+with Max-Q Design", ""
            $cleanName = $cleanName -replace "\s*\(OEM\)", ""
            $cleanName = $cleanName -replace "\s+\d+GB$", ""
            $cleanName = $cleanName -replace "Super", "SUPER"
            $cleanName = $cleanName.Trim()

            $gpuEntry = $allGpuEntries | Where-Object { $_.Name -eq $cleanName } | Select-Object -First 1
            if (-not $gpuEntry) { continue }
            $pfid = $gpuEntry.Value

            try {
                $lookupUrl = "https://gfwsl.geforce.com/services_toolkit/services/com/nvidia/services/AjaxDriverService.php?func=DriverManualLookup&pfid=$pfid&osID=$osId&upCRD=0&dch=1"
                $nvResp = Invoke-WebRequest -Uri $lookupUrl -UseBasicParsing -TimeoutSec 15 -ErrorAction Stop
                $nvJson = $nvResp.Content | ConvertFrom-Json -ErrorAction Stop
                if ($nvJson.Success -eq 1 -and $nvJson.IDS -and $nvJson.IDS.Count -gt 0) {
                    $dlInfo = $nvJson.IDS[0].downloadInfo
                    $latestDateStr = $null
                    try { $latestDateStr = ([datetime]::Parse($dlInfo.ReleaseDateTime)).ToString("yyyy-MM-dd") } catch {}

                    $installedGpuDrvN = $installed | Where-Object { $_.DeviceName -eq $gpuName } | Select-Object -First 1
                    $installedDateStrN = $null
                    if ($installedGpuDrvN -and $installedGpuDrvN.DriverDate) {
                        try { $installedDateStrN = ([datetime]$installedGpuDrvN.DriverDate).ToString("yyyy-MM-dd") } catch {}
                    }
                    $nvidiaResults += [PSCustomObject]@{
                        GpuName           = $gpuName
                        LatestVersion     = $dlInfo.Version
                        LatestReleaseDate = $latestDateStr
                        InstalledVersion  = if ($installedGpuDrvN) { $installedGpuDrvN.DriverVersion } else { $null }
                        InstalledDate     = $installedDateStrN
                        DownloadUrl       = $dlInfo.DownloadURL
                    }
                }
            } catch {}
        }
    }
} catch {}

# ΝΕΟ v2.2.0 ("πηγή" - OEM κατασκευαστής, Dell μόνο προς το παρόν): ΔΕΝ εγκαθιστά τίποτα αυτόματα -
# μόνο ελέγχει αν το επίσημο Dell Command Update (dcu-cli.exe) είναι ΗΔΗ εγκατεστημένο, και αν ναι, το
# τρέχει ΑΘΟΡΥΒΑ (/scan -report=..., ΚΑΝΕΝΑ δικό του παράθυρο) και διαβάζει το επίσημο XML report του.
# ΣΗΜΕΙΩΣΗ ΕΙΛΙΚΡΙΝΕΙΑΣ: η ακριβής μορφή του XML report/exit codes επιβεβαιώθηκε μέσω τεκμηρίωσης +
# πραγματικών, δημόσιων production scripts (RMM/enterprise χρήση) - ΔΕΝ δοκιμάστηκε ζωντανά εδώ (το
# sandbox δεν έχει Dell hardware/DCU εγκατεστημένο). Αν κάτι δεν ταιριάζει στην πράξη, χρειάζεται
# διόρθωση βάσει πραγματικού output από πραγματικό Dell PC.
$dellResult = $null
try {
    $cs = Get-CimInstance Win32_ComputerSystem -ErrorAction Stop
    if ($cs.Manufacturer -match "Dell") {
        $progFilesBase = if ([Environment]::Is64BitOperatingSystem) { ${env:ProgramFiles(x86)} } else { $env:ProgramFiles }
        $dcuPath = Join-Path -Path $progFilesBase -ChildPath "Dell\CommandUpdate\dcu-cli.exe"
        if (Test-Path $dcuPath) {
            # ΣΗΜΑΝΤΙΚΟ (τεκμηριωμένος περιορισμός DCU): το -report= ΔΕΝ επιτρέπει διαδρομή μέσα στο
            # C:\Windows\Temp - το $env:TEMP ενός κανονικού χρήστη (AppData\Local\Temp) είναι ασφαλές.
            $dcuReportDir = Join-Path $env:TEMP "OptimizerDCU_$([guid]::NewGuid().ToString('N'))"
            $dcuReportPath = Join-Path $dcuReportDir "DCUApplicableUpdates.xml"
            try {
                Start-Process -FilePath $dcuPath -ArgumentList "/scan -report=`"$dcuReportDir`"" -Wait -WindowStyle Hidden -ErrorAction Stop
                if (Test-Path $dcuReportPath) {
                    [xml]$dcuXml = Get-Content -Path $dcuReportPath -Raw -ErrorAction Stop
                    $dcuUpdates = @($dcuXml.updates.update | Select-Object -Property name, version, date, urgency, type, category)
                    $dellResult = [PSCustomObject]@{ Installed = $true; Updates = $dcuUpdates; Error = $null }
                } else {
                    $dellResult = [PSCustomObject]@{ Installed = $true; Updates = @(); Error = $null }
                }
            } catch {
                $dellResult = [PSCustomObject]@{ Installed = $true; Updates = @(); Error = $_.Exception.Message }
            } finally {
                if (Test-Path $dcuReportDir) { Remove-Item -Path $dcuReportDir -Recurse -Force -ErrorAction SilentlyContinue }
            }
        } else {
            $dellResult = [PSCustomObject]@{ Installed = $false; Updates = @(); Error = $null }
        }
    }
} catch {}

# ΝΕΟ v2.2.0 (ρητό αίτημα χρήστη - "γράψε κώδικα για την ενσωμάτωση του Snappy Origin ΧΩΡΙΣ παραθυρικό
# περιβάλλον"): αντιστρέφει την προηγούμενη, ρητή απόρριψη του SDI - ΜΟΝΟ επειδή τώρα ζητήθηκε ρητά μια
# αυστηρά ΚΕΦΑΛΙΔΗΣ (headless) προσέγγιση. Χρησιμοποιεί ΜΟΝΟ επίσημα τεκμηριωμένα command-line flags
# (sdi-tool.org/settings/ - ζωντανά ανακτημένα, Αύγουστος 2026): -nogui ("Runs without GUI interface"),
# -autoclose, -output_dir:<dir> ("Path to indexes in human-readable format"), -log_dir:<dir>, -nostamp.
# ΣΚΟΠΙΜΑ ΧΩΡΙΣ -autoinstall - η επίσημη τεκμηρίωση ΔΕΝ αναφέρει κανένα ξεχωριστό "scan-only" flag, άρα η
# ασφαλέστερη ερμηνεία είναι "χωρίς -autoinstall δεν εγκαθιστά τίποτα αυτόματα" (συνεπές με τη
# συντηρητική φιλοσοφία της εφαρμογής - ΠΟΤΕ αθόρυβη εγκατάσταση χωρίς επιλογή χρήστη).
# ΣΗΜΕΙΩΣΗ ΕΙΛΙΚΡΙΝΕΙΑΣ (σημαντική): ΔΕΝ επιβεβαιώθηκε ζωντανά η ΑΚΡΙΒΗΣ μορφή/περιεχόμενο του αρχείου
# που παράγει το -output_dir (δεν υπήρχε διαθέσιμο SDI/hardware για δοκιμή) - ΜΟΝΟ η ύπαρξη του flag είναι
# επίσημα επιβεβαιωμένη. Γι' αυτό ΔΕΝ γίνεται προσπάθεια parsing μεμονωμένων γραμμών/drivers από το
# αρχείο (ρίσκο εμφάνισης λάθος/άχρηστων δεδομένων) - απλώς αναφέρεται ΑΝ παρήχθη έστω ένα αρχείο, με
# κουμπί που ανοίγει τον φάκελο για τον χρήστη να το δει ο ίδιος.
# ΔΙΟΡΘΩΣΗ ΡΙΖΙΚΗ v2.4.0 (η πραγματική αιτία του "Sum: 0" - χρήστης ζήτησε να διορθωθεί): το προηγούμενο
# επιχείρημα ΠΟΤΕ δεν περιείχε flag που να λέει στο SDI να κατεβάσει/ενημερώσει τον τοπικό index των
# driverpacks - το SDI απλά συνέκρινε ενάντια σε ΚΕΝΟ τοπικό index, άρα το "Sum: 0" ήταν ΑΝΑΜΕΝΟΜΕΝΟ σε
# ΚΑΘΕ εκτέλεση, όχι μόνο στην πρώτη. Προστέθηκε το επίσημα τεκμηριωμένο flag `-autoupdate` (βλ.
# https://sdi-tool.org/settings/ - "starts downloading automatically").
# ΕΝΗΜΕΡΩΣΗ v2.6.0 (ρητό αίτημα χρήστη να "γίνει" το Sum>0 σενάριο): περαιτέρω έρευνα (WebSearch, όχι
# επίσημη τεκμηρίωση SDI - η ίδια η σελίδα δεν διευκρινίζει) βρήκε ότι η ελαφριά ("Lite") ροή εργασίας
# του SDI περιγράφεται δημόσια ως "κατεβάζει μικρό index (~50-100MB), σαρώνει το PC, και φέρνει ΜΟΝΟ τους
# οδηγούς που πραγματικά χρειάζονται" - δηλαδή το `-autoupdate` πιθανότατα ΔΕΝ περιορίζεται στον κατάλογο
# όπως υποτέθηκε αρχικά, αλλά μπορεί να φέρνει και τα σχετικά driverpacks για το ΣΥΓΚΕΚΡΙΜΕΝΟ hardware -
# το μέγεθος ανά κατηγορία αναφέρεται δημόσια ως ~1-5GB. ΣΗΜΕΙΩΣΗ ΕΙΛΙΚΡΙΝΕΙΑΣ (σημαντική, ΔΕΝ
# επιβεβαιώθηκε ζωντανά σε κανένα σημείο, ΟΥΤΕ το ΑΚΡΙΒΕΣ μέγεθος ΟΥΤΕ αν πράγματι κατεβάζει driverpacks
# ή μόνο index): το χρονικό όριο αυξήθηκε σημαντικά (180 δευτ. -> 10 λεπτά) ώστε να χωρέσει είτε
# σενάριο, χωρίς να διακόπτεται μια νόμιμη, εν εξελίξει λήψη. Το SDI αποθηκεύει ό,τι κατεβάζει στη ΔΙΚΗ
# ΤΟΥ προεπιλεγμένη τοποθεσία (ΟΧΙ στον προσωρινό $sdioOutDir μας) οπότε θα έπρεπε να παραμένει μόνιμα
# μετά την πρώτη επιτυχή λήψη - οι επόμενες σαρώσεις θα πρέπει να είναι πολύ πιο γρήγορες. Αν αυτό
# αποδειχτεί να κατεβάζει πραγματικά μεγάλο όγκο δεδομένων χωρίς προειδοποίηση στον χρήστη, το επόμενο
# βήμα θα ήταν ένα ρητό μήνυμα συναίνεσης πριν την ΠΡΩΤΗ σάρωση (ίδιο μοτίβο με τα κουμπιά εγκατάστασης
# Dell/Lenovo παραπάνω) - ΔΕΝ προστέθηκε ακόμα, αφού δεν είναι επιβεβαιωμένο ότι πράγματι χρειάζεται.
$sdioResult = $null
try {
    $sdioLinksPath = Join-Path $env:LOCALAPPDATA "Microsoft\WinGet\Links\sdio.exe"
    $sdioPath = $null
    if (Test-Path $sdioLinksPath) { $sdioPath = $sdioLinksPath }
    else { $sdioCmd = Get-Command "sdio.exe" -ErrorAction SilentlyContinue; if ($sdioCmd) { $sdioPath = $sdioCmd.Source } }

    if ($sdioPath) {
        $sdioOutDir = Join-Path $env:TEMP "OptimizerSDIO_$([guid]::NewGuid().ToString('N'))"
        New-Item -ItemType Directory -Path $sdioOutDir -Force | Out-Null
        try {
            $sdioArgs = "-nogui -autoupdate -autoclose -nostamp -output_dir:`"$sdioOutDir`" -log_dir:`"$sdioOutDir`""
            $sdioProc = Start-Process -FilePath $sdioPath -ArgumentList $sdioArgs -WindowStyle Hidden -PassThru -ErrorAction Stop
            $sdioFinished = $sdioProc.WaitForExit(600000)
            if (-not $sdioFinished) { try { $sdioProc.Kill() } catch {} }
            $sdioReportFiles = @(Get-ChildItem -Path $sdioOutDir -Filter "*.txt" -Recurse -ErrorAction SilentlyContinue)
            # ΝΕΟ v2.2.5 (χρήστης ανέβασε πραγματικό log.txt από ζωντανό τρέξιμο - επιβεβαιώθηκε ότι το
            # μόνο αρχείο που παράγεται είναι ένα εκτενές, τεχνικό log.txt, ΟΧΙ καθαρή "λίστα οδηγών προς
            # ενημέρωση"): το log περιέχει μια ενότητα "Driverpacks" με γραμμή "Sum: N" - αν N=0 (καμία
            # τοπική βάση driverpacks ακόμα, συνηθισμένο σε ΠΡΩΤΗ εκτέλεση αφού το SDI Origin τα κατεβάζει
            # ξεχωριστά/online), το SDI ΔΕΝ μπορεί να συγκρίνει τίποτα ουσιαστικά - το αρχείο log.txt που
            # παράγεται ΔΕΝ είναι χρήσιμη αναφορά αποτελεσμάτων για τον χρήστη, είναι απλώς το τεχνικό
            # ημερολόγιο εκτέλεσης. ΣΗΜΕΙΩΣΗ: το log.txt γράφεται στην κωδικοποίηση προεπιλογής συστήματος
            # (ΟΧΙ UTF-8) - διάβασμα ως UTF-8 δίνει αλλοιωμένο ελληνικό κείμενο, [System.Text.Encoding]::
            # Default το διαβάζει σωστά.
            $sdioHasDriverPacks = $false
            $sdioLogFile = $sdioReportFiles | Where-Object { $_.Name -eq "log.txt" } | Select-Object -First 1
            if ($sdioLogFile) {
                try {
                    $sdioLogText = [System.IO.File]::ReadAllText($sdioLogFile.FullName, [System.Text.Encoding]::Default)
                    $sdioSumMatch = [regex]::Match($sdioLogText, "Driverpacks[\s\S]{0,200}?Sum:\s*(\d+)")
                    if ($sdioSumMatch.Success -and [int]$sdioSumMatch.Groups[1].Value -gt 0) { $sdioHasDriverPacks = $true }
                } catch {}
            }
            $sdioResult = [PSCustomObject]@{
                Installed       = $true
                TimedOut        = (-not $sdioFinished)
                ReportFound     = ($sdioReportFiles.Count -gt 0)
                HasDriverPacks  = $sdioHasDriverPacks
                ReportPath      = if ($sdioReportFiles.Count -gt 0) { $sdioOutDir } else { $null }
                Error           = $null
            }
            if ($sdioReportFiles.Count -eq 0) { Remove-Item -Path $sdioOutDir -Recurse -Force -ErrorAction SilentlyContinue }
        } catch {
            $sdioResult = [PSCustomObject]@{ Installed = $true; TimedOut = $false; ReportFound = $false; ReportPath = $null; Error = $_.Exception.Message }
        }
    } else {
        $sdioResult = [PSCustomObject]@{ Installed = $false; TimedOut = $false; ReportFound = $false; ReportPath = $null; Error = $null }
    }
} catch {}

# ΝΕΟ v2.6.0 (Lenovo/HP OEM ανίχνευση - βλ. HANDOFF.md ενότητα 4.Α.3 για την πλήρη έρευνα): σε αντίθεση
# με το Dell Command Update (συχνά ήδη εγκατεστημένο/winget-εγκαταστάσιμο ΚΑΙ με headless -scan/-report
# σε ΕΝΑ βήμα), ΚΑΝΕΝΑ από τα δύο επίσημα εργαλεία Lenovo (ThinInstaller - σκόπιμα φορητό enterprise
# εργαλείο, χρειάζεται -repository path χωρίς επιβεβαιωμένο ασφαλές default) / HP (HP Image Assistant -
# ΔΕΝ προεγκαθίσταται, μόνο χειροκίνητη λήψη ZIP από το hp.com) δεν έχει έναν ασφαλή, headless μηχανισμό
# σάρωσης με το ΙΔΙΟ επίπεδο εμπιστοσύνης του Dell. Αντί να μαντέψουμε/παραλείψουμε εντελώς, γίνεται ΜΟΝΟ
# ανίχνευση κατασκευαστή (WMI, ήδη αποδεδειγμένη τεχνική από το Dell block παραπάνω) - η Complete-DriverScan
# αποφασίζει τι να δείξει (πρόταση εγκατάστασης για Lenovo μέσω επιβεβαιωμένου Microsoft Store ID, απλή
# ενημερωτική γραμμή για HP αφού δεν υπάρχει επιβεβαιωμένο winget/msstore ID).
$oemResult = $null
try {
    $csOem = Get-CimInstance Win32_ComputerSystem -ErrorAction Stop
    if ($csOem.Manufacturer -match "Lenovo") {
        $oemResult = [PSCustomObject]@{ OemName = "Lenovo" }
    } elseif ($csOem.Manufacturer -match "HP|Hewlett-Packard") {
        $oemResult = [PSCustomObject]@{ OemName = "HP" }
    }
} catch {}

$output = [PSCustomObject]@{ Installed = $installed; Updates = $updates; WuError = $wuError; PolicyBlocked = $policyBlocked; AmdResults = $amdResults; NvidiaResults = $nvidiaResults; DellResult = $dellResult; SdioResult = $sdioResult; OemResult = $oemResult }
$output | ConvertTo-Json -Depth 6 -Compress | Out-File -FilePath "OUTFILE_PLACEHOLDER" -Encoding utf8
'@
    $scanScript = $scanScript.Replace("OUTFILE_PLACEHOLDER", $tempOut)
    $scriptFile = Join-Path $env:TEMP "OptimizerDriverScanScript_$([guid]::NewGuid().ToString('N')).ps1"
    Set-Content -Path $scriptFile -Value $scanScript -Encoding utf8

    try {
        $proc = Start-Process -FilePath "powershell.exe" -ArgumentList "-NoProfile -ExecutionPolicy Bypass -File `"$scriptFile`"" -WindowStyle Minimized -PassThru -ErrorAction Stop
    } catch {
        Remove-Item -Path $scriptFile -Force -ErrorAction SilentlyContinue
        $global:lblDriverStatus.Text = "$(TT 'Αποτυχία εκκίνησης σάρωσης'): $($_.Exception.Message)"
        $global:btnDriverScan.Tag.Scanning = $false
        $global:btnDriverScan.Invalidate()
        return
    }
    $global:driverScanState = [PSCustomObject]@{ Process = $proc; OutFile = $tempOut; ScriptFile = $scriptFile }
    $global:driverScanTimer.Start()
}

# ΔΙΑΓΡΑΦΗΚΕ v2.3.0 (καθαρισμός νεκρού κώδικα): το προηγούμενο "SDI μέσω δικού του παραθύρου" μονοπάτι
# (Start-SdiDriverCheck, sdiEnsureState/Timer) - το ΜΟΝΟ click handler του $global:btnDriverScan είναι
# πλέον { Start-DriverScan }, δεν καλούσε πλέον καθόλου κώδικα από εδώ. Η headless (χωρίς παράθυρο)
# ενσωμάτωση SDI βρίσκεται τώρα ΜΕΣΑ στο Start-DriverScan/Complete-DriverScan (βλ. $sdioResult).

function Get-DriverClassIcon {
    param([string]$DriverClass)
    switch -Regex ($DriverClass) {
        "Media|Audio" { return "Speaker" }
        "Display|Video" { return "Monitor" }
        "Net" { return "Network" }
        "HDC|DiskDrive|SCSIAdapter|USB.*Storage" { return "HardDrive" }
        "Keyboard|Mouse|HIDClass" { return "Keyboard" }
        default { return "Chip" }
    }
}

# ΝΕΟ v2.3.0 (trust/stability scoring μεταξύ πηγών driver engine - βλ. HANDOFF.md): ένα ίδιο GPU
# μπορεί να εμφανιστεί ΚΑΙ στα αποτελέσματα Windows Update ΚΑΙ σε αυτά του amd.com/nvidia.com -
# όταν συμφωνούν 2 ανεξάρτητες πηγές για το ΙΔΙΟ φυσικό υλικό, η "πιθανή" ενημέρωση γίνεται
# "επιβεβαιωμένη" (υψηλότερη εμπιστοσύνη). Απλή σύγκριση επικάλυψης ονόματος (ίδιο πνεύμα με το
# ήδη υπάρχον best-effort matching στο Complete-DriverScan μέσω -like) - καμία εξάρτηση σε hardware
# ID, μόνο το κείμενο του ονόματος συσκευής/GPU και από τις δύο πηγές.
function Test-DriverSourceOverlap {
    param([string]$DeviceName, [string[]]$ConfirmedNames)
    if (-not $DeviceName -or -not $ConfirmedNames -or $ConfirmedNames.Count -eq 0) { return $false }
    foreach ($confirmed in $ConfirmedNames) {
        if (-not $confirmed) { continue }
        if ($DeviceName -like "*$confirmed*" -or $confirmed -like "*$DeviceName*") { return $true }
    }
    return $false
}

function Format-DriverFileSize {
    param([long]$Bytes)
    if ($Bytes -le 0) { return (TT "άγνωστο") }
    if ($Bytes -ge 1GB) { return "{0:N1} GB" -f ($Bytes / 1GB) }
    return "{0:N1} MB" -f ($Bytes / 1MB)
}

function Complete-DriverScan {
    param([string]$RawJson)
    $global:btnDriverScan.Tag.Scanning = $false
    $global:btnDriverScan.Tag.Progress = 0
    $global:btnDriverScan.Invalidate()

    if (-not $RawJson) {
        $global:lblDriverStatus.Text = (TT "Η σάρωση απέτυχε ή δεν επέστρεψε αποτελέσματα. Δοκιμάστε ξανά.")
        return
    }
    try {
        $data = $RawJson | ConvertFrom-Json -ErrorAction Stop
    } catch {
        $global:lblDriverStatus.Text = (TT "Σφάλμα ανάλυσης αποτελεσμάτων σάρωσης.")
        return
    }
    if ($data.WuError) {
        $global:lblDriverStatus.Text = "$(TT 'Ο έλεγχος Windows Update απέτυχε'): $($data.WuError)"
        return
    }

    $installed = @($data.Installed)
    $amdResults = @($data.AmdResults)
    # ΝΕΟ v2.3.0 (trust/stability scoring - βλ. Test-DriverSourceOverlap): ονόματα GPU που η AMD/NVIDIA
    # επιβεβαίωσαν ανεξάρτητα ότι έχουν νεότερο οδηγό διαθέσιμο - χρησιμοποιείται παρακάτω στον βρόχο
    # του Windows Update για να αναβαθμιστεί η "πιθανή" ενημέρωση σε "επιβεβαιωμένη" όταν συμφωνούν
    # 2 ανεξάρτητες πηγές για το ΙΔΙΟ φυσικό GPU.
    $confirmedGpuNames = New-Object System.Collections.Generic.List[string]

    $rowY = 5
    # ΝΕΟ v2.2.0 (2η πηγή, AMD amd.com - βλ. σχόλιο στο Start-DriverScan): εμφανίζεται ΠΑΝΤΑ πρώτη, πριν
    # τα αποτελέσματα Windows Update (ακόμα κι αν το WU policy-blocked παρακάτω), ανεξάρτητη πηγή. Η
    # σύγκριση "πιθανή ενημέρωση" βασίζεται σε ΗΜΕΡΟΜΗΝΙΕΣ (όχι σε αριθμό έκδοσης - διαφορετική αρίθμηση
    # μεταξύ Windows DriverVersion και AMD Adrenalin marketing version), άρα η διατύπωση παραμένει σκόπιμα
    # προσεκτική ("πιθανή", όχι βεβαιότητα).
    foreach ($amd in $amdResults) {
        $amdNewer = $false
        if ($amd.LatestReleaseDate -and $amd.InstalledDate) {
            try { $amdNewer = ([datetime]$amd.LatestReleaseDate) -gt ([datetime]$amd.InstalledDate) } catch {}
        } elseif ($amd.LatestReleaseDate -and -not $amd.InstalledDate) {
            $amdNewer = $true
        }
        if (-not $amdNewer) { continue }
        if ($amd.GpuName) { [void]$confirmedGpuNames.Add($amd.GpuName) }

        $amdRowPanel = [System.Windows.Forms.Panel]::new()
        $amdRowPanel.Size = [System.Drawing.Size]::new(970, 66)
        $amdRowPanel.Location = [System.Drawing.Point]::new(5, $rowY)
        $amdRowPanel.BackColor = $theme.CardBg
        $global:driverPanelList.Controls.Add($amdRowPanel)

        $amdIcoPic = [System.Windows.Forms.PictureBox]::new()
        $amdIcoPic.Image = Get-AppIcon -Type "Monitor" -Color $theme.Accent
        $amdIcoPic.Size = [System.Drawing.Size]::new(24, 24)
        $amdIcoPic.Location = [System.Drawing.Point]::new(10, 21)
        $amdIcoPic.SizeMode = "Zoom"
        $amdRowPanel.Controls.Add($amdIcoPic)

        $amdLblName = [System.Windows.Forms.Label]::new()
        $amdLblName.Text = "$($amd.GpuName) - $(TT 'πιθανή νεότερη έκδοση οδηγού')"
        $amdLblName.Font = $fontBtnCustom
        $amdLblName.ForeColor = $theme.Text
        $amdLblName.BackColor = [System.Drawing.Color]::Transparent
        $amdLblName.Size = [System.Drawing.Size]::new(600, 40)
        $amdLblName.Location = [System.Drawing.Point]::new(44, 6)
        $amdRowPanel.Controls.Add($amdLblName)
        $global:allTextLabels += $amdLblName

        $amdInstalledDateTxt = if ($amd.InstalledDate) { $amd.InstalledDate } else { (TT "άγνωστη") }
        $amdLblVer = [System.Windows.Forms.Label]::new()
        $amdLblVer.Text = "$(TT 'Εγκατεστημένος οδηγός'): $($amd.InstalledVersion) ($amdInstalledDateTxt)  |  $(TT 'AMD Adrenalin'): $($amd.LatestVersion) ($($amd.LatestReleaseDate))  |  $([char]0x2713) $(TT 'Πηγή: AMD Επίσημο (amd.com)')"
        $amdLblVer.Font = $fontStatus
        $amdLblVer.ForeColor = $theme.SubText
        $amdLblVer.BackColor = [System.Drawing.Color]::Transparent
        $amdLblVer.Size = [System.Drawing.Size]::new(755, 20)
        $amdLblVer.Location = [System.Drawing.Point]::new(44, 42)
        $amdRowPanel.Controls.Add($amdLblVer)
        $global:allSubTextLabels += $amdLblVer

        $amdDlUrl = $amd.DownloadUrl
        $amdBtnDl = [System.Windows.Forms.Button]::new()
        $amdBtnDl.Size = [System.Drawing.Size]::new(150, 34)
        $amdBtnDl.Location = [System.Drawing.Point]::new(810, 16)
        $amdBtnDl.FlatStyle = "Flat"
        $amdBtnDl.FlatAppearance.BorderSize = 0
        $amdBtnDl.Font = $fontStatus
        $amdBtnDl.Text = "$([char]0x2B07) $(TT 'Λήψη')"
        $amdBtnDl.BackColor = $theme.Accent
        $amdBtnDl.ForeColor = [System.Drawing.Color]::White
        $amdBtnDl.Cursor = [System.Windows.Forms.Cursors]::Hand
        $amdBtnDl.Add_Click({ Start-Process $amdDlUrl }.GetNewClosure())
        Add-ButtonHoverEffect -Button $amdBtnDl -BaseColor $amdBtnDl.BackColor
        $amdRowPanel.Controls.Add($amdBtnDl)

        $global:driverRowItems += $amdRowPanel
        $rowY += 72
    }

    $nvidiaResults = @($data.NvidiaResults)
    # ΝΕΟ v2.2.0 (4η αυτοματοποιημένη πηγή, NVIDIA - βλ. σχόλιο στο Start-DriverScan): ζωντανά επιβεβαιωμένη
    # αλυσίδα (επίσημο NVIDIA lookupValueSearch API + AjaxDriverService). Ίδια λογική σύγκρισης με ημερομηνίες
    # με το AMD block παραπάνω, για τον ίδιο λόγο (διαφορετική αρίθμηση marketing vs Windows DriverVersion).
    foreach ($nv in $nvidiaResults) {
        $nvNewer = $false
        if ($nv.LatestReleaseDate -and $nv.InstalledDate) {
            try { $nvNewer = ([datetime]$nv.LatestReleaseDate) -gt ([datetime]$nv.InstalledDate) } catch {}
        } elseif ($nv.LatestReleaseDate -and -not $nv.InstalledDate) {
            $nvNewer = $true
        }
        if (-not $nvNewer) { continue }
        if ($nv.GpuName) { [void]$confirmedGpuNames.Add($nv.GpuName) }

        $nvRowPanel = [System.Windows.Forms.Panel]::new()
        $nvRowPanel.Size = [System.Drawing.Size]::new(970, 66)
        $nvRowPanel.Location = [System.Drawing.Point]::new(5, $rowY)
        $nvRowPanel.BackColor = $theme.CardBg
        $global:driverPanelList.Controls.Add($nvRowPanel)

        $nvIcoPic = [System.Windows.Forms.PictureBox]::new()
        $nvIcoPic.Image = Get-AppIcon -Type "Monitor" -Color $theme.Accent
        $nvIcoPic.Size = [System.Drawing.Size]::new(24, 24)
        $nvIcoPic.Location = [System.Drawing.Point]::new(10, 21)
        $nvIcoPic.SizeMode = "Zoom"
        $nvRowPanel.Controls.Add($nvIcoPic)

        $nvLblName = [System.Windows.Forms.Label]::new()
        $nvLblName.Text = "$($nv.GpuName) - $(TT 'πιθανή νεότερη έκδοση οδηγού')"
        $nvLblName.Font = $fontBtnCustom
        $nvLblName.ForeColor = $theme.Text
        $nvLblName.BackColor = [System.Drawing.Color]::Transparent
        $nvLblName.Size = [System.Drawing.Size]::new(600, 40)
        $nvLblName.Location = [System.Drawing.Point]::new(44, 6)
        $nvRowPanel.Controls.Add($nvLblName)
        $global:allTextLabels += $nvLblName

        $nvInstalledDateTxt = if ($nv.InstalledDate) { $nv.InstalledDate } else { (TT "άγνωστη") }
        $nvLblVer = [System.Windows.Forms.Label]::new()
        $nvLblVer.Text = "$(TT 'Εγκατεστημένος οδηγός'): $($nv.InstalledVersion) ($nvInstalledDateTxt)  |  $(TT 'NVIDIA'): $($nv.LatestVersion) ($($nv.LatestReleaseDate))  |  $([char]0x2713) $(TT 'Πηγή: NVIDIA Επίσημο (nvidia.com)')"
        $nvLblVer.Font = $fontStatus
        $nvLblVer.ForeColor = $theme.SubText
        $nvLblVer.BackColor = [System.Drawing.Color]::Transparent
        $nvLblVer.Size = [System.Drawing.Size]::new(755, 20)
        $nvLblVer.Location = [System.Drawing.Point]::new(44, 42)
        $nvRowPanel.Controls.Add($nvLblVer)
        $global:allSubTextLabels += $nvLblVer

        $nvDlUrl = $nv.DownloadUrl
        $nvBtnDl = [System.Windows.Forms.Button]::new()
        $nvBtnDl.Size = [System.Drawing.Size]::new(150, 34)
        $nvBtnDl.Location = [System.Drawing.Point]::new(810, 16)
        $nvBtnDl.FlatStyle = "Flat"
        $nvBtnDl.FlatAppearance.BorderSize = 0
        $nvBtnDl.Font = $fontStatus
        $nvBtnDl.Text = "$([char]0x2B07) $(TT 'Λήψη')"
        $nvBtnDl.BackColor = $theme.Accent
        $nvBtnDl.ForeColor = [System.Drawing.Color]::White
        $nvBtnDl.Cursor = [System.Windows.Forms.Cursors]::Hand
        $nvBtnDl.Add_Click({ Start-Process $nvDlUrl }.GetNewClosure())
        Add-ButtonHoverEffect -Button $nvBtnDl -BaseColor $nvBtnDl.BackColor
        $nvRowPanel.Controls.Add($nvBtnDl)

        $global:driverRowItems += $nvRowPanel
        $rowY += 72
    }

    # ΝΕΟ v2.2.0 ("πηγή" - OEM κατασκευαστής, Dell μόνο προς το παρόν - βλ. σχόλιο στο Start-DriverScan
    # για την επιφύλαξη ειλικρίνειας: το XML report format επιβεβαιώθηκε ΜΟΝΟ μέσω τεκμηρίωσης/δημόσιων
    # production scripts, ΟΧΙ ζωντανά σε πραγματικό Dell PC). ΔΕΝ εγκαθιστά τίποτα χωρίς ρητό κλικ χρήστη -
    # αν το DCU δεν είναι εγκατεστημένο, εμφανίζεται ΜΟΝΟ μία γραμμή πρότασης με κουμπί, όχι μόνιμο κουμπί.
    $dellResult = $data.DellResult
    if ($dellResult) {
        if ($dellResult.Installed -and @($dellResult.Updates).Count -gt 0) {
            foreach ($dcuUpd in @($dellResult.Updates)) {
                $dcuRowPanel = [System.Windows.Forms.Panel]::new()
                $dcuRowPanel.Size = [System.Drawing.Size]::new(970, 66)
                $dcuRowPanel.Location = [System.Drawing.Point]::new(5, $rowY)
                $dcuRowPanel.BackColor = $theme.CardBg
                $global:driverPanelList.Controls.Add($dcuRowPanel)

                $dcuIcoPic = [System.Windows.Forms.PictureBox]::new()
                $dcuIcoPic.Image = Get-AppIcon -Type "Chip" -Color $theme.Accent
                $dcuIcoPic.Size = [System.Drawing.Size]::new(24, 24)
                $dcuIcoPic.Location = [System.Drawing.Point]::new(10, 21)
                $dcuIcoPic.SizeMode = "Zoom"
                $dcuRowPanel.Controls.Add($dcuIcoPic)

                $dcuLblName = [System.Windows.Forms.Label]::new()
                $dcuLblName.Text = "$($dcuUpd.name) ($($dcuUpd.type))"
                $dcuLblName.Font = $fontBtnCustom
                $dcuLblName.ForeColor = $theme.Text
                $dcuLblName.BackColor = [System.Drawing.Color]::Transparent
                $dcuLblName.Size = [System.Drawing.Size]::new(910, 40)
                $dcuLblName.Location = [System.Drawing.Point]::new(44, 6)
                $dcuRowPanel.Controls.Add($dcuLblName)
                $global:allTextLabels += $dcuLblName

                $dcuLblVer = [System.Windows.Forms.Label]::new()
                $dcuLblVer.Text = "$(TT 'Έκδοση'): $($dcuUpd.version) ($($dcuUpd.date))  |  $(TT 'Κατηγορία'): $($dcuUpd.category)  |  $([char]0x2713) $(TT 'Πηγή: Dell Command Update (επίσημο)')"
                $dcuLblVer.Font = $fontStatus
                $dcuLblVer.ForeColor = $theme.SubText
                $dcuLblVer.BackColor = [System.Drawing.Color]::Transparent
                $dcuLblVer.Size = [System.Drawing.Size]::new(910, 20)
                $dcuLblVer.Location = [System.Drawing.Point]::new(44, 42)
                $dcuRowPanel.Controls.Add($dcuLblVer)
                $global:allSubTextLabels += $dcuLblVer

                $global:driverRowItems += $dcuRowPanel
                $rowY += 72
            }
            $dcuNoteLbl = [System.Windows.Forms.Label]::new()
            $dcuNoteLbl.Text = if ($global:appSettings.AutoInstallDrivers) { (TT "Ενεργοποιήστε ξανά τη σάρωση μετά την εγκατάσταση για επιβεβαίωση - η αυτόματη εγκατάσταση μέσω Dell Command Update δεν έχει ακόμα συνδεθεί εδώ, χρησιμοποιήστε το Dell Command Update από το μενού Έναρξης.") } else { (TT "Για εγκατάσταση, ανοίξτε το Dell Command Update από το μενού Έναρξης των Windows.") }
            $dcuNoteLbl.Font = $fontStatus
            $dcuNoteLbl.ForeColor = $theme.SubText
            $dcuNoteLbl.BackColor = [System.Drawing.Color]::Transparent
            $dcuNoteLbl.Size = [System.Drawing.Size]::new(960, 34)
            $dcuNoteLbl.Location = [System.Drawing.Point]::new(5, $rowY)
            $global:driverPanelList.Controls.Add($dcuNoteLbl)
            $global:allSubTextLabels += $dcuNoteLbl
            $global:driverRowItems += $dcuNoteLbl
            $rowY += 40
        } elseif (-not $dellResult.Installed) {
            $dcuPromptPanel = [System.Windows.Forms.Panel]::new()
            $dcuPromptPanel.Size = [System.Drawing.Size]::new(970, 50)
            $dcuPromptPanel.Location = [System.Drawing.Point]::new(5, $rowY)
            $dcuPromptPanel.BackColor = $theme.CardBg
            $global:driverPanelList.Controls.Add($dcuPromptPanel)

            $dcuPromptLbl = [System.Windows.Forms.Label]::new()
            $dcuPromptLbl.Text = (TT "Εντοπίστηκε υπολογιστής Dell - το επίσημο Dell Command Update δεν είναι εγκατεστημένο (καλύπτει BIOS/firmware/drivers).")
            $dcuPromptLbl.Font = $fontStatus
            $dcuPromptLbl.ForeColor = $theme.Text
            $dcuPromptLbl.BackColor = [System.Drawing.Color]::Transparent
            $dcuPromptLbl.Size = [System.Drawing.Size]::new(600, 40)
            $dcuPromptLbl.Location = [System.Drawing.Point]::new(10, 5)
            $dcuPromptPanel.Controls.Add($dcuPromptLbl)
            $global:allTextLabels += $dcuPromptLbl

            $dcuBtnInstall = [System.Windows.Forms.Button]::new()
            $dcuBtnInstall.Size = [System.Drawing.Size]::new(280, 34)
            $dcuBtnInstall.Location = [System.Drawing.Point]::new(680, 8)
            $dcuBtnInstall.FlatStyle = "Flat"
            $dcuBtnInstall.FlatAppearance.BorderSize = 0
            $dcuBtnInstall.Font = $fontStatus
            $dcuBtnInstall.Text = (TT "Εγκατάσταση & Έλεγχος μέσω Dell")
            $dcuBtnInstall.BackColor = $theme.Accent
            $dcuBtnInstall.ForeColor = [System.Drawing.Color]::White
            $dcuBtnInstall.Cursor = [System.Windows.Forms.Cursors]::Hand
            $dcuBtnInstall.Add_Click({
                $confirmDcu = Show-CustomMessage -Message (TT "Αυτό θα εγκαταστήσει το επίσημο Dell Command Update μέσω winget, ώστε να ελεγχθούν BIOS/firmware/driver ενημερώσεις απευθείας από τη Dell. Συνέχεια;") -Title (TT "Επιβεβαίωση") -Type "YesNo"
                if ($confirmDcu -ne "Yes") { return }
                if (-not (Get-Command winget.exe -ErrorAction SilentlyContinue)) {
                    Show-CustomMessage -Message (TT "Το winget δεν βρέθηκε στο σύστημα - δεν είναι δυνατή η αυτόματη εγκατάσταση.") -Title "Σφάλμα" -Type "Error"
                    return
                }
                $global:lblDriverStatus.Text = (TT "Εγκατάσταση Dell Command Update σε εξέλιξη...")
                try {
                    Start-Process -FilePath "winget.exe" -ArgumentList @("install", "--id", "Dell.CommandUpdate", "--exact", "--silent", "--accept-source-agreements", "--accept-package-agreements") -WindowStyle Hidden -Wait -ErrorAction Stop
                    $global:lblDriverStatus.Text = (TT "Ολοκληρώθηκε - νέα σάρωση σε εξέλιξη...")
                    Start-DriverScan
                } catch {
                    Show-CustomMessage -Message "$(TT 'Αποτυχία εγκατάστασης'): $($_.Exception.Message)" -Title "Σφάλμα" -Type "Error"
                }
            })
            Add-ButtonHoverEffect -Button $dcuBtnInstall -BaseColor $dcuBtnInstall.BackColor
            $dcuPromptPanel.Controls.Add($dcuBtnInstall)

            $global:driverRowItems += $dcuPromptPanel
            $rowY += 56
        }
    }

    # ΝΕΟ v2.6.0 (Lenovo/HP OEM ανίχνευση - βλ. HANDOFF.md ενότητα 4.Α.3 για γιατί δεν υπάρχει ασφαλής
    # headless σάρωση για αυτούς τους 2 κατασκευαστές, σε αντίθεση με τη Dell): Lenovo παίρνει πρόταση
    # εγκατάστασης (επιβεβαιωμένο Microsoft Store ID για το Lenovo Vantage), HP παίρνει ΜΟΝΟ ενημερωτική
    # γραμμή (κανένα επιβεβαιωμένο winget/msstore ID για το HP Image Assistant - καμία πρόταση εγκατάστασης
    # που δεν μπορούμε να εγγυηθούμε ότι θα δουλέψει).
    $oemResult = $data.OemResult
    if ($oemResult -and $oemResult.OemName -eq "Lenovo") {
        $oemPromptPanel = [System.Windows.Forms.Panel]::new()
        $oemPromptPanel.Size = [System.Drawing.Size]::new(970, 50)
        $oemPromptPanel.Location = [System.Drawing.Point]::new(5, $rowY)
        $oemPromptPanel.BackColor = $theme.CardBg
        $global:driverPanelList.Controls.Add($oemPromptPanel)

        $oemPromptLbl = [System.Windows.Forms.Label]::new()
        $oemPromptLbl.Text = (TT "Εντοπίστηκε υπολογιστής Lenovo - το επίσημο Lenovo Vantage (driver/BIOS ενημερώσεις) δεν φαίνεται εγκατεστημένο.")
        $oemPromptLbl.Font = $fontStatus
        $oemPromptLbl.ForeColor = $theme.Text
        $oemPromptLbl.BackColor = [System.Drawing.Color]::Transparent
        $oemPromptLbl.Size = [System.Drawing.Size]::new(600, 40)
        $oemPromptLbl.Location = [System.Drawing.Point]::new(10, 5)
        $oemPromptPanel.Controls.Add($oemPromptLbl)
        $global:allTextLabels += $oemPromptLbl

        $oemBtnInstall = [System.Windows.Forms.Button]::new()
        $oemBtnInstall.Size = [System.Drawing.Size]::new(280, 34)
        $oemBtnInstall.Location = [System.Drawing.Point]::new(680, 8)
        $oemBtnInstall.FlatStyle = "Flat"
        $oemBtnInstall.FlatAppearance.BorderSize = 0
        $oemBtnInstall.Font = $fontStatus
        $oemBtnInstall.Text = (TT "Εγκατάσταση Lenovo Vantage")
        $oemBtnInstall.BackColor = $theme.Accent
        $oemBtnInstall.ForeColor = [System.Drawing.Color]::White
        $oemBtnInstall.Cursor = [System.Windows.Forms.Cursors]::Hand
        $oemBtnInstall.Add_Click({
            $confirmOem = Show-CustomMessage -Message (TT "Αυτό θα εγκαταστήσει το επίσημο Lenovo Vantage μέσω του Microsoft Store (winget), ώστε να ελέγχετε driver/BIOS ενημερώσεις απευθείας από τη Lenovo. Συνέχεια;") -Title (TT "Επιβεβαίωση") -Type "YesNo"
            if ($confirmOem -ne "Yes") { return }
            if (-not (Get-Command winget.exe -ErrorAction SilentlyContinue)) {
                Show-CustomMessage -Message (TT "Το winget δεν βρέθηκε στο σύστημα - δεν είναι δυνατή η αυτόματη εγκατάσταση.") -Title "Σφάλμα" -Type "Error"
                return
            }
            $global:lblDriverStatus.Text = (TT "Εγκατάσταση Lenovo Vantage σε εξέλιξη...")
            try {
                Start-Process -FilePath "winget.exe" -ArgumentList @("install", "--id", "9WZDNCRFJ4MV", "--source", "msstore", "--accept-source-agreements", "--accept-package-agreements") -WindowStyle Hidden -Wait -ErrorAction Stop
                $global:lblDriverStatus.Text = (TT "Ολοκληρώθηκε - ανοίξτε το Lenovo Vantage από το μενού Έναρξης για έλεγχο ενημερώσεων.")
            } catch {
                Show-CustomMessage -Message "$(TT 'Αποτυχία εγκατάστασης'): $($_.Exception.Message)" -Title "Σφάλμα" -Type "Error"
            }
        })
        Add-ButtonHoverEffect -Button $oemBtnInstall -BaseColor $oemBtnInstall.BackColor
        $oemPromptPanel.Controls.Add($oemBtnInstall)

        $global:driverRowItems += $oemPromptPanel
        $rowY += 56
    } elseif ($oemResult -and $oemResult.OemName -eq "HP") {
        $oemInfoLbl = [System.Windows.Forms.Label]::new()
        $oemInfoLbl.Text = (TT "Εντοπίστηκε υπολογιστής HP - το επίσημο HP Image Assistant (driver/BIOS ενημερώσεις) δεν κατεβαίνει αυτόματα από αυτή την εφαρμογή· διαθέσιμο μέσω hp.com/support.")
        $oemInfoLbl.Font = $fontStatus
        $oemInfoLbl.ForeColor = $theme.SubText
        $oemInfoLbl.BackColor = [System.Drawing.Color]::Transparent
        $oemInfoLbl.Size = [System.Drawing.Size]::new(960, 30)
        $oemInfoLbl.Location = [System.Drawing.Point]::new(5, $rowY)
        $global:driverPanelList.Controls.Add($oemInfoLbl)
        $global:allSubTextLabels += $oemInfoLbl
        $global:driverRowItems += $oemInfoLbl
        $rowY += 36
    }

    # ΝΕΟ v2.2.0 (ρητό αίτημα χρήστη - "γράψε κώδικα για την ενσωμάτωση του Snappy Origin ΧΩΡΙΣ
    # παραθυρικό περιβάλλον" - βλ. αναλυτικό σχόλιο ειλικρίνειας στο Start-DriverScan): ΠΟΤΕ δεν ανοίγει
    # το ίδιο το SDI - είτε προτείνει αθόρυβη εγκατάσταση (με ρητή επιβεβαίωση, ίδιο μοτίβο με Dell) είτε
    # δείχνει status μετά από headless τρέξιμο, με προαιρετικό κουμπί που ανοίγει ΤΟΝ ΦΑΚΕΛΟ αποτελεσμάτων
    # (Explorer σε φάκελο, ΟΧΙ το SDI) για να τα δει ο χρήστης ο ίδιος.
    $sdioResult = $data.SdioResult
    if ($sdioResult) {
        if ($sdioResult.Installed -and $sdioResult.ReportFound -and $sdioResult.HasDriverPacks) {
            $sdioRowPanel = [System.Windows.Forms.Panel]::new()
            $sdioRowPanel.Size = [System.Drawing.Size]::new(970, 50)
            $sdioRowPanel.Location = [System.Drawing.Point]::new(5, $rowY)
            $sdioRowPanel.BackColor = $theme.CardBg
            $global:driverPanelList.Controls.Add($sdioRowPanel)

            $sdioLbl = [System.Windows.Forms.Label]::new()
            $sdioLbl.Text = (TT "Το SDI (Snappy Driver Installer) ολοκλήρωσε αθόρυβο έλεγχο και δημιούργησε αρχείο(α) αναφοράς - καμία εγκατάσταση δεν έγινε αυτόματα.")
            $sdioLbl.Font = $fontStatus
            $sdioLbl.ForeColor = $theme.Text
            $sdioLbl.BackColor = [System.Drawing.Color]::Transparent
            $sdioLbl.Size = [System.Drawing.Size]::new(600, 40)
            $sdioLbl.Location = [System.Drawing.Point]::new(10, 5)
            $sdioRowPanel.Controls.Add($sdioLbl)
            $global:allTextLabels += $sdioLbl

            $sdioReportPath = $sdioResult.ReportPath
            $sdioBtnOpen = [System.Windows.Forms.Button]::new()
            $sdioBtnOpen.Size = [System.Drawing.Size]::new(280, 34)
            $sdioBtnOpen.Location = [System.Drawing.Point]::new(680, 8)
            $sdioBtnOpen.FlatStyle = "Flat"
            $sdioBtnOpen.FlatAppearance.BorderSize = 0
            $sdioBtnOpen.Font = $fontStatus
            $sdioBtnOpen.Text = (TT "Άνοιγμα Φακέλου Αναφοράς")
            $sdioBtnOpen.BackColor = $theme.Accent
            $sdioBtnOpen.ForeColor = [System.Drawing.Color]::White
            $sdioBtnOpen.Cursor = [System.Windows.Forms.Cursors]::Hand
            $sdioBtnOpen.Add_Click({ Start-Process "explorer.exe" -ArgumentList $sdioReportPath }.GetNewClosure())
            Add-ButtonHoverEffect -Button $sdioBtnOpen -BaseColor $sdioBtnOpen.BackColor
            $sdioRowPanel.Controls.Add($sdioBtnOpen)

            $global:driverRowItems += $sdioRowPanel
            $rowY += 56
        } elseif ($sdioResult.Installed -and $sdioResult.ReportFound -and -not $sdioResult.HasDriverPacks) {
            # ΝΕΟ v2.2.5 (χρήστης ανέβασε πραγματικό log.txt - επιβεβαιώθηκε ότι χωρίς τοπική βάση
            # driverpacks το SDI δεν παράγει κανένα χρήσιμο αποτέλεσμα, μόνο τεχνικό log): ΕΙΛΙΚΡΙΝΕΣ
            # μήνυμα αντί για το παραπλανητικό "βρέθηκε αναφορά" - ΚΑΝΕΝΑ κουμπί "Άνοιγμα Φακέλου" εδώ,
            # αφού το μόνο αρχείο μέσα είναι ένα ακατέργαστο, τεχνικό log χωρίς πρακτική αξία για τον
            # χρήστη (ο ίδιος επιβεβαίωσε: "MH XRHSTIKH GIA TON XRHSTH").
            # ΔΙΟΡΘΩΣΗ v2.4.0: μετά την προσθήκη του -autoupdate (βλ. σχόλιο στο Start-DriverScan), αυτό το
            # μονοπάτι πλέον σημαίνει ότι η ΑΥΤΟΜΑΤΗ λήψη index είτε απέτυχε (π.χ. καμία σύνδεση internet)
            # είτε δεν πρόλαβε να ολοκληρωθεί στο νέο χρονικό όριο (3 λεπτά) - το μήνυμα ενημερώθηκε ανάλογα.
            $sdioLblNoPacks = [System.Windows.Forms.Label]::new()
            $sdioLblNoPacks.Text = (TT "Το SDI (Snappy Driver Installer) δεν έχει ακόμα τοπική βάση οδηγών για σύγκριση - η αυτόματη λήψη είτε απέτυχε (ελέγξτε τη σύνδεση internet) είτε χρειάζεται περισσότερο χρόνο· δοκιμάστε ξανά τη σάρωση.")
            $sdioLblNoPacks.Font = $fontStatus
            $sdioLblNoPacks.ForeColor = $theme.SubText
            $sdioLblNoPacks.BackColor = [System.Drawing.Color]::Transparent
            $sdioLblNoPacks.Size = [System.Drawing.Size]::new(960, 30)
            $sdioLblNoPacks.Location = [System.Drawing.Point]::new(5, $rowY)
            $global:driverPanelList.Controls.Add($sdioLblNoPacks)
            $global:allSubTextLabels += $sdioLblNoPacks
            $global:driverRowItems += $sdioLblNoPacks
            $rowY += 36
        } elseif ($sdioResult.Installed -and -not $sdioResult.ReportFound) {
            $sdioLbl2 = [System.Windows.Forms.Label]::new()
            $sdioLbl2.Text = if ($sdioResult.TimedOut) { (TT "Το SDI (Snappy Driver Installer) χρειάστηκε να κατεβάσει δεδομένα κατά την πρώτη εκτέλεση - δοκιμάστε ξανά τη σάρωση.") } else { (TT "Το SDI (Snappy Driver Installer) έτρεξε αλλά δεν παρήγαγε αναγνώσιμη αναφορά αυτή τη φορά.") }
            $sdioLbl2.Font = $fontStatus
            $sdioLbl2.ForeColor = $theme.SubText
            $sdioLbl2.BackColor = [System.Drawing.Color]::Transparent
            $sdioLbl2.Size = [System.Drawing.Size]::new(960, 30)
            $sdioLbl2.Location = [System.Drawing.Point]::new(5, $rowY)
            $global:driverPanelList.Controls.Add($sdioLbl2)
            $global:allSubTextLabels += $sdioLbl2
            $global:driverRowItems += $sdioLbl2
            $rowY += 36
        } elseif (-not $sdioResult.Installed) {
            $sdioPromptPanel = [System.Windows.Forms.Panel]::new()
            $sdioPromptPanel.Size = [System.Drawing.Size]::new(970, 50)
            $sdioPromptPanel.Location = [System.Drawing.Point]::new(5, $rowY)
            $sdioPromptPanel.BackColor = $theme.CardBg
            $global:driverPanelList.Controls.Add($sdioPromptPanel)

            $sdioPromptLbl = [System.Windows.Forms.Label]::new()
            $sdioPromptLbl.Text = (TT "Το SDI (Snappy Driver Installer) δεν είναι εγκατεστημένο - μεγαλύτερη βάση οδηγών, τρέχει πάντα αθόρυβα (καμία δική του διεπαφή).")
            $sdioPromptLbl.Font = $fontStatus
            $sdioPromptLbl.ForeColor = $theme.Text
            $sdioPromptLbl.BackColor = [System.Drawing.Color]::Transparent
            $sdioPromptLbl.Size = [System.Drawing.Size]::new(600, 40)
            $sdioPromptLbl.Location = [System.Drawing.Point]::new(10, 5)
            $sdioPromptPanel.Controls.Add($sdioPromptLbl)
            $global:allTextLabels += $sdioPromptLbl

            $sdioBtnInstall = [System.Windows.Forms.Button]::new()
            $sdioBtnInstall.Size = [System.Drawing.Size]::new(280, 34)
            $sdioBtnInstall.Location = [System.Drawing.Point]::new(680, 8)
            $sdioBtnInstall.FlatStyle = "Flat"
            $sdioBtnInstall.FlatAppearance.BorderSize = 0
            $sdioBtnInstall.Font = $fontStatus
            $sdioBtnInstall.Text = (TT "Εγκατάσταση & Έλεγχος μέσω SDI")
            $sdioBtnInstall.BackColor = $theme.Accent
            $sdioBtnInstall.ForeColor = [System.Drawing.Color]::White
            $sdioBtnInstall.Cursor = [System.Windows.Forms.Cursors]::Hand
            $sdioBtnInstall.Add_Click({
                $confirmSdio = Show-CustomMessage -Message (TT "Αυτό θα εγκαταστήσει το SDI (Snappy Driver Installer Origin) μέσω winget και θα το τρέξει αθόρυβα (χωρίς δική του διεπαφή, καμία εγκατάσταση οδηγών χωρίς επιλογή σας). Συνέχεια;") -Title (TT "Επιβεβαίωση") -Type "YesNo"
                if ($confirmSdio -ne "Yes") { return }
                if (-not (Get-Command winget.exe -ErrorAction SilentlyContinue)) {
                    Show-CustomMessage -Message (TT "Το winget δεν βρέθηκε στο σύστημα - δεν είναι δυνατή η αυτόματη εγκατάσταση.") -Title "Σφάλμα" -Type "Error"
                    return
                }
                $global:lblDriverStatus.Text = (TT "Εγκατάσταση SDI σε εξέλιξη...")
                try {
                    Start-Process -FilePath "winget.exe" -ArgumentList @("install", "--id", "GlennDelahoy.SnappyDriverInstallerOrigin", "--exact", "--silent", "--accept-source-agreements", "--accept-package-agreements") -WindowStyle Hidden -Wait -ErrorAction Stop
                    $global:lblDriverStatus.Text = (TT "Ολοκληρώθηκε - νέα σάρωση σε εξέλιξη...")
                    Start-DriverScan
                } catch {
                    Show-CustomMessage -Message "$(TT 'Αποτυχία εγκατάστασης'): $($_.Exception.Message)" -Title "Σφάλμα" -Type "Error"
                }
            })
            Add-ButtonHoverEffect -Button $sdioBtnInstall -BaseColor $sdioBtnInstall.BackColor
            $sdioPromptPanel.Controls.Add($sdioBtnInstall)

            $global:driverRowItems += $sdioPromptPanel
            $rowY += 56
        }
    }

    # ΝΕΟ v1.8.1 (αναφορά χρήστη: "λέει καμία ενημέρωση ενώ το IObit Driver Booster βρίσκει 11"): αν
    # εντοπιστεί η τεκμηριωμένη πολιτική "ExcludeWUDriversInQualityUpdate" ενεργή, το Windows Update ΔΕΝ
    # μπορεί καν να αναζητήσει drivers - το προηγούμενο μήνυμα "όλοι ενημερωμένοι" ήταν παραπλανητικό σε
    # αυτή την περίπτωση. Δίνεται σαφής εξήγηση + επιλογή απενεργοποίησης της πολιτικής (με προειδοποίηση,
    # απαιτεί επανεκκίνηση για να ισχύσει).
    if ($data.PolicyBlocked) {
        $global:lblDriverStatus.Text = (TT "Το Windows Update είναι ρυθμισμένο να ΜΗΝ αναζητά καθόλου ενημερώσεις οδηγών (πολιτική συστήματος) - πατήστε 'Άρση Αποκλεισμού' για να την απενεργοποιήσετε.")
        $btnUnblock = [System.Windows.Forms.Button]::new()
        $btnUnblock.Text = (TT "Άρση Αποκλεισμού & Νέα Σάρωση")
        $btnUnblock.Font = $fontStatus
        $btnUnblock.Size = [System.Drawing.Size]::new(230, 30)
        $btnUnblock.Location = [System.Drawing.Point]::new(385, 5)
        $btnUnblock.FlatStyle = "Flat"
        $btnUnblock.FlatAppearance.BorderSize = 0
        $btnUnblock.BackColor = $theme.Accent
        $btnUnblock.ForeColor = [System.Drawing.Color]::White
        $btnUnblock.Cursor = [System.Windows.Forms.Cursors]::Hand
        $btnUnblock.Add_Click({
            $confirm = Show-CustomMessage -Message (TT "Αυτό θα απενεργοποιήσει την πολιτική συστήματος που αποκλείει τους drivers από το Windows Update. Θα χρειαστεί νέα σάρωση (και ενδεχομένως επανεκκίνηση) για να ισχύσει. Συνέχεια;") -Title (TT "Επιβεβαίωση") -Type "YesNo"
            if ($confirm -ne "Yes") { return }
            foreach ($p in @("HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate", "HKLM:\SOFTWARE\Microsoft\PolicyManager\current\device\Update", "HKLM:\SOFTWARE\Microsoft\PolicyManager\default\Update", "HKLM:\SOFTWARE\Microsoft\WindowsUpdate\UX\Settings")) {
                try {
                    if (Test-Path $p) { Remove-ItemProperty -Path $p -Name "ExcludeWUDriversInQualityUpdate" -ErrorAction SilentlyContinue }
                } catch {}
            }
            Start-DriverScan
        })
        $global:driverPanelList.Controls.Add($btnUnblock)
        return
    }

    $updates = @($data.Updates)

    if ($updates.Count -eq 0) {
        # ΝΕΟ v1.8.6 (κατόπιν εμπεριστατωμένων προτάσεων χρήστη): το Windows Update API δεν βρήκε τίποτα -
        # αυτό ΔΕΝ σημαίνει απαραίτητα ότι όλα είναι ενημερωμένα (το κανάλι driver ενημερώσεων του Windows
        # Update είναι γνωστά συντηρητικό/περιορισμένο). Αντί να σταματήσουμε εδώ, δίνουμε στον χρήστη μια
        # ΔΕΥΤΕΡΗ, χειροκίνητη γραμμή άμυνας: λίστα εγκατεστημένων συσκευών με κουμπί που ανοίγει το
        # ΕΠΙΣΗΜΟ Microsoft Update Catalog (catalog.update.microsoft.com) προ-συμπληρωμένο με το Hardware
        # ID της συσκευής - 100% επίσημη πηγή, καμία εξάρτηση σε εύθραυστο web-scraping κώδικα.
        $global:lblDriverStatus.Text = (TT "Το Windows Update δεν επέστρεψε αυτόματες προτάσεις. Δείτε παρακάτω τις εγκατεστημένες συσκευές σας - πατήστε 'Έλεγχος' για χειροκίνητη επιβεβαίωση στο επίσημο Microsoft Update Catalog.")
        $devicesWithHwid = @($installed | Where-Object { $_.HardWareID -and $_.HardWareID.Count -gt 0 })
        if ($devicesWithHwid.Count -eq 0) {
            if ($rowY -le 5) {
                $global:lblDriverStatus.Text = (TT "Όλοι οι οδηγοί φαίνονται ενημερωμένοι! Δεν βρέθηκαν διαθέσιμες ενημερώσεις.")
            }
            return
        }
        $rowYManual = $rowY
        foreach ($dev in $devicesWithHwid) {
            $devName = $dev.DeviceName
            $devHwid = @($dev.HardWareID)[0]
            $devIconType = Get-DriverClassIcon -DriverClass $dev.DeviceClass

            $rowPanelM = [System.Windows.Forms.Panel]::new()
            $rowPanelM.Size = [System.Drawing.Size]::new(970, 44)
            $rowPanelM.Location = [System.Drawing.Point]::new(5, $rowYManual)
            $rowPanelM.BackColor = $theme.CardBg
            $global:driverPanelList.Controls.Add($rowPanelM)

            $icoPicM = [System.Windows.Forms.PictureBox]::new()
            $icoPicM.Image = Get-AppIcon -Type $devIconType -Color $theme.Accent
            $icoPicM.Size = [System.Drawing.Size]::new(20, 20)
            $icoPicM.Location = [System.Drawing.Point]::new(10, 12)
            $icoPicM.SizeMode = "Zoom"
            $rowPanelM.Controls.Add($icoPicM)

            $lblNameM = [System.Windows.Forms.Label]::new()
            $lblNameM.Text = "$devName ($($dev.DriverVersion))"
            $lblNameM.Font = $fontStatus
            $lblNameM.ForeColor = $theme.Text
            $lblNameM.BackColor = [System.Drawing.Color]::Transparent
            $lblNameM.Size = [System.Drawing.Size]::new(760, 22)
            $lblNameM.Location = [System.Drawing.Point]::new(40, 11)
            $rowPanelM.Controls.Add($lblNameM)
            $global:allTextLabels += $lblNameM

            $btnCheckM = [System.Windows.Forms.Button]::new()
            $btnCheckM.Size = [System.Drawing.Size]::new(120, 30)
            $btnCheckM.Location = [System.Drawing.Point]::new(810, 7)
            $btnCheckM.FlatStyle = "Flat"
            $btnCheckM.FlatAppearance.BorderSize = 0
            $btnCheckM.Font = $fontStatus
            $btnCheckM.Text = (TT "Έλεγχος")
            $btnCheckM.BackColor = $theme.Accent
            $btnCheckM.ForeColor = [System.Drawing.Color]::White
            $btnCheckM.Cursor = [System.Windows.Forms.Cursors]::Hand
            $btnCheckM.Add_Click({
                # ΔΙΟΡΘΩΣΗ: .GetNewClosure() απαραίτητο - ίδιο μάθημα με το κρίσιμο σφάλμα της v1.8.0.
                $encodedHwid = [System.Uri]::EscapeDataString($devHwid)
                Start-Process "https://www.catalog.update.microsoft.com/Search.aspx?q=$encodedHwid"
            }.GetNewClosure())
            Add-ButtonHoverEffect -Button $btnCheckM -BaseColor $btnCheckM.BackColor
            $rowPanelM.Controls.Add($btnCheckM)

            $rowYManual += 50
        }
        return
    }

    $global:lblDriverStatus.Text = "$(TT 'Βρέθηκαν') $($updates.Count) $(TT 'πιθανές ενημερώσεις οδηγών:')"

    foreach ($upd in $updates) {
        # ΔΙΟΡΘΩΣΗ v1.8.0: ΚΑΘΕ κουμπί λήψης χρειάζεται το ΔΙΚΟ ΤΟΥ UpdateID - ίδιο μάθημα με το bug
        # του K-Lite/Προτεινόμενων Εφαρμογών (v1.8.0): τα scriptblocks σε loop ΠΡΕΠΕΙ να χρησιμοποιούν
        # .GetNewClosure() αλλιώς όλα τα κουμπιά θα μοιράζονται την ΤΕΛΕΥΤΑΙΑ τιμή του loop.
        $updId = $upd.UpdateID
        $updTitle = $upd.Title
        $updSize = $upd.MaxDownloadSize

        # Best-effort αντιστοίχιση με εγκατεστημένη έκδοση (βάσει επικάλυψης ονόματος - το Windows
        # Update δεν εγγυάται ενιαίο κλειδί αντιστοίχισης με το PnP inventory).
        $currentVer = TT "άγνωστη"
        if ($upd.DriverModel) {
            $match = $installed | Where-Object { $_.DeviceName -and $upd.DriverModel -and $_.DeviceName -like "*$($upd.DriverModel)*" } | Select-Object -First 1
            if ($match) { $currentVer = $match.DriverVersion }
        }
        $latestVer = if ($upd.DriverVerDate) { $upd.DriverVerDate } else { (TT "διαθέσιμη μέσω Windows Update") }

        $iconType = Get-DriverClassIcon -DriverClass $upd.DriverClass
        $rowPanel = [System.Windows.Forms.Panel]::new()
        $rowPanel.Size = [System.Drawing.Size]::new(970, 66)
        $rowPanel.Location = [System.Drawing.Point]::new(5, $rowY)
        $rowPanel.BackColor = $theme.CardBg
        $global:driverPanelList.Controls.Add($rowPanel)

        $icoPic = [System.Windows.Forms.PictureBox]::new()
        $icoPic.Image = Get-AppIcon -Type $iconType -Color $theme.Accent
        $icoPic.Size = [System.Drawing.Size]::new(24, 24)
        $icoPic.Location = [System.Drawing.Point]::new(10, 21)
        $icoPic.SizeMode = "Zoom"
        $rowPanel.Controls.Add($icoPic)

        $lblName = [System.Windows.Forms.Label]::new()
        $lblName.Text = $updTitle
        $lblName.Font = $fontBtnCustom
        $lblName.ForeColor = $theme.Text
        $lblName.BackColor = [System.Drawing.Color]::Transparent
        $lblName.Size = [System.Drawing.Size]::new(430, 40)
        $lblName.Location = [System.Drawing.Point]::new(44, 6)
        $rowPanel.Controls.Add($lblName)
        $global:allTextLabels += $lblName

        $lblVer = [System.Windows.Forms.Label]::new()
        # ΝΕΟ v2.2.0 (πολυ-πηγαία αρχιτεκτονική driver engine - βλ. HANDOFF.md ενότητα 0): κάθε γραμμή
        # αποτελέσματος επισημαίνεται με την πηγή της. Windows Update εδώ, AMD (amd.com) στις γραμμές
        # που προστίθενται ΠΡΙΝ από αυτές (βλ. αρχή του Complete-DriverScan) - 2η αυτοματοποιημένη πηγή.
        # ΝΕΟ v2.3.0 (trust/stability scoring): αν το ΙΔΙΟ GPU επιβεβαιώθηκε ανεξάρτητα ΚΑΙ από AMD/NVIDIA
        # (βλ. $confirmedGpuNames παραπάνω), η ετικέτα αναβαθμίζεται από απλή πηγή σε "επιβεβαιωμένο".
        $wuDeviceNameForTrust = if ($match) { $match.DeviceName } else { $updTitle }
        $isCrossConfirmed = ($upd.DriverClass -match "Display|Video") -and (Test-DriverSourceOverlap -DeviceName $wuDeviceNameForTrust -ConfirmedNames $confirmedGpuNames)
        $sourceMark = if ($isCrossConfirmed) { "$([char]0x2713)$([char]0x2713)" } else { "$([char]0x2713)" }
        $sourceLabelText = if ($isCrossConfirmed) { TT "Επιβεβαιωμένο (WU+AMD/NVIDIA)" } else { TT "Πηγή: Windows Update (επίσημη)" }
        $lblVer.Text = "$(TT 'Τρέχουσα'): $currentVer  |  $(TT 'Διαθέσιμη'): $latestVer  |  $(TT 'Μέγεθος'): $(Format-DriverFileSize -Bytes $updSize)  |  $sourceMark $sourceLabelText"
        $lblVer.Font = $fontStatus
        $lblVer.ForeColor = $theme.SubText
        $lblVer.BackColor = [System.Drawing.Color]::Transparent
        $lblVer.Size = [System.Drawing.Size]::new(755, 20)
        $lblVer.Location = [System.Drawing.Point]::new(44, 42)
        $rowPanel.Controls.Add($lblVer)
        $global:allSubTextLabels += $lblVer
        if ($isCrossConfirmed) {
            $global:appToolTip.SetToolTip($lblVer, (TT "Αυτό το GPU εντοπίστηκε ΚΑΙ από το Windows Update ΚΑΙ ξεχωριστά από τον επίσημο ιστότοπο του κατασκευαστή (AMD/NVIDIA) - δύο ανεξάρτητες πηγές συμφωνούν ότι υπάρχει νεότερος οδηγός, υψηλότερη αξιοπιστία από μία μόνο πηγή."))
        }

        $btnDl = [System.Windows.Forms.Button]::new()
        $btnDl.Size = [System.Drawing.Size]::new(150, 34)
        $btnDl.Location = [System.Drawing.Point]::new(810, 16)
        $btnDl.FlatStyle = "Flat"
        $btnDl.FlatAppearance.BorderSize = 0
        $btnDl.Font = $fontStatus
        $btnDl.Text = "$([char]0x2B07) $(TT 'Λήψη')"
        $btnDl.BackColor = $theme.Accent
        $btnDl.ForeColor = [System.Drawing.Color]::White
        $btnDl.Cursor = [System.Windows.Forms.Cursors]::Hand
        $btnDl.Add_Click({
            if ($global:appSettings.AutoInstallDrivers) {
                Install-DriverUpdate -UpdateID $updId -Title $updTitle
            } else {
                # Προεπιλογή (χωρίς το opt-in από τις Ρυθμίσεις): ανοίγει τις επίσημες Ρυθμίσεις
                # Windows Update για έλεγχο/εγκατάσταση από τον ίδιο τον χρήστη - ασφαλές, χωρίς
                # αθόρυβη ενέργεια εκ μέρους της εφαρμογής.
                Start-Process "ms-settings:windowsupdate-optionalupdates"
            }
        }.GetNewClosure())
        Add-ButtonHoverEffect -Button $btnDl -BaseColor $btnDl.BackColor
        $rowPanel.Controls.Add($btnDl)

        $global:driverRowItems += $rowPanel
        $rowY += 72
    }
    Show-ToastNotification -Message (TT "Ο έλεγχος οδηγών ολοκληρώθηκε.") -Title (TT "Οδηγοί")
}

function Install-DriverUpdate {
    param([string]$UpdateID, [string]$Title)
    $global:lblDriverStatus.Text = "$(TT 'Λήψη/εγκατάσταση οδηγού σε εξέλιξη'): $Title..."
    $installScript = @"
`$ErrorActionPreference = "Continue"
try {
    `$session = New-Object -ComObject Microsoft.Update.Session
    `$searcher = `$session.CreateUpdateSearcher()
    `$result = `$searcher.Search("UpdateID='$UpdateID'")
    if (`$result.Updates.Count -eq 0) { exit 1 }
    `$toInstall = New-Object -ComObject Microsoft.Update.UpdateColl
    `$toInstall.Add(`$result.Updates.Item(0)) | Out-Null
    `$downloader = `$session.CreateUpdateDownloader()
    `$downloader.Updates = `$toInstall
    `$downloader.Download() | Out-Null
    `$installer = `$session.CreateUpdateInstaller()
    `$installer.Updates = `$toInstall
    `$installer.Install() | Out-Null
} catch {}
"@
    $scriptFile = Join-Path $env:TEMP "OptimizerDriverInstall_$([guid]::NewGuid().ToString('N')).ps1"
    Set-Content -Path $scriptFile -Value $installScript -Encoding utf8
    try {
        Start-Process -FilePath "powershell.exe" -ArgumentList "-NoProfile -ExecutionPolicy Bypass -File `"$scriptFile`"" -WindowStyle Minimized -ErrorAction Stop
        $global:lblDriverStatus.Text = "$(TT 'Η εγκατάσταση του οδηγού ξεκίνησε σε εξέλιξη στο παρασκήνιο'): $Title"
    } catch {
        Show-CustomMessage -Message "Αποτυχία εκκίνησης εγκατάστασης: $($_.Exception.Message)" -Title "Σφάλμα" -Type "Error"
    }
}

$global:btnDriverScan.Add_Click({ Start-DriverScan })

# ===== ΝΕΑ ΚΑΡΤΑ (v1.9.4): ΑΝΤΙΓΡΑΦΟ ΑΣΦΑΛΕΙΑΣ ΟΔΗΓΩΝ (DRIVER BACKUP/RESTORE) =====
# Χρησιμοποιεί το επίσημο, ενσωματωμένο στα Windows μηχανισμό DISM (Export-WindowsDriver) για εξαγωγή
# ΟΛΩΝ των οδηγών τρίτων κατασκευαστών (ΟΧΙ των native Windows drivers) σε φάκελο, και pnputil για
# επαναφορά - το ίδιο μηχανισμό που χρησιμοποιούν καθιερωμένα εργαλεία δημιουργίας αντιγράφων οδηγών.
# Ιδιαίτερα χρήσιμο πριν από επανεγκατάσταση Windows.
$cardOpt5 = Helper-CreateCard 20 1180 1030 200 $global:scrollPanelOptimization
Add-IconedLabel -IconType "Update" -Text (TT "Αντίγραφο Ασφαλείας Οδηγών Συστήματος") -x 15 -y 10 -w 700 -Font $fontBoldText -IsSubText $false -Parent $cardOpt5 | Out-Null

$lblDriverBackupDesc = [System.Windows.Forms.Label]::new()
$lblDriverBackupDesc.Text = (TT "Δημιουργεί αντίγραφο ασφαλείας όλων των οδηγών τρίτων κατασκευαστών (κάρτα γραφικών, δικτύου, κ.λπ.) σε φάκελο της επιλογής σας. Χρήσιμο πριν από επανεγκατάσταση Windows - επαναφέρετε τους με ένα κλικ.")
$lblDriverBackupDesc.Font = $fontText
$lblDriverBackupDesc.ForeColor = $theme.SubText
$lblDriverBackupDesc.BackColor = [System.Drawing.Color]::Transparent
$lblDriverBackupDesc.Size = [System.Drawing.Size]::new(1000, 40)
$lblDriverBackupDesc.Location = [System.Drawing.Point]::new(15, 38)
$cardOpt5.Controls.Add($lblDriverBackupDesc)
$global:allTextLabels += $lblDriverBackupDesc

$global:lblDriverBackupStatus = [System.Windows.Forms.Label]::new()
$global:lblDriverBackupStatus.Text = (TT "Επιλέξτε ενέργεια.")
$global:lblDriverBackupStatus.Font = $fontStatus
$global:lblDriverBackupStatus.ForeColor = $theme.SubText
$global:lblDriverBackupStatus.Size = [System.Drawing.Size]::new(1000, 40)
$global:lblDriverBackupStatus.Location = [System.Drawing.Point]::new(15, 130)
$cardOpt5.Controls.Add($global:lblDriverBackupStatus)
$global:allSubTextLabels += $global:lblDriverBackupStatus

$global:driverBackupTimer = [System.Windows.Forms.Timer]::new()
$global:driverBackupTimer.Interval = 1000
$global:driverBackupTimer.Add_Tick({
    if (-not $global:driverBackupState) { $global:driverBackupTimer.Stop(); return }
    if (-not $global:driverBackupState.Process.HasExited) { return }
    $global:driverBackupTimer.Stop()
    $exitCodeDb = $global:driverBackupState.Process.ExitCode
    $backupPathDb = $global:driverBackupState.Path
    # ΔΙΟΡΘΩΣΗ: το ίδιο timer/state πλέον εξυπηρετεί ΚΑΙ την Επαναφορά (Restore) - πριν αυτή έκανε
    # Start-Process -Wait ΑΠΕΥΘΕΙΑΣ στο UI thread (pnputil /subdirs σε φάκελο με πολλούς οδηγούς μπορεί
    # να διαρκέσει αρκετά λεπτά), παγώνοντας ολόκληρη την εφαρμογή στο μεταξύ.
    $modeDb = $global:driverBackupState.Mode
    $global:driverBackupState = $null
    if ($modeDb -eq "Restore") {
        if ($exitCodeDb -eq 0) {
            $global:lblDriverBackupStatus.Text = (TT "Η επαναφορά οδηγών ολοκληρώθηκε.")
        } else {
            $global:lblDriverBackupStatus.Text = "$(TT 'Αποτυχία επαναφοράς')($exitCodeDb)"
        }
        return
    }
    if ($exitCodeDb -eq 0) {
        $global:lblDriverBackupStatus.Text = "$(TT 'Το αντίγραφο ασφαλείας ολοκληρώθηκε:') $backupPathDb"
    } else {
        $global:lblDriverBackupStatus.Text = (TT "Η δημιουργία αντιγράφου απέτυχε ή ακυρώθηκε.")
    }
})

$global:btnDriverBackup = Helper-CreateButton (TT "Δημιουργία Αντιγράφου Ασφαλείας") 15 85 350 34 $theme.Accent {
    if ($global:driverBackupState) {
        Show-CustomMessage -Message (TT "Εκτελείται ήδη μια ενέργεια αντιγράφου/επαναφοράς οδηγών - περιμένετε να ολοκληρωθεί.") -Title (TT "Προσοχή") -Type "Info"
        return
    }
    $fbdDriver = [System.Windows.Forms.FolderBrowserDialog]::new()
    $fbdDriver.Description = (TT "Επιλέξτε φάκελο αποθήκευσης αντιγράφου οδηγών")
    if ($fbdDriver.ShowDialog() -ne [System.Windows.Forms.DialogResult]::OK) { return }
    $destPath = Join-Path $fbdDriver.SelectedPath "DriverBackup_$(Get-Date -Format 'yyyy-MM-dd')"
    $global:lblDriverBackupStatus.Text = (TT "Δημιουργία αντιγράφου ασφαλείας σε εξέλιξη - μπορεί να διαρκέσει λίγα λεπτά...")
    try {
        $procDb = Start-Process -FilePath "dism.exe" -ArgumentList "/Online", "/Export-Driver", "/Destination:`"$destPath`"" -WindowStyle Hidden -PassThru -ErrorAction Stop
    } catch {
        $global:lblDriverBackupStatus.Text = "$(TT 'Αποτυχία εκκίνησης'): $($_.Exception.Message)"
        return
    }
    $global:driverBackupState = [PSCustomObject]@{ Process = $procDb; Path = $destPath; Mode = "Backup" }
    $global:driverBackupTimer.Start()
} $cardOpt5 $true (TT "Εξάγει όλους τους οδηγούς τρίτων κατασκευαστών σε φάκελο - χρησιμοποιεί το επίσημο εργαλείο DISM των Windows.")

$global:btnDriverRestore = Helper-CreateButton (TT "Επαναφορά Οδηγών από Αντίγραφο") 375 85 350 34 ([System.Drawing.Color]::FromArgb(90, 90, 100)) {
    if ($global:driverBackupState) {
        Show-CustomMessage -Message (TT "Εκτελείται ήδη μια ενέργεια αντιγράφου/επαναφοράς οδηγών - περιμένετε να ολοκληρωθεί.") -Title (TT "Προσοχή") -Type "Info"
        return
    }
    $fbdRestore = [System.Windows.Forms.FolderBrowserDialog]::new()
    $fbdRestore.Description = (TT "Επιλέξτε τον φάκελο αντιγράφου ασφαλείας οδηγών")
    if ($fbdRestore.ShowDialog() -ne [System.Windows.Forms.DialogResult]::OK) { return }
    $confirmRestoreDrv = Show-CustomMessage -Message "$(TT 'Εγκατάσταση όλων των οδηγών από:') $($fbdRestore.SelectedPath)? $(TT 'Συνιστάται μόνο αν οι οδηγοί προέρχονται από αυτόν τον ίδιο υπολογιστή.')" -Title (TT "Επιβεβαίωση") -Type "YesNo"
    if ($confirmRestoreDrv -ne "Yes") { return }
    $global:lblDriverBackupStatus.Text = (TT "Επαναφορά οδηγών σε εξέλιξη...")
    # ΔΙΟΡΘΩΣΗ (bug: Start-Process -Wait πάγωνε ολόκληρη την εφαρμογή - το pnputil /subdirs σε φάκελο με
    # πολλούς οδηγούς μπορεί να διαρκέσει αρκετά λεπτά). Τώρα ασύγχρονο, ίδιο μοτίβο με το Δημιουργία
    # Αντιγράφου παραπάνω (μοιράζονται το ίδιο driverBackupTimer/driverBackupState, βλ. Mode="Restore").
    try {
        $procDr = Start-Process -FilePath "pnputil.exe" -ArgumentList "/add-driver", "`"$($fbdRestore.SelectedPath)\*.inf`"", "/subdirs", "/install" -WindowStyle Hidden -PassThru -ErrorAction Stop
    } catch {
        Show-CustomMessage -Message "$(TT 'Αποτυχία επαναφοράς'): $($_.Exception.Message)" -Title "Σφάλμα" -Type "Error"
        return
    }
    $global:driverBackupState = [PSCustomObject]@{ Process = $procDr; Path = $fbdRestore.SelectedPath; Mode = "Restore" }
    $global:driverBackupTimer.Start()
} $cardOpt5 $true (TT "Εγκαθιστά ξανά όλους τους οδηγούς από φάκελο αντιγράφου ασφαλείας - απαιτεί δικαιώματα διαχειριστή.")

# ===== ΝΕΑ ΚΑΡΤΑ (κατόπιν reverse engineering του WMT): ΚΑΘΑΡΙΣΜΟΣ ΑΠΟΘΗΚΗΣ ΟΔΗΓΩΝ & ΑΝΑΦΟΡΑ =====
# Χρησιμοποιεί το επίσημο DISM cmdlet Get-WindowsDriver (ΟΧΙ ανάλυση κειμένου του pnputil, το οποίο είναι
# localized ανά γλώσσα Windows και είχε ήδη προκαλέσει bug αλλού στην εφαρμογή - βλ. καθαρισμός
# διαπιστευτηρίων Xbox). Το Get-WindowsDriver επιστρέφει δομημένα αντικείμενα (Driver/OriginalFileName/
# Date/Version/Inbox) ανεξαρτήτως γλώσσας συστήματος. "Inbox" = εργοστασιακός οδηγός Windows (ΠΟΤΕ δεν
# αγγίζεται) - μόνο πακέτα τρίτων κατασκευαστών (Inbox=false) εμφανίζονται. Ομαδοποίηση κατά όνομα αρχείου
# OriginalFileName: αν υπάρχουν 2+ εκδόσεις του ΙΔΙΟΥ πακέτου, κρατάμε πάντα την πιο πρόσφατη και
# προτείνουμε προς διαγραφή μόνο τις παλιότερες - το pnputil αρνείται ούτως ή άλλως να διαγράψει έναν
# οδηγό που βρίσκεται ενεργά σε χρήση, οπότε δεν υπάρχει κίνδυνος να "σπάσει" συσκευή.
$cardDriverStore = Helper-CreateCard 20 1400 1030 350 $global:scrollPanelOptimization
Add-IconedLabel -IconType "Update" -Text (TT "Καθαρισμός Αποθήκης Οδηγών & Αναφορά") -x 15 -y 10 -w 700 -Font $fontBoldText -IsSubText $false -Parent $cardDriverStore | Out-Null

$lblDriverStoreDesc = [System.Windows.Forms.Label]::new()
$lblDriverStoreDesc.Text = (TT "Εντοπίζει παλιότερες, διπλότυπες εκδόσεις οδηγών τρίτων κατασκευαστών στην αποθήκη οδηγών των Windows (ποτέ εργοστασιακούς οδηγούς Windows) και σας επιτρέπει να διαγράψετε μόνο τις παλιές, ελευθερώνοντας χώρο δίσκου.")
$lblDriverStoreDesc.Font = $fontText
$lblDriverStoreDesc.ForeColor = $theme.SubText
$lblDriverStoreDesc.BackColor = [System.Drawing.Color]::Transparent
$lblDriverStoreDesc.Size = [System.Drawing.Size]::new(1000, 40)
$lblDriverStoreDesc.Location = [System.Drawing.Point]::new(15, 38)
$cardDriverStore.Controls.Add($lblDriverStoreDesc)
$global:allTextLabels += $lblDriverStoreDesc

$global:lblDriverStoreStatus = [System.Windows.Forms.Label]::new()
$global:lblDriverStoreStatus.Text = (TT "Πατήστε 'Σάρωση' για έναρξη.")
$global:lblDriverStoreStatus.Font = $fontStatus
$global:lblDriverStoreStatus.ForeColor = $theme.SubText
$global:lblDriverStoreStatus.Size = [System.Drawing.Size]::new(1000, 20)
$global:lblDriverStoreStatus.Location = [System.Drawing.Point]::new(15, 82)
$cardDriverStore.Controls.Add($global:lblDriverStoreStatus)
$global:allSubTextLabels += $global:lblDriverStoreStatus

Helper-CreateButton (TT "Εξαγωγή Αναφοράς Οδηγών") 15 108 320 34 $theme.BtnDefault {
    Invoke-DiagnosticCommand "Get-WindowsDriver -Online -All | Select-Object Driver, OriginalFileName, ClassName, ProviderName, Date, Version, Inbox | Format-Table -AutoSize | Out-File -FilePath '$env:USERPROFILE\Desktop\DriverReport.txt' -Encoding utf8 -Width 300; notepad '$env:USERPROFILE\Desktop\DriverReport.txt'"
} $cardDriverStore $true (TT "Εξάγει πλήρη λίστα εγκατεστημένων οδηγών (όνομα, έκδοση, ημερομηνία, πάροχος) σε αρχείο .txt στην Επιφάνεια Εργασίας.")

$global:btnDriverStoreScan = Helper-CreateButton (TT "Σάρωση για Παλιές Εκδόσεις") 360 108 320 34 $theme.Accent {
    Start-DriverStoreScan
} $cardDriverStore $true (TT "Σαρώνει την αποθήκη οδηγών για παλιότερες, διπλότυπες εκδόσεις πακέτων τρίτων κατασκευαστών (μπορεί να διαρκέσει έως 30 δευτερόλεπτα).")

$global:driverStorePanelList = [System.Windows.Forms.Panel]::new()
$global:driverStorePanelList.Size = [System.Drawing.Size]::new(1000, 180)
$global:driverStorePanelList.Location = [System.Drawing.Point]::new(15, 150)
$global:driverStorePanelList.AutoScroll = $true
Set-PanelScrollbarDarkMode -Panel $global:driverStorePanelList
$global:allThemedScrollPanels = @($global:allThemedScrollPanels) + $global:driverStorePanelList
$global:driverStorePanelList.BackColor = $theme.MainBg
if ($setStyleMethod) { $setStyleMethod.Invoke($global:driverStorePanelList, @($flickerFixStyles, $true)) | Out-Null }
$cardDriverStore.Controls.Add($global:driverStorePanelList)

$global:driverStoreScanState = $null
$global:driverStoreScanTimer = [System.Windows.Forms.Timer]::new()
$global:driverStoreScanTimer.Interval = 800
$global:driverStoreScanTimer.Add_Tick({
    if (-not $global:driverStoreScanState) { $global:driverStoreScanTimer.Stop(); return }
    if (-not $global:driverStoreScanState.Process.HasExited) { return }
    $global:driverStoreScanTimer.Stop()
    $rawJsonDs = $null
    if (Test-Path $global:driverStoreScanState.OutFile) {
        $rawJsonDs = Get-Content -Path $global:driverStoreScanState.OutFile -Raw -ErrorAction SilentlyContinue
        Remove-Item -Path $global:driverStoreScanState.OutFile -Force -ErrorAction SilentlyContinue
    }
    if (Test-Path $global:driverStoreScanState.ScriptFile) {
        Remove-Item -Path $global:driverStoreScanState.ScriptFile -Force -ErrorAction SilentlyContinue
    }
    $global:driverStoreScanState = $null
    $global:driverStorePanelList.Controls.Clear()
    if (-not $rawJsonDs) {
        $global:lblDriverStoreStatus.Text = (TT "Αποτυχία σάρωσης οδηγών.")
        return
    }
    try {
        $allPkgs = @($rawJsonDs | ConvertFrom-Json -ErrorAction Stop)
    } catch {
        $global:lblDriverStoreStatus.Text = (TT "Σφάλμα ανάλυσης αποτελεσμάτων σάρωσης.")
        return
    }
    $groupsDs = $allPkgs | Where-Object { $_.OriginalFileName } | Group-Object { Split-Path $_.OriginalFileName -Leaf }
    $removable = @()
    foreach ($g in $groupsDs) {
        if ($g.Count -lt 2) { continue }
        $sorted = @($g.Group | Sort-Object { [DateTime]$_.Date } -Descending)
        $removable += $sorted[1..($sorted.Count - 1)]
    }
    if ($removable.Count -eq 0) {
        $global:lblDriverStoreStatus.Text = (TT "Δεν βρέθηκαν παλιές, διπλότυπες εκδόσεις οδηγών - η αποθήκη οδηγών είναι καθαρή.")
        return
    }
    $global:lblDriverStoreStatus.Text = "$($removable.Count) $(TT 'παλιές εκδόσεις οδηγών βρέθηκαν - μπορείτε να τις διαγράψετε παρακάτω.')"
    $rowYDs = 5
    foreach ($pkg in $removable) {
        $pkgDriver = $pkg.Driver
        $pkgLabel = "$($pkg.ProviderName) - $(Split-Path $pkg.OriginalFileName -Leaf) ($($pkg.Version), $($pkg.Date)) [$pkgDriver]"

        $rowPanelDs = [System.Windows.Forms.Panel]::new()
        $rowPanelDs.Size = [System.Drawing.Size]::new(970, 34)
        $rowPanelDs.Location = [System.Drawing.Point]::new(5, $rowYDs)
        $rowPanelDs.BackColor = $theme.CardBg
        $global:driverStorePanelList.Controls.Add($rowPanelDs)

        $lblPkgInfo = [System.Windows.Forms.Label]::new()
        $lblPkgInfo.Text = $pkgLabel
        $lblPkgInfo.Font = $fontStatus
        $lblPkgInfo.ForeColor = $theme.Text
        $lblPkgInfo.BackColor = [System.Drawing.Color]::Transparent
        $lblPkgInfo.Size = [System.Drawing.Size]::new(830, 28)
        $lblPkgInfo.Location = [System.Drawing.Point]::new(10, 3)
        $rowPanelDs.Controls.Add($lblPkgInfo)
        $global:allTextLabels += $lblPkgInfo

        $btnDeletePkg = [System.Windows.Forms.Button]::new()
        $btnDeletePkg.Text = (TT "Διαγραφή")
        $btnDeletePkg.Size = [System.Drawing.Size]::new(110, 28)
        $btnDeletePkg.Location = [System.Drawing.Point]::new(850, 3)
        $btnDeletePkg.FlatStyle = "Flat"
        $btnDeletePkg.FlatAppearance.BorderSize = 0
        $btnDeletePkg.Font = $fontStatus
        $btnDeletePkg.BackColor = [System.Drawing.Color]::FromArgb(200, 80, 70)
        $btnDeletePkg.ForeColor = [System.Drawing.Color]::White
        $btnDeletePkg.Cursor = [System.Windows.Forms.Cursors]::Hand
        $btnDeletePkg.Add_Click({
            try {
                $delOutput = & pnputil.exe /delete-driver $pkgDriver /uninstall /force 2>&1 | Out-String
                $rowPanelDs.Dispose()
                $lblStatus.Text = "$pkgDriver $(TT 'διαγράφηκε από την αποθήκη οδηγών.')"
            } catch {
                Show-CustomMessage -Message "$(TT 'Αποτυχία διαγραφής οδηγού'): $($_.Exception.Message)" -Title "Σφάλμα" -Type "Error"
            }
        }.GetNewClosure())
        Add-ButtonHoverEffect -Button $btnDeletePkg -BaseColor $btnDeletePkg.BackColor
        $rowPanelDs.Controls.Add($btnDeletePkg)

        $rowYDs += 38
    }
})

function Start-DriverStoreScan {
    if ($global:driverStoreScanState) { return }
    $global:lblDriverStoreStatus.Text = (TT "Σάρωση αποθήκης οδηγών σε εξέλιξη - μπορεί να διαρκέσει έως 30 δευτερόλεπτα...")
    $global:driverStorePanelList.Controls.Clear()
    $tempOutDs = Join-Path $env:TEMP "OptimizerDriverStore_$([guid]::NewGuid().ToString('N')).json"
    $dsScriptContent = @'
$ErrorActionPreference = "Continue"
$drivers = Get-WindowsDriver -Online -All -ErrorAction SilentlyContinue | Where-Object { -not $_.Inbox } | Select-Object Driver, OriginalFileName, ClassName, ProviderName, Date, Version
($drivers | ConvertTo-Json -Depth 3 -Compress) | Out-File -FilePath "OUTFILE_PLACEHOLDER" -Encoding utf8
'@
    $dsScriptContent = $dsScriptContent.Replace("OUTFILE_PLACEHOLDER", $tempOutDs)
    $dsScriptFile = Join-Path $env:TEMP "OptimizerDriverStoreScript_$([guid]::NewGuid().ToString('N')).ps1"
    Set-Content -Path $dsScriptFile -Value $dsScriptContent -Encoding utf8
    try {
        $procDs = Start-Process -FilePath "powershell.exe" -ArgumentList "-NoProfile -ExecutionPolicy Bypass -File `"$dsScriptFile`"" -WindowStyle Hidden -PassThru -ErrorAction Stop
    } catch {
        $global:lblDriverStoreStatus.Text = "$(TT 'Αποτυχία εκκίνησης'): $($_.Exception.Message)"
        return
    }
    $global:driverStoreScanState = [PSCustomObject]@{ Process = $procDs; OutFile = $tempOutDs; ScriptFile = $dsScriptFile }
    $global:driverStoreScanTimer.Start()
}

