$global:regCleanPanelList = [System.Windows.Forms.Panel]::new()
$global:regCleanPanelList.Size = [System.Drawing.Size]::new(1000, 210)
$global:regCleanPanelList.Location = [System.Drawing.Point]::new(15, 150)
$global:regCleanPanelList.AutoScroll = $true
Set-PanelScrollbarDarkMode -Panel $global:regCleanPanelList
$global:allThemedScrollPanels = @($global:allThemedScrollPanels) + $global:regCleanPanelList
$global:regCleanPanelList.BackColor = $theme.MainBg
if ($setStyleMethod) { $setStyleMethod.Invoke($global:regCleanPanelList, @($flickerFixStyles, $true)) | Out-Null }
$cardRegClean.Controls.Add($global:regCleanPanelList)

$global:regCleanFindings = @()
$global:regCleanCheckboxes = @()
$global:regCleanScanTimer = [System.Windows.Forms.Timer]::new()
$global:regCleanScanTimer.Interval = 800
$global:regCleanScanTimer.Add_Tick({
    if (-not $global:regCleanScanState) { $global:regCleanScanTimer.Stop(); return }
    if (-not $global:regCleanScanState.Process.HasExited) { return }
    $global:regCleanScanTimer.Stop()
    $rawJsonRc = $null
    if (Test-Path $global:regCleanScanState.OutFile) {
        $rawJsonRc = Get-Content -Path $global:regCleanScanState.OutFile -Raw -ErrorAction SilentlyContinue
        Remove-Item -Path $global:regCleanScanState.OutFile -Force -ErrorAction SilentlyContinue
    }
    if (Test-Path $global:regCleanScanState.ScriptFile) {
        Remove-Item -Path $global:regCleanScanState.ScriptFile -Force -ErrorAction SilentlyContinue
    }
    $global:regCleanScanState = $null
    Complete-RegistryCleanScan -RawJson $rawJsonRc
})

function Start-RegistryCleanScan {
    if ($global:regCleanScanState) { return }
    $global:lblRegCleanStatus.Text = (TT "Σάρωση σε εξέλιξη...")
    $global:regCleanPanelList.Controls.Clear()
    $tempOutRc = Join-Path $env:TEMP "OptimizerRegClean_$([guid]::NewGuid().ToString('N')).json"
    $rcScriptContent = @'
$ErrorActionPreference = "Continue"
$rcFindings = New-Object System.Collections.ArrayList
$rcSystemRoot = $env:SystemRoot
$rcProtectedFolders = @("System32", "SysWOW64", "Sysnative", "WinSxS", "servicing", "SystemApps", "Microsoft.NET", "Fonts") | ForEach-Object { Join-Path $rcSystemRoot $_ }

function Test-RcPathExists {
    param($Path)
    if ([string]::IsNullOrWhiteSpace($Path)) { return $false }
    $expanded = [Environment]::ExpandEnvironmentVariables($Path.Trim().Trim('"'))
    if ($expanded -match "%.*%") { return $false }
    return (Test-Path -LiteralPath $expanded -ErrorAction SilentlyContinue)
}
function Test-RcIsProtected {
    param($Path)
    if ([string]::IsNullOrWhiteSpace($Path)) { return $false }
    $expanded = [Environment]::ExpandEnvironmentVariables($Path.Trim().Trim('"'))
    foreach ($pf in $rcProtectedFolders) {
        if ($expanded.StartsWith($pf, [System.StringComparison]::OrdinalIgnoreCase)) { return $true }
    }
    return $false
}
function Get-RcExePath {
    param($UninstallString)
    if ([string]::IsNullOrWhiteSpace($UninstallString)) { return $null }
    $s = $UninstallString.Trim()
    if ($s.StartsWith('"')) {
        $endQuote = $s.IndexOf('"', 1)
        if ($endQuote -gt 0) { return $s.Substring(1, $endQuote - 1) }
    }
    return ($s -split '\s+')[0]
}

foreach ($uPath in @(
    "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*",
    "HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*",
    "HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*"
)) {
    Get-ItemProperty -Path $uPath -ErrorAction SilentlyContinue | ForEach-Object {
        if ($_.DisplayName -and $_.UninstallString -and -not $_.SystemComponent -and -not $_.WindowsInstaller -and -not $_.NoRemove) {
            $exePath = Get-RcExePath -UninstallString $_.UninstallString
            if ($exePath -and -not (Test-RcIsProtected -Path $exePath) -and -not (Test-RcPathExists -Path $exePath)) {
                $regPathClean = $_.PSPath -replace "^Microsoft\.PowerShell\.Core\\Registry::", ""
                [void]$rcFindings.Add([PSCustomObject]@{ Category = "MissingUninstaller"; Display = "$($_.DisplayName)"; RegPath = $regPathClean; ValueName = $null })
            }
        }
    }
}

$muiKey = "HKCU:\Software\Classes\Local Settings\Software\Microsoft\Windows\Shell\MuiCache"
if (Test-Path $muiKey) {
    $muiProps = Get-ItemProperty -Path $muiKey -ErrorAction SilentlyContinue
    if ($muiProps) {
        $muiProps.PSObject.Properties | Where-Object { $_.Name -notmatch "^PS" } | ForEach-Object {
            $cleanPath = $_.Name -replace "\.(FriendlyAppName|ApplicationCompany)$", ""
            if ($cleanPath -match "^[a-zA-Z]:\\" -and -not (Test-RcPathExists -Path $cleanPath)) {
                [void]$rcFindings.Add([PSCustomObject]@{ Category = "ObsoleteMuiCache"; Display = $cleanPath; RegPath = $muiKey; ValueName = $_.Name })
            }
        }
    }
}

($rcFindings | ConvertTo-Json -Depth 4 -Compress) | Out-File -FilePath "OUTFILE_PLACEHOLDER" -Encoding utf8
'@
    $rcScriptContent = $rcScriptContent.Replace("OUTFILE_PLACEHOLDER", $tempOutRc)
    $rcScriptFile = Join-Path $env:TEMP "OptimizerRegCleanScript_$([guid]::NewGuid().ToString('N')).ps1"
    Set-Content -Path $rcScriptFile -Value $rcScriptContent -Encoding utf8
    try {
        $procRc = Start-Process -FilePath "powershell.exe" -ArgumentList "-NoProfile -ExecutionPolicy Bypass -File `"$rcScriptFile`"" -WindowStyle Minimized -PassThru -ErrorAction Stop
    } catch {
        $global:lblRegCleanStatus.Text = "$(TT 'Αποτυχία εκκίνησης'): $($_.Exception.Message)"
        return
    }
    $global:regCleanScanState = [PSCustomObject]@{ Process = $procRc; OutFile = $tempOutRc; ScriptFile = $rcScriptFile }
    $global:regCleanScanTimer.Start()
}

function Complete-RegistryCleanScan {
    param([string]$RawJson)
    $global:regCleanPanelList.Controls.Clear()
    $global:regCleanCheckboxes = @()
    if (-not $RawJson) {
        $global:lblRegCleanStatus.Text = (TT "Δεν βρέθηκαν προβληματικές εγγραφές.")
        $global:regCleanFindings = @()
        return
    }
    try {
        $global:regCleanFindings = @($RawJson | ConvertFrom-Json -ErrorAction Stop)
    } catch {
        $global:lblRegCleanStatus.Text = (TT "Σφάλμα ανάλυσης αποτελεσμάτων.")
        return
    }
    if ($global:regCleanFindings.Count -eq 0) {
        $global:lblRegCleanStatus.Text = (TT "Δεν βρέθηκαν προβληματικές εγγραφές - το μητρώο σας είναι καθαρό.")
        return
    }
    $global:lblRegCleanStatus.Text = "$(TT 'Βρέθηκαν') $($global:regCleanFindings.Count) $(TT 'πιθανά ζητήματα. Επιλέξτε ποια θέλετε να διαγραφούν.')"

    $rowYRc = 5
    for ($fi = 0; $fi -lt $global:regCleanFindings.Count; $fi++) {
        $finding = $global:regCleanFindings[$fi]
        $catLabel = if ($finding.Category -eq "MissingUninstaller") { (TT "Χαμένος Απεγκαταστάτης") } else { (TT "Παρωχημένο MuiCache") }

        $rowPanelRc = [System.Windows.Forms.Panel]::new()
        $rowPanelRc.Size = [System.Drawing.Size]::new(970, 34)
        $rowPanelRc.Location = [System.Drawing.Point]::new(5, $rowYRc)
        $rowPanelRc.BackColor = $theme.CardBg
        $global:regCleanPanelList.Controls.Add($rowPanelRc)

        $chkFinding = [System.Windows.Forms.CheckBox]::new()
        $chkFinding.Size = [System.Drawing.Size]::new(940, 28)
        $chkFinding.Location = [System.Drawing.Point]::new(10, 3)
        $chkFinding.Text = "[$catLabel] $($finding.Display)"
        $chkFinding.Font = $fontStatus
        $chkFinding.ForeColor = $theme.Text
        $chkFinding.BackColor = [System.Drawing.Color]::Transparent
        $chkFinding.Tag = $fi
        $rowPanelRc.Controls.Add($chkFinding)
        $global:allTextLabels += $chkFinding
        $global:regCleanCheckboxes += $chkFinding

        $rowYRc += 38
    }
}

function Invoke-RegistryCleanDelete {
    $selectedFindings = @()
    foreach ($chk in $global:regCleanCheckboxes) {
        if ($chk.Checked) { $selectedFindings += $global:regCleanFindings[$chk.Tag] }
    }
    if ($selectedFindings.Count -eq 0) {
        Show-CustomMessage -Message (TT "Δεν έχετε επιλέξει καμία εγγραφή για διαγραφή.") -Title (TT "Καμία Επιλογή") -Type "Info"
        return
    }
    $confirmRc = Show-CustomMessage -Message "$(TT 'Θα δημιουργηθεί αυτόματο αντίγραφο ασφαλείας και θα διαγραφούν') $($selectedFindings.Count) $(TT 'επιλεγμένες εγγραφές μητρώου. Συνέχεια;')" -Title (TT "Επιβεβαίωση") -Type "YesNo"
    if ($confirmRc -ne "Yes") { return }

    $backupFolder = Join-Path $env:USERPROFILE "Desktop\RegistryCleanerBackup_$(Get-Date -Format 'yyyy-MM-dd_HHmmss')"
    New-Item -Path $backupFolder -ItemType Directory -Force -ErrorAction SilentlyContinue | Out-Null

    $deletedCount = 0
    foreach ($finding in $selectedFindings) {
        try {
            # Αυτόματο .reg backup ΠΡΙΝ από κάθε διαγραφή - αναστρέψιμο με διπλό-κλικ αν χρειαστεί.
            $safeFileName = ($finding.Display -replace '[\\\/\:\*\?"<>\|]', '_')
            $backupFile = Join-Path $backupFolder "$safeFileName.reg"
            $regExportPath = $finding.RegPath -replace "^HKEY_CURRENT_USER", "HKCU" -replace "^HKEY_LOCAL_MACHINE", "HKLM"
            Start-Process -FilePath "reg.exe" -ArgumentList "export", "`"$regExportPath`"", "`"$backupFile`"", "/y" -Wait -WindowStyle Hidden -ErrorAction SilentlyContinue

            if ($finding.ValueName) {
                Remove-ItemProperty -Path $finding.RegPath -Name $finding.ValueName -ErrorAction SilentlyContinue
            } else {
                Remove-Item -Path $finding.RegPath -Recurse -Force -ErrorAction SilentlyContinue
            }
            $deletedCount++
        } catch {}
    }
    $lblStatus.Text = "$deletedCount $(TT 'εγγραφές μητρώου διαγράφηκαν. Αντίγραφο ασφαλείας:') $backupFolder"
    Start-RegistryCleanScan
}

# ===== ΝΕΑ ΕΝΟΤΗΤΑ: ΚΑΘΑΡΙΣΜΟΣ CACHE ΠΕΡΙΗΓΗΤΩΝ (κατόπιν σύγκρισης με Microsoft PC Manager) =====
# ΣΗΜΕΙΩΣΗ ΑΣΦΑΛΕΙΑΣ: καθαρίζει ΜΟΝΟ τους φακέλους cache (όχι ιστορικό/κωδικούς/σελιδοδείκτες/cookies).
# Αν ο περιηγητής είναι ανοιχτός, ορισμένα αρχεία μπορεί να είναι κλειδωμένα και να παραλειφθούν σιωπηλά
# (-ErrorAction SilentlyContinue) - χωρίς να απαιτείται να κλείσει βίαια η εφαρμογή του χρήστη.
function Clear-BrowserCacheFolders {
    param([string]$BrowserName, [string[]]$Paths)
    foreach ($p in $Paths) {
        Get-ChildItem -Path $p -Directory -ErrorAction SilentlyContinue | ForEach-Object {
            Remove-Item -Path "$($_.FullName)\*" -Recurse -Force -ErrorAction SilentlyContinue
        }
    }
    $lblStatus.Text = "$(TT 'Ο cache του') $BrowserName $(TT 'καθαρίστηκε.')"
}

# ΔΙΟΡΘΩΣΗ ΡΙΖΙΚΗ v2.1.2 (ρητό αίτημα χρήστη - "να ανιχνεύει τον εκάστοτε υπολογιστή για browsers και να
# παράγονται τα αντίστοιχα κουμπιά"): πριν υπήρχαν 3 ΠΑΝΤΑ-ΟΡΑΤΑ, hardcoded κουμπιά (Edge/Chrome/Firefox)
# ανεξάρτητα από το αν ο περιηγητής όντως υπάρχει σε αυτό το PC - τώρα ανιχνεύονται 6 δημοφιλείς
# περιηγητές (έλεγχος ύπαρξης του δικού τους φακέλου δεδομένων χρήστη, γρήγορο/συγχρονισμένο Test-Path -
# ίδια λογική με τα ήδη υπάρχοντα Paths, όχι νέα βαριά λειτουργία) και παράγεται κουμπί ΜΟΝΟ για όσους
# όντως βρεθούν, σε πλέγμα 3-ανά-γραμμή. Το ύψος της κάρτας υπολογίζεται δυναμικά από το πλήθος γραμμών
# που χρειάζονται ΠΡΙΝ δημιουργηθεί η ίδια η κάρτα, ώστε η επόμενη κάρτα (WinRE) να μετατοπίζεται σωστά.
$global:browserCacheCatalog = @(
    [PSCustomObject]@{ Name = "Microsoft Edge"; Label = (TT "Καθαρισμός Edge"); DetectPath = "$env:LOCALAPPDATA\Microsoft\Edge\User Data"; Paths = @("$env:LOCALAPPDATA\Microsoft\Edge\User Data\*\Cache", "$env:LOCALAPPDATA\Microsoft\Edge\User Data\*\Code Cache"); Color = [System.Drawing.Color]::FromArgb(0, 120, 215) }
    [PSCustomObject]@{ Name = "Google Chrome"; Label = (TT "Καθαρισμός Chrome"); DetectPath = "$env:LOCALAPPDATA\Google\Chrome\User Data"; Paths = @("$env:LOCALAPPDATA\Google\Chrome\User Data\*\Cache", "$env:LOCALAPPDATA\Google\Chrome\User Data\*\Code Cache"); Color = [System.Drawing.Color]::FromArgb(219, 68, 55) }
    [PSCustomObject]@{ Name = "Mozilla Firefox"; Label = (TT "Καθαρισμός Firefox"); DetectPath = "$env:LOCALAPPDATA\Mozilla\Firefox\Profiles"; Paths = @("$env:LOCALAPPDATA\Mozilla\Firefox\Profiles\*\cache2"); Color = [System.Drawing.Color]::FromArgb(255, 149, 0) }
    [PSCustomObject]@{ Name = "Brave"; Label = (TT "Καθαρισμός Brave"); DetectPath = "$env:LOCALAPPDATA\BraveSoftware\Brave-Browser\User Data"; Paths = @("$env:LOCALAPPDATA\BraveSoftware\Brave-Browser\User Data\*\Cache", "$env:LOCALAPPDATA\BraveSoftware\Brave-Browser\User Data\*\Code Cache"); Color = [System.Drawing.Color]::FromArgb(251, 84, 43) }
    [PSCustomObject]@{ Name = "Opera"; Label = (TT "Καθαρισμός Opera"); DetectPath = "$env:LOCALAPPDATA\Opera Software\Opera Stable"; Paths = @("$env:LOCALAPPDATA\Opera Software\Opera Stable\Cache", "$env:LOCALAPPDATA\Opera Software\Opera Stable\Code Cache"); Color = [System.Drawing.Color]::FromArgb(255, 27, 44) }
    [PSCustomObject]@{ Name = "Vivaldi"; Label = (TT "Καθαρισμός Vivaldi"); DetectPath = "$env:LOCALAPPDATA\Vivaldi\User Data"; Paths = @("$env:LOCALAPPDATA\Vivaldi\User Data\*\Cache", "$env:LOCALAPPDATA\Vivaldi\User Data\*\Code Cache"); Color = [System.Drawing.Color]::FromArgb(239, 42, 63) }
) | Where-Object { Test-Path $_.DetectPath }

$browserRowCount = [Math]::Max(1, [Math]::Ceiling($global:browserCacheCatalog.Count / 3.0))
$cardBrowserCacheH = 70 + ($browserRowCount * 42) + 20

$cardBrowserCache = Helper-CreateCard 20 870 1030 $cardBrowserCacheH $global:scrollPanelHealth
Add-IconedLabel -IconType "Broom" -Text (TT "Καθαρισμός Cache Περιηγητών") -x 15 -y 10 -w 700 -Font $fontBoldText -IsSubText $false -Parent $cardBrowserCache | Out-Null

$lblBrowserCacheDesc = [System.Windows.Forms.Label]::new()
$lblBrowserCacheDesc.Text = (TT "Διαγράφει ΜΟΝΟ τα προσωρινά αρχεία cache (όχι ιστορικό/κωδικούς/σελιδοδείκτες) - για καλύτερο αποτέλεσμα κλείστε πρώτα τον περιηγητή. Εμφανίζονται μόνο οι περιηγητές που εντοπίστηκαν σε αυτόν τον υπολογιστή.")
$lblBrowserCacheDesc.Font = $fontText
$lblBrowserCacheDesc.ForeColor = $theme.SubText
$lblBrowserCacheDesc.BackColor = [System.Drawing.Color]::Transparent
$lblBrowserCacheDesc.Size = [System.Drawing.Size]::new(1000, 22)
$lblBrowserCacheDesc.Location = [System.Drawing.Point]::new(15, 40)
$cardBrowserCache.Controls.Add($lblBrowserCacheDesc)
$global:allTextLabels += $lblBrowserCacheDesc

if ($global:browserCacheCatalog.Count -eq 0) {
    $lblNoBrowsers = [System.Windows.Forms.Label]::new()
    $lblNoBrowsers.Text = (TT "Δεν εντοπίστηκε κανένας υποστηριζόμενος περιηγητής σε αυτόν τον υπολογιστή.")
    $lblNoBrowsers.Font = $fontStatus
    $lblNoBrowsers.ForeColor = $theme.SubText
    $lblNoBrowsers.BackColor = [System.Drawing.Color]::Transparent
    $lblNoBrowsers.Size = [System.Drawing.Size]::new(1000, 22)
    $lblNoBrowsers.Location = [System.Drawing.Point]::new(15, 70)
    $cardBrowserCache.Controls.Add($lblNoBrowsers)
    $global:allSubTextLabels += $lblNoBrowsers
} else {
    $bcIdx = 0
    foreach ($bc in $global:browserCacheCatalog) {
        $bcCol = $bcIdx % 3
        $bcRow = [Math]::Floor($bcIdx / 3)
        $bcX = 15 + ($bcCol * 345)
        $bcY = 70 + ($bcRow * 42)
        $bcAction = { Clear-BrowserCacheFolders -BrowserName $bc.Name -Paths $bc.Paths }.GetNewClosure()
        Helper-CreateButton $bc.Label $bcX $bcY 320 32 $bc.Color $bcAction $cardBrowserCache $true "$(TT 'Καθαρίζει τον φάκελο cache του') $($bc.Name) $(TT '(όλα τα προφίλ).')"
        $bcIdx++
    }
}

# ===== ΝΕΑ ΕΝΟΤΗΤΑ (κατόπιν reverse engineering του WMT): ΕΛΕΓΧΟΣ ΠΕΡΙΒΑΛΛΟΝΤΟΣ ΑΝΑΚΤΗΣΗΣ (WinRE) =====
# Το reagentc /info ολοκληρώνεται σχεδόν ακαριαία (καθαρή ανάγνωση κατάστασης boot configuration, όχι
# σάρωση δίσκου) - εκτελείται συγχρονισμένα μέσα στο κλικ του κουμπιού, όπως κάθε άλλη γρήγορη ανάγνωση
# κατάστασης στην εφαρμογή. Η ΜΟΝΗ ενέργεια εγγραφής (Ενεργοποίηση) ζητά πάντα επιβεβαίωση, καθώς αλλάζει
# boot configuration data.
function Get-WinREStatus {
    try {
        $output = & reagentc.exe /info 2>&1 | Out-String
        $statusLine = ($output -split "`r?`n") | Where-Object { $_ -match "Windows RE status" } | Select-Object -First 1
        $enabled = $false
        if ($statusLine -and $statusLine -match "Enabled" -and $statusLine -notmatch "Disabled") { $enabled = $true }
        [PSCustomObject]@{ Success = $true; Enabled = $enabled; RawOutput = $output }
    } catch {
        [PSCustomObject]@{ Success = $false; Enabled = $false; RawOutput = $_.Exception.Message }
    }
}

$cardWinRE = Helper-CreateCard 20 (870 + $cardBrowserCacheH + 10) 1030 150 $global:scrollPanelHealth
Add-IconedLabel -IconType "Shield" -Text (TT "Περιβάλλον Ανάκτησης Windows (WinRE)") -x 15 -y 10 -w 700 -Font $fontBoldText -IsSubText $false -Parent $cardWinRE | Out-Null

$lblWinREDesc = [System.Windows.Forms.Label]::new()
$lblWinREDesc.Text = (TT "Το WinRE χρειάζεται για επιδιόρθωση εκκίνησης, επαναφορά συστήματος και ανάκτηση - χωρίς αυτό, ορισμένα σενάρια διόρθωσης δεν είναι διαθέσιμα.")
$lblWinREDesc.Font = $fontText
$lblWinREDesc.ForeColor = $theme.SubText
$lblWinREDesc.BackColor = [System.Drawing.Color]::Transparent
$lblWinREDesc.Size = [System.Drawing.Size]::new(1000, 22)
$lblWinREDesc.Location = [System.Drawing.Point]::new(15, 40)
$cardWinRE.Controls.Add($lblWinREDesc)
$global:allTextLabels += $lblWinREDesc

$global:lblWinREStatus = [System.Windows.Forms.Label]::new()
$global:lblWinREStatus.Text = (TT "Κατάσταση: Άγνωστη")
$global:lblWinREStatus.Font = $fontBtnCustom
$global:lblWinREStatus.ForeColor = $theme.SubText
$global:lblWinREStatus.BackColor = [System.Drawing.Color]::Transparent
$global:lblWinREStatus.Size = [System.Drawing.Size]::new(500, 26)
$global:lblWinREStatus.Location = [System.Drawing.Point]::new(15, 68)
$cardWinRE.Controls.Add($global:lblWinREStatus)
$global:allTextLabels += $global:lblWinREStatus

function Update-WinREStatusDisplay {
    $result = Get-WinREStatus
    if (-not $result.Success) {
        $global:lblWinREStatus.Text = (TT "Κατάσταση: Άγνωστη (απαιτούνται δικαιώματα διαχειριστή)")
        $global:lblWinREStatus.ForeColor = $theme.SubText
    } elseif ($result.Enabled) {
        $global:lblWinREStatus.Text = (TT "Κατάσταση: Ενεργοποιημένο")
        $global:lblWinREStatus.ForeColor = [System.Drawing.Color]::FromArgb(90, 200, 120)
    } else {
        $global:lblWinREStatus.Text = (TT "Κατάσταση: Απενεργοποιημένο")
        $global:lblWinREStatus.ForeColor = [System.Drawing.Color]::FromArgb(230, 90, 90)
    }
}
# ΔΙΟΡΘΩΣΗ v2.0.8 (αίτημα χρήστη - "η εφαρμογή αργεί να ξεκινήσει, οι σαρώσεις να μην γίνονται όλες μαζί"):
# η κλήση αυτή έτρεχε reagentc.exe /info ΣΥΓΧΡΟΝΑ κατά την κατασκευή του UI, μπλοκάροντας την εκκίνηση
# της εφαρμογής μέχρι να απαντήσει το εξωτερικό .exe. Μετατράπηκε σε ένα one-shot Timer (καθυστέρηση
# 600ms) - το κύριο παράθυρο εμφανίζεται και γίνεται αλληλεπιδραστικό αμέσως, και η κατάσταση WinRE
# ενημερώνεται λίγο αργότερα, αφού η εφαρμογή έχει ήδη ανοίξει. Σκόπιμα διαφορετική καθυστέρηση από το
# Update-HealthScoreDisplay παρακάτω, ώστε οι δύο "σαρώσεις εκκίνησης" να ΜΗΝ τρέχουν ταυτόχρονα.
$global:startupWinREScanTimer = [System.Windows.Forms.Timer]::new()
$global:startupWinREScanTimer.Interval = 600
$global:startupWinREScanTimer.Add_Tick({
    $global:startupWinREScanTimer.Stop()
    Update-WinREStatusDisplay
})
$global:startupWinREScanTimer.Start()

Helper-CreateButton (TT "Ανανέωση Κατάστασης") 15 105 220 32 $theme.CardBg {
    Update-WinREStatusDisplay
    $lblStatus.Text = (TT "Η κατάσταση WinRE ανανεώθηκε.")
} $cardWinRE $true (TT "Ελέγχει ξανά την τρέχουσα κατάσταση του Περιβάλλοντος Ανάκτησης.")

Helper-CreateButton (TT "Ενεργοποίηση WinRE") 250 105 260 32 $theme.Accent {
    $confirmed = Show-CustomMessage -Message (TT "Θα ενεργοποιηθεί το Περιβάλλον Ανάκτησης Windows (αλλαγή boot configuration). Συνέχεια;") -Title (TT "Επιβεβαίωση") -Type "YesNo"
    if ($confirmed -eq [System.Windows.Forms.DialogResult]::Yes) {
        try {
            $enableOutput = & reagentc.exe /enable 2>&1 | Out-String
            Update-WinREStatusDisplay
            $lblStatus.Text = (TT "Η ενεργοποίηση WinRE ολοκληρώθηκε.")
        } catch {
            Show-CustomMessage -Message "$(TT 'Αποτυχία ενεργοποίησης WinRE'): $($_.Exception.Message)" -Title "Σφάλμα" -Type "Error"
        }
    }
} $cardWinRE $true (TT "Ενεργοποιεί το WinRE αν είναι απενεργοποιημένο - απαραίτητο για επιδιόρθωση εκκίνησης και ανάκτηση συστήματος.")

# ΔΙΟΡΘΩΣΗ v2.1.2: $cardWinRE.Location.Y είναι πλέον δυναμικό (εξαρτάται από το πλήθος ανιχνευμένων
# browsers στην κάρτα Καθαρισμού Cache παραπάνω) - το AutoScrollMinSize υπολογίζεται από το πραγματικό,
# τρέχον κάτω άκρο του cardWinRE αντί για σταθερή τιμή, ώστε να μην κοντεύει ποτέ να μείνει περιεχόμενο
# απρόσιτο σε συστήματα με πολλούς εγκατεστημένους περιηγητές (2 σειρές κουμπιών αντί για 1).
$global:scrollPanelHealth.AutoScrollMinSize = [System.Drawing.Size]::new(1050, ($cardWinRE.Location.Y + $cardWinRE.Height + 20))

Add-IconedLabel -IconType "Shield" -Text (TT "Εργαλεία Δικτύου & Ασφάλειας") -x 95 -y 15 -w 900 -Font $fontBoldText -IsSubText $false -Parent $tabNetwork | Out-Null

