# ===== ΝΕΑ ΕΝΟΤΗΤΑ (v1.9.4): ΔΙΑΧΕΙΡΙΣΗ FIREWALL (FIREWALL MANAGER) =====
# ΣΗΜΕΙΩΣΗ: τα Windows έχουν συνήθως εκατοντάδες built-in κανόνες - η φόρτωση γίνεται ΜΙΑ φορά σε
# background διεργασία (ίδιο αξιόπιστο μοτίβο με driver/storage scan), και το φιλτράρισμα με βάση την
# αναζήτηση γίνεται ΤΟΠΙΚΑ στη μνήμη (χωρίς νέο ερώτημα σε κάθε πληκτρολόγηση) - ταχύτερη εμπειρία.
$cardFirewall = Helper-CreateCard 20 365 1030 400 $global:scrollPanelNetwork
Add-IconedLabel -IconType "Shield" -Text (TT "Διαχείριση Κανόνων Firewall") -x 15 -y 10 -w 700 -Font $fontBoldText -IsSubText $false -Parent $cardFirewall | Out-Null

$lblFirewallDesc = [System.Windows.Forms.Label]::new()
$lblFirewallDesc.Text = (TT "Αναζητήστε κανόνα με το όνομά του για ενεργοποίηση/απενεργοποίηση. Η απενεργοποίηση δεν διαγράφει τον κανόνα - είναι πλήρως αναστρέψιμη ανά πάσα στιγμή.")
$lblFirewallDesc.Font = $fontText
$lblFirewallDesc.ForeColor = $theme.SubText
$lblFirewallDesc.BackColor = [System.Drawing.Color]::Transparent
$lblFirewallDesc.Size = [System.Drawing.Size]::new(1000, 22)
$lblFirewallDesc.Location = [System.Drawing.Point]::new(15, 38)
$cardFirewall.Controls.Add($lblFirewallDesc)
$global:allTextLabels += $lblFirewallDesc

$global:txtFirewallSearch = [System.Windows.Forms.TextBox]::new()
$global:txtFirewallSearch.Size = [System.Drawing.Size]::new(700, 30)
$global:txtFirewallSearch.Location = [System.Drawing.Point]::new(15, 65)
$global:txtFirewallSearch.Font = $fontText
$global:txtFirewallSearch.BackColor = $theme.CardBg
$global:txtFirewallSearch.ForeColor = $theme.Text
$cardFirewall.Controls.Add($global:txtFirewallSearch)

$global:btnFirewallLoad = Helper-CreateButton (TT "Φόρτωση Κανόνων") 725 65 290 30 $theme.Accent { Start-FirewallRulesLoad } $cardFirewall $true (TT "Φορτώνει όλους τους κανόνες firewall του συστήματος (μπορεί να διαρκέσει λίγα δευτερόλεπτα, μόνο την πρώτη φορά).")

$global:lblFirewallStatus = [System.Windows.Forms.Label]::new()
$global:lblFirewallStatus.Text = (TT "Πατήστε 'Φόρτωση Κανόνων' για έναρξη.")
$global:lblFirewallStatus.Font = $fontStatus
$global:lblFirewallStatus.ForeColor = $theme.SubText
$global:lblFirewallStatus.Size = [System.Drawing.Size]::new(1000, 20)
$global:lblFirewallStatus.Location = [System.Drawing.Point]::new(15, 100)
$cardFirewall.Controls.Add($global:lblFirewallStatus)
$global:allSubTextLabels += $global:lblFirewallStatus

$global:firewallPanelList = [System.Windows.Forms.Panel]::new()
$global:firewallPanelList.Size = [System.Drawing.Size]::new(1000, 265)
$global:firewallPanelList.Location = [System.Drawing.Point]::new(15, 125)
$global:firewallPanelList.AutoScroll = $true
Set-PanelScrollbarDarkMode -Panel $global:firewallPanelList
$global:allThemedScrollPanels = @($global:allThemedScrollPanels) + $global:firewallPanelList
$global:firewallPanelList.BackColor = $theme.MainBg
if ($setStyleMethod) { $setStyleMethod.Invoke($global:firewallPanelList, @($flickerFixStyles, $true)) | Out-Null }
$cardFirewall.Controls.Add($global:firewallPanelList)

$global:allFirewallRules = $null
$global:firewallLoadTimer = [System.Windows.Forms.Timer]::new()
$global:firewallLoadTimer.Interval = 700
$global:firewallLoadTimer.Add_Tick({
    if (-not $global:firewallLoadState) { $global:firewallLoadTimer.Stop(); return }
    if (-not $global:firewallLoadState.Process.HasExited) { return }
    $global:firewallLoadTimer.Stop()
    $rawJsonFw = $null
    if (Test-Path $global:firewallLoadState.OutFile) {
        $rawJsonFw = Get-Content -Path $global:firewallLoadState.OutFile -Raw -ErrorAction SilentlyContinue
        Remove-Item -Path $global:firewallLoadState.OutFile -Force -ErrorAction SilentlyContinue
    }
    if (Test-Path $global:firewallLoadState.ScriptFile) {
        Remove-Item -Path $global:firewallLoadState.ScriptFile -Force -ErrorAction SilentlyContinue
    }
    $global:firewallLoadState = $null
    if (-not $rawJsonFw) {
        $global:lblFirewallStatus.Text = (TT "Αποτυχία φόρτωσης κανόνων.")
        return
    }
    try {
        $global:allFirewallRules = @($rawJsonFw | ConvertFrom-Json -ErrorAction Stop)
        $global:lblFirewallStatus.Text = "$(TT 'Φορτώθηκαν') $($global:allFirewallRules.Count) $(TT 'κανόνες. Πληκτρολογήστε για αναζήτηση.')"
        Update-FirewallRulesDisplay
    } catch {
        $global:lblFirewallStatus.Text = (TT "Σφάλμα ανάλυσης κανόνων.")
    }
})

function Start-FirewallRulesLoad {
    if ($global:firewallLoadState) { return }
    $global:lblFirewallStatus.Text = (TT "Φόρτωση κανόνων firewall σε εξέλιξη...")
    $global:firewallPanelList.Controls.Clear()
    $tempOutFw = Join-Path $env:TEMP "OptimizerFirewallLoad_$([guid]::NewGuid().ToString('N')).json"
    $fwScriptContent = @'
$ErrorActionPreference = "Continue"
$rules = Get-NetFirewallRule -ErrorAction SilentlyContinue | Select-Object Name, DisplayName, Direction, Action, Enabled, Profile
($rules | ConvertTo-Json -Depth 3 -Compress) | Out-File -FilePath "OUTFILE_PLACEHOLDER" -Encoding utf8
'@
    $fwScriptContent = $fwScriptContent.Replace("OUTFILE_PLACEHOLDER", $tempOutFw)
    $fwScriptFile = Join-Path $env:TEMP "OptimizerFirewallLoadScript_$([guid]::NewGuid().ToString('N')).ps1"
    Set-Content -Path $fwScriptFile -Value $fwScriptContent -Encoding utf8
    try {
        $procFw = Start-Process -FilePath "powershell.exe" -ArgumentList "-NoProfile -ExecutionPolicy Bypass -File `"$fwScriptFile`"" -WindowStyle Minimized -PassThru -ErrorAction Stop
    } catch {
        $global:lblFirewallStatus.Text = "$(TT 'Αποτυχία εκκίνησης'): $($_.Exception.Message)"
        return
    }
    $global:firewallLoadState = [PSCustomObject]@{ Process = $procFw; OutFile = $tempOutFw; ScriptFile = $fwScriptFile }
    $global:firewallLoadTimer.Start()
}

function Update-FirewallRulesDisplay {
    $global:firewallPanelList.Controls.Clear()
    if (-not $global:allFirewallRules) { return }
    $searchTerm = $global:txtFirewallSearch.Text.Trim()
    $matched = if ($searchTerm) {
        @($global:allFirewallRules | Where-Object { $_.DisplayName -and $_.DisplayName -like "*$searchTerm*" })
    } else {
        @()
    }
    # ΔΙΟΡΘΩΣΗ: όριο 50 αποτελεσμάτων ταυτόχρονα - εκατοντάδες γραμμές ταυτόχρονα θα ήταν αργό/άχρηστο.
    $matched = @($matched | Select-Object -First 50)

    if (-not $searchTerm) {
        $global:lblFirewallStatus.Text = "$($global:allFirewallRules.Count) $(TT 'κανόνες φορτωμένοι. Πληκτρολογήστε για αναζήτηση.')"
        return
    }
    if ($matched.Count -eq 0) {
        $global:lblFirewallStatus.Text = (TT "Δεν βρέθηκαν κανόνες με αυτό το όνομα.")
        return
    }
    $global:lblFirewallStatus.Text = "$(TT 'Εμφανίζονται') $($matched.Count) $(TT 'αποτελέσματα (μέγιστο 50).')"

    $rowYF = 5
    foreach ($rule in $matched) {
        $ruleName = $rule.Name
        $ruleDisplay = $rule.DisplayName
        $ruleEnabled = ($rule.Enabled -eq 1 -or $rule.Enabled -eq "True" -or $rule.Enabled -eq $true)
        $ruleDir = $rule.Direction
        $ruleAction = $rule.Action

        $rowPanelF = [System.Windows.Forms.Panel]::new()
        $rowPanelF.Size = [System.Drawing.Size]::new(970, 34)
        $rowPanelF.Location = [System.Drawing.Point]::new(5, $rowYF)
        $rowPanelF.BackColor = $theme.CardBg
        $global:firewallPanelList.Controls.Add($rowPanelF)

        $lblRuleInfo = [System.Windows.Forms.Label]::new()
        $lblRuleInfo.Text = "$ruleDisplay ($ruleDir / $ruleAction)"
        $lblRuleInfo.Font = $fontStatus
        $lblRuleInfo.ForeColor = $theme.Text
        $lblRuleInfo.BackColor = [System.Drawing.Color]::Transparent
        $lblRuleInfo.Size = [System.Drawing.Size]::new(850, 28)
        $lblRuleInfo.Location = [System.Drawing.Point]::new(10, 3)
        $rowPanelF.Controls.Add($lblRuleInfo)
        $global:allTextLabels += $lblRuleInfo

        $swFirewall = New-ToggleSwitch -OnScript {
            try {
                Set-NetFirewallRule -Name $ruleName -Enabled True -ErrorAction Stop
                $lblStatus.Text = "'$ruleDisplay' $(TT 'ενεργοποιήθηκε.')"
            } catch {
                Show-CustomMessage -Message "$(TT 'Αποτυχία'): $($_.Exception.Message)" -Title "Σφάλμα" -Type "Error"
            }
        }.GetNewClosure() -OffScript {
            try {
                Set-NetFirewallRule -Name $ruleName -Enabled False -ErrorAction Stop
                $lblStatus.Text = "'$ruleDisplay' $(TT 'απενεργοποιήθηκε.')"
            } catch {
                Show-CustomMessage -Message "$(TT 'Αποτυχία'): $($_.Exception.Message)" -Title "Σφάλμα" -Type "Error"
            }
        }.GetNewClosure()
        $swFirewall.Location = [System.Drawing.Point]::new(900, 5)
        $swFirewall.Tag.IsOn = $ruleEnabled
        $rowPanelF.Controls.Add($swFirewall)

        $rowYF += 38
    }
}

$global:txtFirewallSearch.Add_TextChanged({ Update-FirewallRulesDisplay })

# ===== ΝΕΑ ΕΝΟΤΗΤΑ (κατόπιν reverse engineering του WMT): ΕΡΓΑΛΕΙΑ FIREWALL (EXPORT/IMPORT/RESET) =====
# Χρησιμοποιεί το επίσημο netsh advfirewall - το ίδιο μηχανισμό που χρησιμοποιεί και το Windows Firewall
# with Advanced Security GUI για export/import πολιτικής (.wfw). Το Export/Import είναι πλήρως ασφαλή
# (δεν αλλάζουν τίποτα χωρίς ρητή επιλογή αρχείου). Η Επαναφορά Προεπιλογών ζητά πάντα επιβεβαίωση, καθώς
# αντικαθιστά ΟΛΗ την τρέχουσα πολιτική firewall με τις εργοστασιακές ρυθμίσεις των Windows.
$cardFirewallTools = Helper-CreateCard 20 785 1030 160 $global:scrollPanelNetwork
Add-IconedLabel -IconType "Shield" -Text (TT "Εργαλεία Πολιτικής Firewall") -x 15 -y 10 -w 700 -Font $fontBoldText -IsSubText $false -Parent $cardFirewallTools | Out-Null

$lblFirewallToolsDesc = [System.Windows.Forms.Label]::new()
$lblFirewallToolsDesc.Text = (TT "Εξαγωγή/εισαγωγή πλήρους πολιτικής firewall (.wfw) ή επαναφορά στις εργοστασιακές ρυθμίσεις των Windows.")
$lblFirewallToolsDesc.Font = $fontText
$lblFirewallToolsDesc.ForeColor = $theme.SubText
$lblFirewallToolsDesc.BackColor = [System.Drawing.Color]::Transparent
$lblFirewallToolsDesc.Size = [System.Drawing.Size]::new(1000, 22)
$lblFirewallToolsDesc.Location = [System.Drawing.Point]::new(15, 40)
$cardFirewallTools.Controls.Add($lblFirewallToolsDesc)
$global:allTextLabels += $lblFirewallToolsDesc

Helper-CreateButton (TT "Εξαγωγή Πολιτικής (.wfw)") 15 75 320 36 $theme.BtnDefault {
    $sfdFw = [System.Windows.Forms.SaveFileDialog]::new()
    $sfdFw.Filter = "Windows Firewall Policy (*.wfw)|*.wfw"
    $sfdFw.FileName = "FirewallPolicy_$(Get-Date -Format 'yyyy-MM-dd').wfw"
    if ($sfdFw.ShowDialog() -ne [System.Windows.Forms.DialogResult]::OK) { return }
    try {
        $exportResult = & netsh.exe advfirewall export "$($sfdFw.FileName)" 2>&1 | Out-String
        $lblStatus.Text = "$(TT 'Η πολιτική firewall εξήχθη σε'): $($sfdFw.FileName)"
    } catch {
        Show-CustomMessage -Message "$(TT 'Αποτυχία εξαγωγής'): $($_.Exception.Message)" -Title "Σφάλμα" -Type "Error"
    }
} $cardFirewallTools $true (TT "Αποθηκεύει ολόκληρη την τρέχουσα πολιτική firewall (όλοι οι κανόνες, όλα τα προφίλ) σε ένα αρχείο .wfw.")

Helper-CreateButton (TT "Εισαγωγή Πολιτικής (.wfw)") 360 75 320 36 $theme.BtnDefault {
    $ofdFw = [System.Windows.Forms.OpenFileDialog]::new()
    $ofdFw.Filter = "Windows Firewall Policy (*.wfw)|*.wfw"
    if ($ofdFw.ShowDialog() -ne [System.Windows.Forms.DialogResult]::OK) { return }
    $confirmImportFw = Show-CustomMessage -Message "$(TT 'Θα αντικατασταθεί ΟΛΗ η τρέχουσα πολιτική firewall με:') $($ofdFw.FileName). $(TT 'Συνέχεια;')" -Title (TT "Επιβεβαίωση") -Type "YesNo"
    if ($confirmImportFw -ne [System.Windows.Forms.DialogResult]::Yes) { return }
    try {
        $importResult = & netsh.exe advfirewall import "$($ofdFw.FileName)" 2>&1 | Out-String
        $lblStatus.Text = (TT "Η πολιτική firewall εισήχθη επιτυχώς.")
        $global:allFirewallRules = $null
    } catch {
        Show-CustomMessage -Message "$(TT 'Αποτυχία εισαγωγής'): $($_.Exception.Message)" -Title "Σφάλμα" -Type "Error"
    }
} $cardFirewallTools $true (TT "Αντικαθιστά ΟΛΗ την τρέχουσα πολιτική firewall με το περιεχόμενο ενός αρχείου .wfw.")

Helper-CreateButton (TT "Επαναφορά Προεπιλογών Firewall") 705 75 320 36 ([System.Drawing.Color]::FromArgb(200, 80, 70)) {
    $confirmResetFw = Show-CustomMessage -Message (TT "Θα διαγραφούν ΟΛΟΙ οι προσαρμοσμένοι κανόνες firewall και θα επαναφερθούν οι εργοστασιακές ρυθμίσεις των Windows. Αυτό ΔΕΝ αναιρείται - συνιστάται πρώτα Εξαγωγή Πολιτικής. Συνέχεια;") -Title (TT "Επιβεβαίωση") -Type "YesNo"
    if ($confirmResetFw -ne [System.Windows.Forms.DialogResult]::Yes) { return }
    try {
        $resetResult = & netsh.exe advfirewall reset 2>&1 | Out-String
        $lblStatus.Text = (TT "Το firewall επαναφέρθηκε στις εργοστασιακές ρυθμίσεις.")
        $global:allFirewallRules = $null
    } catch {
        Show-CustomMessage -Message "$(TT 'Αποτυχία επαναφοράς προεπιλογών firewall'): $($_.Exception.Message)" -Title "Σφάλμα" -Type "Error"
    }
} $cardFirewallTools $true (TT "Διαγράφει όλους τους προσαρμοσμένους κανόνες και επαναφέρει τις εργοστασιακές ρυθμίσεις firewall των Windows. Μη αναστρέψιμο χωρίς προηγούμενη εξαγωγή.")

$global:scrollPanelNetwork.AutoScrollMinSize = [System.Drawing.Size]::new(1050, 870)

# ===== ΝΕΑ ΕΝΟΤΗΤΑ (κατόπιν reverse engineering του WMT): ΕΠΕΞΕΡΓΑΣΤΗΣ ΑΡΧΕΙΟΥ HOSTS =====
# Άμεση προβολή/επεξεργασία του πραγματικού αρχείου hosts των Windows. ΠΑΝΤΑ δημιουργείται χρονοσημασμένο
# αντίγραφο ασφαλείας πριν από κάθε αποθήκευση (ίδια φιλοσοφία με Backup-RegValueIfNeeded), ώστε μια
# αποτυχημένη χειροκίνητη επεξεργασία να είναι πάντα αναστρέψιμη.
$global:hostsFilePath = Join-Path $env:SystemRoot "System32\drivers\etc\hosts"

$cardHostsEditor = Helper-CreateCard 20 965 1030 380 $global:scrollPanelNetwork
Add-IconedLabel -IconType "Shield" -Text (TT "Επεξεργαστής Αρχείου Hosts") -x 15 -y 10 -w 700 -Font $fontBoldText -IsSubText $false -Parent $cardHostsEditor | Out-Null

$lblHostsDesc = [System.Windows.Forms.Label]::new()
$lblHostsDesc.Text = (TT "Προβολή και επεξεργασία του αρχείου hosts των Windows - αντιστοιχίζει χειροκίνητα ονόματα τομέα σε διευθύνσεις IP (π.χ. αποκλεισμός ιστότοπων). Δημιουργείται πάντα αντίγραφο ασφαλείας πριν από κάθε αποθήκευση.")
$lblHostsDesc.Font = $fontText
$lblHostsDesc.ForeColor = $theme.SubText
$lblHostsDesc.BackColor = [System.Drawing.Color]::Transparent
$lblHostsDesc.Size = [System.Drawing.Size]::new(1000, 22)
$lblHostsDesc.Location = [System.Drawing.Point]::new(15, 38)
$cardHostsEditor.Controls.Add($lblHostsDesc)
$global:allTextLabels += $lblHostsDesc

$global:lblHostsStatus = [System.Windows.Forms.Label]::new()
$global:lblHostsStatus.Text = (TT "Πατήστε 'Φόρτωση' για προβολή του τρέχοντος αρχείου.")
$global:lblHostsStatus.Font = $fontStatus
$global:lblHostsStatus.ForeColor = $theme.SubText
$global:lblHostsStatus.Size = [System.Drawing.Size]::new(1000, 20)
$global:lblHostsStatus.Location = [System.Drawing.Point]::new(15, 62)
$cardHostsEditor.Controls.Add($global:lblHostsStatus)
$global:allSubTextLabels += $global:lblHostsStatus

$global:txtHostsEditor = [System.Windows.Forms.TextBox]::new()
$global:txtHostsEditor.Multiline = $true
$global:txtHostsEditor.ScrollBars = "Vertical"
$global:txtHostsEditor.WordWrap = $false
$global:txtHostsEditor.Size = [System.Drawing.Size]::new(1000, 210)
$global:txtHostsEditor.Location = [System.Drawing.Point]::new(15, 88)
$global:txtHostsEditor.BackColor = $theme.CardBg
$global:txtHostsEditor.ForeColor = $theme.Text
$global:txtHostsEditor.Font = [System.Drawing.Font]::new("Consolas", 9)
$cardHostsEditor.Controls.Add($global:txtHostsEditor)

function Import-HostsFileToEditor {
    try {
        $global:txtHostsEditor.Text = (Get-Content -Path $global:hostsFilePath -Raw -ErrorAction Stop) -replace "`n", "`r`n" -replace "`r`r", "`r"
        $global:lblHostsStatus.Text = "$(TT 'Φορτώθηκε από'): $global:hostsFilePath"
    } catch {
        $global:lblHostsStatus.Text = "$(TT 'Αποτυχία φόρτωσης αρχείου hosts'): $($_.Exception.Message)"
    }
}
Import-HostsFileToEditor

Helper-CreateButton (TT "Φόρτωση") 15 305 150 34 $theme.BtnDefault {
    Import-HostsFileToEditor
} $cardHostsEditor $true (TT "Επαναφορτώνει το τρέχον περιεχόμενο του αρχείου hosts, απορρίπτοντας τυχόν μη αποθηκευμένες αλλαγές.")

Helper-CreateButton (TT "Αποθήκευση") 175 305 150 34 $theme.Accent {
    $confirmSaveHosts = Show-CustomMessage -Message (TT "Θα αντικατασταθεί το αρχείο hosts των Windows με το περιεχόμενο του πλαισίου (θα δημιουργηθεί αντίγραφο ασφαλείας πρώτα). Συνέχεια;") -Title (TT "Επιβεβαίωση") -Type "YesNo"
    if ($confirmSaveHosts -ne [System.Windows.Forms.DialogResult]::Yes) { return }
    try {
        $hostsBackupPath = "$($global:hostsFilePath)_backup_$(Get-Date -Format 'yyyyMMdd_HHmmss').bak"
        Copy-Item -Path $global:hostsFilePath -Destination $hostsBackupPath -Force -ErrorAction Stop
        [System.IO.File]::WriteAllText($global:hostsFilePath, $global:txtHostsEditor.Text, [System.Text.Encoding]::ASCII)
        $global:lblHostsStatus.Text = "$(TT 'Αποθηκεύτηκε. Αντίγραφο ασφαλείας'): $hostsBackupPath"
    } catch {
        Show-CustomMessage -Message "$(TT 'Αποτυχία αποθήκευσης αρχείου hosts'): $($_.Exception.Message)" -Title "Σφάλμα" -Type "Error"
    }
} $cardHostsEditor $true (TT "Αποθηκεύει το περιεχόμενο του πλαισίου ως το αρχείο hosts των Windows. Δημιουργεί πάντα πρώτα αντίγραφο ασφαλείας δίπλα στο αρχικό αρχείο.")

Helper-CreateButton (TT "Επαναφορά Προεπιλογών") 335 305 260 34 ([System.Drawing.Color]::FromArgb(90, 90, 100)) {
    $confirmResetHosts = Show-CustomMessage -Message (TT "Το πλαίσιο θα γεμίσει με το προεπιλεγμένο, κενό περιεχόμενο των Windows (χωρίς ενεργές αντιστοιχίσεις). Δεν αποθηκεύεται ακόμα - πατήστε 'Αποθήκευση' μετά για εφαρμογή. Συνέχεια;") -Title (TT "Επιβεβαίωση") -Type "YesNo"
    if ($confirmResetHosts -ne [System.Windows.Forms.DialogResult]::Yes) { return }
    $global:txtHostsEditor.Text = @"
# Αρχείο Hosts των Windows - αντιστοιχίζει ονόματα κεντρικών υπολογιστών σε διευθύνσεις IP.
# Μία καταχώρηση ανά γραμμή: πρώτα η διεύθυνση IP, μετά το όνομα, με τουλάχιστον ένα κενό ανάμεσα.
# Γραμμές που ξεκινούν με # αγνοούνται (σχόλια).
#
# Παράδειγμα:
#      102.54.94.97     rhino.acme.com          # server παραδείγματος
#       38.25.63.10     x.acme.com              # client παραδείγματος

# Η ανάλυση του localhost γίνεται από το ίδιο το DNS - οι παρακάτω γραμμές παραμένουν σχόλια εξ ορισμού.
#	127.0.0.1       localhost
#	::1             localhost
"@
    $global:lblHostsStatus.Text = (TT "Το πλαίσιο γέμισε με τις προεπιλεγμένες τιμές - πατήστε 'Αποθήκευση' για εφαρμογή.")
} $cardHostsEditor $true (TT "Γεμίζει το πλαίσιο με το προεπιλεγμένο περιεχόμενο των Windows (καμία ενεργή αντιστοίχιση). Δεν εφαρμόζεται μέχρι να πατήσετε Αποθήκευση.")

Helper-CreateButton (TT "Άνοιγμα με Σημειωματάριο") 605 305 250 34 $theme.BtnDefault {
    try { Start-Process "notepad.exe" -ArgumentList "`"$($global:hostsFilePath)`"" -ErrorAction Stop }
    catch { Show-CustomMessage -Message "$(TT 'Αποτυχία ανοίγματος'): $($_.Exception.Message)" -Title "Σφάλμα" -Type "Error" }
} $cardHostsEditor $true (TT "Ανοίγει το αρχείο hosts απευθείας στο Σημειωματάριο.")

# ===== WINDOWS DEFENDER - ΓΡΗΓΟΡΗ ΣΑΡΩΣΗ (μετακινήθηκε ΠΡΩΤΗ στην καρτέλα, κατόπιν ρητού αιτήματος
# χρήστη - "γρήγορη σάρωση Win Defender πρώτο στην καρτέλα Δίκτυο & Ασφάλεια") =====
# Το Start-MpScan τρέχει ΣΥΓΧΡΟΝΑ μέχρι να ολοκληρωθεί η σάρωση (μπορεί να διαρκέσει αρκετά λεπτά) - αν
# καλούνταν απευθείας στο κουμπί θα πάγωνε ολόκληρη την εφαρμογή. Εκτελείται σε background διεργασία
# (ίδιο μοτίβο με τα υπόλοιπα βαριά εργαλεία) - η ίδια η σάρωση εμφανίζει τη ζωντανή πρόοδό της στο
# επίσημο Windows Security app (ανοίγει αυτόματα), δεν χρειάζεται δική μας παρακολούθηση προόδου για
# κάτι που μπορεί να διαρκέσει έως 15+ λεπτά.
$cardDefenderScan = Helper-CreateCard 20 245 1030 110 $global:scrollPanelNetwork
Add-IconedLabel -IconType "Shield" -Text (TT "Windows Defender - Γρήγορη Σάρωση") -x 15 -y 10 -w 700 -Font $fontBoldText -IsSubText $false -Parent $cardDefenderScan | Out-Null

$lblDefenderDesc = [System.Windows.Forms.Label]::new()
$lblDefenderDesc.Text = (TT "Ξεκινά επίσημη Γρήγορη Σάρωση του Windows Defender σε background διεργασία και ανοίγει το Windows Security για να παρακολουθήσετε τη ζωντανή πρόοδο εκεί.")
$lblDefenderDesc.Font = $fontText
$lblDefenderDesc.ForeColor = $theme.SubText
$lblDefenderDesc.BackColor = [System.Drawing.Color]::Transparent
$lblDefenderDesc.Size = [System.Drawing.Size]::new(1000, 22)
$lblDefenderDesc.Location = [System.Drawing.Point]::new(15, 40)
$cardDefenderScan.Controls.Add($lblDefenderDesc)
$global:allTextLabels += $lblDefenderDesc

$global:btnDefenderScan = Helper-CreateButton (TT "Έναρξη Γρήγορης Σάρωσης") 15 70 300 32 $theme.Accent {
    try {
        $defenderScript = 'try { Start-MpScan -ScanType QuickScan -ErrorAction Stop } catch {}'
        $defScriptFile = Join-Path $env:TEMP "OptimizerDefenderScan_$([guid]::NewGuid().ToString('N')).ps1"
        Set-Content -Path $defScriptFile -Value $defenderScript -Encoding utf8
        Start-Process -FilePath "powershell.exe" -ArgumentList "-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -Command `"& { & '$defScriptFile'; Remove-Item -Path '$defScriptFile' -Force -ErrorAction SilentlyContinue }`"" -WindowStyle Hidden -ErrorAction Stop
        Start-Process "windowsdefender://scan/?scantype=quick" -ErrorAction SilentlyContinue
        $lblStatus.Text = (TT "Η Γρήγορη Σάρωση Defender ξεκίνησε στο παρασκήνιο - παρακολουθήστε την πρόοδο στο Windows Security.")
    } catch {
        Show-CustomMessage -Message "$(TT 'Αποτυχία εκκίνησης σάρωσης'): $($_.Exception.Message)" -Title "Σφάλμα" -Type "Error"
    }
} $cardDefenderScan $true (TT "Εκτελεί επίσημη Γρήγορη Σάρωση Windows Defender - ελέγχει τις πιο συνηθισμένες τοποθεσίες μόλυνσης, πολύ πιο γρήγορα από πλήρη σάρωση.")

$global:scrollPanelNetwork.AutoScrollMinSize = [System.Drawing.Size]::new(1050, 1375)

# =========================================================================
# ΚΑΡΤΕΛΑ "ΕΡΓΑΛΕΙΑ & EXTRAS" ΚΑΤΑΡΓΗΘΗΚΕ (v1.4.2)
# =========================================================================
# ΔΙΟΡΘΩΣΗ v1.4.2: Τα 7 κουμπιά αυτής της ενότητας μεταφέρθηκαν στο "Advanced Tools" (μαζί με τα δικά
# του εργαλεία - βλ. παρακάτω "Add-AdvancedToolRow"), και η ενότητα "Επιπλέον Ρυθμίσεις" έγινε δική της
# ξεχωριστή καρτέλα. Αυτό ελευθέρωσε ολόκληρη αυτή την καρτέλα, η οποία καταργήθηκε (7 καρτέλες -> 6),
# μετά από πλήρη ανασχεδιασμό/κατηγοριοποίηση της εφαρμογής - βλ. Ιστορικό Εκδόσεων.

# =========================================================================
# TAB 5: ΕΦΑΡΜΟΓΕΣ & BLOAT
# =========================================================================
Add-IconedLabel -IconType "Package" -Text (TT "Επιλέξτε εγκατάσταση ή αφαίρεση για τα ενσωματωμένα εξαρτήματα των Windows:") -x 100 -y 15 -w 960 -Font $fontText -IsSubText $true -Parent $tabBloatware | Out-Null

$global:scrollPanel = [System.Windows.Forms.Panel]::new()
$global:scrollPanel.Anchor = [System.Windows.Forms.AnchorStyles]::Top -bor [System.Windows.Forms.AnchorStyles]::Bottom -bor [System.Windows.Forms.AnchorStyles]::Left -bor [System.Windows.Forms.AnchorStyles]::Right
$global:scrollPanel.Size = [System.Drawing.Size]::new(1030, 520)
# ΔΙΟΡΘΩΣΗ v2.0.8 (αίτημα χρήστη - "το περιεχόμενο δεν είναι κεντραρισμένο"): X κεντραρίστηκε μέσα
# στο πλατύτερο $content (1230-1030)/2=100.
# ΔΙΟΡΘΩΣΗ v2.1.0: X δυναμικό βάσει πλάτους $content (βλ. σχόλιο στο scrollPanelOptimization).
$global:scrollPanel.Location = [System.Drawing.Point]::new([int]((1230 - $global:sidebarDockWidth - 1030) / 2), 45)
$global:scrollPanel.AutoScroll = $true
Set-PanelScrollbarDarkMode -Panel $global:scrollPanel
$global:allThemedScrollPanels = @($global:allThemedScrollPanels) + $global:scrollPanel
$tabBloatware.Controls.Add($global:scrollPanel)

# ΝΕΟ v1.6.2: Επικεφαλίδα ΚΑΙ για την πρώτη ενότητα (πριν υπήρχε μόνο για τις "Προτεινόμενες Εφαρμογές"
# παρακάτω) - συμμετρικός, σαφής οπτικός διαχωρισμός των δύο διαφορετικών κατηγοριών ("αφαίρεση
# ενσωματωμένων" vs "εγκατάσταση προτεινόμενων"), κατόπιν ρητού αιτήματος.
# ΔΙΟΡΘΩΣΗ v1.6.6: Αντικαταστάθηκε το κείμενο με παύλες ("── ... ──") με εικονίδιο+τίτλο, ίδιο ύφος με
# τις επικεφαλίδες καρτών στην καρτέλα Βελτιστοποίηση (Add-IconedLabel), κατόπιν αιτήματος.

function Add-BloatwareRow {
    param($title, $y, $installScript, $uninstallScript, $tooltip = "")
    $lbl = [System.Windows.Forms.Label]::new()
    $lbl.Text = $title
    $lbl.Font = $fontBtnCustom
    $lbl.ForeColor = $theme.Text
    $lbl.BackColor = [System.Drawing.Color]::Transparent
    # ΔΙΟΡΘΩΣΗ (κανόνας χρήστη - καμία περιγραφή δεν πρέπει να κόβεται): ίδιο fix με το Add-TweakRow
    # (ύψος 30 -> 44, χωράει 2 γραμμές αντί να κόβει τη δεύτερη).
    $lbl.Size = [System.Drawing.Size]::new(620, 44)
    $lbl.Location = [System.Drawing.Point]::new(15, $y + 8)
    # ΔΙΟΡΘΩΣΗ v1.6.4: Χρησιμοποιεί το $global:currentBloatwareTargetPanel (τρέχουσα "ενεργή κάρτα")
    # αντί για πάντα το $global:scrollPanel απευθείας - επιτρέπει στα 3 τμήματα της καρτέλας
    # (Ενσωματωμένα/Προτεινόμενα/Διαχείριση) να έχουν το καθένα δικό του πλαίσιο (κάρτα), όπως στο
    # Office Mode & Gaming Mode της καρτέλας Βελτιστοποίηση, χωρίς να αλλάξει η υπογραφή της function.
    $global:currentBloatwareTargetPanel.Controls.Add($lbl)
    $global:allTextLabels += $lbl
    if ($tooltip) { $global:appToolTip.SetToolTip($lbl, $tooltip) }

    $btnIn = [System.Windows.Forms.Button]::new()
    $btnIn.Size = [System.Drawing.Size]::new(170, 36)
    $btnIn.Location = [System.Drawing.Point]::new(640, $y + 4)
    $btnIn.FlatStyle = "Flat"
    $btnIn.FlatAppearance.BorderSize = 0
    $btnIn.Font = $fontBtnCustom
    # ΝΕΟ v1.7.5: Εικονίδια (ασφαλή σύμβολα εντός BMP, όχι emoji εκτός BMP που είχαν προβλήματα
    # συμβατότητας γραμματοσειράς παλαιότερα) πριν από το κείμενο, για πιο όμορφη/αναγνωρίσιμη εμφάνιση.
    $btnIn.Text = "$([char]0x2B07) $(T 'BtnInstall')"
    $btnIn.BackColor = [System.Drawing.Color]::FromArgb(16, 124, 65)
    $btnIn.ForeColor = [System.Drawing.Color]::White
    $btnIn.Cursor = [System.Windows.Forms.Cursors]::Hand
    $btnIn.Add_Click($installScript)
    Add-ButtonHoverEffect -Button $btnIn -BaseColor $btnIn.BackColor
    $global:currentBloatwareTargetPanel.Controls.Add($btnIn)

    $btnUn = [System.Windows.Forms.Button]::new()
    $btnUn.Size = [System.Drawing.Size]::new(170, 36)
    # ΔΙΟΡΘΩΣΗ v1.8.1: Μετατοπίστηκε αριστερότερα (840->820) ώστε να χωράει εντός του νέου, μικρότερου
    # πλάτους κάρτας (995, από 1015) - πριν το κουμπί (840+170=1010) υπερέβαινε ελαφρώς το διαθέσιμο
    # πλάτος, προκαλώντας την επαναλαμβανόμενη οριζόντια κύλιση.
    $btnUn.Location = [System.Drawing.Point]::new(820, $y + 4)
    $btnUn.FlatStyle = "Flat"
    $btnUn.FlatAppearance.BorderSize = 0
    $btnUn.Font = $fontBtnCustom
    $btnUn.Text = "$([char]0x2715) $(T 'BtnRemove')"
    $btnUn.BackColor = [System.Drawing.Color]::FromArgb(209, 36, 36)
    $btnUn.ForeColor = [System.Drawing.Color]::White
    $btnUn.Cursor = [System.Windows.Forms.Cursors]::Hand
    $btnUn.Add_Click($uninstallScript)
    Add-ButtonHoverEffect -Button $btnUn -BaseColor $btnUn.BackColor
    $global:currentBloatwareTargetPanel.Controls.Add($btnUn)
}

# ΝΕΟ v1.6.4: 3 ξεχωριστά πλαίσια (κάρτες) για τα τρία τμήματα της καρτέλας, ίδιο οπτικό ύφος με τις
# κάρτες Office Mode / Gaming Mode στην καρτέλα Βελτιστοποίηση.
# ΔΙΟΡΘΩΣΗ v1.8.1 (θεμελιώδης αιτία της επαναλαμβανόμενης οριζόντιας κύλισης): οι κάρτες (X=5,
# πλάτος 1015) τελείωναν στο X=1020 - ΠΕΡΙΣΣΟΤΕΡΟ από το πραγματικά διαθέσιμο πλάτος του scrollPanel
# (1030 μείον ~20px που καταλαμβάνει η ΙΔΙΑ η κατακόρυφη μπάρα κύλισης = ~1010). Το AutoScrollMinSize
# ΔΕΝ εμποδίζει κύλιση αν το περιεχόμενο είναι ΠΡΑΓΜΑΤΙΚΑ μεγαλύτερο - απλά την προκαλεί αν είναι πολύ
# μικρό. Μειώθηκε το ΠΡΑΓΜΑΤΙΚΟ πλάτος των καρτών (1015->995).
$cardBuiltin = Helper-CreateCard 5 5 995 375 $global:scrollPanel
# ΔΙΟΡΘΩΣΗ v1.7.6: Ύψος αυξήθηκε σημαντικά (460->1490) - η κατηγοριοποίηση των Προτεινόμενων Εφαρμογών
# σε 7 ομάδες (Περιήγηση/Συμπίεση/Πολυμέσα/Επικοινωνία/Εργαλεία/Έγγραφα/Βιβλιοθήκες Συστήματος, ~20
# εφαρμογές συνολικά) χρειάζεται πολύ περισσότερο κατακόρυφο χώρο από την προηγούμενη επίπεδη λίστα.
# ΔΙΟΡΘΩΣΗ v1.7.8: Ύψος μειώθηκε σημαντικά (1490->1080) - η μετατροπή σε διάταξη 2 στηλών για τις
# Προτεινόμενες Εφαρμογές (κατόπιν αιτήματος "σωστή στοίχιση χωρίς μπάρα κύλισης") μείωσε το απαιτούμενο
# ύψος κατά ~27%, ακριβώς υπολογισμένο πριν την υλοποίηση (πίνακας συντεταγμένων: 1057px + περιθώριο).
$cardRecommended = Helper-CreateCard 5 390 995 1080 $global:scrollPanel
$cardUwpManage = Helper-CreateCard 5 1490 995 90 $global:scrollPanel
# ΔΙΟΡΘΩΣΗ v1.6.4: Ίδιο προληπτικό AutoScrollMinSize (βλ. αντίστοιχη διόρθωση στο παράθυρο διαχείρισης
# UWP) - εξασφαλίζει ότι η κύλιση της καρτέλας φτάνει πλήρως μέχρι το τέλος του 3ου πλαισίου.
# ΔΙΟΡΘΩΣΗ v1.7.2: Ρητό πλάτος (όχι μόνο ύψος) στο AutoScrollMinSize - χωρίς αυτό, το WinForms Panel
# ενδέχεται να εμφανίσει ΚΑΙ οριζόντια μπάρα κύλισης (ακόμα κι όταν δεν χρειάζεται) σε ορισμένες
# περιπτώσεις υπολογισμού πλάτους περιεχομένου. Το 1010 ταιριάζει ακριβώς με το πλάτος των καρτών (1015
# ξεκινώντας από x=5, άρα ουσιαστικό πλάτος περιεχομένου ~1010) - καμία ανάγκη οριζόντιας κύλισης.
# ΔΙΟΡΘΩΣΗ v1.8.0 (επαναλαμβανόμενη αναφορά): η οριζόντια μπάρα κύλισης εμφανιζόταν επειδή το
# AutoScrollMinSize.Width (1010) ήταν σχεδόν ίσο με το πραγματικό διαθέσιμο πλάτος του panel (1030
# μείον τον χώρο που καταλαμβάνει η ΙΔΙΑ η κατακόρυφη μπάρα κύλισης, ~17-20px, αφού το περιεχόμενο
# είναι πάντα ψηλότερο από το ορατό ύψος) - αυτό το ελάχιστο περιθώριο πυροδοτούσε ΚΑΙ οριζόντια
# κύλιση. Μειώθηκε ρητά σε ασφαλές πλάτος με άφθονο περιθώριο.
$global:scrollPanel.AutoScrollMinSize = [System.Drawing.Size]::new(1005, 1960)

# ===== ΝΕΟ (v1.8.8): ΒΑΘΙΑ ΑΠΕΓΚΑΤΑΣΤΑΣΗ (DEEP UNINSTALL) - κατόπιν σύγκρισης με Microsoft PC Manager =====
# ΣΗΜΕΙΩΣΗ ΑΣΦΑΛΕΙΑΣ: η απεγκατάσταση τρέχει ΠΑΝΤΑ τον ΚΑΝΟΝΙΚΟ, επίσημο uninstaller της κάθε εφαρμογής
# (UninstallString από το registry) - ΧΩΡΙΣ προσθήκη silent flags που δεν είναι γνωστό αν υποστηρίζονται
# (θα μπορούσε να σπάσει τον uninstaller). Ο χρήστης βλέπει το κανονικό UI του uninstaller και το
# ολοκληρώνει ο ίδιος. Η αναζήτηση υπολειμμάτων ΜΕΤΑ την απεγκατάσταση είναι αμιγώς ΠΛΗΡΟΦΟΡΙΑΚΗ και
# ΧΕΙΡΟΚΙΝΗΤΗ (ο χρήστης επιλέγει τι να διαγράψει, πάντα μέσω Κάδου Ανακύκλωσης) - ΠΟΤΕ αυτόματη διαγραφή.
$cardDeepUninstall = Helper-CreateCard 5 1595 995 340 $global:scrollPanel
Add-IconedLabel -IconType "Apps" -Text (TT "Βαθιά Απεγκατάσταση Εφαρμογών") -x 15 -y 10 -w 700 -Font $fontBoldText -IsSubText $false -Parent $cardDeepUninstall | Out-Null

$lblDeepUninstallDesc = [System.Windows.Forms.Label]::new()
$lblDeepUninstallDesc.Text = (TT "Λίστα εγκατεστημένων εφαρμογών του υπολογιστή σας (πέρα από τις προτεινόμενες παραπάνω). Η απεγκατάσταση τρέχει τον επίσημο uninstaller κάθε εφαρμογής - ολοκληρώστε τον όπως συνήθως.")
$lblDeepUninstallDesc.Font = $fontText
$lblDeepUninstallDesc.ForeColor = $theme.SubText
$lblDeepUninstallDesc.BackColor = [System.Drawing.Color]::Transparent
# ΔΙΟΡΘΩΣΗ v1.9.4 (γενικός έλεγχος κομμένων περιγραφών): ύψος αυξήθηκε (34->40) για ασφαλές περιθώριο.
$lblDeepUninstallDesc.Size = [System.Drawing.Size]::new(750, 40)
$lblDeepUninstallDesc.Location = [System.Drawing.Point]::new(15, 38)
$cardDeepUninstall.Controls.Add($lblDeepUninstallDesc)
$global:allTextLabels += $lblDeepUninstallDesc

$global:btnRefreshDeepUninstall = Helper-CreateButton (TT "Ανανέωση Λίστας") 800 40 180 30 $theme.Accent { Load-InstalledAppsList } $cardDeepUninstall $true (TT "Επαναφορτώνει τη λίστα εγκατεστημένων εφαρμογών από το μητρώο Windows.")

$global:deepUninstallPanelList = [System.Windows.Forms.Panel]::new()
$global:deepUninstallPanelList.Size = [System.Drawing.Size]::new(965, 250)
$global:deepUninstallPanelList.Location = [System.Drawing.Point]::new(15, 80)
$global:deepUninstallPanelList.AutoScroll = $true
Set-PanelScrollbarDarkMode -Panel $global:deepUninstallPanelList
$global:allThemedScrollPanels = @($global:allThemedScrollPanels) + $global:deepUninstallPanelList
$global:deepUninstallPanelList.BackColor = $theme.MainBg
if ($setStyleMethod) { $setStyleMethod.Invoke($global:deepUninstallPanelList, @($flickerFixStyles, $true)) | Out-Null }
$cardDeepUninstall.Controls.Add($global:deepUninstallPanelList)

function Get-ResidualFolders {
    param([string]$AppName)
    $safeName = $AppName -replace '[\\\/\:\*\?"<>\|]', ''
    $candidates = @()
    foreach ($base in @("$env:LOCALAPPDATA", "$env:APPDATA", "$env:ProgramData")) {
        if (Test-Path $base) {
            Get-ChildItem -Path $base -Directory -ErrorAction SilentlyContinue | Where-Object { $_.Name -like "*$safeName*" } | ForEach-Object { $candidates += $_.FullName }
        }
    }
    return $candidates
}

# ΔΙΟΡΘΩΣΗ (bug εντοπίστηκε: το κουμπί "Απεγκατάσταση & Καθαρισμός" έκανε Start-Process -Wait ΑΠΕΥΘΕΙΑΣ
# στο UI thread - ο ίδιος ο διάλογος επιβεβαίωσης λέει ρητά στον χρήστη "Ολοκληρώστε τα βήματα στο
# παράθυρο που θα ανοίξει", δηλαδή ο επίσημος uninstaller ΑΠΑΙΤΕΙ διαδραστικά βήματα από τον χρήστη -
# όλη η εφαρμογή "πάγωνε"/εμφανιζόταν ως "Δεν Ανταποκρίνεται" σε όλη τη διάρκεια, ενδεχομένως λεπτά.
# Ίδιο μοτίβο ασύγχρονης εκτέλεσης (Start-Process -PassThru + Timer polling) με τα υπόλοιπα βαριά
# εργαλεία της εφαρμογής (winget, driver scan, K-Lite, κ.λπ.).
$global:deepUninstallState = $null
$global:deepUninstallTimer = [System.Windows.Forms.Timer]::new()
$global:deepUninstallTimer.Interval = 500
$global:deepUninstallTimer.Add_Tick({
    if (-not $global:deepUninstallState) { $global:deepUninstallTimer.Stop(); return }
    if (-not $global:deepUninstallState.Process.HasExited) { return }
    $global:deepUninstallTimer.Stop()
    $appNameDu = $global:deepUninstallState.AppName
    $global:deepUninstallState = $null

    $residuals = Get-ResidualFolders -AppName $appNameDu
    if ($residuals.Count -gt 0) {
        $residualText = ($residuals -join "`n")
        $confirmResidual = Show-CustomMessage -Message "$(TT 'Βρέθηκαν πιθανοί υπολειπόμενοι φάκελοι:')`n$residualText`n`n$(TT 'Αποστολή τους στον Κάδο Ανακύκλωσης;')" -Title (TT "Υπολειπόμενα Αρχεία") -Type "YesNo"
        if ($confirmResidual -eq "Yes") {
            Add-Type -AssemblyName Microsoft.VisualBasic
            foreach ($resPath in $residuals) {
                try {
                    [Microsoft.VisualBasic.FileIO.FileSystem]::DeleteDirectory($resPath, [Microsoft.VisualBasic.FileIO.UIOption]::OnlyErrorDialogs, [Microsoft.VisualBasic.FileIO.RecycleOption]::SendToRecycleBin)
                } catch {}
            }
        }
    }
    $lblStatus.Text = "'$appNameDu' - $(TT 'ολοκληρώθηκε.')"
    Load-InstalledAppsList
})

function Load-InstalledAppsList {
    $global:deepUninstallPanelList.Controls.Clear()
    $apps = [System.Collections.ArrayList]::new()
    $seenNames = @{}
    foreach ($uPath in @(
        "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*",
        "HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*",
        "HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*"
    )) {
        Get-ItemProperty -Path $uPath -ErrorAction SilentlyContinue | Where-Object {
            $_.DisplayName -and $_.UninstallString -and -not $_.SystemComponent
        } | ForEach-Object {
            if (-not $seenNames.ContainsKey($_.DisplayName)) {
                $seenNames[$_.DisplayName] = $true
                [void]$apps.Add([PSCustomObject]@{ Name = $_.DisplayName; UninstallCmd = $_.UninstallString; Publisher = $_.Publisher })
            }
        }
    }
    $apps = $apps | Sort-Object Name

    $rowYD = 5
    foreach ($app in $apps) {
        $appName = $app.Name
        $uninstallCmd = $app.UninstallCmd
        $publisher = $app.Publisher

        $rowPanelD = [System.Windows.Forms.Panel]::new()
        $rowPanelD.Size = [System.Drawing.Size]::new(940, 34)
        $rowPanelD.Location = [System.Drawing.Point]::new(5, $rowYD)
        $rowPanelD.BackColor = $theme.CardBg
        $global:deepUninstallPanelList.Controls.Add($rowPanelD)

        $lblAppName = [System.Windows.Forms.Label]::new()
        $lblAppName.Text = if ($publisher) { "$appName ($publisher)" } else { $appName }
        $lblAppName.Font = $fontStatus
        $lblAppName.ForeColor = $theme.Text
        $lblAppName.BackColor = [System.Drawing.Color]::Transparent
        # ΔΙΟΡΘΩΣΗ v1.9.0 (βελτίωση περιθωρίου): πλάτος μειώθηκε ελαφρώς (680->655) δίνοντας πιο γενναιόδωρο
        # κενό (10px->35px) πριν το κουμπί, αντί για στενό διαχωρισμό.
        $lblAppName.Size = [System.Drawing.Size]::new(655, 28)
        $lblAppName.Location = [System.Drawing.Point]::new(10, 3)
        $rowPanelD.Controls.Add($lblAppName)
        $global:allTextLabels += $lblAppName

        $btnUninstallApp = [System.Windows.Forms.Button]::new()
        $btnUninstallApp.Size = [System.Drawing.Size]::new(230, 26)
        $btnUninstallApp.Location = [System.Drawing.Point]::new(700, 4)
        $btnUninstallApp.FlatStyle = "Flat"
        $btnUninstallApp.FlatAppearance.BorderSize = 0
        $btnUninstallApp.Font = $fontStatus
        $btnUninstallApp.Text = (TT "Απεγκατάσταση & Καθαρισμός")
        $btnUninstallApp.BackColor = [System.Drawing.Color]::FromArgb(209, 36, 36)
        $btnUninstallApp.ForeColor = [System.Drawing.Color]::White
        $btnUninstallApp.Cursor = [System.Windows.Forms.Cursors]::Hand
        $btnUninstallApp.Add_Click({
            # ΔΙΟΡΘΩΣΗ: .GetNewClosure() απαραίτητο - ίδιο μάθημα με το κρίσιμο σφάλμα της v1.8.0.
            if ($global:deepUninstallState) {
                Show-CustomMessage -Message (TT "Εκτελείται ήδη μια απεγκατάσταση - περιμένετε να ολοκληρωθεί πριν ξεκινήσετε άλλη.") -Title (TT "Προσοχή") -Type "Info"
                return
            }
            $confirmUninstallApp = Show-CustomMessage -Message "$(TT 'Εκκίνηση του επίσημου uninstaller για') '$appName'. $(TT 'Ολοκληρώστε τα βήματα στο παράθυρο που θα ανοίξει. Συνέχεια;')" -Title (TT "Επιβεβαίωση") -Type "YesNo"
            if ($confirmUninstallApp -ne "Yes") { return }
            # ΔΙΟΡΘΩΣΗ (bug: -Wait πάγωνε ολόκληρη την εφαρμογή όσο ο χρήστης αλληλεπιδρούσε με τον
            # εξωτερικό uninstaller) - τώρα ασύγχρονο μέσω $global:deepUninstallTimer (βλ. ορισμό παραπάνω).
            try {
                $procDu = Start-Process -FilePath "cmd.exe" -ArgumentList "/c `"$uninstallCmd`"" -PassThru -ErrorAction Stop
            } catch {
                Show-CustomMessage -Message "$(TT 'Αποτυχία εκκίνησης uninstaller'): $($_.Exception.Message)" -Title "Σφάλμα" -Type "Error"
                return
            }
            $lblStatus.Text = "'$appName' - $(TT 'η απεγκατάσταση βρίσκεται σε εξέλιξη...')"
            $global:deepUninstallState = [PSCustomObject]@{ Process = $procDu; AppName = $appName }
            $global:deepUninstallTimer.Start()
        }.GetNewClosure())
        Add-ButtonHoverEffect -Button $btnUninstallApp -BaseColor $btnUninstallApp.BackColor
        $rowPanelD.Controls.Add($btnUninstallApp)

        $rowYD += 38
    }
}
