Add-BloatwareRow (TT "Windows Media Player (Legacy)") 210 {
    # ΔΙΟΡΘΩΣΗ: Το σφάλμα "One or several parent features are disabled" σήμαινε ότι το γονικό feature
    # "MediaPlayback" ήταν απενεργοποιημένο. Το ενεργοποιούμε πρώτα.
    Enable-WindowsOptionalFeature -Online -FeatureName "MediaPlayback" -NoRestart -ErrorAction SilentlyContinue | Out-Null
    Enable-WindowsOptionalFeature -Online -FeatureName "WindowsMediaPlayer" -NoRestart -ErrorAction SilentlyContinue | Out-Null

    # ΝΕΟ: Ορισμός ως προεπιλογή για αρχεία μουσικής + καρφίτσωμα στη γραμμή εργασιών (best-effort).
    $wmpExe = "$env:WINDIR\System32\wmplayer.exe"
    $assocOk = Set-DefaultAppAssociations -Associations @{ ".mp3"="Applications\wmplayer.exe"; ".wma"="Applications\wmplayer.exe"; ".wav"="Applications\wmplayer.exe"; ".m4a"="Applications\wmplayer.exe" }
    $pinOk = Add-TaskbarPin -ExePath $wmpExe
    $msg = "Ο Windows Media Player εγκαταστάθηκε επιτυχώς!"
    if (-not $assocOk) { $msg += "`n(Ο ορισμός προεπιλογής για μουσική ενδέχεται να απαιτεί χειροκίνητη επιβεβαίωση από Ρυθμίσεις > Προεπιλεγμένες Εφαρμογές.)" }
    if (-not $pinOk) { $msg += "`n(Το αυτόματο καρφίτσωμα στη γραμμή εργασιών δεν υποστηρίζεται σε όλα τα builds - καρφιτσώστε το χειροκίνητα αν χρειάζεται.)" }
    Show-CustomMessage -Message $msg -Title "Επιτυχία"
} {
    Disable-WindowsOptionalFeature -Online -FeatureName "WindowsMediaPlayer" -NoRestart -ErrorAction SilentlyContinue | Out-Null
    Show-CustomMessage -Message "Ο Windows Media Player απενεργοποιήθηκε!" -Title "Ολοκλήρωση"
} (TT "Ο κλασικός Windows Media Player (προαιρετικό Windows feature). Θα οριστεί ως προεπιλογή για μουσική & θα καρφιτσωθεί στη γραμμή εργασιών (best-effort).")
