# ΝΕΟ: Λεξικό επίσημων ονομάτων για τις πιο συνηθισμένες προεγκατεστημένες εφαρμογές Metro/UWP, ώστε
# η λίστα να δείχνει αναγνωρίσιμα ονόματα αντί για τεχνικά PackageFamilyName. Ίδια λογική με τις
# περιγραφές των έξι ενσωματωμένων στοιχείων στην αρχή της καρτέλας.
$global:friendlyAppNames = @{
    "Microsoft.WindowsCalculator"                 = "Υπολογιστής (Calculator)"
    "Microsoft.WindowsAlarms"                      = "Ρολόι (Alarms & Clock)"
    "Microsoft.WindowsCamera"                      = "Κάμερα"
    "Microsoft.Windows.Photos"                     = "Φωτογραφίες"
    "microsoft.windowscommunicationsapps"          = "Mail & Calendar"
    "Microsoft.WindowsMaps"                        = "Χάρτες"
    "Microsoft.ZuneVideo"                          = "Ταινίες & Τηλεόραση"
    "Microsoft.MicrosoftSolitaireCollection"       = "Solitaire Collection"
    "Microsoft.MicrosoftStickyNotes"               = "Αυτοκόλλητες Σημειώσεις"
    "Microsoft.WindowsSoundRecorder"                = "Εγγραφή Ήχου"
    "Microsoft.XboxApp"                            = "Xbox App (Παλιά έκδοση)"
    "Microsoft.GamingApp"                          = "Xbox App"
    "Microsoft.WindowsStore"                       = "Microsoft Store"
    "Microsoft.GetHelp"                            = "Βοήθεια (Get Help)"
    "Microsoft.WindowsFeedbackHub"                 = "Feedback Hub"
    "Microsoft.Getstarted"                         = "Συμβουλές (Tips)"
    "Microsoft.Paint"                              = "Paint"
    "Microsoft.ScreenSketch"                       = "Αποκοπή & Σχεδίαση (Snip & Sketch)"
    "Microsoft.People"                             = "Άτομα (People)"
    "Microsoft.Todos"                              = "Microsoft To Do"
    "Microsoft.Office.OneNote"                     = "OneNote"
    "Microsoft.SkypeApp"                           = "Skype"
    "Microsoft.YourPhone"                          = "Phone Link"
    "Microsoft.MicrosoftOfficeHub"                 = "Office"
    "Microsoft.Windows.DevHome"                    = "Dev Home"
    "Clipchamp.Clipchamp"                          = "Clipchamp"
    "MicrosoftTeams"                               = "Microsoft Teams (Free)"
    "Microsoft.549981C3F5F10"                      = "Cortana"
    "Microsoft.WindowsNotepad"                     = "Σημειωματάριο (Notepad)"
}
function Get-FriendlyAppName {
    param($app)
    $famPrefix = ($app.PackageFamilyName -split '_')[0]
    if ($global:friendlyAppNames.ContainsKey($famPrefix)) { return $global:friendlyAppNames[$famPrefix] }
    if ($app.Name) {
        return [regex]::Replace($app.Name, '(?<=[a-z0-9])(?=[A-Z])', ' ')
    }
    return $app.PackageFullName
}

function Show-UwpAppManagerWindow {
    $currTheme = Get-ThemeColors
    $uwpForm = [System.Windows.Forms.Form]::new()
    $uwpForm.Text = TT "Διαχείριση Εγκατεστημένων Εφαρμογών Metro/UWP"
    $uwpForm.Size = [System.Drawing.Size]::new(900, 700)
    $uwpForm.StartPosition = "CenterParent"
    $uwpForm.FormBorderStyle = "FixedDialog"
    $uwpForm.MaximizeBox = $false
    $uwpForm.MinimizeBox = $false
    $uwpForm.BackColor = $currTheme.MainBg
    $uwpForm.BackgroundImage = New-ThemedBackgroundBitmap -Width 900 -Height 700 -Style $currTheme.BgStyle -IsDark $global:isDarkMode
    $uwpForm.BackgroundImageLayout = "Stretch"

    $btnScanUwp = [System.Windows.Forms.Button]::new()
    $btnScanUwp.Text = T "BtnScanApps"
    $btnScanUwp.Font = $fontBtnCustom
    $btnScanUwp.Size = [System.Drawing.Size]::new(300, 34)
    $btnScanUwp.Location = [System.Drawing.Point]::new(20, 20)
    $btnScanUwp.BackColor = [System.Drawing.Color]::FromArgb(40, 110, 190)
    $btnScanUwp.ForeColor = [System.Drawing.Color]::White
    $btnScanUwp.FlatStyle = "Flat"
    $btnScanUwp.FlatAppearance.BorderSize = 0
    $btnScanUwp.Cursor = [System.Windows.Forms.Cursors]::Hand
    Add-ButtonHoverEffect -Button $btnScanUwp -BaseColor $btnScanUwp.BackColor
    $uwpForm.Controls.Add($btnScanUwp)

    $lblUwpStatus = [System.Windows.Forms.Label]::new()
    $lblUwpStatus.Text = TT "Πατήστε 'Ανίχνευση' για εντοπισμό εγκατεστημένων εφαρμογών Metro/UWP."
    $lblUwpStatus.Font = $fontStatus
    $lblUwpStatus.ForeColor = $currTheme.SubText
    $lblUwpStatus.BackColor = [System.Drawing.Color]::Transparent
    $lblUwpStatus.Size = [System.Drawing.Size]::new(540, 24)
    $lblUwpStatus.Location = [System.Drawing.Point]::new(335, 27)
    $uwpForm.Controls.Add($lblUwpStatus)

    $uwpListPanel = [System.Windows.Forms.Panel]::new()
    $uwpListPanel.Size = [System.Drawing.Size]::new(855, 605)
    $uwpListPanel.Location = [System.Drawing.Point]::new(20, 65)
    $uwpListPanel.AutoScroll = $true
Set-PanelScrollbarDarkMode -Panel $uwpListPanel
$global:allThemedScrollPanels = @($global:allThemedScrollPanels) + $uwpListPanel
    $uwpForm.Controls.Add($uwpListPanel)

    $btnScanUwp.Add_Click({
        foreach ($ctrl in @($uwpListPanel.Controls)) { $uwpListPanel.Controls.Remove($ctrl); $ctrl.Dispose() }
        $lblUwpStatus.Text = TT "Σάρωση σε εξέλιξη..."
        $uwpForm.Refresh()

        # Εξαιρούνται frameworks, resource packages και πακέτα συστήματος (SignatureKind 'System') -
        # αυτά ΔΕΝ πρέπει να αφαιρούνται χειροκίνητα γιατί υποστηρίζουν τη λειτουργία των Windows.
        # Το SignatureKind -eq "Store" περιορίζει τη λίστα σε πραγματικά εγκατεστημένες εφαρμογές μέσω
        # Microsoft Store, εξαιρώντας desktop-bridge εφαρμογές (WhatsApp, Adobe κ.λπ.) που τεχνικά είναι
        # AppX πακέτα αλλά ΔΕΝ είναι πραγματικές εφαρμογές Metro/UWP.
        $uwpApps = @(Get-AppxPackage -ErrorAction SilentlyContinue | Where-Object {
            -not $_.IsFramework -and -not $_.IsResourcePackage -and $_.SignatureKind -eq "Store"
        } | Sort-Object Name)

        if ($uwpApps.Count -eq 0) {
            $lblUwpStatus.Text = TT "Δεν βρέθηκαν πρόσθετες εφαρμογές Metro/UWP προς απεγκατάσταση."
            return
        }

        $lblUwpStatus.Text = "$(TT 'Βρέθηκαν') $($uwpApps.Count) $(TT 'εφαρμογές Metro/UWP:')"
        $yPos = 5

        foreach ($app in $uwpApps) {
            $rowPanel = [System.Windows.Forms.Panel]::new()
            $rowPanel.Size = [System.Drawing.Size]::new(830, 40)
            $rowPanel.Location = [System.Drawing.Point]::new(0, $yPos)
            $uwpListPanel.Controls.Add($rowPanel)

            $lblApp = [System.Windows.Forms.Label]::new()
            $lblApp.Text = Get-FriendlyAppName -app $app
            $lblApp.Font = $fontBtnCustom
            $lblApp.ForeColor = $currTheme.Text
            $lblApp.BackColor = [System.Drawing.Color]::Transparent
            $lblApp.Size = [System.Drawing.Size]::new(620, 24)
            $lblApp.Location = [System.Drawing.Point]::new(0, 8)
            $rowPanel.Controls.Add($lblApp)
            $global:appToolTip.SetToolTip($lblApp, "Τεχνικό όνομα πακέτου: $($app.PackageFamilyName)")

            $pkgFullName = $app.PackageFullName
            $btnUninst = [System.Windows.Forms.Button]::new()
            $btnUninst.Text = T "BtnUninstall"
            $btnUninst.Font = $fontBtnCustom
            $btnUninst.Size = [System.Drawing.Size]::new(170, 34)
            $btnUninst.Location = [System.Drawing.Point]::new(655, 3)
            $btnUninst.BackColor = [System.Drawing.Color]::FromArgb(209, 36, 36)
            $btnUninst.ForeColor = [System.Drawing.Color]::White
            $btnUninst.FlatStyle = "Flat"
            $btnUninst.FlatAppearance.BorderSize = 0
            $btnUninst.Cursor = [System.Windows.Forms.Cursors]::Hand
            Add-ButtonHoverEffect -Button $btnUninst -BaseColor $btnUninst.BackColor
            $btnUninst.Add_Click({
                param($sender, $e)
                $confirmResult = Show-CustomMessage -Message "Απεγκατάσταση του πακέτου:`n$pkgFullName" -Title "Επιβεβαίωση Απεγκατάστασης" -Type "YesNo"
                if ($confirmResult -eq [System.Windows.Forms.DialogResult]::Yes) {
                    try {
                        Remove-AppxPackage -Package $pkgFullName -ErrorAction Stop
                        Show-CustomMessage -Message "Η απεγκατάσταση ολοκληρώθηκε!" -Title "Ολοκλήρωση"
                        $sender.Parent.Visible = $false
                    } catch {
                        Show-CustomMessage -Message "Αποτυχία απεγκατάστασης: $($_.Exception.Message)" -Title "Σφάλμα" -Type "Error"
                    }
                }
            }.GetNewClosure())
            $rowPanel.Controls.Add($btnUninst)

            $yPos += 44
        }
        # ΔΙΟΡΘΩΣΗ v1.6.4: Χωρίς ρητό AutoScrollMinSize, το WinForms Panel υπολογίζει μερικές φορές
        # ελαφρώς ανεπαρκή συνολικό ύψος κύλισης όταν τα παιδικά controls προστίθενται δυναμικά ένα-ένα -
        # η τελευταία εφαρμογή της λίστας έκοβε λίγα pixels ακόμα και όταν η κύλιση έφτανε ως το τέλος.
        # Ορίζεται ρητά εδώ, με επιπλέον περιθώριο 20px στο κάτω μέρος.
        $uwpListPanel.AutoScrollMinSize = [System.Drawing.Size]::new(0, $yPos + 20)
    })

    $uwpForm.ShowDialog($mainForm) | Out-Null
    $uwpForm.Dispose()
}

