Add-IconedLabel -IconType "AdvancedTools" -Text (TT "Προηγμένα εργαλεία και λειτουργίες διαχείρισης και συντήρησης συστήματος:") -x 100 -y 15 -w 960 -Font $fontText -IsSubText $true -Parent $tabAdvancedTools | Out-Null

$global:scrollPanelAdvanced = [System.Windows.Forms.Panel]::new()
$global:scrollPanelAdvanced.Anchor = [System.Windows.Forms.AnchorStyles]::Top -bor [System.Windows.Forms.AnchorStyles]::Bottom -bor [System.Windows.Forms.AnchorStyles]::Left -bor [System.Windows.Forms.AnchorStyles]::Right
$global:scrollPanelAdvanced.Size = [System.Drawing.Size]::new(1030, 520)
# ΝΕΟ v1.7.5: Ρητό AutoScrollMinSize (ίδιο προληπτικό μοτίβο με τα άλλα scroll panels) - μετά την
# αναδιοργάνωση σε 2 στήλες μόνο-κουμπιών, το περιεχόμενο (~420px) είναι πλέον πολύ πιο σύντομο από το
# ορατό ύψος του panel (520px) - ουσιαστικά δεν χρειάζεται καν κύλιση πια, αλλά ορίζεται ρητά για ασφάλεια.
$global:scrollPanelAdvanced.AutoScrollMinSize = [System.Drawing.Size]::new(1010, 425)
# ΔΙΟΡΘΩΣΗ v2.0.8: X κεντραρίστηκε μέσα στο πλατύτερο $content (1230-1030)/2=100.
# ΔΙΟΡΘΩΣΗ v2.1.0: X δυναμικό βάσει πλάτους $content (βλ. σχόλιο στο scrollPanelOptimization).
$global:scrollPanelAdvanced.Location = [System.Drawing.Point]::new([int]((1230 - $global:sidebarDockWidth - 1030) / 2), 45)
$global:scrollPanelAdvanced.AutoScroll = $true
Set-PanelScrollbarDarkMode -Panel $global:scrollPanelAdvanced
$global:allThemedScrollPanels = @($global:allThemedScrollPanels) + $global:scrollPanelAdvanced
$tabAdvancedTools.Controls.Add($global:scrollPanelAdvanced)

function Add-AdvancedToolRow {
    param($title, $x, $y, $actionScript, $tooltip = "", $parent = $global:scrollPanelAdvanced)
    # ΔΙΟΡΘΩΣΗ v2.0.1 (χρήστης εντόπισε "ένας ενιαίος τίτλος και ένα σωρό κουμπιά χωρίς ομαδοποίηση"):
    # προστέθηκε προαιρετικό $parent (προεπιλογή: το ίδιο scrollPanel, συμβατό με προηγούμενες κλήσεις)
    # ώστε τα κουμπιά να μπορούν να μπουν μέσα σε ξεχωριστές, θεματικές κάρτες αντί όλα απευθείας στο
    # scrollPanel.
    # ΔΙΟΡΘΩΣΗ ΡΙΖΙΚΗ v2.1.2 (ρητό αίτημα χρήστη - "στις όλες πρόσθετες λειτουργίες Windows δεν
    # εμφανίζονται οι περιγραφές"): το $tooltip περνιόταν ΠΑΝΤΑ ως όρισμα σε ΚΑΘΕ κλήση αυτής της
    # συνάρτησης, αλλά ΠΟΤΕ δεν αποδιδόταν πουθενά - ούτε ως ορατή ετικέτα, ούτε καν ως native ToolTip.
    # Η περιγραφή ήταν ΕΝΤΕΛΩΣ αόρατη σε ΟΛΕΣ τις 26+ γραμμές που χρησιμοποιούν αυτή τη συνάρτηση
    # (Συντήρηση & Διάγνωση, Εργαλειοθήκη, τα 6 quick-toggle Windows Features). Προστέθηκε πραγματική,
    # ορατή ετικέτα περιγραφής ΠΑΝΩ από κάθε κουμπί - ίδια φιλοσοφία με το Helper-CreateButton (βλ. σχόλιο
    # εκεί: "τα tooltips εμφανίζονται ΜΟΝΟ σε ετικέτες περιγραφής"). Το ύψος κάθε γραμμής/η απόσταση
    # μεταξύ τους αυξήθηκε ανάλογα σε ΟΛΕΣ τις κάρτες που την καλούν, ώστε να χωράει η περιγραφή χωρίς
    # επικάλυψη με την επόμενη γραμμή.
    $lblDesc = [System.Windows.Forms.Label]::new()
    $lblDesc.Text = $tooltip
    # ΔΙΟΡΘΩΣΗ v2.2.5 (αίτημα χρήστη - στιγμιότυπο: "σε όλη την καρτέλα Προηγμένα Εργαλεία κόβονται τα
    # κείμενα"): 2 συνδυασμένες αιτίες μέσα στο ίδιο, στενό (76px) ύψος γραμμής. (1) Οι περιγραφές
    # χρησιμοποιούσαν το $fontStatus (9.5pt, Italic - η πλάγια γραφή είναι ΚΑΙ ελαφρώς πλατύτερη) σε
    # ύψος μόλις 40px, ανεπαρκές για τις μακρύτερες προτάσεις περιγραφής - αντικαταστάθηκε με το
    # μικρότερο, ΜΗ-πλάγιο $fontDescSmall (8.75pt Regular, ήδη υπάρχον σε όλη την εφαρμογή). (2) Οι
    # τίτλοι κουμπιών ΔΕΝ τύλιγαν σωστά σε 30px ύψος - μικρότερη γραμματοσειρά (9.75->8.5pt Bold).
    $lblDesc.Font = $fontDescSmall
    $lblDesc.ForeColor = $theme.SubText
    $lblDesc.BackColor = [System.Drawing.Color]::Transparent
    $lblDesc.Size = [System.Drawing.Size]::new(485, 40)
    $lblDesc.Location = [System.Drawing.Point]::new($x, $y)
    $parent.Controls.Add($lblDesc)
    $global:allSubTextLabels += $lblDesc

    $btnRun = [System.Windows.Forms.Button]::new()
    $btnRun.Size = [System.Drawing.Size]::new(485, 34)
    $btnRun.Location = [System.Drawing.Point]::new($x, $y + 42)
    $btnRun.FlatStyle = "Flat"
    $btnRun.FlatAppearance.BorderSize = 0
    $btnRun.Font = Get-SafeFont -Size 8.5 -Style ([System.Drawing.FontStyle]::Bold)
    $btnRun.Text = $title
    $btnRun.TextAlign = [System.Drawing.ContentAlignment]::MiddleCenter
    $btnRun.BackColor = [System.Drawing.Color]::FromArgb(40, 110, 190)
    $btnRun.ForeColor = [System.Drawing.Color]::White
    $btnRun.Cursor = [System.Windows.Forms.Cursors]::Hand
    $btnRun.Add_Click($actionScript)
    Add-ButtonHoverEffect -Button $btnRun -BaseColor $btnRun.BackColor
    $parent.Controls.Add($btnRun)
}

# ΔΙΟΡΘΩΣΗ v2.0.1: 2 ξεχωριστές, θεματικές κάρτες αντί για όλα τα κουμπιά απευθείας στο scrollPanel.
$cardAdvMaintenance = Helper-CreateCard 0 0 1010 600 $global:scrollPanelAdvanced
Add-IconedLabel -IconType "Tools" -Text (TT "Συντήρηση & Διάγνωση Συστήματος") -x 15 -y 10 -w 700 -Font $fontBoldText -IsSubText $false -Parent $cardAdvMaintenance | Out-Null

$cardAdvToolbox = Helper-CreateCard 0 610 1010 370 $global:scrollPanelAdvanced
Add-IconedLabel -IconType "AdvancedTools" -Text (TT "Εργαλειοθήκη (Γρήγορη Πρόσβαση)") -x 15 -y 10 -w 700 -Font $fontBoldText -IsSubText $false -Parent $cardAdvToolbox | Out-Null
$global:scrollPanelAdvanced.AutoScrollMinSize = [System.Drawing.Size]::new(1010, 800)

Add-AdvancedToolRow (TT "Full System Maintenance & Component Suite") 15 50 {
    $progressBar.Visible = $true
    $progressBar.Value = 25
    $lblStatus.Text = (TT "Εκτέλεση Full System Maintenance...")
    $mainForm.Refresh()
    
    Remove-Item -Path "$env:TEMP\*" -Recurse -Force -ErrorAction SilentlyContinue
    $progressBar.Value = 60
    Invoke-DiagnosticCommand "sfc /scannow; DISM /Online /Cleanup-Image /RestoreHealth"
    $progressBar.Value = 100
    
    Start-Sleep -Milliseconds 300
    $progressBar.Visible = $false
    $lblStatus.Text = (TT "Η συντήρηση συστήματος ξεκίνησε επιτυχώς!")
} (TT "Καθαρίζει προσωρινά αρχεία και ξεκινά SFC + DISM RestoreHealth σε ένα βήμα. Ίδια βασική λειτουργία με τα κουμπιά της καρτέλας 'Υγεία & Συντήρηση', αλλά συνδυασμένα.") $cardAdvMaintenance

Add-AdvancedToolRow (TT "Ενεργοποίηση Προνομίων Συστήματος (Token Privileges)") 515 50 {
    try {
        [NativeSysInterop.TokenManipulator]::EnablePrivilege("SeTcbPrivilege") | Out-Null
        [NativeSysInterop.TokenManipulator]::EnablePrivilege("SeDebugPrivilege") | Out-Null
        Show-CustomMessage -Message "Τα προνομιακά δικαιώματα (Token Privileges) ενεργοποιήθηκαν επιτυχώς!" -Title "Token Tool"
    } catch {
        Show-CustomMessage -Message "Σφάλμα κατά την ενεργοποίηση προνομίων: $($_.Exception.Message)" -Title "Σφάλμα" -Type "Error"
    }
} (TT "Ενεργοποιεί προνόμια (SeTcbPrivilege, SeDebugPrivilege) που η διεργασία ήδη διαθέτει ως Administrator. Προχωρημένη λειτουργία - χρησιμοποιήστε μόνο αν γνωρίζετε τι κάνει.") $cardAdvMaintenance

Add-AdvancedToolRow (TT "Advanced Network Reset & Winsock Flush") 15 126 {
    $progressBar.Visible = $true
    $progressBar.Value = 30
    $lblStatus.Text = (TT "Εκτέλεση Advanced Network Reset...")
    $mainForm.Refresh()
    
    netsh winsock reset | Out-Null
    netsh int ip reset | Out-Null
    ipconfig /flushdns | Out-Null
    $progressBar.Value = 100
    
    Start-Sleep -Milliseconds 300
    $progressBar.Visible = $false
    Show-CustomMessage -Message "Η επαναφορά δικτύου ολοκληρώθηκε!" -Title "Network Reset"
} (TT "Winsock reset + IP reset + Flush DNS σε ένα κλικ. Καλύπτει την ίδια λειτουργία με τα κουμπιά DNS/δικτύου της καρτέλας 'Δίκτυο & Ασφάλεια'.") $cardAdvMaintenance

Add-AdvancedToolRow (TT "Καθαρισμός Event Logs Συστήματος (Logs Purge)") 515 126 {
    $progressBar.Visible = $true
    $progressBar.Value = 40
    $lblStatus.Text = (TT "Εκκαθάριση Event Logs...")
    $mainForm.Refresh()
    
    Get-WinEvent -ListLog * -ErrorAction SilentlyContinue | ForEach-Object {
        try { [Diagnostics.Eventing.Reader.EventLogSession]::GlobalSession.ClearLog($null, $_.LogName) } catch {}
    }
    $progressBar.Value = 100
    
    Start-Sleep -Milliseconds 300
    $progressBar.Visible = $false
    Show-CustomMessage -Message "Όλα τα καταγραφικά αρχεία (Event Logs) εκκαθαρίστηκαν!" -Title "Logs Purge"
} (TT "Αδειάζει όλα τα Windows Event Logs. Χρήσιμο για ελευθέρωση χώρου, αλλά χάνετε το ιστορικό καταγραφών - μη το τρέχετε πριν από αντιμετώπιση σφαλμάτων.") $cardAdvMaintenance

Add-AdvancedToolRow (TT "Βελτιστοποίηση Μνήμης & Garbage Collection") 15 202 {
    $progressBar.Visible = $true
    $progressBar.Value = 50
    $lblStatus.Text = (TT "Βελτιστοποίηση μνήμης RAM...")
    $mainForm.Refresh()
    
    [System.GC]::Collect()
    [System.GC]::WaitForPendingFinalizers()
    $progressBar.Value = 100
    
    Start-Sleep -Milliseconds 300
    $progressBar.Visible = $false
    Show-CustomMessage -Message "Η μνήμη RAM βελτιστοποιήθηκε επιτυχώς!" -Title "Memory Optimizer"
} (TT "Εξαναγκάζει .NET Garbage Collection στη διεργασία του ίδιου του εργαλείου. Δεν 'καθαρίζει' τη RAM όλου του συστήματος.") $cardAdvMaintenance

Add-AdvancedToolRow (TT "Deep Diagnostics Report (Εξαγωγή Αναφοράς)") 515 202 {
    $reportPath = "$env:USERPROFILE\Desktop\Deep_Diagnostics.txt"
    $sysInfo = Get-ComputerInfo
    "Deep Diagnostics Report`nGenerated: $(Get-Date)`nOS: $($sysInfo.OsName)`nCS: $($sysInfo.CsName)`nTotal Physical Memory: $([math]::Round($sysInfo.CsTotalPhysicalMemory / 1GB, 2)) GB" | Out-File -FilePath $reportPath -Encoding UTF8
    Start-Process notepad $reportPath
    Show-CustomMessage -Message "Η αναφορά διαγνωστικών δημιουργήθηκε στην επιφάνεια εργασίας!" -Title "Diagnostics"
} (TT "Εξάγει βασικά στοιχεία συστήματος (OS, όνομα υπολογιστή, RAM) σε αρχείο .txt στην Επιφάνεια Εργασίας.") $cardAdvMaintenance

