# ===== ΝΕΑ ΚΑΡΤΑ (κατόπιν reverse engineering του WMT): ΠΡΟΣΘΕΤΕΣ ΛΕΙΤΟΥΡΓΙΕΣ WINDOWS (OPTIONAL FEATURES) =====
# Γενίκευση - πριν υπήρχαν μόνο 2 hardcoded κλήσεις Enable/Disable-WindowsOptionalFeature (Windows Media
# Player legacy). Κάθε κουμπί εδώ ελέγχει ΠΡΩΤΑ συγχρονισμένα την τρέχουσα κατάσταση (γρήγορο ερώτημα DISM,
# ~1 δευτ.), μετά ζητά επιβεβαίωση, και τέλος στέλνει την πραγματική ενεργοποίηση/απενεργοποίηση (που
# μπορεί να διαρκέσει αρκετά λεπτά) στο Invoke-DiagnosticCommand - ίδιο ασύγχρονο μοτίβο (ξεχωριστή
# διεργασία κονσόλας) με SFC/DISM παραπάνω, ώστε να ΜΗΝ παγώνει το UI thread.
function Invoke-OptionalFeatureToggle {
    param([string]$FeatureName, [string]$DisplayName)
    try {
        $featState = (Get-WindowsOptionalFeature -Online -FeatureName $FeatureName -ErrorAction Stop).State
    } catch {
        Show-CustomMessage -Message "$(TT 'Αποτυχία ελέγχου κατάστασης λειτουργίας'): $($_.Exception.Message)" -Title "Σφάλμα" -Type "Error"
        return
    }
    if ($featState -eq "Enabled") {
        $confirmOff = Show-CustomMessage -Message "$(TT 'Η λειτουργία') '$DisplayName' $(TT 'είναι ενεργή. Θέλετε να απενεργοποιηθεί; Μπορεί να διαρκέσει αρκετά λεπτά και ενδέχεται να ζητηθεί επανεκκίνηση.')" -Title (TT "Επιβεβαίωση") -Type "YesNo"
        if ($confirmOff -ne [System.Windows.Forms.DialogResult]::Yes) { return }
        Invoke-DiagnosticCommand "Disable-WindowsOptionalFeature -Online -FeatureName '$FeatureName' -NoRestart"
    } else {
        $confirmOn = Show-CustomMessage -Message "$(TT 'Θα ενεργοποιηθεί η λειτουργία') '$DisplayName'. $(TT 'Μπορεί να διαρκέσει αρκετά λεπτά και ενδέχεται να ζητηθεί επανεκκίνηση. Συνέχεια;')" -Title (TT "Επιβεβαίωση") -Type "YesNo"
        if ($confirmOn -ne [System.Windows.Forms.DialogResult]::Yes) { return }
        Invoke-DiagnosticCommand "Enable-WindowsOptionalFeature -Online -FeatureName '$FeatureName' -All -NoRestart"
    }
    $lblStatus.Text = (TT "Η ενέργεια ξεκίνησε στο παρασκήνιο - παρακολουθήστε το παράθυρο κονσόλας.")
}

