$global:allWinFeaturesData = @()

function Render-AllWinFeaturesList {
    $global:winFeaturesPanelList.Controls.Clear()
    $filterTxt = $global:txtWinFeaturesSearch.Text.Trim()
    $filtered = if ($filterTxt) { @($global:allWinFeaturesData | Where-Object { $_.DisplayName -like "*$filterTxt*" -or $_.FeatureName -like "*$filterTxt*" }) } else { @($global:allWinFeaturesData) }
    if ($filtered.Count -eq 0) {
        $global:lblWinFeaturesStatus.Text = if ($global:allWinFeaturesData.Count -eq 0) { (TT "Πατήστε 'Ανανέωση Λίστας' για πλήρη λίστα λειτουργιών Windows.") } else { (TT "Καμία λειτουργία δεν ταιριάζει με την αναζήτηση.") }
        return
    }
    $global:lblWinFeaturesStatus.Text = "$($filtered.Count) $(TT 'λειτουργίες')"
    $currWfTheme = Get-ThemeColors
    $rowYWf = 5
    foreach ($feat in $filtered) {
        $rowPanelWf = [System.Windows.Forms.Panel]::new()
        $rowPanelWf.Size = [System.Drawing.Size]::new(965, 32)
        $rowPanelWf.Location = [System.Drawing.Point]::new(5, $rowYWf)
        $global:winFeaturesPanelList.Controls.Add($rowPanelWf)

        $lblFeatName = [System.Windows.Forms.Label]::new()
        $lblFeatName.Text = $feat.DisplayName
        $lblFeatName.Font = $fontText
        $lblFeatName.ForeColor = $currWfTheme.Text
        $lblFeatName.BackColor = [System.Drawing.Color]::Transparent
        $lblFeatName.Size = [System.Drawing.Size]::new(650, 24)
        $lblFeatName.Location = [System.Drawing.Point]::new(0, 4)
        $rowPanelWf.Controls.Add($lblFeatName)
        $global:allTextLabels += $lblFeatName

        $stateOnWf = ($feat.State -eq "Enabled")
        $lblFeatState = [System.Windows.Forms.Label]::new()
        $lblFeatState.Text = if ($stateOnWf) { (TT "Ενεργή") } else { (TT "Ανενεργή") }
        $lblFeatState.Font = $fontStatus
        $lblFeatState.ForeColor = if ($stateOnWf) { [System.Drawing.Color]::FromArgb(90, 200, 120) } else { $currWfTheme.SubText }
        $lblFeatState.BackColor = [System.Drawing.Color]::Transparent
        $lblFeatState.TextAlign = "MiddleLeft"
        $lblFeatState.Size = [System.Drawing.Size]::new(90, 24)
        $lblFeatState.Location = [System.Drawing.Point]::new(655, 4)
        $rowPanelWf.Controls.Add($lblFeatState)
        $global:allSubTextLabels += $lblFeatState

        $btnToggleText = if ($stateOnWf) { (TT "Απενεργοποίηση") } else { (TT "Ενεργοποίηση") }
        $btnToggleColor = if ($stateOnWf) { [System.Drawing.Color]::FromArgb(180, 70, 70) } else { $theme.Accent }
        $btnToggleAction = { Invoke-OptionalFeatureToggle -FeatureName $feat.FeatureName -DisplayName $feat.DisplayName }.GetNewClosure()
        $btnFeatToggle = Helper-CreateButton $btnToggleText 755 0 210 30 $btnToggleColor $btnToggleAction $rowPanelWf $true

        $rowYWf += 36
    }
}
$global:txtWinFeaturesSearch.Add_TextChanged({ Render-AllWinFeaturesList })

$global:winFeaturesScanState = $null
$global:winFeaturesScanTimer = [System.Windows.Forms.Timer]::new()
$global:winFeaturesScanTimer.Interval = 800
$global:winFeaturesScanTimer.Add_Tick({
    if (-not $global:winFeaturesScanState) { $global:winFeaturesScanTimer.Stop(); return }
    if (-not $global:winFeaturesScanState.Process.HasExited) { return }
    $global:winFeaturesScanTimer.Stop()
    $rawJsonWf = $null
    if (Test-Path $global:winFeaturesScanState.OutFile) {
        $rawJsonWf = Get-Content -Path $global:winFeaturesScanState.OutFile -Raw -ErrorAction SilentlyContinue
        Remove-Item -Path $global:winFeaturesScanState.OutFile -Force -ErrorAction SilentlyContinue
    }
    if (Test-Path $global:winFeaturesScanState.ScriptFile) {
        Remove-Item -Path $global:winFeaturesScanState.ScriptFile -Force -ErrorAction SilentlyContinue
    }
    $global:winFeaturesScanState = $null
    if (-not $rawJsonWf) {
        $global:lblWinFeaturesStatus.Text = (TT "Η φόρτωση απέτυχε ή δεν επέστρεψε αποτελέσματα.")
        return
    }
    try {
        $global:allWinFeaturesData = @($rawJsonWf | ConvertFrom-Json -ErrorAction Stop)
    } catch {
        $global:lblWinFeaturesStatus.Text = (TT "Σφάλμα ανάλυσης αποτελεσμάτων σάρωσης.")
        return
    }
    Render-AllWinFeaturesList
})

function Start-AllWinFeaturesScan {
    if ($global:winFeaturesScanState) { return }
    $global:lblWinFeaturesStatus.Text = (TT "Φόρτωση πλήρους λίστας μέσω DISM...")
    $global:winFeaturesPanelList.Controls.Clear()

    $tempOutWf = Join-Path $env:TEMP "OptimizerWinFeatures_$([guid]::NewGuid().ToString('N')).json"
    $scanScriptWf = @'
$ErrorActionPreference = "Continue"
# ΔΙΟΡΘΩΣΗ v2.1.2 (χρήστης εντόπισε): ο Windows Media Player (WindowsMediaPlayer) εμφανιζόταν ΚΑΙ εδώ
# (γενική λίστα) ΚΑΙ ως ειδικό, εμπλουτισμένο toggle στην καρτέλα Εφαρμογές & Bloat (Add-BloatwareRow -
# εκεί κάνει ΚΑΙ ορισμό προεπιλογής μουσικής ΚΑΙ καρφίτσωμα στη γραμμή εργασιών, όχι μόνο enable/disable) -
# ενεργοποίηση από ΕΔΩ θα παρέκαμπτε σιωπηλά αυτή την πρόσθετη λογική. Εξαιρούνται όλα τα features που
# έχουν ήδη δικό τους ειδικό toggle αλλού στην εφαρμογή (WMP + τα 6 quick-toggle της κάρτας "Πρόσθετες
# Λειτουργίες Windows" παραπάνω) ώστε να μην υπάρχουν 2 διαφορετικοί, ενδεχομένως ασυνεπείς τρόποι.
$excludeNames = @("MediaPlayback", "WindowsMediaPlayer", "NetFx3", "Containers-DisposableClientVM", "Microsoft-Hyper-V-All", "Microsoft-Windows-Subsystem-Linux", "TelnetClient", "SMB1Protocol")
$feats = Get-WindowsOptionalFeature -Online -ErrorAction SilentlyContinue | Where-Object { $excludeNames -notcontains $_.FeatureName } | Sort-Object DisplayName
$results = @()
foreach ($f in $feats) {
    $results += [PSCustomObject]@{ FeatureName = $f.FeatureName; DisplayName = $f.DisplayName; State = [string]$f.State }
}
$results | ConvertTo-Json -Depth 4 -Compress | Out-File -FilePath "OUTFILE_PLACEHOLDER" -Encoding utf8
'@
    $scanScriptWf = $scanScriptWf.Replace("OUTFILE_PLACEHOLDER", $tempOutWf)
    $scriptFileWf = Join-Path $env:TEMP "OptimizerWinFeaturesScript_$([guid]::NewGuid().ToString('N')).ps1"
    Set-Content -Path $scriptFileWf -Value $scanScriptWf -Encoding utf8

    try {
        $procWf = Start-Process -FilePath "powershell.exe" -ArgumentList "-NoProfile -ExecutionPolicy Bypass -File `"$scriptFileWf`"" -WindowStyle Hidden -PassThru -ErrorAction Stop
    } catch {
        $global:lblWinFeaturesStatus.Text = "$(TT 'Αποτυχία εκκίνησης σάρωσης'): $($_.Exception.Message)"
        return
    }
    $global:winFeaturesScanState = [PSCustomObject]@{ Process = $procWf; OutFile = $tempOutWf; ScriptFile = $scriptFileWf }
    $global:winFeaturesScanTimer.Start()
}

# ===== ΝΕΑ ΚΑΡΤΑ (κατόπιν reverse engineering του WMT): ΔΙΑΧΕΙΡΙΣΗ ΣΥΣΚΕΥΩΝ-ΦΑΝΤΑΣΜΑΤΩΝ (GHOST DEVICES) =====
# "Ghost/hidden devices" = συσκευές υλικού που έχουν αποσυνδεθεί (π.χ. παλιό USB stick, εξωτερικός δίσκος)
# αλλά παραμένουν καταχωρημένες στα Windows, αόρατες στη συνηθισμένη Διαχείριση Συσκευών. Χρησιμοποιεί τα
# επίσημα cmdlets Get-PnpDevice/Remove-PnpDevice (module "PnpDevice", ενσωματωμένο στα Windows 10/11) -
# ΠΟΤΕ κείμενο pnputil (locale-ασφαλές, ίδια λογική με τον καθαρισμό αποθήκης οδηγών παραπάνω). Only
# "Present=false" συσκευές εμφανίζονται - συνδεδεμένο υλικό δεν αγγίζεται ποτέ.
$cardGhostDevices = Helper-CreateCard 0 1680 1010 320 $global:scrollPanelAdvanced
Add-IconedLabel -IconType "Tools" -Text (TT "Διαχείριση Συσκευών-Φαντασμάτων") -x 15 -y 10 -w 700 -Font $fontBoldText -IsSubText $false -Parent $cardGhostDevices | Out-Null

$lblGhostDesc = [System.Windows.Forms.Label]::new()
$lblGhostDesc.Text = (TT "Εντοπίζει συσκευές υλικού που έχουν αποσυνδεθεί αλλά παραμένουν καταχωρημένες στα Windows. Η αφαίρεσή τους ελευθερώνει καταχωρήσεις registry - δεν αγγίζει ποτέ συνδεδεμένο υλικό.")
$lblGhostDesc.Font = $fontText
$lblGhostDesc.ForeColor = $theme.SubText
$lblGhostDesc.BackColor = [System.Drawing.Color]::Transparent
$lblGhostDesc.Size = [System.Drawing.Size]::new(1000, 22)
$lblGhostDesc.Location = [System.Drawing.Point]::new(15, 38)
$cardGhostDevices.Controls.Add($lblGhostDesc)
$global:allTextLabels += $lblGhostDesc

$global:lblGhostStatus = [System.Windows.Forms.Label]::new()
$global:lblGhostStatus.Text = (TT "Πατήστε 'Σάρωση' για έναρξη.")
$global:lblGhostStatus.Font = $fontStatus
$global:lblGhostStatus.ForeColor = $theme.SubText
$global:lblGhostStatus.Size = [System.Drawing.Size]::new(1000, 20)
$global:lblGhostStatus.Location = [System.Drawing.Point]::new(15, 62)
$cardGhostDevices.Controls.Add($global:lblGhostStatus)
$global:allSubTextLabels += $global:lblGhostStatus

