$global:ghostDevicePanelList.AutoScroll = $true
Set-PanelScrollbarDarkMode -Panel $global:ghostDevicePanelList
$global:allThemedScrollPanels = @($global:allThemedScrollPanels) + $global:ghostDevicePanelList
$global:ghostDevicePanelList.BackColor = $theme.MainBg
if ($setStyleMethod) { $setStyleMethod.Invoke($global:ghostDevicePanelList, @($flickerFixStyles, $true)) | Out-Null }
$cardGhostDevices.Controls.Add($global:ghostDevicePanelList)

$global:ghostScanState = $null
$global:ghostScanTimer = [System.Windows.Forms.Timer]::new()
$global:ghostScanTimer.Interval = 800
$global:ghostScanTimer.Add_Tick({
    if (-not $global:ghostScanState) { $global:ghostScanTimer.Stop(); return }
    if (-not $global:ghostScanState.Process.HasExited) { return }
    $global:ghostScanTimer.Stop()
    $rawJsonGh = $null
    if (Test-Path $global:ghostScanState.OutFile) {
        $rawJsonGh = Get-Content -Path $global:ghostScanState.OutFile -Raw -ErrorAction SilentlyContinue
        Remove-Item -Path $global:ghostScanState.OutFile -Force -ErrorAction SilentlyContinue
    }
    if (Test-Path $global:ghostScanState.ScriptFile) {
        Remove-Item -Path $global:ghostScanState.ScriptFile -Force -ErrorAction SilentlyContinue
    }
    $global:ghostScanState = $null
    $global:ghostDevicePanelList.Controls.Clear()
    if (-not $rawJsonGh) {
        $global:lblGhostStatus.Text = (TT "Δεν βρέθηκαν συσκευές-φαντάσματα.")
        return
    }
    try {
        $ghostDevs = @($rawJsonGh | ConvertFrom-Json -ErrorAction Stop)
    } catch {
        $global:lblGhostStatus.Text = (TT "Σφάλμα ανάλυσης αποτελεσμάτων σάρωσης.")
        return
    }
    if ($ghostDevs.Count -eq 0) {
        $global:lblGhostStatus.Text = (TT "Δεν βρέθηκαν συσκευές-φαντάσματα - τίποτα προς αφαίρεση.")
        return
    }
    $global:lblGhostStatus.Text = "$($ghostDevs.Count) $(TT 'συσκευές-φαντάσματα βρέθηκαν.')"
    $rowYGh = 5
    foreach ($dev in $ghostDevs) {
        $devInstanceId = $dev.InstanceId
        $devLabel = "$($dev.FriendlyName) [$($dev.Class)]"

        $rowPanelGh = [System.Windows.Forms.Panel]::new()
        $rowPanelGh.Size = [System.Drawing.Size]::new(970, 34)
        $rowPanelGh.Location = [System.Drawing.Point]::new(5, $rowYGh)
        $rowPanelGh.BackColor = $theme.CardBg
        $global:ghostDevicePanelList.Controls.Add($rowPanelGh)

        $lblGhostInfo = [System.Windows.Forms.Label]::new()
        $lblGhostInfo.Text = $devLabel
        $lblGhostInfo.Font = $fontStatus
        $lblGhostInfo.ForeColor = $theme.Text
        $lblGhostInfo.BackColor = [System.Drawing.Color]::Transparent
        $lblGhostInfo.Size = [System.Drawing.Size]::new(830, 28)
        $lblGhostInfo.Location = [System.Drawing.Point]::new(10, 3)
        $rowPanelGh.Controls.Add($lblGhostInfo)
        $global:allTextLabels += $lblGhostInfo

        $btnRemoveGhost = [System.Windows.Forms.Button]::new()
        $btnRemoveGhost.Text = (TT "Αφαίρεση")
        $btnRemoveGhost.Size = [System.Drawing.Size]::new(110, 28)
        $btnRemoveGhost.Location = [System.Drawing.Point]::new(850, 3)
        $btnRemoveGhost.FlatStyle = "Flat"
        $btnRemoveGhost.FlatAppearance.BorderSize = 0
        $btnRemoveGhost.Font = $fontStatus
        $btnRemoveGhost.BackColor = [System.Drawing.Color]::FromArgb(200, 80, 70)
        $btnRemoveGhost.ForeColor = [System.Drawing.Color]::White
        $btnRemoveGhost.Cursor = [System.Windows.Forms.Cursors]::Hand
        $btnRemoveGhost.Add_Click({
            try {
                Remove-PnpDevice -InstanceId $devInstanceId -Confirm:$false -ErrorAction Stop
                $rowPanelGh.Dispose()
                $lblStatus.Text = "'$($dev.FriendlyName)' $(TT 'αφαιρέθηκε.')"
            } catch {
                Show-CustomMessage -Message "$(TT 'Αποτυχία αφαίρεσης συσκευής'): $($_.Exception.Message)" -Title "Σφάλμα" -Type "Error"
            }
        }.GetNewClosure())
        Add-ButtonHoverEffect -Button $btnRemoveGhost -BaseColor $btnRemoveGhost.BackColor
        $rowPanelGh.Controls.Add($btnRemoveGhost)

        $rowYGh += 38
    }
})

function Start-GhostDeviceScan {
    if ($global:ghostScanState) { return }
    $global:lblGhostStatus.Text = (TT "Σάρωση για συσκευές-φαντάσματα σε εξέλιξη...")
    $global:ghostDevicePanelList.Controls.Clear()
    $tempOutGh = Join-Path $env:TEMP "OptimizerGhostDevices_$([guid]::NewGuid().ToString('N')).json"
    $ghScriptContent = @'
$ErrorActionPreference = "Continue"
$devs = Get-PnpDevice -PresentOnly:$false -ErrorAction SilentlyContinue | Where-Object { -not $_.Present -and $_.FriendlyName } | Select-Object InstanceId, FriendlyName, Class
($devs | ConvertTo-Json -Depth 3 -Compress) | Out-File -FilePath "OUTFILE_PLACEHOLDER" -Encoding utf8
'@
    $ghScriptContent = $ghScriptContent.Replace("OUTFILE_PLACEHOLDER", $tempOutGh)
    $ghScriptFile = Join-Path $env:TEMP "OptimizerGhostDevicesScript_$([guid]::NewGuid().ToString('N')).ps1"
    Set-Content -Path $ghScriptFile -Value $ghScriptContent -Encoding utf8
    try {
        $procGh = Start-Process -FilePath "powershell.exe" -ArgumentList "-NoProfile -ExecutionPolicy Bypass -File `"$ghScriptFile`"" -WindowStyle Hidden -PassThru -ErrorAction Stop
    } catch {
        $global:lblGhostStatus.Text = "$(TT 'Αποτυχία εκκίνησης'): $($_.Exception.Message)"
        return
    }
    $global:ghostScanState = [PSCustomObject]@{ Process = $procGh; OutFile = $tempOutGh; ScriptFile = $ghScriptFile }
    $global:ghostScanTimer.Start()
}

