$global:driveBenchState = $null
$global:driveBenchTimer = [System.Windows.Forms.Timer]::new()
$global:driveBenchTimer.Interval = 500
$global:driveBenchTimer.Add_Tick({
    if (-not $global:driveBenchState) { $global:driveBenchTimer.Stop(); return }
    if (-not $global:driveBenchState.Process.HasExited) { return }
    $global:driveBenchTimer.Stop()
    $rawJsonBn = $null
    if (Test-Path $global:driveBenchState.OutFile) {
        $rawJsonBn = Get-Content -Path $global:driveBenchState.OutFile -Raw -ErrorAction SilentlyContinue
        Remove-Item -Path $global:driveBenchState.OutFile -Force -ErrorAction SilentlyContinue
    }
    if (Test-Path $global:driveBenchState.ScriptFile) {
        Remove-Item -Path $global:driveBenchState.ScriptFile -Force -ErrorAction SilentlyContinue
    }
    $global:driveBenchState = $null
    $global:btnStartBenchmark.Enabled = $true
    if (-not $rawJsonBn) {
        $global:lblBenchStatus.Text = (TT "Η δοκιμή απέτυχε ή δεν επέστρεψε αποτελέσματα.")
        return
    }
    try {
        $benchData = $rawJsonBn | ConvertFrom-Json -ErrorAction Stop
    } catch {
        $global:lblBenchStatus.Text = (TT "Σφάλμα ανάλυσης αποτελεσμάτων σάρωσης.")
        return
    }
    if ($benchData.Error) {
        $global:lblBenchStatus.Text = "$(TT 'Αποτυχία δοκιμής'): $($benchData.Error)"
        return
    }
    $global:lblBenchWriteVal.Text = "$($benchData.WriteMBps) MB/s"
    $global:lblBenchReadVal.Text = "$($benchData.ReadMBps) MB/s"
    $global:lblBenchStatus.Text = (TT "ολοκληρώθηκε.")
})

function Start-DriveBenchmark {
    param([string]$Drive)
    if ($global:driveBenchState) { return }
    try {
        $freeInfo = Get-CimInstance Win32_LogicalDisk -Filter "DeviceID='$Drive'" -ErrorAction Stop
        if ($freeInfo.FreeSpace -lt 1GB) {
            $global:lblBenchStatus.Text = (TT "Ανεπαρκής ελεύθερος χώρος (χρειάζεται τουλάχιστον 1GB) για ασφαλή δοκιμή.")
            return
        }
    } catch {}

    $global:btnStartBenchmark.Enabled = $false
    $global:lblBenchStatus.Text = "$(TT 'Δοκιμή σε εξέλιξη για') $Drive..."
    $global:lblBenchWriteVal.Text = "-- MB/s"
    $global:lblBenchReadVal.Text = "-- MB/s"

    $tempOutBn = Join-Path $env:TEMP "OptimizerBenchResult_$([guid]::NewGuid().ToString('N')).json"
    $benchScript = @'
$ErrorActionPreference = "Stop"
$drive = "DRIVE_PLACEHOLDER"
$testSizeMB = 256
$testPath = Join-Path "$drive\" "OptimizerBenchTest_TEMP.bin"
$result = [PSCustomObject]@{ WriteMBps = 0; ReadMBps = 0; Error = $null }
try {
    $data = New-Object byte[] ($testSizeMB * 1MB)
    $sw = [System.Diagnostics.Stopwatch]::StartNew()
    $fs = [System.IO.File]::Open($testPath, [System.IO.FileMode]::Create, [System.IO.FileAccess]::Write)
    $fs.Write($data, 0, $data.Length)
    $fs.Flush($true)
    $fs.Close()
    $sw.Stop()
    if ($sw.Elapsed.TotalSeconds -gt 0) { $result.WriteMBps = [Math]::Round(($testSizeMB / $sw.Elapsed.TotalSeconds), 1) }

    $sw2 = [System.Diagnostics.Stopwatch]::StartNew()
    $fs2 = [System.IO.File]::Open($testPath, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read)
    $buffer = New-Object byte[] (4MB)
    while ($fs2.Read($buffer, 0, $buffer.Length) -gt 0) { }
    $fs2.Close()
    $sw2.Stop()
    if ($sw2.Elapsed.TotalSeconds -gt 0) { $result.ReadMBps = [Math]::Round(($testSizeMB / $sw2.Elapsed.TotalSeconds), 1) }
} catch {
    $result.Error = $_.Exception.Message
} finally {
    if (Test-Path $testPath) { Remove-Item -Path $testPath -Force -ErrorAction SilentlyContinue }
}
$result | ConvertTo-Json -Compress | Out-File -FilePath "OUTFILE_PLACEHOLDER" -Encoding utf8
'@
    $benchScript = $benchScript.Replace("DRIVE_PLACEHOLDER", $Drive).Replace("OUTFILE_PLACEHOLDER", $tempOutBn)
    $benchScriptFile = Join-Path $env:TEMP "OptimizerBenchScript_$([guid]::NewGuid().ToString('N')).ps1"
    Set-Content -Path $benchScriptFile -Value $benchScript -Encoding utf8

    try {
        $procBn = Start-Process -FilePath "powershell.exe" -ArgumentList "-NoProfile -ExecutionPolicy Bypass -File `"$benchScriptFile`"" -WindowStyle Hidden -PassThru -ErrorAction Stop
    } catch {
        $global:lblBenchStatus.Text = "$(TT 'Αποτυχία εκκίνησης σάρωσης'): $($_.Exception.Message)"
        $global:btnStartBenchmark.Enabled = $true
        return
    }
    $global:driveBenchState = [PSCustomObject]@{ Process = $procBn; OutFile = $tempOutBn; ScriptFile = $benchScriptFile }
    $global:driveBenchTimer.Start()
}

