Add-TweakRow (TT "Ανάληψη Κυριότητας στο Μενού Δεξιού Κλικ") 1746 {
    try {
        Install-ContextMenuCommand -KeyPath "Registry::HKEY_CLASSES_ROOT\*\shell\runas" -MenuText (TT "Ανάληψη Κυριότητας") -Command 'cmd.exe /c takeown /f "%1" && icacls "%1" /grant *S-1-3-4:F /c /l & pause' -RequireElevation
        Install-ContextMenuCommand -KeyPath "Registry::HKEY_CLASSES_ROOT\Directory\shell\runas" -MenuText (TT "Ανάληψη Κυριότητας") -Command 'cmd.exe /c takeown /f "%1" /r /d y && icacls "%1" /grant *S-1-3-4:F /t /c /l & pause' -RequireElevation
        Install-ContextMenuCommand -KeyPath "Registry::HKEY_CLASSES_ROOT\Drive\shell\runas" -MenuText (TT "Ανάληψη Κυριότητας") -Command 'cmd.exe /c takeown /f "%1" /r /d y && icacls "%1" /grant *S-1-3-4:F /t /c /l & pause' -RequireElevation
        $lblStatus.Text = (TT "Η 'Ανάληψη Κυριότητας' προστέθηκε στο μενού δεξιού κλικ!")
    } catch {
        $lblStatus.Text = (TT "Αποτυχία προσθήκης στο μενού δεξιού κλικ.")
    }
} {
    Remove-ContextMenuCommand -KeyPath "Registry::HKEY_CLASSES_ROOT\*\shell\runas"
    Remove-ContextMenuCommand -KeyPath "Registry::HKEY_CLASSES_ROOT\Directory\shell\runas"
    Remove-ContextMenuCommand -KeyPath "Registry::HKEY_CLASSES_ROOT\Drive\shell\runas"
    $lblStatus.Text = (TT "Η 'Ανάληψη Κυριότητας' αφαιρέθηκε από το μενού δεξιού κλικ.")
} (TT "Προσθέτει επιλογή 'Ανάληψη Κυριότητας' στο δεξί κλικ αρχείων, φακέλων και δίσκων, για πλήρη έλεγχο πρόσβασης όταν τα Windows αρνούνται πρόσβαση. Η Επαναφορά αφαιρεί την επιλογή χωρίς να επηρεάσει ήδη τροποποιημένα δικαιώματα αρχείων.")

