# ===== ΝΕΑ ΕΝΟΤΗΤΑ (κατόπιν reverse engineering του WMT): ΓΕΝΙΚΗΣ ΧΡΗΣΗΣ CUSTOM ΔΕΞΙ-ΚΛΙΚ (CONTEXT MENU BUILDER) =====
# Σε αντίθεση με τα 2 hardcoded toggle παραπάνω (Ανάληψη Κυριότητας/PowerShell Εδώ), εδώ ο χρήστης μπορεί
# να προσθέσει ΟΠΟΙΑΔΗΠΟΤΕ δική του εντολή στο δεξί κλικ. Η μεταδεδομένα (MenuText/Command/Scope/Id)
# αποθηκεύονται σε ξεχωριστό JSON (ίδιο μοτίβο με το OptimizerTweakBackup.json) ώστε η εφαρμογή να ξέρει
# ΠΟΙΑ registry keys δημιούργησε η ίδια και να μπορεί να τα απαριθμήσει/αφαιρέσει με ασφάλεια - το registry
# key name (π.χ. "OptimizerCustom_a1b2c3d4") δεν έχει καμία σχέση με άλλα, προϋπάρχοντα shell verbs.
$global:customContextMenuPath = Join-Path $PSScriptRoot "OptimizerCustomContextMenu.json"

function Get-CustomContextMenuItems {
    if (Test-Path $global:customContextMenuPath) {
        try { return @(Get-Content $global:customContextMenuPath -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop) } catch { return @() }
    }
    return @()
}

function Save-CustomContextMenuItems {
    param($Items)
    try { @($Items) | ConvertTo-Json -Depth 3 | Out-File -FilePath $global:customContextMenuPath -Encoding UTF8 -Force } catch {}
}

function Get-CustomContextMenuRegPath {
    param([string]$Scope, [string]$Id)
    switch ($Scope) {
        "Files" { return "Registry::HKEY_CLASSES_ROOT\*\shell\$Id" }
        "FolderBackground" { return "Registry::HKEY_CLASSES_ROOT\Directory\Background\shell\$Id" }
        default { return "Registry::HKEY_CLASSES_ROOT\Directory\shell\$Id" }
    }
}

