function Update-CustomContextMenuDisplay {
    $global:customMenuPanelList.Controls.Clear()
    $items = @(Get-CustomContextMenuItems)
    if ($items.Count -eq 0) {
        $lblEmptyCm = [System.Windows.Forms.Label]::new()
        $lblEmptyCm.Text = (TT "Δεν έχετε προσθέσει ακόμα καμία προσαρμοσμένη επιλογή.")
        $lblEmptyCm.Font = $fontStatus
        $lblEmptyCm.ForeColor = $theme.SubText
        $lblEmptyCm.BackColor = [System.Drawing.Color]::Transparent
        $lblEmptyCm.Size = [System.Drawing.Size]::new(980, 24)
        $lblEmptyCm.Location = [System.Drawing.Point]::new(5, 5)
        $global:customMenuPanelList.Controls.Add($lblEmptyCm)
        $global:allSubTextLabels += $lblEmptyCm
        return
    }
    $rowYCm = 5
    foreach ($cmItem in $items) {
        $itemId = $cmItem.Id
        $itemScope = $cmItem.Scope
        $scopeLabel = switch ($itemScope) { "Files" { TT "Αρχεία" }; "FolderBackground" { TT "Φόντο Φακέλου" }; default { TT "Φάκελοι" } }

        $rowPanelCm = [System.Windows.Forms.Panel]::new()
        $rowPanelCm.Size = [System.Drawing.Size]::new(970, 34)
        $rowPanelCm.Location = [System.Drawing.Point]::new(5, $rowYCm)
        $rowPanelCm.BackColor = $theme.CardBg
        $global:customMenuPanelList.Controls.Add($rowPanelCm)

        $lblCmInfo = [System.Windows.Forms.Label]::new()
        $lblCmInfo.Text = "$($cmItem.MenuText)  [$scopeLabel]  -  $($cmItem.Command)"
        $lblCmInfo.Font = $fontStatus
        $lblCmInfo.ForeColor = $theme.Text
        $lblCmInfo.BackColor = [System.Drawing.Color]::Transparent
        $lblCmInfo.AutoEllipsis = $true
        $lblCmInfo.Size = [System.Drawing.Size]::new(830, 28)
        $lblCmInfo.Location = [System.Drawing.Point]::new(10, 3)
        $rowPanelCm.Controls.Add($lblCmInfo)
        $global:allTextLabels += $lblCmInfo

        $btnRemoveCm = [System.Windows.Forms.Button]::new()
        $btnRemoveCm.Text = (TT "Αφαίρεση")
        $btnRemoveCm.Size = [System.Drawing.Size]::new(110, 28)
        $btnRemoveCm.Location = [System.Drawing.Point]::new(850, 3)
        $btnRemoveCm.FlatStyle = "Flat"
        $btnRemoveCm.FlatAppearance.BorderSize = 0
        $btnRemoveCm.Font = $fontStatus
        $btnRemoveCm.BackColor = [System.Drawing.Color]::FromArgb(200, 80, 70)
        $btnRemoveCm.ForeColor = [System.Drawing.Color]::White
        $btnRemoveCm.Cursor = [System.Windows.Forms.Cursors]::Hand
        $btnRemoveCm.Add_Click({
            try {
                Remove-ContextMenuCommand -KeyPath (Get-CustomContextMenuRegPath -Scope $itemScope -Id $itemId)
                $remaining = @(Get-CustomContextMenuItems | Where-Object { $_.Id -ne $itemId })
                Save-CustomContextMenuItems -Items $remaining
                Update-CustomContextMenuDisplay
                $lblStatus.Text = (TT "Η προσαρμοσμένη επιλογή αφαιρέθηκε από το μενού δεξιού κλικ.")
            } catch {
                Show-CustomMessage -Message "$(TT 'Αποτυχία αφαίρεσης'): $($_.Exception.Message)" -Title "Σφάλμα" -Type "Error"
            }
        }.GetNewClosure())
        Add-ButtonHoverEffect -Button $btnRemoveCm -BaseColor $btnRemoveCm.BackColor
        $rowPanelCm.Controls.Add($btnRemoveCm)

        $rowYCm += 38
    }
}
Update-CustomContextMenuDisplay

