    $txtName.Size = [System.Drawing.Size]::new(460, 28)
    $txtName.Location = [System.Drawing.Point]::new(20, 45)
    $txtName.BackColor = $currTheme.CardBg
    $txtName.ForeColor = $currTheme.Text
    $addForm.Controls.Add($txtName)

    $lblCmd = [System.Windows.Forms.Label]::new()
    $lblCmd.Text = (TT "Πλήρης Εντολή (χρησιμοποιήστε %1 για το στοιχείο, %V για τον φάκελο)")
    $lblCmd.Font = $fontText
    $lblCmd.ForeColor = $currTheme.Text
    $lblCmd.BackColor = [System.Drawing.Color]::Transparent
    $lblCmd.Size = [System.Drawing.Size]::new(460, 22)
    $lblCmd.Location = [System.Drawing.Point]::new(20, 85)
    $addForm.Controls.Add($lblCmd)

    $txtCmd = [System.Windows.Forms.TextBox]::new()
    $txtCmd.Font = $fontText
    $txtCmd.Size = [System.Drawing.Size]::new(460, 28)
    $txtCmd.Location = [System.Drawing.Point]::new(20, 110)
    $txtCmd.BackColor = $currTheme.CardBg
    $txtCmd.ForeColor = $currTheme.Text
    $addForm.Controls.Add($txtCmd)

    $lblScope = [System.Windows.Forms.Label]::new()
    $lblScope.Text = (TT "Εφαρμογή σε:")
    $lblScope.Font = $fontText
    $lblScope.ForeColor = $currTheme.Text
    $lblScope.BackColor = [System.Drawing.Color]::Transparent
    $lblScope.Size = [System.Drawing.Size]::new(200, 22)
    $lblScope.Location = [System.Drawing.Point]::new(20, 150)
    $addForm.Controls.Add($lblScope)

    $cmbScope = [System.Windows.Forms.ComboBox]::new()
    $cmbScope.Font = $fontText
    $cmbScope.DropDownStyle = "DropDownList"
    $cmbScope.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
    $cmbScope.BackColor = $currTheme.CardBg
    $cmbScope.ForeColor = $currTheme.Text
    $cmbScope.Size = [System.Drawing.Size]::new(460, 28)
    $cmbScope.Location = [System.Drawing.Point]::new(20, 175)
    [void]$cmbScope.Items.Add((TT "Αρχεία"))
    [void]$cmbScope.Items.Add((TT "Φάκελοι"))
    [void]$cmbScope.Items.Add((TT "Φόντο Φακέλου"))
    $cmbScope.SelectedIndex = 1
    Set-ThemedComboBoxDrawing -ComboBox $cmbScope
    $addForm.Controls.Add($cmbScope)
    Add-ComboBoxArrowOverlay -ComboBox $cmbScope

    $btnAddOk = [System.Windows.Forms.Button]::new()
    $btnAddOk.Text = (TT "Προσθήκη")
    $btnAddOk.Size = [System.Drawing.Size]::new(150, 38)
    $btnAddOk.Location = [System.Drawing.Point]::new(120, 230)
    $btnAddOk.FlatStyle = "Flat"
    $btnAddOk.FlatAppearance.BorderSize = 0
    $btnAddOk.Font = New-Object System.Drawing.Font("Segoe UI", 9.5, [System.Drawing.FontStyle]::Bold)
    $btnAddOk.BackColor = $currTheme.Accent
    $btnAddOk.ForeColor = [System.Drawing.Color]::White
    $btnAddOk.Cursor = [System.Windows.Forms.Cursors]::Hand
    $btnAddOk.Add_Click({
        if (-not $txtName.Text.Trim() -or -not $txtCmd.Text.Trim()) {
            Show-CustomMessage -Message (TT "Συμπληρώστε το κείμενο μενού και την εντολή.") -Title (TT "Προσοχή") -Type "Info"
            return
        }
        $scopeMap = @{ 0 = "Files"; 1 = "Directory"; 2 = "FolderBackground" }
        $selectedScope = $scopeMap[$cmbScope.SelectedIndex]
        $newId = "OptimizerCustom_$([guid]::NewGuid().ToString('N').Substring(0,10))"
        try {
            $regPath = Get-CustomContextMenuRegPath -Scope $selectedScope -Id $newId
            $cmdSuffix = if ($selectedScope -eq "FolderBackground") { "%V" } else { "%1" }
            $fullCmd = $txtCmd.Text.Trim()
            if ($fullCmd -notmatch '%1|%V') { $fullCmd = "$fullCmd `"$cmdSuffix`"" }
            Install-ContextMenuCommand -KeyPath $regPath -MenuText $txtName.Text.Trim() -Command $fullCmd
            $existing = @(Get-CustomContextMenuItems)
            $existing += [PSCustomObject]@{ Id = $newId; MenuText = $txtName.Text.Trim(); Command = $fullCmd; Scope = $selectedScope }
            Save-CustomContextMenuItems -Items $existing
            Update-CustomContextMenuDisplay
            $lblStatus.Text = (TT "Η προσαρμοσμένη επιλογή προστέθηκε στο μενού δεξιού κλικ!")
            $addForm.Close()
        } catch {
            Show-CustomMessage -Message "$(TT 'Αποτυχία προσθήκης'): $($_.Exception.Message)" -Title "Σφάλμα" -Type "Error"
        }
    })
    $addForm.Controls.Add($btnAddOk)

    $btnAddCancel = [System.Windows.Forms.Button]::new()
    $btnAddCancel.Text = (T "BtnClose")
    $btnAddCancel.Size = [System.Drawing.Size]::new(150, 38)
    $btnAddCancel.Location = [System.Drawing.Point]::new(280, 230)
    $btnAddCancel.FlatStyle = "Flat"
    $btnAddCancel.FlatAppearance.BorderSize = 0
    $btnAddCancel.Font = $fontText
    $btnAddCancel.BackColor = $currTheme.BtnDefault
    $btnAddCancel.ForeColor = $currTheme.Text
    $btnAddCancel.Cursor = [System.Windows.Forms.Cursors]::Hand
    $btnAddCancel.Add_Click({ $addForm.Close() })
    $addForm.Controls.Add($btnAddCancel)

    $addForm.ShowDialog($mainForm) | Out-Null
}

